VARIABLE _EXT4-JWV-PHASE
VARIABLE _EXT4-JWV-TX-ACTIVE
VARIABLE _EXT4-JWV-COMMITTED-SHAPE
VARIABLE _EXT4-JWV-CAP
VARIABLE _EXT4-JWV-CREDIT
VARIABLE _EXT4-JWV-USED
VARIABLE _EXT4-JWV-ACTIVE

: _EXT4-JWV-EXPECT  ( address -- )
    _EXT4-JWV-CURSOR @ <> IF 0 _EXT4-JWV-OK ! THEN ;

: _EXT4-JWV-ADVANCE  ( count bytes-per-item -- )
    * _EXT4-JWV-CURSOR +! ;

: _EXT4-JWR-SHAPE?  ( writer -- flag )
    _EXT4-JWV-WRITER !
    _EXT4-JWV-WRITER @ 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAGIC + @
    _EXT4-JWR-MAGIC <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.SELF + @
    _EXT4-JWV-WRITER @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TOTAL + @
    _EXT4-JWR-SIZE U< IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ DUP
    _EXT4-JWV-CTX ! 0= IF FALSE EXIT THEN
    _EXT4-JWV-CTX @ _EXT4-JWR-CONTEXT? 0= IF FALSE EXIT THEN
    _EXT4-JWV-CTX @ _EXT4-C.J.WRITER + @
    _EXT4-JWV-WRITER @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ DUP 1024 =
    OVER 2048 = OR SWAP 4096 = OR 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JWV-CTX @ _EXT4-C.BSIZE + @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @ DUP 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @ U< 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @
    _EXT4-JWV-CTX @ _EXT4-C.J.FIRST + @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @
    _EXT4-JWV-CTX @ _EXT4-C.J.MAXLEN + @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @ 0<
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @ 0< OR
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @ 0< OR IF
        FALSE EXIT
    THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JWR-MEASURE _EXT4-JWV-IOR ! _EXT4-JWV-BYTES !
    _EXT4-JWV-IOR @ IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TOTAL + @
    _EXT4-JWV-BYTES @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JWM-META-SLOTS @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JWM-DATA-SLOTS @ <> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JWM-REVOKE-SLOTS @ <> IF FALSE EXIT THEN
    -1 _EXT4-JWV-OK !
    _EXT4-JWV-WRITER @ _EXT4-JWR-SIZE + _EXT4-JWV-CURSOR !
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-ENTRIES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-ENTRIES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-HASH + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-SLOTS + @
    1 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-HASH + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    1 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-HASH + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    1 CELLS _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-IMAGES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-IMAGES + @ _EXT4-JWV-EXPECT
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JWV-EXPECT
    1 _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-WRITER @ _EXT4-JWR.SCRATCH-B + @ _EXT4-JWV-EXPECT
    1 _EXT4-JWV-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JWV-ADVANCE
    _EXT4-JWV-CURSOR @
    _EXT4-JWV-WRITER @ _EXT4-JWR.TOTAL + @
    _EXT4-JWV-WRITER @ + <> IF 0 _EXT4-JWV-OK ! THEN
    _EXT4-JWV-OK @ ;

: _EXT4-JWR-COUNTS?  ( capacity credit used active -- flag )
    _EXT4-JWV-ACTIVE ! _EXT4-JWV-USED !
    _EXT4-JWV-CREDIT ! _EXT4-JWV-CAP !
    _EXT4-JWV-CAP @ 0< _EXT4-JWV-CREDIT @ 0< OR
    _EXT4-JWV-USED @ 0< OR _EXT4-JWV-ACTIVE @ 0< OR IF FALSE EXIT THEN
    _EXT4-JWV-CREDIT @ _EXT4-JWV-CAP @ U>
    _EXT4-JWV-USED @ _EXT4-JWV-CREDIT @ U> OR
    _EXT4-JWV-ACTIVE @ _EXT4-JWV-USED @ U> OR 0= ;

: _EXT4-JWV-RING-POS?  ( logical -- flag )
    DUP _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @ U< IF DROP FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @ U< ;

: _EXT4-JWR-CLEAR-CP-AUTHORITY  ( writer -- )
    _EXT4-JWR.CP-MODE +
    _EXT4-JWR-SIZE _EXT4-JWR.CP-MODE - 0 FILL ;

: _EXT4-JWR-TRANSACTION-CLEAN?  ( writer -- flag )
    DUP _EXT4-JWR.META-CREDIT + @
    OVER _EXT4-JWR.DATA-CREDIT + @ OR
    OVER _EXT4-JWR.REVOKE-CREDIT + @ OR
    OVER _EXT4-JWR.META-USED + @ OR
    OVER _EXT4-JWR.DATA-USED + @ OR
    OVER _EXT4-JWR.REVOKE-USED + @ OR
    OVER _EXT4-JWR.META-ACTIVE + @ OR
    OVER _EXT4-JWR.DATA-ACTIVE + @ OR
    OVER _EXT4-JWR.REVOKE-ACTIVE + @ OR
    OVER _EXT4-JWR.LOG-RESERVED + @ OR
    OVER _EXT4-JWR.TX-START + @ OR
    OVER _EXT4-JWR.TX-CURSOR + @ OR
    OVER _EXT4-JWR.TX-TID + @ OR
    OVER _EXT4-JWR.CP-MODE + @ OR
    OVER _EXT4-JWR.CP-EPOCH + @ OR
    OVER _EXT4-JWR.CP-O-INO + @ OR
    OVER _EXT4-JWR.CP-O-LOGICAL + @ OR
    OVER _EXT4-JWR.CP-O-SLOT + @ OR
    OVER _EXT4-JWR.CP-O-HOME + @ OR
    OVER _EXT4-JWR.CP-O-GEN + @ OR
    OVER _EXT4-JWR.CP-TARGET-GEN + @ OR
    OVER _EXT4-JWR.CP-TARGET-HOME + @ OR
    OVER _EXT4-JWR.CP-TARGET-OFF + @ OR
    OVER _EXT4-JWR.CP-TARGET-CRC + @ OR
    OVER _EXT4-JWR.CP-ORPHAN-CRC + @ OR
    OVER _EXT4-JWR.CP-TARGET-ENTRIES + @ OR
    OVER _EXT4-JWR.CP-INODE-BITMAP-HOME + @ OR
    OVER _EXT4-JWR.CP-INODE-BITMAP-CRC + @ OR
    OVER _EXT4-JWR.CP-INODE-GDT-HOME + @ OR
    OVER _EXT4-JWR.CP-INODE-GDT-OFF + @ OR
    OVER _EXT4-JWR.CP-INODE-GDT-CRC + @ OR
    OVER _EXT4-JWR.CP-INODE-SUPER-CRC + @ OR
    OVER _EXT4-JWR.CP-DATA-FIRST + @ OR
    SWAP _EXT4-JWR.CP-DATA-COUNT + @ OR 0= ;

: _EXT4-JWR-IDLE-CLEAN?  ( writer -- flag )
    DUP _EXT4-JWR-TRANSACTION-CLEAN?
    SWAP _EXT4-JWR.PHASE + @ 0= AND ;

VARIABLE _EXT4-JWV-LOG-EXPECTED
VARIABLE _EXT4-JWV-LOG-IOR
VARIABLE _EXT4-JWV-RES-META
VARIABLE _EXT4-JWV-RES-REVOKE
VARIABLE _EXT4-JWV-RES-WRITER

: _EXT4-JWV-CEIL/  ( nonnegative-n positive-d -- quotient )
    /MOD SWAP 0<> IF 1+ THEN ;

: _EXT4-JWV-LOG-ADD?  ( nonnegative-u -- flag )
    _EXT4-JWV-LOG-EXPECTED @ SWAP _EXT4-UADD?
    _EXT4-JWV-LOG-IOR ! _EXT4-JWV-LOG-EXPECTED !
    _EXT4-JWV-LOG-IOR @ 0= ;

: _EXT4-JWR-RESERVATION-COUNTS?
  ( meta-count revoke-count writer -- flag )
    _EXT4-JWV-RES-WRITER ! _EXT4-JWV-RES-REVOKE !
    _EXT4-JWV-RES-META !
    _EXT4-JWV-RES-META @ _EXT4-JWV-LOG-EXPECTED !
    _EXT4-JWV-RES-META @
    _EXT4-JWV-RES-WRITER @ _EXT4-JWR.BSIZE + @
    32 - _EXT4-JBD2-TAG3-SIZE /
    _EXT4-JWV-CEIL/ _EXT4-JWV-LOG-ADD? 0= IF FALSE EXIT THEN
    _EXT4-JWV-RES-REVOKE @
    _EXT4-JWV-RES-WRITER @ _EXT4-JWR.BSIZE + @ 20 - 8 /
    _EXT4-JWV-CEIL/ _EXT4-JWV-LOG-ADD? 0= IF FALSE EXIT THEN
    2 _EXT4-JWV-LOG-ADD? 0= IF FALSE EXIT THEN
    _EXT4-JWV-RES-WRITER @ _EXT4-JWR.LOG-RESERVED + @
    _EXT4-JWV-LOG-EXPECTED @ = ;

: _EXT4-JWR-RESERVATION?  ( writer -- flag )
    DUP _EXT4-JWR.META-CREDIT + @
    OVER _EXT4-JWR.REVOKE-CREDIT + @
    ROT _EXT4-JWR-RESERVATION-COUNTS? ;

: _EXT4-JWR-ACTUAL-RESERVATION?  ( writer -- flag )
    DUP _EXT4-JWR.META-ACTIVE + @
    OVER _EXT4-JWR.REVOKE-ACTIVE + @
    ROT _EXT4-JWR-RESERVATION-COUNTS? ;

: _EXT4-JWP-ACTIVATION?  ( phase -- flag )
    DUP _EXT4-JWP-GUARD-PRESEED >=
    SWAP _EXT4-JWP-GUARD-RETIRE <= AND ;

: _EXT4-JWP-EMISSION?  ( phase -- flag )
    DUP _EXT4-JWP-ORDERED-DATA >=
    SWAP _EXT4-JWP-COMMIT-FLUSH <= AND ;

: _EXT4-JWP-CHECKPOINT?  ( phase -- flag )
    DUP _EXT4-JWP-CHECKPOINT-PREFLIGHT >=
    SWAP _EXT4-JWP-CHECKPOINT-FINAL-PROOF <= AND ;

: _EXT4-JWP-DEACTIVATION?  ( phase -- flag )
    DUP _EXT4-JWP-DEACTIVATE-PREFLIGHT >=
    SWAP _EXT4-JWP-DEACTIVATE-FINAL-PROOF <= AND ;

VARIABLE _EXT4-JCA-WRITER
VARIABLE _EXT4-JCA-MODE
VARIABLE _EXT4-JCA-TARGET-HOME
VARIABLE _EXT4-JCA-BITMAP-HOME
VARIABLE _EXT4-JCA-GDT-HOME
VARIABLE _EXT4-JCA-TARGET-ENTRIES
VARIABLE _EXT4-JCA-DATA-FIRST
VARIABLE _EXT4-JCA-DATA-COUNT

: _EXT4-JCPM-ORPHAN-MODERN?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-FINAL =
    OVER _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL = OR
    SWAP _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL = OR ;

: _EXT4-JCPM-ORPHAN-LEGACY?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-LEGACY-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR ;

: _EXT4-JCPM-ORPHAN-DELETE?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL =
    OVER _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL = OR
    OVER _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL = OR
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR ;

: _EXT4-JCPM-ORPHAN-DATA-DELETE?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL =
    SWAP _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL = OR ;

: _EXT4-JCPM-ORPHAN-FINAL?  ( mode -- flag )
    DUP _EXT4-JCPM-ORPHAN-MODERN?
    SWAP _EXT4-JCPM-ORPHAN-LEGACY? OR ;

\ A final-cleanup certificate is arena-owned transaction state, not a global
\ permission bit.  These are coarse header bounds only; the exact retained
\ plan, raw locators, and staged images are authenticated again at checkpoint.
: _EXT4-JWR-CP-AUTHORITY?  ( writer -- flag )
    DUP _EXT4-JCA-WRITER ! _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JCA-MODE ! _EXT4-JCPM-NONE = IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EPOCH +
        _EXT4-JWR-SIZE _EXT4-JWR.CP-EPOCH - _EXT4-BYTES-ZERO? EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-FINAL? 0= IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-EPOCH + @
    _EXT4-JCA-WRITER @ _EXT4-JWR.EPOCH + @ <> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-INO + @ DUP
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF DROP FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.INODES + @ U> IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @ U< 0= IF
        FALSE EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ 0< IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-SLOT + @ DUP 0< IF
            DROP FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ 8 - 4 / U< 0= IF
            FALSE EXIT
        THEN
    ELSE
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-SLOT + @ OR IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK <> IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-TARGET-HOME !
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
    _EXT4-JCA-TARGET-HOME @
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = IF FALSE EXIT THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-GEN + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + @ 0xFFFFFFFF U> IF
        FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @
    DUP 0< OVER 4 U> OR IF DROP FALSE EXIT THEN
    _EXT4-JCA-TARGET-ENTRIES !
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DATA-DELETE? IF
        _EXT4-JCA-TARGET-ENTRIES @ 1 <> IF FALSE EXIT THEN
    ELSE
        _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
            _EXT4-JCA-TARGET-ENTRIES @ IF FALSE EXIT THEN
        ELSE
            _EXT4-JCA-TARGET-ENTRIES @ 0= IF
                _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ IF
                    FALSE EXIT
                THEN
            THEN
        THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ U< 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ SWAP -
    _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.ISIZE + @ U< IF
        FALSE EXIT
    THEN
    _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + @ DUP
        _EXT4-JCA-BITMAP-HOME ! DUP 0< IF DROP FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
        _EXT4-JCA-BITMAP-HOME @ _EXT4-JCA-TARGET-HOME @ =
        _EXT4-JCA-BITMAP-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR IF
            FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + @
        0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @ DUP
        _EXT4-JCA-GDT-HOME ! DUP 0< IF DROP FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
        _EXT4-JCA-GDT-HOME @ _EXT4-JCA-BITMAP-HOME @ =
        _EXT4-JCA-GDT-HOME @ _EXT4-JCA-TARGET-HOME @ = OR
        _EXT4-JCA-GDT-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-O-HOME + @ = OR IF
            FALSE EXIT
        THEN
        _EXT4-JCA-BITMAP-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK =
        _EXT4-JCA-GDT-HOME @
        _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-PRIMARY-SUPER-BLOCK = OR IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @ DUP 0< IF
            DROP FALSE EXIT
        THEN
        DUP _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ U< 0= IF
            DROP FALSE EXIT
        THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.BSIZE + @ SWAP -
        _EXT4-DESC-SIZE U< IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @
        0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @
        0xFFFFFFFF U> IF FALSE EXIT THEN
        _EXT4-JCA-MODE @ _EXT4-JCPM-ORPHAN-DATA-DELETE? IF
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DATA-FIRST + @ DUP
            _EXT4-JCA-DATA-FIRST ! DROP
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DATA-COUNT + @ DUP
            _EXT4-JCA-DATA-COUNT ! 1 <> IF FALSE EXIT THEN
            _EXT4-JCA-DATA-FIRST @
            _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.FIRST + @
            U< IF FALSE EXIT THEN
            _EXT4-JCA-DATA-FIRST @ _EXT4-JCA-DATA-COUNT @
            _EXT4-JCA-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @
            BLOCK-RANGE? 0= IF FALSE EXIT THEN
        ELSE
            _EXT4-JCA-WRITER @ _EXT4-JWR.CP-DATA-FIRST +
            2 CELLS _EXT4-BYTES-ZERO? 0= IF FALSE EXIT THEN
        THEN
    ELSE
        _EXT4-JCA-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME +
        _EXT4-JWR-SIZE _EXT4-JWR.CP-INODE-BITMAP-HOME -
        _EXT4-BYTES-ZERO? 0= IF FALSE EXIT THEN
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
        _EXT4-JCA-WRITER @ _EXT4-JWR.PHASE + @ DUP
        _EXT4-JWP-EMISSION? SWAP _EXT4-JWP-CHECKPOINT? OR EXIT
    THEN
    _EXT4-JCA-WRITER @ _EXT4-JWR.STATE + @ DUP
    _EXT4-JWR-STAGING = OVER _EXT4-JWR-EMITTING = OR
    OVER _EXT4-JWR-COMMITTED = OR
    SWAP _EXT4-JWR-CHECKPOINTING = OR ;

: _EXT4-JWR-RUNTIME?  ( writer -- flag )
    DUP _EXT4-JWV-WRITER !
    _EXT4-JWR.STATE + @ DUP _EXT4-JWV-STATE !
    DUP 0< SWAP _EXT4-JWR-DEACTIVATING U> OR IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.PHASE + @ _EXT4-JWV-PHASE !
    _EXT4-JWV-WRITER @ _EXT4-JWR-CP-AUTHORITY? 0= IF FALSE EXIT THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED = IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.FAULT + @ 0= IF FALSE EXIT THEN
        _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION?
        _EXT4-JWV-PHASE @ _EXT4-JWP-EMISSION? OR
        _EXT4-JWV-PHASE @ _EXT4-JWP-CHECKPOINT? OR
        _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? OR 0= IF
            FALSE EXIT
        THEN
    ELSE
        _EXT4-JWV-WRITER @ _EXT4-JWR.FAULT + @ IF FALSE EXIT THEN
        _EXT4-JWV-STATE @ _EXT4-JWR-ACTIVATING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION? 0= IF FALSE EXIT THEN
        ELSE _EXT4-JWV-STATE @ _EXT4-JWR-EMITTING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-EMISSION? 0= IF FALSE EXIT THEN
        ELSE _EXT4-JWV-STATE @ _EXT4-JWR-CHECKPOINTING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-CHECKPOINT? 0= IF
                FALSE EXIT
            THEN
        ELSE _EXT4-JWV-STATE @ _EXT4-JWR-DEACTIVATING = IF
            _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? 0= IF
                FALSE EXIT
            THEN
        ELSE
            _EXT4-JWV-PHASE @ IF FALSE EXIT THEN
        THEN THEN THEN THEN
    THEN
    0 _EXT4-JWV-COMMITTED-SHAPE !
    _EXT4-JWV-STATE @ _EXT4-JWR-COMMITTED =
    _EXT4-JWV-STATE @ _EXT4-JWR-CHECKPOINTING = OR
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
    _EXT4-JWV-PHASE @ _EXT4-JWP-CHECKPOINT? AND OR IF
        -1 _EXT4-JWV-COMMITTED-SHAPE !
    THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-ACTIVATING =
    _EXT4-JWV-STATE @ _EXT4-JWR-DEACTIVATING = OR IF
        _EXT4-JWV-WRITER @ _EXT4-JWR-TRANSACTION-CLEAN? 0= IF
            FALSE EXIT
        THEN
    ELSE _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
        _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION?
        _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? OR AND IF
            _EXT4-JWV-WRITER @ _EXT4-JWR-TRANSACTION-CLEAN? 0= IF
                FALSE EXIT
            THEN
        THEN
    THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.MAXLEN + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.FIRST + @ - 1-
    _EXT4-JWV-RING-CAP !
    _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @
    _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TAIL + @
    _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.FREE + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.NEXT-TID + @
    0xFFFFFFFF U> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @
    0xFFFFFFFF U> IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-CREDIT + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JWR-COUNTS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-CREDIT + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.DATA-ACTIVE + @
    _EXT4-JWR-COUNTS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JWV-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    _EXT4-JWR-COUNTS? 0= IF FALSE EXIT THEN
    _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ DUP 0< IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
    _EXT4-JWV-COMMITTED-SHAPE @ IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOURNAL-NEXT
        <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.SEQUENCE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.HEAD + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.ANCHOR + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.CURSOR + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.COMMITTED + @
        1 <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.J.NEXT-SEQUENCE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @ 2 +
        0xFFFFFFFF AND <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-ACTIVE <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.J.WITNESS + @ DUP IF
            _EXT4-JW-RECOVERY <> IF FALSE EXIT THEN
            _EXT4-JWV-PHASE @
            _EXT4-JWP-CHECKPOINT-WITNESS-CLEAR < IF FALSE EXIT THEN
        ELSE
            DROP
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @
        _EXT4-C.J.PRIMARY-TORN + @ IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.SUPER-TORN + @ IF
            FALSE EXIT
        THEN
    ELSE
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.J.START + @ IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-IDLE = IF
        _EXT4-JWV-WRITER @ _EXT4-JWR-IDLE-CLEAN? EXIT
    THEN
    0 _EXT4-JWV-TX-ACTIVE !
    _EXT4-JWV-STATE @ _EXT4-JWR-STAGING =
    _EXT4-JWV-STATE @ _EXT4-JWR-EMITTING = OR IF
        -1 _EXT4-JWV-TX-ACTIVE !
    THEN
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
    _EXT4-JWV-PHASE @ _EXT4-JWP-EMISSION? AND IF
        -1 _EXT4-JWV-TX-ACTIVE !
    THEN
    _EXT4-JWV-TX-ACTIVE @ IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ 0= IF
            FALSE EXIT
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR-RESERVATION? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.NEXT-TID + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.FREE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP
        _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
        TRUE EXIT
    THEN
    _EXT4-JWV-COMMITTED-SHAPE @ IF
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ 0= IF
            FALSE EXIT
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR-ACTUAL-RESERVATION? 0= IF
            FALSE EXIT
        THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @
        _EXT4-JWV-RING-POS? 0= IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TAIL + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-START + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOURNAL-ADVANCE
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.HEAD + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.TX-TID + @ 1+
        0xFFFFFFFF AND
        _EXT4-JWV-WRITER @ _EXT4-JWR.NEXT-TID + @ <> IF FALSE EXIT THEN
        _EXT4-JWV-WRITER @ _EXT4-JWR.FREE + @
        _EXT4-JWV-WRITER @ _EXT4-JWR.LOG-RESERVED + @ _EXT4-UADD?
        DUP IF 2DROP FALSE EXIT THEN DROP
        _EXT4-JWV-RING-CAP @ U> IF FALSE EXIT THEN
        TRUE EXIT
    THEN
    \ The only remaining states are activation/deactivation, or a fault in one
    \ of those clean-transaction protocols, whose invariant was proved above.
    _EXT4-JWV-STATE @ _EXT4-JWR-ACTIVATING =
    _EXT4-JWV-STATE @ _EXT4-JWR-DEACTIVATING = OR
    _EXT4-JWV-STATE @ _EXT4-JWR-FAULTED =
    _EXT4-JWV-PHASE @ _EXT4-JWP-ACTIVATION?
    _EXT4-JWV-PHASE @ _EXT4-JWP-DEACTIVATION? OR AND OR ;

: _EXT4-JWR-VALID?  ( writer -- flag )
    DUP _EXT4-JWR-SHAPE? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.CTX + @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        DROP FALSE EXIT
    THEN
    _EXT4-JWR-RUNTIME? ;

VARIABLE _EXT4-JWN-META
VARIABLE _EXT4-JWN-DATA
VARIABLE _EXT4-JWN-REVOKE
VARIABLE _EXT4-JWN-CTX
VARIABLE _EXT4-JWN-BSIZE
VARIABLE _EXT4-JWN-MAXLEN
VARIABLE _EXT4-JWN-FIRST
VARIABLE _EXT4-JWN-HEAD
VARIABLE _EXT4-JWN-FREE
VARIABLE _EXT4-JWN-BYTES
VARIABLE _EXT4-JWN-IOR
VARIABLE _EXT4-JWN-WRITER
VARIABLE _EXT4-JWN-CURSOR

: _EXT4-JWR-MATCH?  ( writer -- flag )
    DUP _EXT4-JWR-VALID? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.CTX + @ _EXT4-JWN-CTX @ =
    OVER _EXT4-JWR.TOTAL + @ _EXT4-JWN-BYTES @ = AND
    OVER _EXT4-JWR.BSIZE + @ _EXT4-JWN-BSIZE @ = AND
    OVER _EXT4-JWR.MAXLEN + @ _EXT4-JWN-MAXLEN @ = AND
    OVER _EXT4-JWR.FIRST + @ _EXT4-JWN-FIRST @ = AND
    OVER _EXT4-JWR.META-CAP + @ _EXT4-JWN-META @ = AND
    OVER _EXT4-JWR.DATA-CAP + @ _EXT4-JWN-DATA @ = AND
    SWAP _EXT4-JWR.REVOKE-CAP + @ _EXT4-JWN-REVOKE @ = AND ;

: _EXT4-JWR-ZERO-OWNED  ( writer -- )
    DUP _EXT4-JWR.META-ENTRIES + @
    OVER _EXT4-JWR.META-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.DATA-ENTRIES + @
    OVER _EXT4-JWR.DATA-CAP + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.REVOKE-ENTRIES + @
    OVER _EXT4-JWR.REVOKE-CAP + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.META-HASH + @
    OVER _EXT4-JWR.META-SLOTS + @ CELLS 0 FILL
    DUP _EXT4-JWR.DATA-HASH + @
    OVER _EXT4-JWR.DATA-SLOTS + @ CELLS 0 FILL
    DUP _EXT4-JWR.REVOKE-HASH + @
    OVER _EXT4-JWR.REVOKE-SLOTS + @ CELLS 0 FILL
    DUP _EXT4-JWR.META-IMAGES + @
    OVER _EXT4-JWR.META-CAP + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.DATA-IMAGES + @
    OVER _EXT4-JWR.DATA-CAP + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.SCRATCH-A + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JWR.SCRATCH-B + @ SWAP _EXT4-JWR.BSIZE + @ 0 FILL ;

: _EXT4-JWR-REBASE-IDLE  ( writer -- writer )
    DUP _EXT4-JWR-ZERO-OWNED
    DUP _EXT4-JWR-CLEAR-CP-AUTHORITY
    0 OVER _EXT4-JWR.META-CREDIT + !
    0 OVER _EXT4-JWR.DATA-CREDIT + !
    0 OVER _EXT4-JWR.REVOKE-CREDIT + !
    0 OVER _EXT4-JWR.META-USED + !
    0 OVER _EXT4-JWR.DATA-USED + !
    0 OVER _EXT4-JWR.REVOKE-USED + !
    0 OVER _EXT4-JWR.META-ACTIVE + !
    0 OVER _EXT4-JWR.DATA-ACTIVE + !
    0 OVER _EXT4-JWR.REVOKE-ACTIVE + !
    0 OVER _EXT4-JWR.LOG-RESERVED + !
    0 OVER _EXT4-JWR.TX-START + !
    0 OVER _EXT4-JWR.TX-CURSOR + !
    0 OVER _EXT4-JWR.TX-TID + !
    0 OVER _EXT4-JWR.PHASE + !
    _EXT4-JWN-HEAD @ DUP 2 PICK _EXT4-JWR.HEAD + !
    OVER _EXT4-JWR.TAIL + !
    _EXT4-JWN-FREE @ OVER _EXT4-JWR.FREE + !
    _EXT4-JWN-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    OVER _EXT4-JWR.NEXT-TID + ! ;

\ Allocate and publish exactly once.  A later request may reuse only the same
\ complete geometry; a different request cannot be satisfied without leaking
\ the monotonic mount arena, so it is a conflict rather than implicit growth.
: _EXT4-JWR-ENSURE  ( meta-cap data-cap revoke-cap ctx -- writer ior )
    _EXT4-JWN-CTX ! _EXT4-JWN-REVOKE !
    _EXT4-JWN-DATA ! _EXT4-JWN-META !
    _EXT4-JWN-CTX @ _EXT4-JWR-CONTEXT? 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JWN-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JWN-CTX @ _EXT4-C.BSIZE + @ _EXT4-JWN-BSIZE !
    _EXT4-JWN-META @ _EXT4-JWN-DATA @ _EXT4-JWN-REVOKE @
    _EXT4-JWN-BSIZE @
    _EXT4-JWR-MEASURE _EXT4-JWN-IOR ! _EXT4-JWN-BYTES !
    _EXT4-JWN-IOR @ IF 0 _EXT4-JWN-IOR @ EXIT THEN
    _EXT4-JWN-CTX @ _EXT4-C.J.MAXLEN + @ _EXT4-JWN-MAXLEN !
    _EXT4-JWN-CTX @ _EXT4-C.J.FIRST + @ _EXT4-JWN-FIRST !
    _EXT4-JWN-MAXLEN @ _EXT4-JWN-FIRST @ - DUP 0= IF
        DROP 0 VFS-E-INVALID EXIT
    THEN
    1- _EXT4-JWN-FREE !
    _EXT4-JWN-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-JWN-FIRST @
    ELSE
        DUP _EXT4-JWN-FIRST @ U<
        OVER _EXT4-JWN-MAXLEN @ U< 0= OR IF
            DROP 0 VFS-E-INVALID EXIT
        THEN
    THEN _EXT4-JWN-HEAD !
    _EXT4-JWN-CTX @ _EXT4-C.J.WRITER + @ ?DUP IF
        DUP _EXT4-JWR-VALID? 0= IF DROP 0 VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR-MATCH? 0= IF DROP 0 VFS-E-CONFLICT EXIT THEN
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
            DROP 0 VFS-E-BUSY EXIT
        THEN
        DUP _EXT4-JWR.FAULT + @ IF DROP 0 VFS-E-BUSY EXIT THEN
        _EXT4-JWR-REBASE-IDLE 0 EXIT
    THEN
    _EXT4-JWN-CTX @ _EXT4-C.ARENA + @ _EXT4-JWN-BYTES @ ARENA-ALLOT?
    IF DROP 0 VFS-E-NOMEM EXIT THEN
    DUP _EXT4-JWN-WRITER ! _EXT4-JWN-BYTES @ 0 FILL
    _EXT4-JWR-MAGIC _EXT4-JWN-WRITER @ _EXT4-JWR.MAGIC + !
    _EXT4-JWN-WRITER @ DUP _EXT4-JWR.SELF + !
    _EXT4-JWN-CTX @ _EXT4-JWN-WRITER @ _EXT4-JWR.CTX + !
    _EXT4-JWN-BYTES @ _EXT4-JWN-WRITER @ _EXT4-JWR.TOTAL + !
    _EXT4-JWN-BSIZE @ _EXT4-JWN-WRITER @ _EXT4-JWR.BSIZE + !
    _EXT4-JWN-MAXLEN @ _EXT4-JWN-WRITER @ _EXT4-JWR.MAXLEN + !
    _EXT4-JWN-FIRST @ _EXT4-JWN-WRITER @ _EXT4-JWR.FIRST + !
    _EXT4-JWN-META @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-CAP + !
    _EXT4-JWM-META-SLOTS @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-SLOTS + !
    _EXT4-JWN-DATA @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-CAP + !
    _EXT4-JWM-DATA-SLOTS @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-SLOTS + !
    _EXT4-JWN-REVOKE @ _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-CAP + !
    _EXT4-JWM-REVOKE-SLOTS @
    _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-SLOTS + !
    _EXT4-JWN-WRITER @ _EXT4-JWR-SIZE + _EXT4-JWN-CURSOR !
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.META-ENTRIES + !
    _EXT4-JWN-META @ _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS *
    _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-ENTRIES + !
    _EXT4-JWN-DATA @ _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS *
    _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @
    _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + !
    _EXT4-JWN-REVOKE @ _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS *
    _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-HASH + !
    _EXT4-JWM-META-SLOTS @ CELLS _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-HASH + !
    _EXT4-JWM-DATA-SLOTS @ CELLS _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.REVOKE-HASH + !
    _EXT4-JWM-REVOKE-SLOTS @ CELLS _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.META-IMAGES + !
    _EXT4-JWN-META @ _EXT4-JWN-BSIZE @ * _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.DATA-IMAGES + !
    _EXT4-JWN-DATA @ _EXT4-JWN-BSIZE @ * _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.SCRATCH-A + !
    _EXT4-JWN-BSIZE @ _EXT4-JWN-CURSOR +!
    _EXT4-JWN-CURSOR @ _EXT4-JWN-WRITER @ _EXT4-JWR.SCRATCH-B + !
    _EXT4-JWN-CURSOR @ _EXT4-JWN-BSIZE @ +
    _EXT4-JWN-WRITER @ _EXT4-JWN-BYTES @ + <> IF
        0 _EXT4-JWN-WRITER @ _EXT4-JWR.MAGIC + !
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWN-HEAD @ DUP _EXT4-JWN-WRITER @ _EXT4-JWR.HEAD + !
    _EXT4-JWN-WRITER @ _EXT4-JWR.TAIL + !
    _EXT4-JWN-FREE @ _EXT4-JWN-WRITER @ _EXT4-JWR.FREE + !
    \ Linux advances past a clean superblock's persisted tail sequence when
    \ it initializes the next running transaction, including 32-bit wrap.
    _EXT4-JWN-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JWN-WRITER @ _EXT4-JWR.NEXT-TID + !
    _EXT4-JWN-WRITER @ _EXT4-JWN-CTX @ _EXT4-C.J.WRITER + !
    _EXT4-JWN-WRITER @ 0 ;

VARIABLE _EXT4-JMR-CTX
VARIABLE _EXT4-JMR-WRITER
VARIABLE _EXT4-JMR-HEAD
VARIABLE _EXT4-JMR-FREE
VARIABLE _EXT4-JMR-WRITE-ACTIVE

\ Rebase only after publication has been withdrawn and strict validation has
\ authenticated an empty standard journal.  Mount recovery supplies a clean
\ endpoint; a live checkpoint supplies the equally standard RECOVER-set,
\ write-active endpoint so later transactions do not repeat AKW1 activation.
: _EXT4-JWR-REBASE-ENDPOINT  ( ctx write-active? -- ior )
    _EXT4-JMR-WRITE-ACTIVE ! _EXT4-JMR-CTX !
    _EXT4-JMR-WRITE-ACTIVE @ IF
        _EXT4-JMR-CTX @ _EXT4-C.RECOVERY + @ 0=
        _EXT4-JMR-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JMR-CTX @ _EXT4-C.SB + DUP
        _EXT4-SUPER-CHECKSUM? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JMR-CTX @ _EXT4-C.RECOVERY + @
        _EXT4-JMR-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JMR-CTX @ _EXT4-C.J.START + @
    _EXT4-JMR-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.SUPER-TORN + @ OR
    _EXT4-JMR-CTX @ _EXT4-C.J.WRITER-CURRENT + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JMR-CTX @ _EXT4-C.J.WRITER + @ DUP 0= IF DROP 0 EXIT THEN
    DUP _EXT4-JMR-WRITER ! _EXT4-JWR-SHAPE? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JMR-CTX @ _EXT4-C.J.MAXLEN + @
    _EXT4-JMR-CTX @ _EXT4-C.J.FIRST + @ - 1- DUP 0< IF
        DROP VFS-E-CORRUPT EXIT
    THEN _EXT4-JMR-FREE !
    _EXT4-JMR-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-JMR-CTX @ _EXT4-C.J.FIRST + @
    ELSE
        DUP _EXT4-JMR-CTX @ _EXT4-C.J.FIRST + @ U<
        OVER _EXT4-JMR-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
            DROP VFS-E-CORRUPT EXIT
        THEN
    THEN _EXT4-JMR-HEAD !
    _EXT4-JMR-WRITER @ _EXT4-JWR-ZERO-OWNED
    _EXT4-JMR-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.FAULT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.META-CREDIT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.DATA-CREDIT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.REVOKE-CREDIT + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.META-USED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.DATA-USED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.REVOKE-USED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.META-ACTIVE + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.DATA-ACTIVE + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.LOG-RESERVED + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.TX-START + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.TX-CURSOR + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.TX-TID + !
    0 _EXT4-JMR-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JMR-HEAD @ DUP _EXT4-JMR-WRITER @ _EXT4-JWR.HEAD + !
    _EXT4-JMR-WRITER @ _EXT4-JWR.TAIL + !
    _EXT4-JMR-FREE @ _EXT4-JMR-WRITER @ _EXT4-JWR.FREE + !
    _EXT4-JMR-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JMR-WRITER @ _EXT4-JWR.NEXT-TID + !
    _EXT4-JWR-IDLE _EXT4-JMR-WRITER @ _EXT4-JWR.STATE + !
    0 ;

\ A failed mount preserves the one arena allocation and all of its bytes for
\ diagnosis or retry, but never republishes it as a usable transaction.  Only
\ the final authenticated clean endpoint may scrub those retained bytes.
: _EXT4-JWR-REBASE-MOUNTED  ( ctx -- ior )
    0 _EXT4-JWR-REBASE-ENDPOINT ;

: _EXT4-JWR-REBASE-WRITE-ACTIVE  ( ctx -- ior )
    -1 _EXT4-JWR-REBASE-ENDPOINT ;

VARIABLE _EXT4-JHL-HOME
VARIABLE _EXT4-JHL-ENTRIES
VARIABLE _EXT4-JHL-STRIDE
VARIABLE _EXT4-JHL-HASH
VARIABLE _EXT4-JHL-SLOTS
VARIABLE _EXT4-JHL-USED
VARIABLE _EXT4-JHL-SLOT
VARIABLE _EXT4-JHL-INDEX
VARIABLE _EXT4-JHL-IOR

: _EXT4-JTX-HASH-FIND
  ( home entries entry-cells hash slots used -- index found? ior )
    _EXT4-JHL-USED ! _EXT4-JHL-SLOTS ! _EXT4-JHL-HASH !
    _EXT4-JHL-STRIDE !
    _EXT4-JHL-ENTRIES ! _EXT4-JHL-HOME !
    _EXT4-JHL-SLOTS @ 0= IF 0 FALSE 0 EXIT THEN
    _EXT4-JHL-HOME @ _EXT4-JHL-SLOTS @ 1- AND _EXT4-JHL-SLOT !
    _EXT4-JHL-SLOTS @ 0 ?DO
        _EXT4-JHL-HASH @ _EXT4-JHL-SLOT @ CELLS + @ DUP 0= IF
            DROP 0 FALSE 0 UNLOOP EXIT
        THEN
        1- DUP _EXT4-JHL-INDEX !
        _EXT4-JHL-USED @ U< 0= IF
            0 FALSE VFS-E-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JHL-INDEX @ _EXT4-JHL-STRIDE @ *
        CELLS _EXT4-JHL-ENTRIES @ + @
        _EXT4-JHL-HOME @ = IF
            _EXT4-JHL-INDEX @ TRUE 0 UNLOOP EXIT
        THEN
        _EXT4-JHL-SLOT @ 1+ _EXT4-JHL-SLOTS @ 1- AND
        _EXT4-JHL-SLOT !
    LOOP
    0 FALSE 0 ;

VARIABLE _EXT4-JHI-HOME
VARIABLE _EXT4-JHI-INDEX
VARIABLE _EXT4-JHI-HASH
VARIABLE _EXT4-JHI-SLOTS
VARIABLE _EXT4-JHI-SLOT

: _EXT4-JTX-HASH-INSERT  ( home index hash slots -- ior )
    _EXT4-JHI-SLOTS ! _EXT4-JHI-HASH !
    _EXT4-JHI-INDEX ! _EXT4-JHI-HOME !
    _EXT4-JHI-SLOTS @ 0= IF VFS-E-NOSPC EXIT THEN
    _EXT4-JHI-HOME @ _EXT4-JHI-SLOTS @ 1- AND _EXT4-JHI-SLOT !
    _EXT4-JHI-SLOTS @ 0 ?DO
        _EXT4-JHI-HASH @ _EXT4-JHI-SLOT @ CELLS + DUP @ 0= IF
            _EXT4-JHI-INDEX @ 1+ SWAP ! 0 UNLOOP EXIT
        THEN
        DROP
        _EXT4-JHI-SLOT @ 1+ _EXT4-JHI-SLOTS @ 1- AND
        _EXT4-JHI-SLOT !
    LOOP
    VFS-E-NOSPC ;

: _EXT4-JTX-ENTRY  ( index entries entry-cells -- entry )
    ROT * CELLS + ;

VARIABLE _EXT4-JIC-BUFFER
VARIABLE _EXT4-JIC-WRITER

: _EXT4-JTX-IMAGE-CRC  ( buffer writer -- crc )
    _EXT4-JIC-WRITER ! _EXT4-JIC-BUFFER !
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JIC-BUFFER @
    _EXT4-JIC-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-CRC-ADD
    _EXT4-CRC@ ;

: _EXT4-JTX-CEIL/  ( nonnegative-n positive-d -- quotient )
    /MOD SWAP 0<> IF 1+ THEN ;

: _EXT4-JTX-TAGS/BLOCK-SIZE  ( block-size -- tags )
    32 - _EXT4-JBD2-TAG3-SIZE / ;

: _EXT4-JTX-REVOKES/BLOCK-SIZE  ( block-size -- revokes )
    20 - 8 / ;

: _EXT4-JTX-TAGS/BLOCK  ( writer -- tags )
    _EXT4-JWR.BSIZE + @ _EXT4-JTX-TAGS/BLOCK-SIZE ;

: _EXT4-JTX-REVOKES/BLOCK  ( writer -- revokes )
    _EXT4-JWR.BSIZE + @ _EXT4-JTX-REVOKES/BLOCK-SIZE ;

VARIABLE _EXT4-JLG-META
VARIABLE _EXT4-JLG-REVOKE
VARIABLE _EXT4-JLG-WRITER
VARIABLE _EXT4-JLG-BSIZE
VARIABLE _EXT4-JLG-TOTAL
VARIABLE _EXT4-JLG-ADD

: _EXT4-JTX-LOG-ADD  ( u -- ior )
    _EXT4-JLG-ADD !
    _EXT4-JLG-TOTAL @ _EXT4-JLG-ADD @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JLG-TOTAL ! 0 ;

: _EXT4-JTX-LOG-BLOCKS-FOR
  ( meta-credit revoke-credit block-size -- blocks ior )
    _EXT4-JLG-BSIZE ! _EXT4-JLG-REVOKE ! _EXT4-JLG-META !
    _EXT4-JLG-META @ 0< _EXT4-JLG-REVOKE @ 0< OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JLG-BSIZE @ 1024 =
    _EXT4-JLG-BSIZE @ 2048 = OR
    _EXT4-JLG-BSIZE @ 4096 = OR 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JLG-META @ _EXT4-JLG-TOTAL !
    _EXT4-JLG-META @
    _EXT4-JLG-BSIZE @ _EXT4-JTX-TAGS/BLOCK-SIZE
    _EXT4-JTX-CEIL/ _EXT4-JTX-LOG-ADD ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JLG-REVOKE @
    _EXT4-JLG-BSIZE @ _EXT4-JTX-REVOKES/BLOCK-SIZE
    _EXT4-JTX-CEIL/ _EXT4-JTX-LOG-ADD ?DUP IF 0 SWAP EXIT THEN
    \ One block holds the standard active-super guard outside the JBD2
    \ record stream, and one holds the transaction commit.  The ring's
    \ separately excluded spare remains available as an exact terminator.
    2 _EXT4-JTX-LOG-ADD ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JLG-TOTAL @ 0 ;

: _EXT4-JTX-LOG-BLOCKS  ( meta-credit revoke-credit writer -- blocks ior )
    DUP _EXT4-JLG-WRITER ! _EXT4-JWR-VALID? 0= IF
        2DROP 0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JLG-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-JTX-LOG-BLOCKS-FOR ;

VARIABLE _EXT4-JPC-META
VARIABLE _EXT4-JPC-DATA
VARIABLE _EXT4-JPC-REVOKE
VARIABLE _EXT4-JPC-CTX
VARIABLE _EXT4-JPC-BSIZE
VARIABLE _EXT4-JPC-BYTES
VARIABLE _EXT4-JPC-LOG
VARIABLE _EXT4-JPC-FREE
VARIABLE _EXT4-JPC-IOR

\ Prove that one requested workspace and transaction can fit the authenticated
\ journal geometry before _EXT4-JWR-ENSURE can consume the monotonic arena.
\ This performs arithmetic and context inspection only; it allocates, stages,
\ publishes, writes, and flushes nothing.
: _EXT4-JTX-PREFLIGHT-CAPACITY
  ( meta-cap data-cap revoke-cap ctx -- ior )
    _EXT4-JPC-CTX ! _EXT4-JPC-REVOKE !
    _EXT4-JPC-DATA ! _EXT4-JPC-META !
    _EXT4-JPC-CTX @ _EXT4-JWR-GEOMETRY? 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.BSIZE + @ _EXT4-JPC-BSIZE !
    _EXT4-JPC-META @ _EXT4-JPC-DATA @ _EXT4-JPC-REVOKE @
    _EXT4-JPC-BSIZE @
    _EXT4-JWR-MEASURE _EXT4-JPC-IOR ! _EXT4-JPC-BYTES !
    _EXT4-JPC-IOR @ ?DUP IF EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.WRITER + @ 0= IF
        _EXT4-JPC-BYTES @ _EXT4-JPC-CTX @ _EXT4-C.ARENA + @ ARENA-FREE
        U> IF VFS-E-NOMEM EXIT THEN
    THEN
    _EXT4-JPC-META @ _EXT4-JPC-REVOKE @ _EXT4-JPC-BSIZE @
    _EXT4-JTX-LOG-BLOCKS-FOR _EXT4-JPC-IOR ! _EXT4-JPC-LOG !
    _EXT4-JPC-IOR @ ?DUP IF EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.MAXLEN + @
    _EXT4-JPC-CTX @ _EXT4-C.J.FIRST + @ - DUP 0= IF
        DROP VFS-E-INVALID EXIT
    THEN
    1- DUP _EXT4-JPC-FREE ! 0< IF VFS-E-INVALID EXIT THEN
    _EXT4-JPC-LOG @ _EXT4-JPC-FREE @ U> IF VFS-E-NOSPC EXIT THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.MAX-TRANSACTION + @ ?DUP IF
        _EXT4-JPC-LOG @ 1- SWAP U> IF VFS-E-NOSPC EXIT THEN
    THEN
    _EXT4-JPC-CTX @ _EXT4-C.J.MAX-TRANS-DATA + @ ?DUP IF
        _EXT4-JPC-DATA @ SWAP U> IF VFS-E-NOSPC EXIT THEN
    THEN
    0 ;

: _EXT4-JTX-CLEAR-HASHES  ( writer -- )
    DUP _EXT4-JWR.META-SLOTS + @ ?DUP IF
        OVER _EXT4-JWR.META-HASH + @ SWAP CELLS 0 FILL
    THEN
    DUP _EXT4-JWR.DATA-SLOTS + @ ?DUP IF
        OVER _EXT4-JWR.DATA-HASH + @ SWAP CELLS 0 FILL
    THEN
    DUP _EXT4-JWR.REVOKE-SLOTS + @ ?DUP IF
        OVER _EXT4-JWR.REVOKE-HASH + @ SWAP CELLS 0 FILL
    THEN
    DROP ;

VARIABLE _EXT4-JB-META
VARIABLE _EXT4-JB-DATA
VARIABLE _EXT4-JB-REVOKE
VARIABLE _EXT4-JB-WRITER
VARIABLE _EXT4-JB-LOG
VARIABLE _EXT4-JB-IOR

: _EXT4-JTX-BEGIN
  ( meta-credit data-credit revoke-credit writer -- transaction ior )
    _EXT4-JB-WRITER ! _EXT4-JB-REVOKE !
    _EXT4-JB-DATA ! _EXT4-JB-META !
    _EXT4-JB-WRITER @ _EXT4-JWR-VALID? 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        0 VFS-E-BUSY EXIT
    THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.FAULT + @ IF 0 VFS-E-BUSY EXIT THEN
    _EXT4-JB-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
    _EXT4-JB-META @ 0< _EXT4-JB-DATA @ 0< OR
    _EXT4-JB-REVOKE @ 0< OR IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JB-META @ _EXT4-JB-WRITER @ _EXT4-JWR.META-CAP + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-DATA @ _EXT4-JB-WRITER @ _EXT4-JWR.DATA-CAP + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-REVOKE @
    _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-CAP + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-META @ _EXT4-JB-REVOKE @ _EXT4-JB-WRITER @
    _EXT4-JTX-LOG-BLOCKS _EXT4-JB-IOR ! _EXT4-JB-LOG !
    _EXT4-JB-IOR @ IF 0 _EXT4-JB-IOR @ EXIT THEN
    _EXT4-JB-LOG @ _EXT4-JB-WRITER @ _EXT4-JWR.FREE + @ U> IF
        0 VFS-E-NOSPC EXIT
    THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.J.MAX-TRANSACTION + @ ?DUP IF
        \ s_max_transaction bounds JBD2 records; the private guard is not a
        \ record and therefore does not consume that advertised limit.
        _EXT4-JB-LOG @ 1- SWAP U> IF 0 VFS-E-NOSPC EXIT THEN
    THEN
    _EXT4-JB-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-C.J.MAX-TRANS-DATA + @ ?DUP IF
        _EXT4-JB-DATA @ SWAP U> IF 0 VFS-E-NOSPC EXIT THEN
    THEN
    _EXT4-JB-WRITER @ _EXT4-JTX-CLEAR-HASHES
    0 _EXT4-JB-WRITER @ _EXT4-JWR.META-USED + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.DATA-USED + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-USED + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.META-ACTIVE + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.DATA-ACTIVE + !
    0 _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + !
    _EXT4-JB-META @ _EXT4-JB-WRITER @ _EXT4-JWR.META-CREDIT + !
    _EXT4-JB-DATA @ _EXT4-JB-WRITER @ _EXT4-JWR.DATA-CREDIT + !
    _EXT4-JB-REVOKE @ _EXT4-JB-WRITER @ _EXT4-JWR.REVOKE-CREDIT + !
    _EXT4-JB-LOG @ _EXT4-JB-WRITER @ _EXT4-JWR.LOG-RESERVED + !
    _EXT4-JB-LOG @ NEGATE _EXT4-JB-WRITER @ _EXT4-JWR.FREE + +!
    _EXT4-JB-WRITER @ _EXT4-JWR.HEAD + @ DUP
    _EXT4-JB-WRITER @ _EXT4-JWR.TX-START + !
    _EXT4-JB-WRITER @ _EXT4-JWR.TX-CURSOR + !
    _EXT4-JB-WRITER @ _EXT4-JWR.NEXT-TID + @
    _EXT4-JB-WRITER @ _EXT4-JWR.TX-TID + !
    1 _EXT4-JB-WRITER @ _EXT4-JWR.EPOCH + +!
    _EXT4-JWR-STAGING _EXT4-JB-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JB-WRITER @ 0 ;

VARIABLE _EXT4-JHV-HOME
VARIABLE _EXT4-JHV-WRITER

: _EXT4-JTX-HOME?  ( home writer -- flag )
    _EXT4-JHV-WRITER ! _EXT4-JHV-HOME !
    _EXT4-JHV-HOME @
    _EXT4-JHV-WRITER @ _EXT4-JWR.CTX + @ _EXT4-C.BLOCKS + @ U< 0= IF
        FALSE EXIT
    THEN
    _EXT4-JHV-HOME @ _EXT4-JHV-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JOURNAL-DATA? 0= ;

: _EXT4-JWR-META-ENTRY  ( index writer -- entry )
    _EXT4-JWR.META-ENTRIES + @ _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTX-ENTRY ;

: _EXT4-JWR-DATA-ENTRY  ( index writer -- entry )
    _EXT4-JWR.DATA-ENTRIES + @ _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTX-ENTRY ;

: _EXT4-JWR-REVOKE-ENTRY  ( index writer -- entry )
    _EXT4-JWR.REVOKE-ENTRIES + @ _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTX-ENTRY ;

: _EXT4-JWR-META-IMAGE  ( index writer -- image )
    DUP _EXT4-JWR.BSIZE + @ ROT *
    SWAP _EXT4-JWR.META-IMAGES + @ + ;

: _EXT4-JWR-DATA-IMAGE  ( index writer -- image )
    DUP _EXT4-JWR.BSIZE + @ ROT *
    SWAP _EXT4-JWR.DATA-IMAGES + @ + ;

VARIABLE _EXT4-JTV-WRITER
VARIABLE _EXT4-JTV-ENTRIES
VARIABLE _EXT4-JTV-STRIDE
VARIABLE _EXT4-JTV-HASH
VARIABLE _EXT4-JTV-SLOTS
VARIABLE _EXT4-JTV-USED
VARIABLE _EXT4-JTV-ACTIVE
VARIABLE _EXT4-JTV-ALLOW-CANCELLED
VARIABLE _EXT4-JTV-COUNT
VARIABLE _EXT4-JTV-INDEX
VARIABLE _EXT4-JTV-ENTRY
VARIABLE _EXT4-JTV-IOR

: _EXT4-JTX-TABLE-VALID?
  ( entries entry-cells hash slots used active allow-cancelled? writer -- flag )
    _EXT4-JTV-WRITER ! _EXT4-JTV-ALLOW-CANCELLED !
    _EXT4-JTV-ACTIVE ! _EXT4-JTV-USED ! _EXT4-JTV-SLOTS !
    _EXT4-JTV-HASH ! _EXT4-JTV-STRIDE ! _EXT4-JTV-ENTRIES !
    0 _EXT4-JTV-COUNT !
    _EXT4-JTV-USED @ 0 ?DO
        I _EXT4-JTV-INDEX !
        I _EXT4-JTV-STRIDE @ * CELLS _EXT4-JTV-ENTRIES @ +
        DUP _EXT4-JTV-ENTRY !
        DUP @ _EXT4-JTV-WRITER @ _EXT4-JTX-HOME? 0= IF
            DROP FALSE UNLOOP EXIT
        THEN
        CELL+ @ DUP _EXT4-JE-ACTIVE = IF
            DROP 1 _EXT4-JTV-COUNT +!
        ELSE
            _EXT4-JE-CANCELLED <>
            _EXT4-JTV-ALLOW-CANCELLED @ 0= OR IF
                FALSE UNLOOP EXIT
            THEN
        THEN
        _EXT4-JTV-ENTRY @ @
        _EXT4-JTV-ENTRIES @ _EXT4-JTV-STRIDE @
        _EXT4-JTV-HASH @ _EXT4-JTV-SLOTS @ _EXT4-JTV-USED @
        _EXT4-JTX-HASH-FIND _EXT4-JTV-IOR !
        _EXT4-JTV-IOR @ IF 2DROP FALSE UNLOOP EXIT THEN
        0= IF DROP FALSE UNLOOP EXIT THEN
        _EXT4-JTV-INDEX @ <> IF FALSE UNLOOP EXIT THEN
    LOOP
    _EXT4-JTV-COUNT @ _EXT4-JTV-ACTIVE @ = ;

: _EXT4-JTX-TABLES-VALID?  ( writer -- flag )
    _EXT4-JTV-WRITER !
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.META-ACTIVE + @
    -1 _EXT4-JTV-WRITER @
    _EXT4-JTX-TABLE-VALID? 0= IF FALSE EXIT THEN
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.DATA-ACTIVE + @
    0 _EXT4-JTV-WRITER @
    _EXT4-JTX-TABLE-VALID? 0= IF FALSE EXIT THEN
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTV-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    -1 _EXT4-JTV-WRITER @ _EXT4-JTX-TABLE-VALID? ;

: _EXT4-JTX-ACTIVE?  ( writer -- ior )
    DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-JWR.FAULT + @ IF DROP VFS-E-BUSY EXIT THEN
    DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING <> IF
        DROP VFS-E-BUSY EXIT
    THEN
    DUP _EXT4-JTX-TABLES-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    DROP 0 ;

\ Publishing checkpoint authority freezes the complete retained transaction.
\ It remains abortable and emittable, but no generic or typed mutation may
\ change an image after the certificate CRCs and plan identity are sealed.
: _EXT4-JTX-MUTABLE?  ( writer -- ior )
    DUP _EXT4-JTX-ACTIVE? ?DUP IF NIP EXIT THEN
    _EXT4-JWR.CP-MODE + @ _EXT4-JCPM-NONE <> IF VFS-E-BUSY EXIT THEN
    0 ;

VARIABLE _EXT4-JTM-BUFFER
VARIABLE _EXT4-JTM-HOME
VARIABLE _EXT4-JTM-WRITER
VARIABLE _EXT4-JTM-INDEX
VARIABLE _EXT4-JTM-ENTRY
VARIABLE _EXT4-JTM-IMAGE
VARIABLE _EXT4-JTM-NEW
VARIABLE _EXT4-JTM-REVOKE-INDEX
VARIABLE _EXT4-JTM-REVOKE-FOUND

: _EXT4-JTX-META-PUT  ( buffer home transaction -- ior )
    _EXT4-JTM-WRITER ! _EXT4-JTM-HOME ! _EXT4-JTM-BUFFER !
    _EXT4-JTM-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTM-BUFFER @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JTM-HOME @ _EXT4-JTM-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTM-HOME @
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTM-WRITER @ _EXT4-JWR-DATA-ENTRY CELL+ @
        _EXT4-JE-ACTIVE = IF VFS-E-CONFLICT ELSE VFS-E-CORRUPT THEN EXIT
    ELSE DROP THEN
    0 _EXT4-JTM-REVOKE-FOUND !
    _EXT4-JTM-HOME @
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        DUP _EXT4-JTM-REVOKE-INDEX !
        _EXT4-JTM-WRITER @ _EXT4-JWR-REVOKE-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF
            DROP
            _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ 0= IF
                VFS-E-CORRUPT EXIT
            THEN
        ELSE
            _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
        THEN
        -1 _EXT4-JTM-REVOKE-FOUND !
    ELSE DROP THEN
    0 _EXT4-JTM-NEW !
    _EXT4-JTM-HOME @
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTM-INDEX !
    ELSE
        DROP
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + @
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-CREDIT + @ U< 0= IF
            VFS-E-NOSPC EXIT
        THEN
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + @ DUP
        _EXT4-JTM-INDEX ! _EXT4-JTM-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JTM-ENTRY !
        _EXT4-JTM-HOME @ OVER !
        0 OVER CELL+ ! 0 SWAP 2 CELLS + !
        _EXT4-JTM-HOME @ _EXT4-JTM-INDEX @
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-HASH + @
        _EXT4-JTM-WRITER @ _EXT4-JWR.META-SLOTS + @
        _EXT4-JTX-HASH-INSERT ?DUP IF
            0 _EXT4-JTM-ENTRY @ ! EXIT
        THEN
        -1 _EXT4-JTM-NEW !
    THEN
    _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-ENTRY
    DUP _EXT4-JTM-ENTRY !
    _EXT4-JTM-NEW @ 0= IF
        CELL+ @ DUP _EXT4-JE-ACTIVE <
        OVER _EXT4-JE-CANCELLED > OR IF DROP VFS-E-CORRUPT EXIT THEN DROP
    ELSE
        DROP
    THEN
    _EXT4-JTM-INDEX @ _EXT4-JTM-WRITER @ _EXT4-JWR-META-IMAGE
    DUP _EXT4-JTM-IMAGE !
    _EXT4-JTM-BUFFER @ SWAP
    _EXT4-JTM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JTM-IMAGE @ _EXT4-JTM-WRITER @ _EXT4-JTX-IMAGE-CRC
    _EXT4-JTM-ENTRY @ 2 CELLS + !
    _EXT4-JTM-ENTRY @ CELL+ @ _EXT4-JE-ACTIVE <> IF
        1 _EXT4-JTM-WRITER @ _EXT4-JWR.META-ACTIVE + +!
    THEN
    _EXT4-JE-ACTIVE _EXT4-JTM-ENTRY @ CELL+ !
    _EXT4-JTM-NEW @ IF 1 _EXT4-JTM-WRITER @ _EXT4-JWR.META-USED + +! THEN
    _EXT4-JTM-REVOKE-FOUND @ IF
        _EXT4-JTM-REVOKE-INDEX @
        _EXT4-JTM-WRITER @ _EXT4-JWR-REVOKE-ENTRY DUP CELL+ @
        _EXT4-JE-ACTIVE = IF
            _EXT4-JE-CANCELLED SWAP CELL+ !
            -1 _EXT4-JTM-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + +!
        ELSE DROP THEN
    THEN
    0 ;

VARIABLE _EXT4-JMA-SOURCE
VARIABLE _EXT4-JMA-HOME
VARIABLE _EXT4-JMA-WRITER
VARIABLE _EXT4-JMA-INDEX
VARIABLE _EXT4-JMA-ENTRY
VARIABLE _EXT4-JMA-IMAGE
VARIABLE _EXT4-JMA-SCRATCH

\ Acquire a private editing copy of one authenticated metadata block.  A
\ second typed edit of the same home must start from the retained transaction
\ after-image, not from stale media, or the later full-block PUT would silently
\ discard the earlier edit.  The writer-owned image remains immutable while
\ the caller edits SCRATCH-A, so its stored CRC continues to authenticate both
\ transaction preflight and abort until META-REPLACE atomically installs the
\ new complete after-image.
: _EXT4-JTX-META-ACQUIRE
  ( authenticated-source home transaction -- afterimage ior )
    _EXT4-JMA-WRITER ! _EXT4-JMA-HOME ! _EXT4-JMA-SOURCE !
    _EXT4-JMA-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JMA-SOURCE @ 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-JMA-HOME @ _EXT4-JMA-WRITER @ _EXT4-JTX-HOME? 0= IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JMA-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JMA-SCRATCH !
    _EXT4-JMA-HOME @
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JMA-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP 0 _EXT4-JHL-IOR @ EXIT THEN
    IF
        DUP _EXT4-JMA-INDEX !
        _EXT4-JMA-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JMA-ENTRY ! CELL+ @ DUP _EXT4-JE-ACTIVE = IF
            DROP
            _EXT4-JMA-INDEX @ _EXT4-JMA-WRITER @ _EXT4-JWR-META-IMAGE
            DUP _EXT4-JMA-IMAGE !
            _EXT4-JMA-WRITER @ _EXT4-JTX-IMAGE-CRC
            _EXT4-JMA-ENTRY @ 2 CELLS + @ <> IF
                0 VFS-E-CORRUPT EXIT
            THEN
            _EXT4-JMA-IMAGE @
        ELSE
            _EXT4-JE-CANCELLED <> IF 0 VFS-E-CORRUPT EXIT THEN
            _EXT4-JMA-SOURCE @
        THEN
    ELSE
        DROP _EXT4-JMA-SOURCE @
    THEN
    _EXT4-JMA-SCRATCH @
    _EXT4-JMA-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JMA-SCRATCH @ 0 ;

\ Publish one complete scratch after-image through the ordinary conflict,
\ credit, revoke-cancellation, and image-CRC authority of META-PUT.
: _EXT4-JTX-META-REPLACE  ( afterimage home transaction -- ior )
    _EXT4-JTX-META-PUT ;

VARIABLE _EXT4-JTD-BUFFER
VARIABLE _EXT4-JTD-HOME
VARIABLE _EXT4-JTD-WRITER
VARIABLE _EXT4-JTD-INDEX
VARIABLE _EXT4-JTD-ENTRY
VARIABLE _EXT4-JTD-IMAGE
VARIABLE _EXT4-JTD-NEW

: _EXT4-JTX-DATA-PUT  ( buffer home transaction -- ior )
    _EXT4-JTD-WRITER ! _EXT4-JTD-HOME ! _EXT4-JTD-BUFFER !
    _EXT4-JTD-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTD-BUFFER @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JTD-HOME @ _EXT4-JTD-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTD-HOME @
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTD-WRITER @ _EXT4-JWR-META-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF DROP VFS-E-CONFLICT EXIT THEN
        _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
    ELSE DROP THEN
    _EXT4-JTD-HOME @
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTD-WRITER @ _EXT4-JWR-REVOKE-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF DROP VFS-E-CONFLICT EXIT THEN
        _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
    ELSE DROP THEN
    0 _EXT4-JTD-NEW !
    _EXT4-JTD-HOME @
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTD-INDEX !
    ELSE
        DROP
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + @
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-CREDIT + @ U< 0= IF
            VFS-E-NOSPC EXIT
        THEN
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + @ DUP
        _EXT4-JTD-INDEX ! _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JTD-ENTRY !
        _EXT4-JTD-HOME @ OVER !
        0 OVER CELL+ ! 0 SWAP 2 CELLS + !
        _EXT4-JTD-HOME @ _EXT4-JTD-INDEX @
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-HASH + @
        _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-SLOTS + @
        _EXT4-JTX-HASH-INSERT ?DUP IF
            0 _EXT4-JTD-ENTRY @ ! EXIT
        THEN
        -1 _EXT4-JTD-NEW !
    THEN
    _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-ENTRY
    DUP _EXT4-JTD-ENTRY !
    _EXT4-JTD-NEW @ 0= IF
        CELL+ @ _EXT4-JE-ACTIVE <> IF VFS-E-CORRUPT EXIT THEN
    ELSE
        DROP
    THEN
    _EXT4-JTD-INDEX @ _EXT4-JTD-WRITER @ _EXT4-JWR-DATA-IMAGE
    DUP _EXT4-JTD-IMAGE !
    _EXT4-JTD-BUFFER @ SWAP
    _EXT4-JTD-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JTD-IMAGE @ _EXT4-JTD-WRITER @ _EXT4-JTX-IMAGE-CRC
    _EXT4-JTD-ENTRY @ 2 CELLS + !
    _EXT4-JTD-NEW @ IF
        1 _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-USED + +!
        1 _EXT4-JTD-WRITER @ _EXT4-JWR.DATA-ACTIVE + +!
        _EXT4-JE-ACTIVE _EXT4-JTD-ENTRY @ CELL+ !
    THEN
    0 ;

VARIABLE _EXT4-JTR-HOME
VARIABLE _EXT4-JTR-WRITER
VARIABLE _EXT4-JTR-INDEX
VARIABLE _EXT4-JTR-ENTRY
VARIABLE _EXT4-JTR-NEW
VARIABLE _EXT4-JTR-META-INDEX
VARIABLE _EXT4-JTR-META-FOUND

: _EXT4-JTX-REVOKE  ( home transaction -- ior )
    _EXT4-JTR-WRITER ! _EXT4-JTR-HOME !
    _EXT4-JTR-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JTR-HOME @ _EXT4-JTR-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JTR-HOME @
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-HASH + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-SLOTS + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.DATA-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTR-WRITER @ _EXT4-JWR-DATA-ENTRY CELL+ @
        _EXT4-JE-ACTIVE = IF VFS-E-CONFLICT ELSE VFS-E-CORRUPT THEN EXIT
    ELSE DROP THEN
    0 _EXT4-JTR-META-FOUND !
    _EXT4-JTR-HOME @
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-HASH + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-SLOTS + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        DUP _EXT4-JTR-META-INDEX !
        _EXT4-JTR-WRITER @ _EXT4-JWR-META-ENTRY CELL+ @ DUP
        _EXT4-JE-ACTIVE = IF
            DROP
            _EXT4-JTR-WRITER @ _EXT4-JWR.META-ACTIVE + @ 0= IF
                VFS-E-CORRUPT EXIT
            THEN
        ELSE
            _EXT4-JE-CANCELLED <> IF VFS-E-CORRUPT EXIT THEN
        THEN
        -1 _EXT4-JTR-META-FOUND !
    ELSE DROP THEN
    0 _EXT4-JTR-NEW !
    _EXT4-JTR-HOME @
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-ENTRIES + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-HASH + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
    _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + @
    _EXT4-JTX-HASH-FIND _EXT4-JHL-IOR !
    _EXT4-JHL-IOR @ IF 2DROP _EXT4-JHL-IOR @ EXIT THEN
    IF
        _EXT4-JTR-INDEX !
    ELSE
        DROP
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + @
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ U< 0= IF
            VFS-E-NOSPC EXIT
        THEN
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + @ DUP
        _EXT4-JTR-INDEX ! _EXT4-JTR-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        DUP _EXT4-JTR-ENTRY !
        _EXT4-JTR-HOME @ OVER ! 0 SWAP CELL+ !
        _EXT4-JTR-HOME @ _EXT4-JTR-INDEX @
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-HASH + @
        _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-SLOTS + @
        _EXT4-JTX-HASH-INSERT ?DUP IF
            0 _EXT4-JTR-ENTRY @ ! EXIT
        THEN
        -1 _EXT4-JTR-NEW !
    THEN
    _EXT4-JTR-INDEX @ _EXT4-JTR-WRITER @ _EXT4-JWR-REVOKE-ENTRY
    DUP _EXT4-JTR-ENTRY !
    _EXT4-JTR-NEW @ 0= IF
        CELL+ @ DUP _EXT4-JE-ACTIVE <
        OVER _EXT4-JE-CANCELLED > OR IF DROP VFS-E-CORRUPT EXIT THEN DROP
    ELSE
        DROP
    THEN
    _EXT4-JTR-ENTRY @ CELL+ @ _EXT4-JE-ACTIVE <> IF
        1 _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + +!
    THEN
    _EXT4-JE-ACTIVE _EXT4-JTR-ENTRY @ CELL+ !
    _EXT4-JTR-NEW @ IF
        1 _EXT4-JTR-WRITER @ _EXT4-JWR.REVOKE-USED + +!
    THEN
    _EXT4-JTR-META-FOUND @ IF
        _EXT4-JTR-META-INDEX @
        _EXT4-JTR-WRITER @ _EXT4-JWR-META-ENTRY DUP CELL+ @
        _EXT4-JE-ACTIVE = IF
            _EXT4-JE-CANCELLED SWAP CELL+ !
            -1 _EXT4-JTR-WRITER @ _EXT4-JWR.META-ACTIVE + +!
        ELSE DROP THEN
    THEN
    0 ;

: _EXT4-JTX-DATA-ZERO  ( home transaction -- ior )
    DUP _EXT4-JTX-MUTABLE? ?DUP IF NIP NIP EXIT THEN
    DUP _EXT4-JWR.SCRATCH-B + @
    OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JWR.SCRATCH-B + @ ROT ROT _EXT4-JTX-DATA-PUT ;

: _EXT4-JTX-CLEAR-STAGED  ( writer -- )
    DUP _EXT4-JWR-CLEAR-CP-AUTHORITY
    DUP _EXT4-JWR.META-ENTRIES + @
    OVER _EXT4-JWR.META-USED + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.DATA-ENTRIES + @
    OVER _EXT4-JWR.DATA-USED + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.REVOKE-ENTRIES + @
    OVER _EXT4-JWR.REVOKE-USED + @
    _EXT4-JWR-REVOKE-ENTRY-CELLS CELLS * 0 FILL
    DUP _EXT4-JWR.META-IMAGES + @
    OVER _EXT4-JWR.META-USED + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.DATA-IMAGES + @
    OVER _EXT4-JWR.DATA-USED + @ 2 PICK _EXT4-JWR.BSIZE + @ * 0 FILL
    DUP _EXT4-JWR.SCRATCH-A + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JWR.SCRATCH-B + @ OVER _EXT4-JWR.BSIZE + @ 0 FILL
    DUP _EXT4-JTX-CLEAR-HASHES
    0 OVER _EXT4-JWR.META-CREDIT + !
    0 OVER _EXT4-JWR.DATA-CREDIT + !
    0 OVER _EXT4-JWR.REVOKE-CREDIT + !
    0 OVER _EXT4-JWR.META-USED + !
    0 OVER _EXT4-JWR.DATA-USED + !
    0 OVER _EXT4-JWR.REVOKE-USED + !
    0 OVER _EXT4-JWR.META-ACTIVE + !
    0 OVER _EXT4-JWR.DATA-ACTIVE + !
    0 OVER _EXT4-JWR.REVOKE-ACTIVE + !
    0 OVER _EXT4-JWR.LOG-RESERVED + !
    0 OVER _EXT4-JWR.TX-START + !
    0 OVER _EXT4-JWR.TX-CURSOR + !
    0 OVER _EXT4-JWR.TX-TID + !
    0 SWAP _EXT4-JWR.PHASE + ! ;

VARIABLE _EXT4-JAB-WRITER
VARIABLE _EXT4-JAB-FREE
VARIABLE _EXT4-JAB-IOR

: _EXT4-JTX-ABORT  ( transaction -- ior )
    DUP _EXT4-JAB-WRITER ! _EXT4-JTX-ACTIVE? ?DUP IF EXIT THEN
    _EXT4-JAB-WRITER @ _EXT4-JWR.FREE + @
    _EXT4-JAB-WRITER @ _EXT4-JWR.LOG-RESERVED + @
    _EXT4-UADD? _EXT4-JAB-IOR ! _EXT4-JAB-FREE !
    _EXT4-JAB-IOR @ IF _EXT4-JAB-IOR @ EXIT THEN
    _EXT4-JAB-FREE @
    _EXT4-JAB-WRITER @ _EXT4-JWR.MAXLEN + @
    _EXT4-JAB-WRITER @ _EXT4-JWR.FIRST + @ - 1- U> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAB-FREE @ _EXT4-JAB-WRITER @ _EXT4-JWR.FREE + !
    _EXT4-JAB-WRITER @ _EXT4-JTX-CLEAR-STAGED
    _EXT4-JWR-IDLE _EXT4-JAB-WRITER @ _EXT4-JWR.STATE + !
    0 ;

VARIABLE _EXT4-JS-CTX
VARIABLE _EXT4-JS-POS
VARIABLE _EXT4-JS-SEQUENCE
VARIABLE _EXT4-JS-LEFT
VARIABLE _EXT4-JS-PASS
VARIABLE _EXT4-JS-DONE
VARIABLE _EXT4-JS-TYPE
VARIABLE _EXT4-JS-DESC
VARIABLE _EXT4-JS-OFF
VARIABLE _EXT4-JS-LIMIT
VARIABLE _EXT4-JS-TAG
VARIABLE _EXT4-JS-FLAGS
VARIABLE _EXT4-JS-HOME
VARIABLE _EXT4-JS-TAG-CHECKSUM
VARIABLE _EXT4-JS-LAST
VARIABLE _EXT4-JS-COMMIT-CURSOR
VARIABLE _EXT4-JS-CURRENT
VARIABLE _EXT4-JS-FIRST
VARIABLE _EXT4-JS-TX-REVOKES
VARIABLE _EXT4-JS-REVOKE-COUNT
VARIABLE _EXT4-JS-REVOKE-OFF
VARIABLE _EXT4-JS-REVOKE-HIGH
VARIABLE _EXT4-JS-REVOKE-BLOCK

VARIABLE _EXT4-JSB-WRITER
VARIABLE _EXT4-JSB-META-INDEX
VARIABLE _EXT4-JSB-META-BOUND
VARIABLE _EXT4-JSB-REVOKE-INDEX
VARIABLE _EXT4-JSB-REVOKE-BOUND
VARIABLE _EXT4-JSB-PAYLOAD
VARIABLE _EXT4-JSB-HOME
VARIABLE _EXT4-JSB-ENTRY
VARIABLE _EXT4-JSB-IOR

: _EXT4-JSCAN-FULL?  ( pass -- flag )
    DUP _EXT4-JSCAN-PREFLIGHT =
    SWAP _EXT4-JSCAN-BINDING = OR ;

: _EXT4-JSCAN-BIND-BEGIN  ( writer -- )
    _EXT4-JSB-WRITER !
    0 _EXT4-JSB-META-INDEX !
    0 _EXT4-JSB-META-BOUND !
    0 _EXT4-JSB-REVOKE-INDEX !
    0 _EXT4-JSB-REVOKE-BOUND ! ;

\ Compare the logical, unescaped descriptor stream in the same deterministic
\ order used by emission.  Cancelled retained entries never entered the log.
: _EXT4-JSCAN-BIND-METADATA  ( payload home -- ior )
    _EXT4-JSB-HOME ! _EXT4-JSB-PAYLOAD !
    _EXT4-JSB-WRITER @ 0= IF 0 EXIT THEN
    BEGIN
        _EXT4-JSB-META-INDEX @
        _EXT4-JSB-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JSB-META-INDEX @ _EXT4-JSB-WRITER @
        _EXT4-JWR-META-ENTRY DUP _EXT4-JSB-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JSB-ENTRY @ @ _EXT4-JSB-HOME @ <> IF
                VFS-E-CORRUPT EXIT
            THEN
            _EXT4-JSB-PAYLOAD @
            _EXT4-JSB-META-INDEX @ _EXT4-JSB-WRITER @
            _EXT4-JWR-META-IMAGE
            _EXT4-JSB-WRITER @ _EXT4-JWR.BSIZE + @
            _EXT4-BYTES=? 0= IF VFS-E-CORRUPT EXIT THEN
            1 _EXT4-JSB-META-INDEX +!
            1 _EXT4-JSB-META-BOUND +!
            0 EXIT
        THEN
        1 _EXT4-JSB-META-INDEX +!
    REPEAT
    VFS-E-CORRUPT ;

\ Revoke records are emitted in retained insertion order as well.  Equality
\ with the next admissible retained home rejects duplicates, omissions, and
\ any reordered or substituted revoke identity without allocating a seen set.
: _EXT4-JSCAN-BIND-REVOKE  ( home -- ior )
    _EXT4-JSB-HOME !
    _EXT4-JSB-WRITER @ 0= IF 0 EXIT THEN
    _EXT4-JSB-HOME @ _EXT4-JSB-WRITER @ _EXT4-JTX-HOME? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    BEGIN
        _EXT4-JSB-REVOKE-INDEX @
        _EXT4-JSB-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JSB-REVOKE-INDEX @ _EXT4-JSB-WRITER @
        _EXT4-JWR-REVOKE-ENTRY DUP _EXT4-JSB-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JSB-ENTRY @ @ _EXT4-JSB-HOME @ <> IF
                VFS-E-CORRUPT EXIT
            THEN
            1 _EXT4-JSB-REVOKE-INDEX +!
            1 _EXT4-JSB-REVOKE-BOUND +!
            0 EXIT
        THEN
        1 _EXT4-JSB-REVOKE-INDEX +!
    REPEAT
    VFS-E-CORRUPT ;

\ Always withdraw the transient binding publication, including after a scan
\ error.  On success every active retained identity must have appeared once.
: _EXT4-JSCAN-BIND-FINISH  ( scan-ior -- ior )
    _EXT4-JSB-IOR !
    _EXT4-JSB-IOR @ 0= _EXT4-JSB-WRITER @ 0<> AND IF
        _EXT4-JSB-META-BOUND @
        _EXT4-JSB-WRITER @ _EXT4-JWR.META-ACTIVE + @ <>
        _EXT4-JSB-REVOKE-BOUND @
        _EXT4-JSB-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> OR IF
            VFS-E-CORRUPT _EXT4-JSB-IOR !
        THEN
    THEN
    0 _EXT4-JSB-WRITER !
    _EXT4-JSB-IOR @ ;

: _EXT4-JSCAN-READ-NEXT  ( -- ior )
    _EXT4-JS-LEFT @ 0= IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    _EXT4-JS-POS @ DUP _EXT4-JS-CURRENT !
    _EXT4-JS-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JS-POS @ _EXT4-JS-CTX @ _EXT4-JOURNAL-NEXT _EXT4-JS-POS !
    -1 _EXT4-JS-LEFT +!
    0 ;

: _EXT4-JBD2-TAG-CHECKSUM?  ( buffer stored -- flag )
    _EXT4-JC-STORED ! _EXT4-JC-BUF !
    _EXT4-JS-SEQUENCE @
    _EXT4-JS-CTX @ _EXT4-C.TMP + _EXT4-BE32!
    _EXT4-JS-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JS-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD
    _EXT4-JC-BUF @ _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    _EXT4-CRC@ _EXT4-JC-STORED @ = ;

VARIABLE _EXT4-JIP-BUF
VARIABLE _EXT4-JIP-HOME
VARIABLE _EXT4-JIP-CTX
VARIABLE _EXT4-RPC-SB
VARIABLE _EXT4-RPC-CTX
VARIABLE _EXT4-RGD-DESC
VARIABLE _EXT4-RGD-CTX
VARIABLE _EXT4-RGD-STORED
VARIABLE _EXT4-RGD-CALC
VARIABLE _EXT4-RAP-BUF
VARIABLE _EXT4-RAP-HOME
VARIABLE _EXT4-RAP-CTX

: _EXT4-PRIMARY-SUPER-CANDIDATE?  ( sb ctx -- flag )
    _EXT4-RPC-CTX ! _EXT4-RPC-SB !
    _EXT4-RPC-SB @ _EXT4-SUPER-CHECKSUM? 0= IF FALSE EXIT THEN
    _EXT4-RPC-SB @ _EXT4-SUPER-SEED? 0= IF FALSE EXIT THEN
    _EXT4-RPC-SB @ _EXT4-SB.INCOMPAT + L@
    _EXT4-INCOMPAT-RECOVER AND 0= IF FALSE EXIT THEN
    _EXT4-RPC-SB @ -1 _EXT4-VALIDATE-SUPER-RETRY-EARLY IF
        FALSE EXIT
    THEN
    _EXT4-RPC-SB @ _EXT4-VALIDATE-SUPER-RETRY-LATE IF
        FALSE EXIT
    THEN
    _EXT4-RPC-SB @ _EXT4-RPC-CTX @
    _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS IF FALSE EXIT THEN
    _EXT4-RPC-SB @ 0
    _EXT4-RPC-CTX @ _EXT4-C.J.WITNESS-SUPER +
    _EXT4-SUPER-INVARIANTS? ;

: _EXT4-PRIMARY-GDT-CANDIDATE?  ( block ctx -- flag )
    _EXT4-RGD-CTX ! DUP _EXT4-RGD-DESC !
    DUP _EXT4-GD.BLOCK-BITMAP-HI + L@
    OVER _EXT4-GD.INODE-BITMAP-HI + L@ OR
    OVER _EXT4-GD.INODE-TABLE-HI + L@ OR IF DROP FALSE EXIT THEN
    DUP _EXT4-GD.BLOCK-BITMAP-LO + L@
        _EXT4-RGD-CTX @ _EXT4-C.J.BLOCK-BITMAP-BLOCK + @ <>
    OVER _EXT4-GD.INODE-BITMAP-LO + L@
        _EXT4-RGD-CTX @ _EXT4-C.J.INODE-BITMAP-BLOCK + @ <> OR
    OVER _EXT4-GD.INODE-TABLE-LO + L@
        _EXT4-RGD-CTX @ _EXT4-C.J.INODE-TABLE-BASE + @ <> OR IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-GD.CHECKSUM + W@ _EXT4-RGD-STORED !
    0 OVER _EXT4-GD.CHECKSUM + W!
    0 _EXT4-RGD-CTX @ _EXT4-C.TMP + L!
    _EXT4-RGD-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-RGD-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD
    _EXT4-DESC-SIZE _EXT4-CRC-ADD
    _EXT4-CRC@ 0xFFFF AND _EXT4-RGD-CALC !
    _EXT4-RGD-STORED @ _EXT4-RGD-DESC @ _EXT4-GD.CHECKSUM + W!
    _EXT4-RGD-CALC @ _EXT4-RGD-STORED @ = ;

: _EXT4-JOURNAL-INODE-PRESERVED?  ( payload home ctx -- flag )
    _EXT4-JIP-CTX ! _EXT4-JIP-HOME ! _EXT4-JIP-BUF !
    _EXT4-JIP-HOME @
    _EXT4-JIP-CTX @ _EXT4-C.J.INODE-TABLE-BLOCK + @ <> IF TRUE EXIT THEN
    _EXT4-JIP-BUF @
    _EXT4-JIP-CTX @ _EXT4-C.J.INODE-TABLE-OFF + @ +
    _EXT4-JIP-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JIP-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? ;

\ A valid JBD2 checksum authenticates bytes but does not authorize changing
\ the bootstrap chain.  Hard-frozen sparse copies are never home targets;
\ mutable primary metadata may change only while retaining the exact fields,
\ allocation bit, or inode slice needed by the next retry.
: _EXT4-RECOVERY-AUTHORITY-PRESERVED?  ( payload home ctx -- flag )
    _EXT4-RAP-CTX ! _EXT4-RAP-HOME ! _EXT4-RAP-BUF !
    _EXT4-RAP-HOME @ _EXT4-RAP-CTX @
    _EXT4-RECOVERY-FROZEN-BLOCK? IF FALSE EXIT THEN
    _EXT4-RAP-BUF @ _EXT4-RAP-HOME @ _EXT4-RAP-CTX @
    _EXT4-JOURNAL-INODE-PRESERVED? 0= IF FALSE EXIT THEN
    _EXT4-RAP-HOME @
    _EXT4-RAP-CTX @ _EXT4-C.J.INODE-BITMAP-BLOCK + @ = IF
        _EXT4-RAP-BUF @ _EXT4-JOURNAL-INODE 1- 8 / + C@
        1 _EXT4-JOURNAL-INODE 1- 8 MOD LSHIFT AND 0= IF FALSE EXIT THEN
    THEN
    _EXT4-RAP-HOME @ _EXT4-RAP-CTX @ _EXT4-PRIMARY-SUPER-BLOCK = IF
        _EXT4-RAP-BUF @ _EXT4-RAP-CTX @ _EXT4-PRIMARY-SUPER-OFF +
        _EXT4-RAP-CTX @ _EXT4-PRIMARY-SUPER-CANDIDATE? 0= IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-RAP-HOME @ _EXT4-RAP-CTX @ _EXT4-GDT-BASE = IF
        _EXT4-RAP-BUF @ _EXT4-RAP-CTX @
        _EXT4-PRIMARY-GDT-CANDIDATE? 0= IF FALSE EXIT THEN
    THEN
    TRUE ;

\ A checksum-v3/64-bit revoke block carries a byte count followed by exact
\ big-endian 64-bit home-block numbers and a checksum tail.  Preflight counts
\ records provisionally until the transaction commit is authenticated; the
\ revoke pass records the latest committed sequence for each block.
: _EXT4-JSCAN-REVOKE  ( -- ior )
    _EXT4-JS-CTX @ _EXT4-C.J.FEATURES + @
    _EXT4-JBD2-I-REVOKE AND 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JS-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-JS-CTX @ _EXT4-JBD2-BLOCK-CHECKSUM? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    12 + _EXT4-BE32@ DUP _EXT4-JS-REVOKE-COUNT !
    DUP 16 U< IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ _EXT4-JBD2-TAIL-SIZE -
    U> IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    16 - DUP 8 MOD IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    8 / _EXT4-JS-REVOKE-COUNT !
    _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? IF
        _EXT4-JS-TX-REVOKES @ _EXT4-JS-REVOKE-COUNT @ + DUP
        _EXT4-JS-TX-REVOKES @ U< IF
            DROP EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JS-TX-REVOKES !
        _EXT4-JSB-WRITER @ 0= IF 0 EXIT THEN
        16 _EXT4-JS-REVOKE-OFF !
        _EXT4-JS-REVOKE-COUNT @ 0 ?DO
            _EXT4-JS-CTX @ _EXT4-C.BLOCK +
            _EXT4-JS-REVOKE-OFF @ + DUP
            _EXT4-BE32@ _EXT4-JS-REVOKE-HIGH !
            4 + _EXT4-BE32@ _EXT4-JS-REVOKE-BLOCK !
            _EXT4-JS-REVOKE-HIGH @ IF
                EXT4-D-JOURNAL _EXT4-UNSUPPORTED UNLOOP EXIT
            THEN
            _EXT4-JS-REVOKE-BLOCK @ _EXT4-JSCAN-BIND-REVOKE
            ?DUP IF UNLOOP EXIT THEN
            8 _EXT4-JS-REVOKE-OFF +!
        LOOP
        0 EXIT
    THEN
    _EXT4-JS-PASS @ _EXT4-JSCAN-REVOKES <> IF 0 EXIT THEN
    16 _EXT4-JS-REVOKE-OFF !
    _EXT4-JS-REVOKE-COUNT @ 0 ?DO
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-REVOKE-OFF @ + DUP
        _EXT4-BE32@ _EXT4-JS-REVOKE-HIGH !
        4 + _EXT4-BE32@ _EXT4-JS-REVOKE-BLOCK !
        _EXT4-JS-REVOKE-HIGH @ IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED UNLOOP EXIT
        THEN
        _EXT4-JS-REVOKE-BLOCK @ _EXT4-JS-CTX @
        _EXT4-JOURNAL-DATA? IF
            EXT4-D-JOURNAL _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-JS-REVOKE-BLOCK @ _EXT4-JS-SEQUENCE @ _EXT4-JS-CTX @
        _EXT4-REVOKE-PUT ?DUP IF UNLOOP EXIT THEN
        8 _EXT4-JS-REVOKE-OFF +!
    LOOP
    0 ;

: _EXT4-JSCAN-DESCRIPTOR  ( -- ior )
    _EXT4-JS-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-JS-CTX @ _EXT4-C.DIR-BLOCK + DUP _EXT4-JS-DESC !
    _EXT4-JS-CTX @ _EXT4-JBD2-BLOCK-CHECKSUM? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JS-CTX @ _EXT4-C.BSIZE + @ _EXT4-JBD2-TAIL-SIZE -
    _EXT4-JS-LIMIT !
    12 _EXT4-JS-OFF ! 0 _EXT4-JS-LAST !
    BEGIN _EXT4-JS-LAST @ 0= WHILE
        _EXT4-JS-OFF @ _EXT4-JBD2-TAG3-SIZE +
        _EXT4-JS-LIMIT @ U> IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
        _EXT4-JS-DESC @ _EXT4-JS-OFF @ + DUP _EXT4-JS-TAG !
        _EXT4-BE32@ DUP _EXT4-JS-HOME !
        _EXT4-JS-CTX @ _EXT4-C.BLOCKS + @ >= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-HOME @ _EXT4-JS-CTX @ _EXT4-JOURNAL-DATA? IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-TAG @ 4 + _EXT4-BE32@ DUP _EXT4-JS-FLAGS !
        _EXT4-JBD2-F-ALL INVERT AND IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-TAG @ 8 + _EXT4-BE32@ IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JS-TAG @ 12 + _EXT4-BE32@ _EXT4-JS-TAG-CHECKSUM !
        _EXT4-JS-OFF @ _EXT4-JBD2-TAG3-SIZE + _EXT4-JS-OFF !
        _EXT4-JS-FLAGS @ _EXT4-JBD2-F-SAME-UUID AND 0= IF
            _EXT4-JS-OFF @ 16 + _EXT4-JS-LIMIT @ U> IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            \ The tag UUID is an opaque per-client identity field, not the
            \ journal superblock UUID.  Recovery uses its flag for tag
            \ layout; the descriptor checksum authenticates its bytes.
            16 _EXT4-JS-OFF +!
        THEN
        _EXT4-JSCAN-READ-NEXT ?DUP IF EXIT THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-TAG-CHECKSUM @
        _EXT4-JBD2-TAG-CHECKSUM? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        \ Tag checksums cover the escaped on-disk form.  Reconstruct the
        \ logical home image before comparing or writing it.
        _EXT4-JS-FLAGS @ _EXT4-JBD2-F-ESCAPE AND IF
            _EXT4-JBD2-MAGIC
            _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-BE32!
        THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-HOME @ _EXT4-JS-CTX @
        _EXT4-RECOVERY-AUTHORITY-PRESERVED? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-HOME @
        _EXT4-JSCAN-BIND-METADATA ?DUP IF EXIT THEN
        \ A checksum-torn primary super is admitted provisionally so this
        \ authenticated payload can be inspected.  Do not grant replay
        \ authority until the enclosing transaction's commit is verified.
        _EXT4-JS-PASS @ _EXT4-JSCAN-PREFLIGHT =
        _EXT4-JS-HOME @ _EXT4-JS-CTX @ _EXT4-PRIMARY-SUPER-BLOCK = AND IF
            _EXT4-JS-SEQUENCE @ 1+
            _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
        THEN
        _EXT4-JS-PASS @ _EXT4-JSCAN-REPLAY = IF
            _EXT4-JS-HOME @ _EXT4-JS-SEQUENCE @ _EXT4-JS-CTX @
            _EXT4-JOURNAL-REVOKED? IF
                1 _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-HITS + +!
            ELSE
                _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-HOME @
                _EXT4-JS-CTX @ _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
                1 _EXT4-JS-CTX @ _EXT4-C.J.HOME-WRITES + +!
            THEN
        THEN
        _EXT4-JS-FLAGS @ _EXT4-JBD2-F-LAST AND IF
            -1 _EXT4-JS-LAST !
        THEN
    REPEAT
    0 ;

: _EXT4-JSCAN-FINISH  ( -- ior )
    \ A descriptor without its authenticated commit is only an incomplete
    \ tail.  Never let its provisional repair claim survive this scan.
    0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
    _EXT4-JS-SEQUENCE @ 1+ 0xFFFFFFFF AND
    _EXT4-JS-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-JS-COMMIT-CURSOR @ _EXT4-JS-CTX @ _EXT4-C.J.CURSOR + !
    0 ;

: _EXT4-JSCAN  ( pass ctx -- ior )
    _EXT4-JS-CTX ! _EXT4-JS-PASS !
    _EXT4-JS-PASS @ _EXT4-JSCAN-REPLAY = IF
        _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-READY + @ 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JS-CTX @ _EXT4-REVOKE-GEOMETRY? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JS-CTX @ _EXT4-C.J.START + @ _EXT4-JS-POS !
    _EXT4-JS-CTX @ _EXT4-C.J.SEQUENCE + @ _EXT4-JS-SEQUENCE !
    _EXT4-JS-CTX @ _EXT4-C.J.MAXLEN + @
    _EXT4-JS-CTX @ _EXT4-C.J.FIRST + @ - _EXT4-JS-LEFT !
    0 _EXT4-JS-DONE !
    0 _EXT4-JS-TX-REVOKES !
    _EXT4-JS-POS @ _EXT4-JS-COMMIT-CURSOR !
    0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
    _EXT4-JS-PASS @ _EXT4-JSCAN-PREFLIGHT = IF
        0 _EXT4-JS-CTX @ _EXT4-C.J.COMMITTED + !
        0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + !
        0 _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + !
        0 _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-HITS + !
    THEN
    BEGIN
        _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? 0= IF
            _EXT4-JS-DONE @
            _EXT4-JS-CTX @ _EXT4-C.J.COMMITTED + @ >= IF 0 EXIT THEN
        THEN
        _EXT4-JS-LEFT @ 0= IF
            _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JS-DONE @ IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
            _EXT4-JSCAN-FINISH EXIT
        THEN
        _EXT4-JSCAN-READ-NEXT ?DUP IF EXIT THEN
        _EXT4-JS-CTX @ _EXT4-C.BLOCK + DUP
        _EXT4-BE32@ _EXT4-JBD2-MAGIC <>
        OVER 8 + _EXT4-BE32@ _EXT4-JS-SEQUENCE @ <> OR IF
            DROP
            _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JSCAN-FINISH EXIT
        THEN
        4 + _EXT4-BE32@ _EXT4-JS-TYPE !
        _EXT4-JS-TYPE @ _EXT4-JBD2-DESCRIPTOR = IF
            _EXT4-JSCAN-DESCRIPTOR ?DUP IF EXIT THEN
        ELSE _EXT4-JS-TYPE @ _EXT4-JBD2-COMMIT = IF
            _EXT4-JS-CTX @ _EXT4-C.BLOCK + _EXT4-JS-CTX @
            _EXT4-JBD2-COMMIT-CHECKSUM? 0= IF
                EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
            THEN
            1 _EXT4-JS-DONE +!
            _EXT4-JS-PASS @ _EXT4-JSCAN-PREFLIGHT = IF
                _EXT4-JS-DONE @
                _EXT4-JS-CTX @ _EXT4-C.J.COMMITTED + !
                _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + @
                _EXT4-JS-TX-REVOKES @ + DUP
                _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + @ U< IF
                    DROP EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
                THEN
                _EXT4-JS-CTX @ _EXT4-C.J.REVOKE-COUNT + !
                _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + @ IF
                    _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + @
                    _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + !
                THEN
                0 _EXT4-JS-CTX @ _EXT4-C.J.SUPER-REPAIR-PENDING + !
                0 _EXT4-JS-TX-REVOKES !
            THEN
            _EXT4-JS-SEQUENCE @ 1+ 0xFFFFFFFF AND _EXT4-JS-SEQUENCE !
            _EXT4-JS-POS @ _EXT4-JS-COMMIT-CURSOR !
        ELSE _EXT4-JS-TYPE @ _EXT4-JBD2-REVOKE = IF
            _EXT4-JSCAN-REVOKE ?DUP IF EXIT THEN
        ELSE
            _EXT4-JS-TYPE @ _EXT4-JBD2-SUPER-V2 =
            _EXT4-JS-PASS @ _EXT4-JSCAN-FULL? AND IF
                _EXT4-JS-CTX @ _EXT4-C.J.FIRST + @ _EXT4-JS-FIRST !
                _EXT4-JS-CURRENT @ _EXT4-JS-CTX @
                _EXT4-JBD2-ANCHOR-BLOCK? IF
                    _EXT4-JS-CTX @ _EXT4-C.J.FIRST + @
                    _EXT4-JS-FIRST @ =
                    _EXT4-JA-FEATURES @
                    _EXT4-JS-CTX @ _EXT4-C.J.FEATURES + @ = AND
                    _EXT4-JS-CTX @ _EXT4-C.BLOCK +
                    _EXT4-JS.SEQUENCE + _EXT4-BE32@
                    _EXT4-JS-SEQUENCE @ 1+ 0xFFFFFFFF AND = AND IF
                        _EXT4-JSCAN-FINISH EXIT
                    THEN
                THEN
            THEN
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN THEN THEN
    AGAIN ;

VARIABLE _EXT4-RM-CTX

: _EXT4-RECOVERY-MEDIA  ( ctx -- ior )
    _EXT4-RM-CTX !
    _EXT4-RM-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
    _EXT4-RO-READONLY AND IF EXT4-D-RECOVERY _EXT4-READONLY EXIT THEN
    _EXT4-IO-VOL @ VOL.FLAGS VOL-F-READONLY AND IF
        VOL-E-READONLY VFS-IOR-F-READONLY
        VFS-IOR-D-VOLUME VFS-R-READONLY VFS-IOR-MAKE EXIT
    THEN
    _EXT4-IO-VOL @ VOL.BD BD.CAPS 0x06 AND 0x06 <> IF
        0 0 VFS-IOR-D-VOLUME VFS-R-UNSUPPORTED VFS-IOR-MAKE EXIT
    THEN
    0 ;

VARIABLE _EXT4-RJ-CTX
VARIABLE _EXT4-RJ-V
VARIABLE _EXT4-RJ-PHYS
VARIABLE _EXT4-RJ-ANCHOR
VARIABLE _EXT4-RJ-OLD-SEQUENCE
VARIABLE _EXT4-RJ-OLD-HEAD
VARIABLE _EXT4-RJ-OLD-CRC
VARIABLE _EXT4-RJ-EMPTY-PREDECESSOR
VARIABLE _EXT4-RJ-PREDECESSOR-MAGIC
VARIABLE _EXT4-RJ-PREDECESSOR-VALUE

: _EXT4-PREPARE-CLEAR  ( ctx -- )
    DUP _EXT4-RJ-CTX !
    _EXT4-C.SB + _EXT4-PREPARE-RECOVERED-SUPER ;

: _EXT4-STAMP-JOURNAL-RESET  ( ctx -- )
    _EXT4-RJ-CTX !
    0 _EXT4-RJ-EMPTY-PREDECESSOR !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.SEQUENCE + _EXT4-BE32@ _EXT4-RJ-OLD-SEQUENCE !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.HEAD + _EXT4-BE32@ _EXT4-RJ-OLD-HEAD !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-CTX @
    _EXT4-JOURNAL-IMAGE-CRC _EXT4-RJ-OLD-CRC !
    _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @ _EXT4-JC-ACTIVE = IF
        _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RJ-ANCHOR !
    ELSE
        _EXT4-RJ-CTX @ _EXT4-C.J.CURSOR + @ _EXT4-RJ-ANCHOR !
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.START + _EXT4-BE32@ 0= IF
            _EXT4-RJ-OLD-SEQUENCE @ 1+ 0xFFFFFFFF AND
            _EXT4-RJ-CTX @ _EXT4-C.J.NEXT-SEQUENCE + @ = IF
                _EXT4-RJ-OLD-HEAD @ DUP 0= IF
                    DROP _EXT4-RJ-CTX @ _EXT4-C.J.FIRST + @
                ELSE
                    DUP _EXT4-RJ-CTX @ _EXT4-C.J.FIRST + @ U<
                    OVER _EXT4-RJ-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
                        DROP 0
                    THEN
                THEN
                _EXT4-RJ-ANCHOR @ = IF
                    -1 _EXT4-RJ-EMPTY-PREDECESSOR !
                THEN
            THEN
        THEN
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.NEXT-SEQUENCE + @
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.SEQUENCE + _EXT4-BE32!
    0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.START + _EXT4-BE32!
    _EXT4-RJ-ANCHOR @
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-JBD2-RECOVERY-MAGIC
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.RECOVERY-MAGIC + _EXT4-BE32!
    \ AKR1 authenticates the clean super image deterministically derived from
    \ the durable current super.  This is unchanged after PREPARE-CLEAR and
    \ also lets a live checkpoint retire AKG1 while deliberately retaining
    \ the standard RECOVER-set endpoint for the next transaction.
    _EXT4-RJ-CTX @ _EXT4-C.SB +
    _EXT4-INTENDED-RECOVERED-SUPER-CHECKSUM DUP
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-CHECKSUM + _EXT4-BE32!
    INVERT 0xFFFFFFFF AND
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-CHECKSUM-XOR + _EXT4-BE32!
    _EXT4-RJ-ANCHOR @ DUP
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-ANCHOR + _EXT4-BE32!
    INVERT 0xFFFFFFFF AND
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JS.RECOVERY-ANCHOR-XOR + _EXT4-BE32!
    0 _EXT4-RJ-PREDECESSOR-MAGIC !
    _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @ _EXT4-JC-ACTIVE = IF
        _EXT4-JBD2-ACTIVE-RESET-MAGIC _EXT4-RJ-PREDECESSOR-MAGIC !
        _EXT4-RJ-OLD-SEQUENCE @ _EXT4-RJ-PREDECESSOR-VALUE !
    ELSE
        _EXT4-RJ-EMPTY-PREDECESSOR @ IF
            _EXT4-JBD2-EMPTY-RESET-MAGIC _EXT4-RJ-PREDECESSOR-MAGIC !
            _EXT4-RJ-OLD-HEAD @ _EXT4-RJ-PREDECESSOR-VALUE !
        THEN
    THEN
    _EXT4-RJ-PREDECESSOR-MAGIC @ ?DUP IF
        DUP _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
        INVERT 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
        _EXT4-RJ-PREDECESSOR-VALUE @ DUP
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
        INVERT 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
        _EXT4-RJ-OLD-CRC @ DUP
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + _EXT4-BE32!
        INVERT 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    ELSE
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + _EXT4-BE32!
        0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
        _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    THEN
    0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.CHECKSUM + _EXT4-BE32!
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + 1024 _EXT4-CRC-ADD
    _EXT4-CRC@
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-JS.CHECKSUM + _EXT4-BE32! ;

VARIABLE _EXT4-AJS-BUF
VARIABLE _EXT4-AJS-GUARD
VARIABLE _EXT4-AJS-CTX
VARIABLE _EXT4-AJS-OLD
VARIABLE _EXT4-AJS-NEW

: _EXT4-STAMP-JOURNAL-ACTIVATION  ( buffer guard ctx -- )
    _EXT4-AJS-CTX ! _EXT4-AJS-GUARD ! _EXT4-AJS-BUF !
    _EXT4-AJS-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-INCOMPAT + _EXT4-BE32!
    _EXT4-AJS-BUF @ _EXT4-JS.HEAD + _EXT4-BE32@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-HEAD + _EXT4-BE32!
    _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-CSUM-TYPE + L!
    _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32@
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-OLD-CHECKSUM + _EXT4-BE32!
    0 _EXT4-AJS-BUF @ _EXT4-JS.START + _EXT4-BE32!
    _EXT4-AJS-GUARD @ _EXT4-AJS-BUF @ _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-JBD2-I-RECOVERY-REVOKE
    _EXT4-AJS-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32!
    4 _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM-TYPE + L!
    0 _EXT4-AJS-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32!
    _EXT4-AJS-CTX @ _EXT4-C.SB + _EXT4-INTENDED-SUPER-CHECKSUM
    DUP _EXT4-AJS-OLD !
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-CHECKSUM + _EXT4-BE32!
    _EXT4-AJS-OLD @ INVERT 0xFFFFFFFF AND
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-CHECKSUM-XOR + _EXT4-BE32!
    _EXT4-AJS-GUARD @
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-ANCHOR + _EXT4-BE32!
    _EXT4-AJS-GUARD @ INVERT 0xFFFFFFFF AND
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-ANCHOR-XOR + _EXT4-BE32!
    _EXT4-AJS-CTX @ _EXT4-C.SB +
    _EXT4-INTENDED-DIRTY-SUPER-CHECKSUM DUP _EXT4-AJS-NEW !
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32!
    _EXT4-AJS-NEW @ INVERT 0xFFFFFFFF AND
    _EXT4-AJS-BUF @ _EXT4-JS.ACTIVATION-CHECKSUM-XOR + _EXT4-BE32!
    _EXT4-JBD2-ACTIVATION-MAGIC
    _EXT4-AJS-BUF @ _EXT4-JS.RECOVERY-MAGIC + _EXT4-BE32!
    0 _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32!
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-AJS-BUF @ 1024 _EXT4-CRC-ADD
    _EXT4-CRC@
    _EXT4-AJS-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32! ;

: _EXT4-RESET-JOURNAL  ( ctx -- ior )
    _EXT4-RJ-CTX !
    _EXT4-RJ-CTX @ _EXT4-C.J.PRIMARY-TORN + @ IF
        _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @
        _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
        0 _EXT4-RJ-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-RJ-PHYS !
        _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-PHYS @ _EXT4-RJ-CTX @
        _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        0 _EXT4-RJ-CTX @ _EXT4-C.J.PRIMARY-TORN + !
        _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-ACTIVE <> IF 0 EXIT THEN
    THEN
    0 _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.CLEANUP + @ _EXT4-JC-ACTIVE = IF
        _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RJ-CTX @
        _EXT4-JBD2-ACTIVE-GUARD? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-RJ-CTX @ _EXT4-STAMP-JOURNAL-RESET
    \ Preseed the whole anchor block with the intended image but invalid byte
    \ zero.  After that flush, the valid write changes only byte zero, so any
    \ applied prefix is either still invalid or already the exact anchor.
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ CMOVE
    0 _EXT4-RJ-CTX @ _EXT4-C.BLOCK + C!
    _EXT4-RJ-ANCHOR @
    _EXT4-RJ-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-RJ-PHYS !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-PHYS @ _EXT4-RJ-CTX @
    _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-PHYS @ _EXT4-RJ-CTX @
    _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    0 _EXT4-RJ-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-RJ-PHYS !
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-PHYS @ _EXT4-RJ-CTX @
    _EXT4-WRITE-BLOCK ;

: _EXT4-WRITE-CLEARED-SUPER  ( ctx -- ior )
    _EXT4-RJ-CTX !
    _EXT4-RJ-CTX @ _EXT4-C.SB + 2 2 _EXT4-WRITE-SECTORS ;

\ Return journal block zero to a stock JBD2 superblock only after the witness's
\ authenticated ext4 endpoint is durable, and before retiring its anchor.
: _EXT4-CLEAR-JOURNAL-WITNESS  ( ctx -- ior )
    _EXT4-RJ-CTX !
    0 _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-JBD2-SUPER-CHECKSUM? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK + _EXT4-RJ-CTX @
    _EXT4-JBD2-WITNESS? 0= IF EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @ 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-JOURNAL-WITNESS-SUPER? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    \ Freeze the raw primary before the anchor reread.  With the authenticated
    \ ext4 endpoint already durable, witness authority may be withdrawn only if
    \ the named anchor is still exact and the complete primary block equals
    \ it; a checksum-valid 1024-byte prefix is insufficient on larger media.
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @
    _EXT4-RJ-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RJ-CTX @
    _EXT4-JBD2-ANCHOR-BLOCK? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-RJ-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-C.DIR-BLOCK + DUP
    _EXT4-ZERO-JOURNAL-WITNESS
    0 _EXT4-RJ-CTX @ _EXT4-WRITE-JBLOCK ;

VARIABLE _EXT4-JDW-CTX

\ A live checkpoint or mount-time retained-orphan resume may retire AKG1
\ without first clearing ext4 RECOVER.  The on-media reset predecessor tuple,
\ not a same-session cleanup enum, proves that the witness came from an active
\ journal.  This matters after remount, where validation reconstructs the
\ witness but deliberately does not retain the emitter's in-memory enum.
: _EXT4-CLEAR-JOURNAL-WITNESS-DIRTY  ( ctx -- ior )
    DUP _EXT4-JDW-CTX ! _EXT4-C.RECOVERY + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.SUPER-TORN + @ IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM? 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JDW-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JDW-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-JBD2-SUPER-CHECKSUM? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JDW-CTX @ _EXT4-JBD2-WITNESS? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-RECOVERY <> IF DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-JBD2-RESET-PREDECESSOR? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@
    _EXT4-JBD2-ACTIVE-RESET-MAGIC <> IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JS.START + _EXT4-BE32@ IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-JS.HEAD + _EXT4-BE32@
    _EXT4-JDW-CTX @ _EXT4-C.J.ANCHOR + @ <> IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-JOURNAL-WITNESS-SUPER? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDW-CTX @ _EXT4-C.BSIZE + @ CMOVE
    _EXT4-JDW-CTX @ _EXT4-C.J.ANCHOR + @
    _EXT4-JDW-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JDW-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-JDW-CTX @
    _EXT4-JBD2-ANCHOR-BLOCK? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.BLOCK +
    _EXT4-JDW-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDW-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDW-CTX @ _EXT4-C.DIR-BLOCK + DUP
    _EXT4-ZERO-JOURNAL-WITNESS
    0 _EXT4-JDW-CTX @ _EXT4-WRITE-JBLOCK ;

VARIABLE _EXT4-RA-CTX
VARIABLE _EXT4-RA-LOGICAL

\ Zeroing byte zero first makes every applied prefix cease to be a valid JBD2
\ superblock.  Once the standard primary is durable this slot has no authority.
: _EXT4-RETIRE-JOURNAL-ANCHOR  ( ctx -- ior )
    _EXT4-RA-CTX !
    _EXT4-RA-CTX @ _EXT4-C.J.WITNESS + @ IF
        _EXT4-RA-CTX @ _EXT4-C.J.ANCHOR + @
    ELSE
        _EXT4-RA-CTX @ _EXT4-C.J.CURSOR + @
    THEN DUP _EXT4-RA-LOGICAL !
    _EXT4-RA-CTX @ _EXT4-C.J.FIRST + @ U<
    _EXT4-RA-LOGICAL @ _EXT4-RA-CTX @ _EXT4-C.J.MAXLEN + @ >= OR IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RA-CTX @ _EXT4-C.BLOCK +
    _EXT4-RA-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _EXT4-RA-CTX @ _EXT4-C.BLOCK +
    _EXT4-RA-LOGICAL @ _EXT4-RA-CTX @ _EXT4-JOURNAL-MAP@
    _EXT4-RA-CTX @ _EXT4-WRITE-BLOCK ;

VARIABLE _EXT4-JWF-IOR
VARIABLE _EXT4-JWF-WRITER

: _EXT4-JWR-LATCH-FAULT  ( ior writer -- ior )
    _EXT4-JWF-WRITER ! _EXT4-JWF-IOR !
    _EXT4-JWF-IOR @ 0= IF 0 EXIT THEN
    _EXT4-JWF-WRITER @ _EXT4-JWR.FAULT + @ 0= IF
        _EXT4-JWF-IOR @ _EXT4-JWF-WRITER @ _EXT4-JWR.FAULT + !
    THEN
    _EXT4-JWR-FAULTED _EXT4-JWF-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-IO-VFS @ ?DUP IF
        DUP V.FLAGS DUP @ VFS-F-RO OR VFS-F-DIRTY OR SWAP ! DROP
    THEN
    _EXT4-JWF-WRITER @ _EXT4-JWR.FAULT + @ ;

VARIABLE _EXT4-JAP-BUF
VARIABLE _EXT4-JAP-WRITER
VARIABLE _EXT4-JAP-CTX
VARIABLE _EXT4-JAP-HEAD
VARIABLE _EXT4-JAP-EXPECTED-HEAD
VARIABLE _EXT4-JAP-EXPECTED-NEXT

\ Bind a fresh clean-primary reread to an exact validated journal endpoint.
\ A feature-zero JBD2 superblock has no checksum, so generic usability alone
\ cannot prevent stale geometry or identity from being newly authenticated.
: _EXT4-ACTIVATION-PRIMARY?
  ( buffer ctx expected-head expected-next-tid -- flag )
    _EXT4-JAP-EXPECTED-NEXT ! _EXT4-JAP-EXPECTED-HEAD !
    _EXT4-JAP-CTX ! _EXT4-JAP-BUF !
    _EXT4-JAP-BUF @ _EXT4-JS.MAGIC + _EXT4-BE32@
    _EXT4-JBD2-MAGIC <> IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.TYPE + _EXT4-BE32@
    _EXT4-JBD2-SUPER-V2 <> IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.HEADER-SEQUENCE + _EXT4-BE32@ IF
        FALSE EXIT
    THEN
    _EXT4-JAP-BUF @ _EXT4-JS.BLOCK-SIZE + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.BSIZE + @ <> IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.MAXLEN + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.MAXLEN + @ <> IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.FIRST + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.FIRST + @ <> IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.SEQUENCE + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.SEQUENCE + @ <> IF FALSE EXIT THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JAP-EXPECTED-NEXT @ <> IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.START + _EXT4-BE32@ IF FALSE EXIT THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.START + @ IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.HEAD + _EXT4-BE32@ DUP _EXT4-JAP-HEAD !
    _EXT4-JAP-CTX @ _EXT4-C.J.HEAD + @ <> IF FALSE EXIT THEN
    _EXT4-JAP-HEAD @ DUP 0= IF
        DROP _EXT4-JAP-CTX @ _EXT4-C.J.FIRST + @
    THEN
    _EXT4-JAP-EXPECTED-HEAD @ <> IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.ERRNO + _EXT4-BE32@ IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.COMPAT + _EXT4-BE32@ IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.RO-COMPAT + _EXT4-BE32@ IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.FEATURES + @ <> IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.UUID +
    _EXT4-JAP-CTX @ _EXT4-C.SB + _EXT4-SB.UUID +
    16 _EXT4-BYTES=? 0= IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.NR-USERS + _EXT4-BE32@ 1 <> IF
        FALSE EXIT
    THEN
    _EXT4-JAP-BUF @ _EXT4-JS.DYNSUPER + _EXT4-BE32@ IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.MAX-TRANSACTION + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.MAX-TRANSACTION + @ <> IF FALSE EXIT THEN
    _EXT4-JAP-BUF @ _EXT4-JS.MAX-TRANS-DATA + _EXT4-BE32@
    _EXT4-JAP-CTX @ _EXT4-C.J.MAX-TRANS-DATA + @ <> IF FALSE EXIT THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.FEATURES + @ IF
        _EXT4-JAP-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@ 4 <> IF
            FALSE EXIT
        THEN
        _EXT4-JAP-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32@ IF
            FALSE EXIT
        THEN
        _EXT4-JAP-BUF @ _EXT4-JBD2-SUPER-CHECKSUM? 0= IF FALSE EXIT THEN
    ELSE
        _EXT4-JAP-BUF @ _EXT4-JS.CHECKSUM-TYPE + L@
        _EXT4-JAP-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32@ OR
        _EXT4-JAP-BUF @ _EXT4-JS.CHECKSUM + _EXT4-BE32@ OR IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JAP-BUF @ _EXT4-JAP-CTX @ _EXT4-JBD2-WITNESS? 0= IF
        FALSE EXIT
    THEN
    _EXT4-JAP-CTX @ _EXT4-C.J.WITNESS + @ 0= ;

: _EXT4-JWR-ACTIVATION-PRIMARY?  ( buffer writer -- flag )
    _EXT4-JAP-WRITER ! _EXT4-JAP-BUF !
    _EXT4-JAP-BUF @
    _EXT4-JAP-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JAP-WRITER @ _EXT4-JWR.HEAD + @
    _EXT4-JAP-WRITER @ _EXT4-JWR.NEXT-TID + @
    _EXT4-ACTIVATION-PRIMARY? ;

VARIABLE _EXT4-JWA-WRITER
VARIABLE _EXT4-JWA-CTX
VARIABLE _EXT4-JWA-GUARD
VARIABLE _EXT4-JAC-CTX
VARIABLE _EXT4-JAC-GUARD
VARIABLE _EXT4-JAC-SUPER
VARIABLE _EXT4-JAC-SCRATCH
VARIABLE _EXT4-JAC-WRITER

: _EXT4-JAC-PHASE  ( phase -- )
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWR.PHASE + !
    ELSE
        DROP
    THEN ;

: _EXT4-JAC-FAULT  ( ior -- ior )
    DUP 0= IF EXIT THEN
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWR-LATCH-FAULT EXIT
    THEN
    \ Mount owns writer-free activation failures.  Its next attempt must be
    \ able to resolve the durable AKW1 prefix without retaining a synthetic
    \ read-only latch that would poison later private-writer use.
    ;

\ Perform the witnessed clean-journal activation using caller-owned block
\ buffers.  The private writer supplies its retained scratch pair during
\ ordinary mutation; mount-time orphan recovery borrows DIR-BLOCK/TREE-BLOCK,
\ avoiding a one-off arena allocation that would freeze later writer credits.
\ All checks before ACTIVATING are non-mutating.  Every later failure leaves
\ AKW1 or a standard recovery endpoint for the next mount.
: _EXT4-ACTIVATE-CLEAN-JOURNAL
  ( ctx guard super-buffer scratch-buffer writer|0 -- ior )
    _EXT4-JAC-WRITER ! _EXT4-JAC-SCRATCH ! _EXT4-JAC-SUPER !
    _EXT4-JAC-GUARD ! _EXT4-JAC-CTX !
    _EXT4-JAC-CTX @ _EXT4-C.BLOCK + _EXT4-JAC-SUPER @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JAC-SUPER @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-STAMP-JOURNAL-ACTIVATION
    _EXT4-JAC-SUPER @ _EXT4-JBD2-SUPER-CHECKSUM? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWR-ACTIVATING SWAP _EXT4-JWR.STATE + !
    THEN
    _EXT4-JWP-GUARD-PRESEED _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ _EXT4-JAC-SCRATCH @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ MOVE
    0 _EXT4-JAC-SCRATCH @ C!
    _EXT4-JAC-SCRATCH @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-GUARD _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-PRIMARY _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ 0 _EXT4-JAC-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-EXT4-SUPER _EXT4-JAC-PHASE
    _EXT4-JAC-CTX @ _EXT4-C.SB + _EXT4-PREPARE-DIRTY-SUPER
    _EXT4-JAC-CTX @ _EXT4-C.SB + _EXT4-SB.CHECKSUM + L@
    _EXT4-AJS-NEW @ <> IF VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + 2 2 _EXT4-WRITE-SECTORS
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-PROOF _EXT4-JAC-PHASE
    0 _EXT4-JAC-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.BLOCK + _EXT4-JAC-SUPER @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.BLOCK + _EXT4-JAC-SUPER @
    _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JAC-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM? 0= IF
        DROP VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        DROP VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-SB.CHECKSUM + L@ _EXT4-AJS-NEW @ <> IF
        VFS-E-CORRUPT _EXT4-JAC-FAULT EXIT
    THEN
    _EXT4-JWP-WITNESS-CLEAR _EXT4-JAC-PHASE
    _EXT4-JAC-SUPER @ _EXT4-ZERO-JOURNAL-WITNESS
    _EXT4-JAC-SUPER @ 0 _EXT4-JAC-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JWP-GUARD-RETIRE _EXT4-JAC-PHASE
    _EXT4-JAC-SCRATCH @ _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _EXT4-JAC-SCRATCH @ _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @
    _EXT4-WRITE-JBLOCK ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JAC-FAULT EXIT THEN
    _EXT4-JBD2-I-RECOVERY-REVOKE
    _EXT4-JAC-CTX @ _EXT4-C.J.FEATURES + !
    0xFFFFFFFF _EXT4-CRC-START
    _EXT4-JAC-SUPER @ _EXT4-JS.UUID + 16 _EXT4-CRC-ADD
    _EXT4-CRC@ _EXT4-JAC-CTX @ _EXT4-C.J.SEED + !
    _EXT4-JAC-SUPER @ _EXT4-JS.SEQUENCE + _EXT4-BE32@
    _EXT4-JAC-CTX @ _EXT4-C.J.SEQUENCE + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.START + !
    _EXT4-JAC-GUARD @ _EXT4-JAC-CTX @ _EXT4-C.J.HEAD + !
    _EXT4-JW-NONE _EXT4-JAC-CTX @ _EXT4-C.J.WITNESS + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.WITNESS-CHECKSUM + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
    0 _EXT4-JAC-CTX @ _EXT4-C.J.ANCHOR + !
    -1 _EXT4-JAC-CTX @ _EXT4-C.RECOVERY + !
    -1 _EXT4-JAC-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-IO-VFS @ ?DUP IF
        VFS-F-DIRTY SWAP V.FLAGS DUP @ ROT OR SWAP !
    THEN
    _EXT4-JAC-SUPER @ _EXT4-JAC-CTX @ _EXT4-C.BSIZE + @ 0 FILL
    _EXT4-JAC-WRITER @ ?DUP IF
        _EXT4-JWP-NONE OVER _EXT4-JWR.PHASE + !
        _EXT4-JWR-IDLE SWAP _EXT4-JWR.STATE + !
    THEN
    0 ;

: _EXT4-JWR-ACTIVATE  ( writer -- ior )
    DUP _EXT4-JWA-WRITER ! _EXT4-JWR-VALID? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.FAULT + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JWA-CTX !
    _EXT4-C.RECOVERY + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-IO-VFS @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-CTX _EXT4-JWA-CTX @ <> IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-ATTACHED? 0= IF DROP VFS-E-STALE EXIT THEN
    V.VOLUME @ _EXT4-IO-VOL @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM? 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.STATE + W@ 1 <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.J.START + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.J.WITNESS + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    0 _EXT4-JWA-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JWA-CTX @ _EXT4-C.BLOCK + _EXT4-JWA-WRITER @
    _EXT4-JWR-ACTIVATION-PRIMARY? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWA-WRITER @ _EXT4-JWR.HEAD + @ DUP _EXT4-JWA-GUARD !
    DUP _EXT4-JWA-WRITER @ _EXT4-JWR.FIRST + @ U<
    SWAP _EXT4-JWA-WRITER @ _EXT4-JWR.MAXLEN + @ U< 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWA-CTX @
    _EXT4-JWA-GUARD @
    _EXT4-JWA-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JWA-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JWA-WRITER @
    _EXT4-ACTIVATE-CLEAN-JOURNAL ;

\ =====================================================================
\  Private one-transaction JBD2 emission
\ =====================================================================
\
\ The public mutation surface remains disabled.  This layer turns one fully
\ staged transaction into an ordered, checksum-v3 JBD2 commit and deliberately
\ stops in COMMITTED state with all after-images retained for checkpointing.

VARIABLE _EXT4-JEC-BUF
VARIABLE _EXT4-JEC-CTX
VARIABLE _EXT4-JEC-FIELD
VARIABLE _EXT4-JEC-TID

: _EXT4-JBD2-STAMP-BLOCK-CHECKSUM  ( buffer ctx -- )
    _EXT4-JEC-CTX ! DUP _EXT4-JEC-BUF !
    _EXT4-JEC-CTX @ _EXT4-C.BSIZE + @ 4 - + _EXT4-JEC-FIELD !
    0 _EXT4-JEC-FIELD @ _EXT4-BE32!
    _EXT4-JEC-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JEC-BUF @ _EXT4-JEC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    _EXT4-CRC@ _EXT4-JEC-FIELD @ _EXT4-BE32! ;

: _EXT4-JBD2-STAMP-COMMIT-CHECKSUM  ( buffer ctx -- )
    _EXT4-JEC-CTX ! DUP _EXT4-JEC-BUF !
    16 + _EXT4-JEC-FIELD !
    0 _EXT4-JEC-FIELD @ _EXT4-BE32!
    _EXT4-JEC-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JEC-BUF @ _EXT4-JEC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    _EXT4-CRC@ _EXT4-JEC-FIELD @ _EXT4-BE32! ;

: _EXT4-JBD2-EMIT-TAG-CHECKSUM  ( payload tid ctx -- crc )
    _EXT4-JEC-CTX ! _EXT4-JEC-TID ! _EXT4-JEC-BUF !
    _EXT4-JEC-TID @ _EXT4-JEC-CTX @ _EXT4-C.TMP + _EXT4-BE32!
    _EXT4-JEC-CTX @ _EXT4-C.J.SEED + @ _EXT4-CRC-START
    _EXT4-JEC-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD
    _EXT4-JEC-BUF @ _EXT4-JEC-CTX @ _EXT4-C.BSIZE + @ _EXT4-CRC-ADD
    _EXT4-CRC@ ;

VARIABLE _EXT4-JEE-SOURCE
VARIABLE _EXT4-JEE-DEST
VARIABLE _EXT4-JEE-WRITER

: _EXT4-JTX-ESCAPED-COPY  ( source dest writer -- flags )
    _EXT4-JEE-WRITER ! _EXT4-JEE-DEST ! _EXT4-JEE-SOURCE !
    _EXT4-JEE-SOURCE @ _EXT4-JEE-DEST @
    _EXT4-JEE-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JEE-DEST @ _EXT4-BE32@ _EXT4-JBD2-MAGIC = IF
        0 _EXT4-JEE-DEST @ _EXT4-BE32!
        _EXT4-JBD2-F-ESCAPE EXIT
    THEN
    0 ;

VARIABLE _EXT4-JEH-TYPE
VARIABLE _EXT4-JEH-BUF
VARIABLE _EXT4-JEH-WRITER

: _EXT4-JTX-HEADER!  ( type buffer writer -- )
    _EXT4-JEH-WRITER ! _EXT4-JEH-BUF ! _EXT4-JEH-TYPE !
    _EXT4-JBD2-MAGIC _EXT4-JEH-BUF @ _EXT4-BE32!
    _EXT4-JEH-TYPE @ _EXT4-JEH-BUF @ 4 + _EXT4-BE32!
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-TID + @
    _EXT4-JEH-BUF @ 8 + _EXT4-BE32! ;

: _EXT4-JTX-BUILD-COMMIT  ( buffer writer -- )
    DUP _EXT4-JEH-WRITER ! SWAP DUP _EXT4-JEH-BUF !
    SWAP _EXT4-JWR.BSIZE + @ 0 FILL
    _EXT4-JBD2-COMMIT _EXT4-JEH-BUF @ _EXT4-JEH-WRITER @
    _EXT4-JTX-HEADER!
    _EXT4-JEH-BUF @ _EXT4-JEH-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JBD2-STAMP-COMMIT-CHECKSUM ;

: _EXT4-JTX-STAMP-ACTIVE-SUPER  ( buffer writer -- )
    _EXT4-JEH-WRITER ! _EXT4-JEH-BUF !
    _EXT4-JEH-BUF @ _EXT4-ZERO-JOURNAL-WITNESS
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-TID + @
    _EXT4-JEH-BUF @ _EXT4-JS.SEQUENCE + _EXT4-BE32!
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEH-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOURNAL-NEXT
    _EXT4-JEH-BUF @ _EXT4-JS.START + _EXT4-BE32!
    _EXT4-JEH-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEH-BUF @ _EXT4-JS.HEAD + _EXT4-BE32!
    _EXT4-JBD2-I-RECOVERY-REVOKE
    _EXT4-JEH-BUF @ _EXT4-JS.INCOMPAT + _EXT4-BE32!
    4 _EXT4-JEH-BUF @ _EXT4-JS.CHECKSUM-TYPE + L!
    0 _EXT4-JEH-BUF @ _EXT4-JS.FC-BLOCKS + _EXT4-BE32!
    _EXT4-JEH-BUF @ _EXT4-STAMP-JOURNAL-SUPER-CHECKSUM ;

VARIABLE _EXT4-JEP-WRITER
VARIABLE _EXT4-JEP-CTX
VARIABLE _EXT4-JEP-INDEX
VARIABLE _EXT4-JEP-INNER
VARIABLE _EXT4-JEP-ENTRY
VARIABLE _EXT4-JEP-IMAGE
VARIABLE _EXT4-JEP-HOME
VARIABLE _EXT4-JEP-ACTUAL
VARIABLE _EXT4-JEP-IOR
VARIABLE _EXT4-JEP-SENTINEL

: _EXT4-JTX-PREFLIGHT-IMAGES  ( writer -- ior )
    DUP _EXT4-JEP-WRITER ! _EXT4-JWR.CTX + @ _EXT4-JEP-CTX !
    0 _EXT4-JEP-INDEX !
    BEGIN
        _EXT4-JEP-INDEX @
        _EXT4-JEP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JEP-ENTRY ! @ DUP _EXT4-JEP-HOME !
        0xFFFFFFFF U> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-META-IMAGE
        DUP _EXT4-JEP-IMAGE ! _EXT4-JEP-WRITER @ _EXT4-JTX-IMAGE-CRC
        _EXT4-JEP-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JEP-ENTRY @ CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JEP-IMAGE @ _EXT4-JEP-HOME @ _EXT4-JEP-CTX @
            _EXT4-RECOVERY-AUTHORITY-PRESERVED? 0= IF
                VFS-E-CORRUPT EXIT
            THEN
            0 _EXT4-JEP-INNER !
            BEGIN
                _EXT4-JEP-INNER @
                _EXT4-JEP-WRITER @ _EXT4-JWR.DATA-USED + @ U<
            WHILE
                _EXT4-JEP-INNER @ _EXT4-JEP-WRITER @
                _EXT4-JWR-DATA-ENTRY DUP CELL+ @ _EXT4-JE-ACTIVE = IF
                    @ _EXT4-JEP-HOME @ = IF VFS-E-CORRUPT EXIT THEN
                ELSE DROP THEN
                1 _EXT4-JEP-INNER +!
            REPEAT
            0 _EXT4-JEP-INNER !
            BEGIN
                _EXT4-JEP-INNER @
                _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
            WHILE
                _EXT4-JEP-INNER @ _EXT4-JEP-WRITER @
                _EXT4-JWR-REVOKE-ENTRY DUP CELL+ @ _EXT4-JE-ACTIVE = IF
                    @ _EXT4-JEP-HOME @ = IF VFS-E-CORRUPT EXIT THEN
                ELSE DROP THEN
                1 _EXT4-JEP-INNER +!
            REPEAT
        THEN
        1 _EXT4-JEP-INDEX +!
    REPEAT
    0 _EXT4-JEP-INDEX !
    BEGIN
        _EXT4-JEP-INDEX @
        _EXT4-JEP-WRITER @ _EXT4-JWR.DATA-USED + @ U<
    WHILE
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JEP-ENTRY ! @ DUP _EXT4-JEP-HOME !
        0xFFFFFFFF U> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-DATA-IMAGE
        DUP _EXT4-JEP-IMAGE ! _EXT4-JEP-WRITER @ _EXT4-JTX-IMAGE-CRC
        _EXT4-JEP-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JEP-HOME @ _EXT4-JEP-CTX @
        _EXT4-RECOVERY-AUTHORITY-BLOCK? IF VFS-E-INVALID EXIT THEN
        0 _EXT4-JEP-INNER !
        BEGIN
            _EXT4-JEP-INNER @
            _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
        WHILE
            _EXT4-JEP-INNER @ _EXT4-JEP-WRITER @
            _EXT4-JWR-REVOKE-ENTRY DUP CELL+ @ _EXT4-JE-ACTIVE = IF
                @ _EXT4-JEP-HOME @ = IF VFS-E-CORRUPT EXIT THEN
            ELSE DROP THEN
            1 _EXT4-JEP-INNER +!
        REPEAT
        1 _EXT4-JEP-INDEX +!
    REPEAT
    0 _EXT4-JEP-INDEX !
    BEGIN
        _EXT4-JEP-INDEX @
        _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JEP-INDEX @ _EXT4-JEP-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        @ 0xFFFFFFFF U> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        1 _EXT4-JEP-INDEX +!
    REPEAT
    0 ;

: _EXT4-JTX-PREFLIGHT  ( writer -- ior )
    DUP _EXT4-JEP-WRITER ! _EXT4-JTX-ACTIVE? ?DUP IF EXIT THEN
    _EXT4-JEP-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JEP-CTX !
    _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.START + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.WITNESS + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.J.PRIMARY-TORN + @
    _EXT4-JEP-CTX @ _EXT4-C.J.CLEANUP + @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.SUPER-TORN + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-IO-VFS @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-CTX _EXT4-JEP-CTX @ <> IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-ATTACHED? 0= IF DROP VFS-E-STALE EXIT THEN
    V.VOLUME @ _EXT4-IO-VOL @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM? 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-SB.STATE + W@ 1 <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    8 _EXT4-JEP-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.INODE +
    _EXT4-JEP-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JEP-CTX @ _EXT4-C.ISIZE + @ CMOVE
    _EXT4-JEP-WRITER @ _EXT4-JTX-PREFLIGHT-IMAGES ?DUP IF EXIT THEN
    _EXT4-JEP-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JEP-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @
    _EXT4-JEP-WRITER @ _EXT4-JTX-LOG-BLOCKS
    _EXT4-JEP-IOR ! _EXT4-JEP-ACTUAL !
    _EXT4-JEP-IOR @ IF _EXT4-JEP-IOR @ EXIT THEN
    _EXT4-JEP-ACTUAL @ 2 U< IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JEP-ACTUAL @
    _EXT4-JEP-WRITER @ _EXT4-JWR.LOG-RESERVED + @ U> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JEP-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEP-ACTUAL @ _EXT4-JEP-CTX @ _EXT4-JOURNAL-ADVANCE
    DUP _EXT4-JEP-SENTINEL !
    _EXT4-JEP-WRITER @ _EXT4-JWR.TX-START + @ = IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JEP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JEP-CTX @ _EXT4-C.BLOCK + _EXT4-JEP-WRITER @
    _EXT4-JWR-ACTIVATION-PRIMARY? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

VARIABLE _EXT4-JEM-WRITER
VARIABLE _EXT4-JEM-CTX
VARIABLE _EXT4-JEM-CURSOR
VARIABLE _EXT4-JEM-COMMIT
VARIABLE _EXT4-JEM-SENTINEL
VARIABLE _EXT4-JEM-ACTUAL
VARIABLE _EXT4-JEM-INDEX
VARIABLE _EXT4-JEM-SCAN
VARIABLE _EXT4-JEM-BATCH-START
VARIABLE _EXT4-JEM-BATCH-END
VARIABLE _EXT4-JEM-COUNT
VARIABLE _EXT4-JEM-OFF
VARIABLE _EXT4-JEM-LAST-TAG
VARIABLE _EXT4-JEM-ENTRY
VARIABLE _EXT4-JEM-IMAGE
VARIABLE _EXT4-JEM-TAG
VARIABLE _EXT4-JEM-FLAGS
VARIABLE _EXT4-JEM-OLD-RESERVED

: _EXT4-JEM-FAULT  ( ior -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR-LATCH-FAULT ;

: _EXT4-JEM-ADVANCE  ( -- )
    _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT
    _EXT4-JEM-CURSOR ! ;

: _EXT4-JTX-EMIT-ORDERED-DATA  ( -- ior )
    0 _EXT4-JEM-INDEX !
    BEGIN
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.DATA-USED + @ U<
    WHILE
        _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-DATA-ENTRY
        DUP _EXT4-JEM-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JWP-ORDERED-DATA
            _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
            _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-DATA-IMAGE
            _EXT4-JEM-ENTRY @ @ _EXT4-JEM-CTX @ _EXT4-WRITE-BLOCK
            ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        THEN
        1 _EXT4-JEM-INDEX +!
    REPEAT
    0 ;

: _EXT4-JEM-SKIP-CANCELLED-META  ( -- )
    BEGIN
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-META-ENTRY
        CELL+ @ _EXT4-JE-ACTIVE = IF EXIT THEN
        1 _EXT4-JEM-INDEX +!
    REPEAT ;

: _EXT4-JEM-PREPARE-META-PAYLOAD  ( index -- flags )
    _EXT4-JEM-WRITER @ _EXT4-JWR-META-IMAGE
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-ESCAPED-COPY ;

: _EXT4-JTX-EMIT-METADATA  ( -- ior )
    0 _EXT4-JEM-INDEX !
    BEGIN
        _EXT4-JEM-SKIP-CANCELLED-META
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ DUP
        _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ 0 FILL
        _EXT4-JBD2-DESCRIPTOR SWAP _EXT4-JEM-WRITER @
        _EXT4-JTX-HEADER!
        _EXT4-JEM-INDEX @ _EXT4-JEM-BATCH-START !
        0 _EXT4-JEM-COUNT ! 12 _EXT4-JEM-OFF !
        BEGIN
            _EXT4-JEM-INDEX @
            _EXT4-JEM-WRITER @ _EXT4-JWR.META-USED + @ U<
            _EXT4-JEM-COUNT @
            _EXT4-JEM-WRITER @ _EXT4-JTX-TAGS/BLOCK U< AND
        WHILE
            _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-META-ENTRY
            DUP _EXT4-JEM-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
                _EXT4-JEM-INDEX @ _EXT4-JEM-PREPARE-META-PAYLOAD
                _EXT4-JEM-FLAGS !
                _EXT4-JEM-COUNT @ IF
                    _EXT4-JEM-FLAGS @ _EXT4-JBD2-F-SAME-UUID OR
                    _EXT4-JEM-FLAGS !
                THEN
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
                _EXT4-JEM-OFF @ + DUP _EXT4-JEM-TAG !
                _EXT4-JEM-ENTRY @ @ OVER _EXT4-BE32!
                _EXT4-JEM-FLAGS @ OVER 4 + _EXT4-BE32!
                0 OVER 8 + _EXT4-BE32!
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
                _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @
                _EXT4-JEM-CTX @ _EXT4-JBD2-EMIT-TAG-CHECKSUM
                SWAP 12 + _EXT4-BE32!
                _EXT4-JEM-COUNT @ 0= IF
                    _EXT4-JEM-CTX @ _EXT4-C.SB + _EXT4-SB.UUID +
                    _EXT4-JEM-TAG @ _EXT4-JBD2-TAG3-SIZE +
                    16 MOVE
                THEN
                _EXT4-JEM-TAG @ _EXT4-JEM-LAST-TAG !
                _EXT4-JBD2-TAG3-SIZE _EXT4-JEM-OFF +!
                _EXT4-JEM-COUNT @ 0= IF 16 _EXT4-JEM-OFF +! THEN
                1 _EXT4-JEM-COUNT +!
            THEN
            1 _EXT4-JEM-INDEX +!
        REPEAT
        _EXT4-JEM-INDEX @ _EXT4-JEM-BATCH-END !
        _EXT4-JEM-COUNT @ 0= IF VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-LAST-TAG @ 4 + DUP _EXT4-BE32@
        _EXT4-JBD2-F-LAST OR SWAP _EXT4-BE32!
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JEM-CTX @
        _EXT4-JBD2-STAMP-BLOCK-CHECKSUM
        _EXT4-JWP-DESCRIPTOR _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
        _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-ADVANCE
        _EXT4-JEM-BATCH-START @ _EXT4-JEM-SCAN !
        BEGIN
            _EXT4-JEM-SCAN @ _EXT4-JEM-BATCH-END @ U<
        WHILE
            _EXT4-JEM-SCAN @ _EXT4-JEM-WRITER @ _EXT4-JWR-META-ENTRY
            CELL+ @ _EXT4-JE-ACTIVE = IF
                _EXT4-JEM-SCAN @ _EXT4-JEM-PREPARE-META-PAYLOAD DROP
                _EXT4-JWP-PAYLOAD _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
                _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
                ?DUP IF _EXT4-JEM-FAULT EXIT THEN
                _EXT4-JEM-ADVANCE
            THEN
            1 _EXT4-JEM-SCAN +!
        REPEAT
    REPEAT
    0 ;

: _EXT4-JEM-SKIP-CANCELLED-REVOKE  ( -- )
    BEGIN
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-REVOKE-ENTRY
        CELL+ @ _EXT4-JE-ACTIVE = IF EXIT THEN
        1 _EXT4-JEM-INDEX +!
    REPEAT ;

: _EXT4-JTX-EMIT-REVOKES  ( -- ior )
    0 _EXT4-JEM-INDEX !
    BEGIN
        _EXT4-JEM-SKIP-CANCELLED-REVOKE
        _EXT4-JEM-INDEX @
        _EXT4-JEM-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
    WHILE
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ DUP
        _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ 0 FILL
        _EXT4-JBD2-REVOKE SWAP _EXT4-JEM-WRITER @ _EXT4-JTX-HEADER!
        0 _EXT4-JEM-COUNT ! 16 _EXT4-JEM-OFF !
        BEGIN
            _EXT4-JEM-INDEX @
            _EXT4-JEM-WRITER @ _EXT4-JWR.REVOKE-USED + @ U<
            _EXT4-JEM-COUNT @
            _EXT4-JEM-WRITER @ _EXT4-JTX-REVOKES/BLOCK U< AND
        WHILE
            _EXT4-JEM-INDEX @ _EXT4-JEM-WRITER @ _EXT4-JWR-REVOKE-ENTRY
            DUP _EXT4-JEM-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
                _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
                _EXT4-JEM-OFF @ +
                0 OVER _EXT4-BE32!
                _EXT4-JEM-ENTRY @ @ SWAP 4 + _EXT4-BE32!
                8 _EXT4-JEM-OFF +!
                1 _EXT4-JEM-COUNT +!
            THEN
            1 _EXT4-JEM-INDEX +!
        REPEAT
        _EXT4-JEM-COUNT @ 0= IF VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-COUNT @ 8 * 16 +
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ 12 + _EXT4-BE32!
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @ _EXT4-JEM-CTX @
        _EXT4-JBD2-STAMP-BLOCK-CHECKSUM
        _EXT4-JWP-REVOKE _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
        _EXT4-JEM-CURSOR @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
        ?DUP IF _EXT4-JEM-FAULT EXIT THEN
        _EXT4-JEM-ADVANCE
    REPEAT
    0 ;

: _EXT4-JTX-PRESEED-COMMIT-AND-SENTINEL  ( -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-BUILD-COMMIT
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    0 _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @ C!
    _EXT4-JEM-CURSOR @ _EXT4-JEM-COMMIT !
    _EXT4-JWP-COMMIT-PRESEED _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-COMMIT @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-COMMIT @ _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT
    DUP _EXT4-JEM-CURSOR ! _EXT4-JEM-SENTINEL @ <> IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ 0 FILL
    _EXT4-JWP-SENTINEL _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-SENTINEL @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-BODY-FLUSH _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    0 ;

: _EXT4-JTX-INSTALL-ACTIVE-SUPER  ( -- ior )
    _EXT4-JWP-ACTIVE-GUARD-PRESEED
    _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    0 _EXT4-JEM-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK + _EXT4-JEM-WRITER @
    _EXT4-JWR-ACTIVATION-PRIMARY? 0= IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK +
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-STAMP-ACTIVE-SUPER
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    0 _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @ C!
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-ACTIVE-GUARD _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-ACTIVE-PRIMARY _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    0 _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    0 _EXT4-JEM-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK +
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-READ-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JEM-CTX @ _EXT4-C.BLOCK +
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    0 ;

: _EXT4-JTX-WRITE-COMMIT  ( -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-WRITER @ _EXT4-JTX-BUILD-COMMIT
    _EXT4-JWP-COMMIT _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JEM-COMMIT @ _EXT4-JEM-CTX @ _EXT4-WRITE-JBLOCK
    ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    _EXT4-JWP-COMMIT-FLUSH _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JEM-FAULT EXIT THEN
    0 ;

: _EXT4-JTX-PUBLISH-COMMITTED  ( -- ior )
    _EXT4-JEM-WRITER @ _EXT4-JWR.LOG-RESERVED + @
    DUP _EXT4-JEM-OLD-RESERVED ! _EXT4-JEM-ACTUAL @ U< IF
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    _EXT4-JEM-OLD-RESERVED @ _EXT4-JEM-ACTUAL @ -
    _EXT4-JEM-WRITER @ _EXT4-JWR.FREE + +!
    _EXT4-JEM-ACTUAL @ _EXT4-JEM-WRITER @ _EXT4-JWR.LOG-RESERVED + !
    _EXT4-JEM-SENTINEL @ DUP
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-CURSOR + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.HEAD + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-WRITER @ _EXT4-JWR.TAIL + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @ 1+
    0xFFFFFFFF AND _EXT4-JEM-WRITER @ _EXT4-JWR.NEXT-TID + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT
    _EXT4-JEM-CTX @ _EXT4-C.J.START + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @
    _EXT4-JEM-CTX @ _EXT4-C.J.SEQUENCE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @ DUP
    _EXT4-JEM-CTX @ _EXT4-C.J.HEAD + !
    _EXT4-JEM-CTX @ _EXT4-C.J.ANCHOR + !
    _EXT4-JEM-SENTINEL @ _EXT4-JEM-CTX @ _EXT4-C.J.CURSOR + !
    1 _EXT4-JEM-CTX @ _EXT4-C.J.COMMITTED + !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-TID + @ 2 +
    0xFFFFFFFF AND _EXT4-JEM-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-JC-ACTIVE _EXT4-JEM-CTX @ _EXT4-C.J.CLEANUP + !
    _EXT4-JWP-NONE _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JWR-COMMITTED _EXT4-JEM-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JEM-WRITER @ _EXT4-JWR-VALID? 0= IF
        _EXT4-JWP-COMMIT-FLUSH
        _EXT4-JEM-WRITER @ _EXT4-JWR.PHASE + !
        VFS-E-CORRUPT _EXT4-JEM-FAULT EXIT
    THEN
    0 ;

: _EXT4-JTX-EMIT  ( transaction -- ior )
    DUP _EXT4-JEM-WRITER ! _EXT4-JTX-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JEM-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JEM-CTX !
    _EXT4-JEP-ACTUAL @ _EXT4-JEM-ACTUAL !
    _EXT4-JEP-SENTINEL @ _EXT4-JEM-SENTINEL !
    _EXT4-JEM-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JEM-CTX @ _EXT4-JOURNAL-NEXT _EXT4-JEM-CURSOR !
    _EXT4-JWR-EMITTING _EXT4-JEM-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JTX-EMIT-ORDERED-DATA ?DUP IF EXIT THEN
    _EXT4-JTX-EMIT-METADATA ?DUP IF EXIT THEN
    _EXT4-JTX-EMIT-REVOKES ?DUP IF EXIT THEN
    _EXT4-JTX-PRESEED-COMMIT-AND-SENTINEL ?DUP IF EXIT THEN
    _EXT4-JTX-INSTALL-ACTIVE-SUPER ?DUP IF EXIT THEN
    _EXT4-JTX-WRITE-COMMIT ?DUP IF EXIT THEN
    _EXT4-JTX-PUBLISH-COMMITTED ;

\ =====================================================================
\  Unified legacy/modern orphan recovery preflight
\ =====================================================================
\
\ Orphan state is authoritative only after committed JBD2 after-images have
\ reached home.  Mount therefore calls this through VALIDATE-REST after replay
\ and strict reload.  Two passes first derive the exact union count, then fill
\ one arena-backed open-addressed plan.  Each occupied slot authenticates an
\ inode and retains only protocol locators that can be reauthenticated before
\ later cleanup: legacy { inode, next } or modern { logical block, slot }.
\ This slice never changes an inode, orphan-file block, or legacy link;
\ nonempty recovery remains a stable refusal.

VARIABLE _EXT4-OW-CTX
VARIABLE _EXT4-OW-COUNT
VARIABLE _EXT4-OW-REQUIRED
VARIABLE _EXT4-OW-BYTES

4 CONSTANT _EXT4-ORPHAN-RECORD-CELLS
_EXT4-ORPHAN-RECORD-CELLS CELLS CONSTANT _EXT4-ORPHAN-RECORD-SIZE
0 CONSTANT _EXT4-OE.INO
1 CELLS CONSTANT _EXT4-OE.KIND
2 CELLS CONSTANT _EXT4-OE.LOCATOR-A
3 CELLS CONSTANT _EXT4-OE.LOCATOR-B
1 CONSTANT _EXT4-OK-LEGACY
2 CONSTANT _EXT4-OK-MODERN

_EXT4-NONNEG-MAX _EXT4-ORPHAN-RECORD-SIZE /
CONSTANT _EXT4-ORPHAN-SLOTS-MAX

: _EXT4-ORPHAN-WORKSPACE?  ( ctx -- flag )
    DUP _EXT4-C.O.TABLE + @
    SWAP _EXT4-C.O.SLOTS + @
    2DUP OR 0= IF 2DROP TRUE EXIT THEN
    OVER 0= OVER 0= OR IF 2DROP FALSE EXIT THEN
    DUP 2 U< IF 2DROP FALSE EXIT THEN
    DUP _EXT4-ORPHAN-SLOTS-MAX U> IF 2DROP FALSE EXIT THEN
    DUP 1- AND 0= NIP ;

\ Allocate a half-full power-of-two uniqueness table from the caller's arena.
\ Failed-mount retries reuse and clear the original allocation.  A retry that
\ needs a larger table fails without consuming a second monotonic allocation.
: _EXT4-ENSURE-ORPHAN-WORKSPACE  ( active-count ctx -- ior )
    _EXT4-OW-CTX ! DUP _EXT4-OW-COUNT ! DROP
    _EXT4-OW-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OW-COUNT @ _EXT4-HASH-SLOTS
    DUP IF NIP EXIT THEN DROP _EXT4-OW-REQUIRED !
    _EXT4-OW-CTX @ _EXT4-C.O.TABLE + @ IF
        _EXT4-OW-CTX @ _EXT4-C.O.SLOTS + @
        _EXT4-OW-REQUIRED @ U< IF VFS-E-NOMEM EXIT THEN
        _EXT4-OW-CTX @ _EXT4-C.O.TABLE + @
        _EXT4-OW-CTX @ _EXT4-C.O.SLOTS + @
        _EXT4-ORPHAN-RECORD-SIZE * 0 FILL
        0 EXIT
    THEN
    _EXT4-OW-COUNT @ 0= IF 0 EXIT THEN
    _EXT4-OW-REQUIRED @ _EXT4-ORPHAN-SLOTS-MAX U> IF
        EXT4-D-ORPHAN-FILE _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-OW-REQUIRED @ _EXT4-ORPHAN-RECORD-SIZE * _EXT4-OW-BYTES !
    _EXT4-OW-CTX @ _EXT4-C.ARENA + @
    _EXT4-OW-BYTES @ ARENA-ALLOT? IF DROP VFS-E-NOMEM EXIT THEN
    DUP _EXT4-OW-CTX @ _EXT4-C.O.TABLE + !
    _EXT4-OW-BYTES @ 0 FILL
    _EXT4-OW-REQUIRED @ _EXT4-OW-CTX @ _EXT4-C.O.SLOTS + !
    0 ;

VARIABLE _EXT4-OH-CTX
VARIABLE _EXT4-OH-INO
VARIABLE _EXT4-OH-KIND
VARIABLE _EXT4-OH-A
VARIABLE _EXT4-OH-B
VARIABLE _EXT4-OH-SLOT

: _EXT4-ORPHAN-TABLE-ENTRY  ( slot ctx -- address )
    _EXT4-C.O.TABLE + @ SWAP _EXT4-ORPHAN-RECORD-SIZE * + ;

: _EXT4-ORPHAN-TABLE-PUT  ( inode kind locator-a locator-b ctx -- ior )
    _EXT4-OH-CTX ! _EXT4-OH-B ! _EXT4-OH-A !
    _EXT4-OH-KIND ! _EXT4-OH-INO !
    _EXT4-OH-INO @ 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OH-KIND @ _EXT4-OK-LEGACY = IF
        _EXT4-OH-B @ IF EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    ELSE
        _EXT4-OH-KIND @ _EXT4-OK-MODERN <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-OH-CTX @ _EXT4-C.O.SLOTS + @ DUP 0= IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    1- _EXT4-OH-INO @ SWAP AND _EXT4-OH-SLOT !
    _EXT4-OH-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        _EXT4-OH-SLOT @ _EXT4-OH-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP @ DUP 0= IF
            DROP
            _EXT4-OH-INO @ OVER _EXT4-OE.INO + !
            _EXT4-OH-KIND @ OVER _EXT4-OE.KIND + !
            _EXT4-OH-A @ OVER _EXT4-OE.LOCATOR-A + !
            _EXT4-OH-B @ SWAP _EXT4-OE.LOCATOR-B + !
            0 UNLOOP EXIT
        THEN
        NIP _EXT4-OH-INO @ = IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-OH-SLOT @ 1+
        _EXT4-OH-CTX @ _EXT4-C.O.SLOTS + @ 1- AND
        _EXT4-OH-SLOT !
    LOOP
    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT ;

VARIABLE _EXT4-OP-CTX
VARIABLE _EXT4-OP-COUNT
VARIABLE _EXT4-OP-ENTRIES
VARIABLE _EXT4-OL-CTX
VARIABLE _EXT4-OL-CURRENT
VARIABLE _EXT4-OL-NEXT
VARIABLE _EXT4-OL-COUNT
VARIABLE _EXT4-OL-LIMIT
VARIABLE _EXT4-OL-SLOW
VARIABLE _EXT4-OL-FAST
VARIABLE _EXT4-OS-CTX
VARIABLE _EXT4-OS-INO
VARIABLE _EXT4-ON-CTX
VARIABLE _EXT4-ON-INO

: _EXT4-ORPHAN-INODE-NUMBER?  ( inode-number ctx -- flag )
    _EXT4-ON-CTX ! _EXT4-ON-INO !
    _EXT4-ON-INO @
    _EXT4-ON-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< 0=
    _EXT4-ON-INO @ _EXT4-ON-CTX @ _EXT4-C.INODES + @ U> 0= AND ;

: _EXT4-LEGACY-ORPHAN-NEXT  ( inode-number ctx -- next ior )
    _EXT4-OS-CTX ! DUP _EXT4-OS-INO !
    _EXT4-OS-CTX @ _EXT4-ORPHAN-INODE-NUMBER? 0= IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OS-INO @ _EXT4-OS-CTX @
    _EXT4-LOAD-ORPHAN-INODE DUP IF 0 SWAP EXIT THEN DROP
    _EXT4-OS-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@ DUP IF
        DUP _EXT4-OS-CTX @ _EXT4-ORPHAN-INODE-NUMBER? 0= IF
            DROP 0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

\ Floyd's constant-space pass rejects cycles before the exact counting pass.
\ This avoids making a short malformed loop consume the whole inode-count
\ bound while retaining an allocation-free first pass.
: _EXT4-VALIDATE-LEGACY-TERMINATION  ( ctx -- ior )
    DUP _EXT4-OL-CTX ! _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
    DUP _EXT4-OL-SLOW ! _EXT4-OL-FAST !
    BEGIN
        _EXT4-OL-FAST @ 0= IF 0 EXIT THEN
        _EXT4-OL-FAST @ _EXT4-OL-CTX @ _EXT4-LEGACY-ORPHAN-NEXT
        DUP IF NIP EXIT THEN DROP _EXT4-OL-FAST !
        _EXT4-OL-FAST @ 0= IF 0 EXIT THEN
        _EXT4-OL-FAST @ _EXT4-OL-CTX @ _EXT4-LEGACY-ORPHAN-NEXT
        DUP IF NIP EXIT THEN DROP _EXT4-OL-FAST !
        _EXT4-OL-SLOW @ _EXT4-OL-CTX @ _EXT4-LEGACY-ORPHAN-NEXT
        DUP IF NIP EXIT THEN DROP _EXT4-OL-SLOW !
        _EXT4-OL-FAST @ _EXT4-OL-SLOW @ = IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    AGAIN ;

\ Count the legacy singly linked list without allocating cycle state.  No
\ valid chain can visit more distinct inode numbers than FIRST_INO..INODES;
\ crossing that geometry-derived bound proves nontermination.  The second
\ pass inserts into the shared uniqueness plan and therefore identifies the
\ repeated inode directly.
: _EXT4-COUNT-LEGACY-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OL-CTX !
    DUP _EXT4-VALIDATE-LEGACY-TERMINATION ?DUP IF NIP EXIT THEN
    DUP _EXT4-C.INODES + @
    OVER _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ - 1+
    _EXT4-OL-LIMIT !
    _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ _EXT4-OL-CURRENT !
    0 _EXT4-OL-COUNT !
    BEGIN _EXT4-OL-CURRENT @ WHILE
        _EXT4-OL-COUNT @ _EXT4-OL-LIMIT @ U< 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-OL-CURRENT @ _EXT4-OL-CTX @
        _EXT4-LEGACY-ORPHAN-NEXT DUP IF NIP EXIT THEN
        DROP _EXT4-OL-NEXT !
        1 _EXT4-OL-COUNT +!
        _EXT4-OL-NEXT @ _EXT4-OL-CURRENT !
    REPEAT
    _EXT4-OL-COUNT @ _EXT4-OL-CTX @
    _EXT4-C.O.LEGACY-ACTIVE + !
    0 ;

: _EXT4-COUNT-ACTIVE-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OP-CTX !
    _EXT4-C.BSIZE + @ 8 - 4 / _EXT4-OP-ENTRIES !
    0 _EXT4-OP-COUNT !
    _EXT4-OV-BLOCKS @ 0 ?DO
        I _EXT4-OP-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-OP-ENTRIES @ 0 ?DO
            _EXT4-OP-CTX @ _EXT4-C.BLOCK + I 4 * + L@ ?DUP IF
                _EXT4-OP-CTX @ _EXT4-ORPHAN-INODE-NUMBER? 0= IF
                    EXT4-D-ORPHAN-FILE _EXT4-CORRUPT
                    UNLOOP UNLOOP EXIT
                THEN
                1 _EXT4-OP-COUNT +!
            THEN
        LOOP
    LOOP
    _EXT4-OP-COUNT @ _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + !
    0 ;

: _EXT4-INDEX-ACTIVE-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OP-CTX !
    _EXT4-C.BSIZE + @ 8 - 4 / _EXT4-OP-ENTRIES !
    _EXT4-OV-BLOCKS @ 0 ?DO
        I _EXT4-OP-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF
            UNLOOP EXIT
        THEN
        _EXT4-OP-ENTRIES @ 0 ?DO
            _EXT4-OP-CTX @ _EXT4-C.BLOCK + I 4 * + L@ ?DUP IF
                _EXT4-OK-MODERN J I _EXT4-OP-CTX @
                _EXT4-ORPHAN-TABLE-PUT ?DUP IF
                    UNLOOP UNLOOP EXIT
                THEN
            THEN
        LOOP
    LOOP
    0 ;

: _EXT4-INDEX-LEGACY-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OL-CTX !
    _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ _EXT4-OL-CURRENT !
    _EXT4-OL-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ 0 ?DO
        _EXT4-OL-CURRENT @ 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-OL-CURRENT @ _EXT4-OL-CTX @
        _EXT4-LEGACY-ORPHAN-NEXT DUP IF NIP UNLOOP EXIT THEN
        DROP _EXT4-OL-NEXT !
        _EXT4-OL-CURRENT @ _EXT4-OK-LEGACY
        _EXT4-OL-NEXT @ 0 _EXT4-OL-CTX @
        _EXT4-ORPHAN-TABLE-PUT ?DUP IF UNLOOP EXIT THEN
        _EXT4-OL-NEXT @ _EXT4-OL-CURRENT !
    LOOP
    _EXT4-OL-CURRENT @ IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-OI-CTX
VARIABLE _EXT4-OI-INO
VARIABLE _EXT4-OI-IN
VARIABLE _EXT4-OI-NLINK
VARIABLE _EXT4-OI-TYPE
VARIABLE _EXT4-OI-IOR

\ ext4_orphan_get() admits allocated, checksum-valid inodes at or above
\ s_first_ino.  Linked entries must be truncatable; unlinked entries may be
\ any valid inode type because cleanup deletes them.  STAGE-CURRENT-INODE
\ already owns the complete type/size/flag/map checks.  For an unlinked inode
\ only, temporarily substitute a nonzero link count in the authenticated cache
\ while running that read-only validator, then restore the original bytes.
: _EXT4-VALIDATE-ACTIVE-ORPHAN  ( inode-number ctx -- ior )
    _EXT4-OI-CTX ! DUP _EXT4-OI-INO !
    DUP _EXT4-OI-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U<
    OVER _EXT4-OI-CTX @ _EXT4-C.INODES + @ U> OR IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-OI-INO @ _EXT4-OI-CTX @ _EXT4-LOAD-ORPHAN-INODE ?DUP IF
        EXIT
    THEN
    _EXT4-OI-CTX @ _EXT4-C.INODE + DUP _EXT4-OI-IN !
    _EXT4-I.LINKS + W@ DUP _EXT4-OI-NLINK ! 0= IF
        1 _EXT4-OI-IN @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-OI-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-OI-IOR ! _EXT4-OI-TYPE !
    _EXT4-OI-NLINK @ 0= IF
        0 _EXT4-OI-IN @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-OI-IOR @ ?DUP IF EXIT THEN
    _EXT4-OI-NLINK @ IF
        _EXT4-OI-TYPE @ VFS-T-FILE =
        _EXT4-OI-TYPE @ VFS-T-DIR = OR
        _EXT4-OI-TYPE @ VFS-T-SYMLINK = OR 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-OI-CTX @ _EXT4-OI-TYPE @ _EXT4-FAST-SYMLINK-STORAGE? IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

VARIABLE _EXT4-OQ-CTX
VARIABLE _EXT4-OQ-RECORD

: _EXT4-ORPHAN-RECORD?  ( record ctx -- flag )
    _EXT4-OQ-CTX ! DUP _EXT4-OQ-RECORD !
    DUP _EXT4-OE.INO + @ _EXT4-OQ-CTX @
    _EXT4-ORPHAN-INODE-NUMBER? 0= IF DROP FALSE EXIT THEN
    DUP _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        DUP _EXT4-OE.LOCATOR-B + @ IF DROP FALSE EXIT THEN
        _EXT4-OE.LOCATOR-A + @ ?DUP IF
            _EXT4-OQ-CTX @ _EXT4-ORPHAN-INODE-NUMBER?
        ELSE
            TRUE
        THEN EXIT
    THEN
    DUP _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        DUP _EXT4-OE.LOCATOR-A + @ _EXT4-OV-BLOCKS @ U<
        SWAP _EXT4-OE.LOCATOR-B + @
        _EXT4-OQ-CTX @ _EXT4-C.BSIZE + @ 8 - 4 / U< AND
        EXIT
    THEN
    DROP FALSE ;

VARIABLE _EXT4-OM-RECORD
VARIABLE _EXT4-OM-CTX
VARIABLE _EXT4-OM-BASE
VARIABLE _EXT4-OM-OFF
VARIABLE _EXT4-OM-INO
VARIABLE _EXT4-OM-SLOT
VARIABLE _EXT4-OM-ENTRY

\ Cleanup authority belongs to the exact retained discovery plan, not to a
\ caller-authored record that merely copies its four cells.
: _EXT4-ORPHAN-PLAN-MEMBER?  ( record ctx -- flag )
    _EXT4-OM-CTX ! _EXT4-OM-RECORD !
    _EXT4-OM-RECORD @ 0= _EXT4-OM-CTX @ 0= OR IF FALSE EXIT THEN
    _EXT4-OM-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF FALSE EXIT THEN
    _EXT4-OM-CTX @ _EXT4-C.O.TABLE + @ DUP _EXT4-OM-BASE !
    _EXT4-OM-RECORD @ U> IF FALSE EXIT THEN
    _EXT4-OM-RECORD @ _EXT4-OM-BASE @ - DUP _EXT4-OM-OFF !
    _EXT4-ORPHAN-RECORD-SIZE MOD IF FALSE EXIT THEN
    _EXT4-OM-OFF @
    _EXT4-OM-CTX @ _EXT4-C.O.SLOTS + @
    _EXT4-ORPHAN-RECORD-SIZE * U< 0= IF FALSE EXIT THEN
    _EXT4-OM-RECORD @ @ DUP 0= IF DROP FALSE EXIT THEN
    _EXT4-OM-INO !
    _EXT4-OM-INO @
    _EXT4-OM-CTX @ _EXT4-C.O.SLOTS + @ 1- AND _EXT4-OM-SLOT !
    _EXT4-OM-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        _EXT4-OM-SLOT @ _EXT4-OM-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP _EXT4-OM-ENTRY ! @ DUP 0= IF
            DROP FALSE UNLOOP EXIT
        THEN
        _EXT4-OM-INO @ = IF
            _EXT4-OM-ENTRY @ _EXT4-OM-RECORD @ = UNLOOP EXIT
        THEN
        _EXT4-OM-SLOT @ 1+
        _EXT4-OM-CTX @ _EXT4-C.O.SLOTS + @ 1- AND
        _EXT4-OM-SLOT !
    LOOP
    FALSE ;

VARIABLE _EXT4-ORA-RECORD
VARIABLE _EXT4-ORA-CTX
VARIABLE _EXT4-ORA-INO
VARIABLE _EXT4-ORA-KIND

\ Reauthenticate both the retained discovery record and the current media
\ locator, then leave the checksum-valid target inode in C.INODE.  This is a
\ read-only authority check; staged transaction images never stand in for the
\ plan or for the raw orphan chain that the plan names.
: _EXT4-REAUTH-ORPHAN-PLAN-RECORD  ( plan-record ctx -- ior )
    _EXT4-ORA-CTX ! _EXT4-ORA-RECORD !
    _EXT4-ORA-RECORD @ 0= _EXT4-ORA-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ORA-RECORD @ _EXT4-ORA-CTX @
    _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ORA-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-ORA-INO !
    _EXT4-ORA-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-ORA-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-ORA-RECORD @ _EXT4-ORA-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ORA-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-ORA-KIND !
    _EXT4-OK-MODERN = IF
        _EXT4-ORA-RECORD @ _EXT4-OE.LOCATOR-A + @
        _EXT4-ORA-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-ORA-CTX @ _EXT4-C.BLOCK +
        _EXT4-ORA-RECORD @ _EXT4-OE.LOCATOR-B + @ 4 * + L@
        _EXT4-ORA-INO @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-ORA-KIND @ _EXT4-OK-LEGACY <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-ORA-INO @ _EXT4-ORA-CTX @ _EXT4-LOAD-ORPHAN-INODE
    ?DUP IF EXIT THEN
    _EXT4-ORA-KIND @ _EXT4-OK-LEGACY = IF
        _EXT4-ORA-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
        _EXT4-ORA-RECORD @ _EXT4-OE.LOCATOR-A + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

: _EXT4-VALIDATE-INDEXED-ORPHANS  ( ctx -- ior )
    DUP _EXT4-OP-CTX !
    _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-OP-CTX @ _EXT4-ORPHAN-TABLE-ENTRY
        DUP _EXT4-OQ-RECORD ! @ ?DUP IF
            _EXT4-OQ-RECORD @ _EXT4-OP-CTX @
            _EXT4-ORPHAN-RECORD? 0= IF
                DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
            THEN
            _EXT4-OP-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF
                UNLOOP EXIT
            THEN
        THEN
    LOOP
    0 ;

\ Build and authenticate the complete legacy/modern union without deciding
\ whether a caller is allowed to continue past a nonempty recovery plan.
\ Public mount validation retains the refusal policy below; the narrowly
\ sealed final-cleanup checkpoint uses this core and then proves one exact
\ writer-owned singleton plan.
: _EXT4-AUTHENTICATE-ORPHAN-PLAN  ( ctx -- ior )
    _EXT4-OP-CTX !
    0 _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + !
    0 _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + !
    0 _EXT4-OP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + !
    0 _EXT4-OP-CTX @ _EXT4-C.O.CLEAR-PENDING + !
    _EXT4-OP-CTX @ _EXT4-COUNT-LEGACY-ORPHANS ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-COUNT-ACTIVE-ORPHANS ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
        _EXT4-RO-ORPHAN-PRESENT AND 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @
    _EXT4-OP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ _EXT4-UADD?
    DUP IF
        2DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN DROP
    DUP _EXT4-OP-CTX @ _EXT4-C.INODES + @ U> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DUP _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + !
    _EXT4-OP-CTX @
    _EXT4-ENSURE-ORPHAN-WORKSPACE ?DUP IF EXIT THEN
    _EXT4-OP-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-INDEX-ACTIVE-ORPHANS ?DUP IF EXIT THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-INDEX-LEGACY-ORPHANS ?DUP IF EXIT THEN
    THEN
    _EXT4-OP-CTX @ _EXT4-C.O.ACTIVE + @ IF
        _EXT4-OP-CTX @ _EXT4-VALIDATE-INDEXED-ORPHANS ?DUP IF EXIT THEN
    ELSE
        _EXT4-OP-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
        _EXT4-RO-ORPHAN-PRESENT AND IF
            -1 _EXT4-OP-CTX @ _EXT4-C.O.CLEAR-PENDING + !
        THEN
    THEN
    0 ;

: _EXT4-VALIDATE-ORPHAN-FILE  ( ctx -- ior )
    DUP _EXT4-AUTHENTICATE-ORPHAN-PLAN ?DUP IF NIP EXIT THEN
    _EXT4-C.O.ACTIVE + @ IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

\ =====================================================================
\  Typed, non-emitting orphan-recovery metadata after-images
\ =====================================================================
\
\ These private builders stop at the transaction-staging boundary.  They
\ reauthenticate every plan locator against media, compose same-home edits in
\ writer scratch, and restamp the affected ext4 checksum before replacing the
\ complete retained after-image.  They neither activate nor emit a journal
\ transaction and therefore grant no cleanup or public-write authority by
\ themselves.

VARIABLE _EXT4-RI-INODE
VARIABLE _EXT4-RI-INO
VARIABLE _EXT4-RI-CTX
VARIABLE _EXT4-RI-EXTRA
VARIABLE _EXT4-RI-HAS-HI
VARIABLE _EXT4-RI-CALC

: _EXT4-RESTAMP-INODE  ( inode inode-number ctx -- ior )
    _EXT4-RI-CTX ! _EXT4-RI-INO ! _EXT4-RI-INODE !
    _EXT4-RI-INODE @ 0= _EXT4-RI-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-RI-INO @ 0=
    _EXT4-RI-INO @ _EXT4-RI-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-RI-CTX @ _EXT4-C.ISIZE + @ 128 U< IF
        EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-RI-HAS-HI !
    _EXT4-RI-CTX @ _EXT4-C.ISIZE + @ 128 > IF
        _EXT4-RI-INODE @ _EXT4-I.EXTRA-SIZE + W@
        DUP _EXT4-RI-EXTRA ! 4 U< IF
            EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RI-EXTRA @ 4 MOD IF
            EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RI-EXTRA @ 128 +
        _EXT4-RI-CTX @ _EXT4-C.ISIZE + @ U> IF
            EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        -1 _EXT4-RI-HAS-HI !
    THEN
    0 _EXT4-RI-INODE @ _EXT4-I.CSUM-LO + W!
    _EXT4-RI-HAS-HI @ IF
        0 _EXT4-RI-INODE @ _EXT4-I.CSUM-HI + W!
    THEN
    _EXT4-RI-INO @ _EXT4-RI-CTX @ _EXT4-C.TMP + L!
    _EXT4-RI-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-RI-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD
    _EXT4-RI-INODE @ _EXT4-I.GENERATION + 4 _EXT4-CRC-ADD
    _EXT4-RI-INODE @ _EXT4-RI-CTX @ _EXT4-C.ISIZE + @ _EXT4-CRC-ADD
    _EXT4-CRC@ DUP _EXT4-RI-CALC !
    _EXT4-RI-INODE @ _EXT4-I.CSUM-LO + W!
    _EXT4-RI-HAS-HI @ IF
        _EXT4-RI-CALC @ 16 RSHIFT
        _EXT4-RI-INODE @ _EXT4-I.CSUM-HI + W!
    THEN
    0 ;

VARIABLE _EXT4-ITM-SECONDS
VARIABLE _EXT4-ITM-NSEC
VARIABLE _EXT4-ITM-INODE
VARIABLE _EXT4-ITM-CTX
VARIABLE _EXT4-ITM-LOW
VARIABLE _EXT4-ITM-SIGNED
VARIABLE _EXT4-ITM-EPOCH
VARIABLE _EXT4-ITM-EXTRA

\ Encode one explicit timestamp into both mtime and ctime without consulting
\ an ambiguous ambient clock.  Ext4 decodes the low word as signed and then
\ adds the extra field's two epoch bits, so derive those bits from the
\ sign-extended low word rather than from a logical seconds shift.
: _EXT4-SET-INODE-MTIME-CTIME  ( seconds nsec inode ctx -- ior )
    _EXT4-ITM-CTX ! _EXT4-ITM-INODE !
    _EXT4-ITM-NSEC ! _EXT4-ITM-SECONDS !
    _EXT4-ITM-CTX @ 0= _EXT4-ITM-INODE @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ITM-NSEC @ 0<
    _EXT4-ITM-NSEC @ 1000000000 U< 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ITM-CTX @ _EXT4-C.ISIZE + @ DUP 128 =
    SWAP 256 = OR 0= IF
        EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ITM-SECONDS @ -2147483648 <
    _EXT4-ITM-SECONDS @ 15032385535 > OR IF
        VFS-E-OVERFLOW EXIT
    THEN
    _EXT4-ITM-SECONDS @ 0xFFFFFFFF AND DUP _EXT4-ITM-LOW !
    DUP 0x80000000 AND IF 0xFFFFFFFF00000000 OR THEN
    _EXT4-ITM-SIGNED !
    _EXT4-ITM-SECONDS @ _EXT4-ITM-SIGNED @ - 32 RSHIFT
    DUP _EXT4-ITM-EPOCH ! 3 U> IF VFS-E-OVERFLOW EXIT THEN
    _EXT4-ITM-CTX @ _EXT4-C.ISIZE + @ 128 = IF
        _EXT4-ITM-NSEC @ _EXT4-ITM-EPOCH @ OR IF
            VFS-E-OVERFLOW EXIT
        THEN
        0 _EXT4-ITM-EXTRA !
    ELSE
        \ This first writable slice follows live-inode staging's modern
        \ profile: all three extra timestamps and the high checksum exist.
        \ Old-format 256-byte records with extra_isize zero remain readable
        \ but are not silently upgraded by a data overwrite.
        _EXT4-ITM-INODE @ _EXT4-I.EXTRA-SIZE + W@
        DUP 16 U< IF DROP EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT THEN
        DUP 4 MOD IF DROP EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT THEN
        128 + _EXT4-ITM-CTX @ _EXT4-C.ISIZE + @ U> IF
            EXT4-D-INODE-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-ITM-NSEC @ 2 LSHIFT _EXT4-ITM-EPOCH @ OR
        _EXT4-ITM-EXTRA !
    THEN
    _EXT4-ITM-LOW @ _EXT4-ITM-INODE @ _EXT4-I.CTIME + L!
    _EXT4-ITM-LOW @ _EXT4-ITM-INODE @ _EXT4-I.MTIME + L!
    _EXT4-ITM-CTX @ _EXT4-C.ISIZE + @ 128 > IF
        _EXT4-ITM-EXTRA @
        _EXT4-ITM-INODE @ _EXT4-I.CTIME-EXTRA + L!
        _EXT4-ITM-EXTRA @
        _EXT4-ITM-INODE @ _EXT4-I.MTIME-EXTRA + L!
    THEN
    0 ;

VARIABLE _EXT4-ROB-BLOCK
VARIABLE _EXT4-ROB-PHYS
VARIABLE _EXT4-ROB-INO
VARIABLE _EXT4-ROB-GEN
VARIABLE _EXT4-ROB-CTX
VARIABLE _EXT4-ROB-TAIL

: _EXT4-RESTAMP-ORPHAN-BLOCK
  ( block physical orphan-inode generation ctx -- ior )
    _EXT4-ROB-CTX ! _EXT4-ROB-GEN ! _EXT4-ROB-INO !
    _EXT4-ROB-PHYS ! _EXT4-ROB-BLOCK !
    _EXT4-ROB-BLOCK @ 0= _EXT4-ROB-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-ROB-INO @ _EXT4-ROB-CTX @ _EXT4-C.ORPHAN-INO + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROB-PHYS @
    _EXT4-ROB-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROB-PHYS @ 0xFFFFFFFF U>
    _EXT4-ROB-GEN @ 0xFFFFFFFF U> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROB-BLOCK @ _EXT4-ROB-CTX @ _EXT4-C.BSIZE + @ 8 - +
    DUP _EXT4-ROB-TAIL ! L@ _EXT4-ORPHAN-MAGIC <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-ROB-INO @ _EXT4-ROB-CTX @ _EXT4-C.TMP + L!
    _EXT4-ROB-GEN @ _EXT4-ROB-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-ROB-PHYS @ _EXT4-ROB-CTX @ _EXT4-C.TMP 8 + + L!
    0 _EXT4-ROB-CTX @ _EXT4-C.TMP 12 + + L!
    _EXT4-ROB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-ROB-CTX @ _EXT4-C.TMP + 16 _EXT4-CRC-ADD
    _EXT4-ROB-BLOCK @
    _EXT4-ROB-CTX @ _EXT4-C.BSIZE + @ 8 - _EXT4-CRC-ADD
    _EXT4-CRC@
    _EXT4-ROB-TAIL @ 4 + L!
    0 ;

VARIABLE _EXT4-OCV-STORED

: _EXT4-ORPHAN-BLOCK-CHECKSUM?
  ( block physical orphan-inode generation ctx -- flag )
    _EXT4-ROB-CTX ! _EXT4-ROB-GEN ! _EXT4-ROB-INO !
    _EXT4-ROB-PHYS ! _EXT4-ROB-BLOCK !
    _EXT4-ROB-BLOCK @ 0= _EXT4-ROB-CTX @ 0= OR IF FALSE EXIT THEN
    _EXT4-ROB-INO @ _EXT4-ROB-CTX @ _EXT4-C.ORPHAN-INO + @ <> IF
        FALSE EXIT
    THEN
    _EXT4-ROB-PHYS @
    _EXT4-ROB-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF FALSE EXIT THEN
    _EXT4-ROB-PHYS @ 0xFFFFFFFF U>
    _EXT4-ROB-GEN @ 0xFFFFFFFF U> OR IF FALSE EXIT THEN
    _EXT4-ROB-BLOCK @ _EXT4-ROB-CTX @ _EXT4-C.BSIZE + @ 8 - + DUP
    L@ _EXT4-ORPHAN-MAGIC <> IF DROP FALSE EXIT THEN
    4 + L@ _EXT4-OCV-STORED !
    _EXT4-ROB-INO @ _EXT4-ROB-CTX @ _EXT4-C.TMP + L!
    _EXT4-ROB-GEN @ _EXT4-ROB-CTX @ _EXT4-C.TMP 4 + + L!
    _EXT4-ROB-PHYS @ _EXT4-ROB-CTX @ _EXT4-C.TMP 8 + + L!
    0 _EXT4-ROB-CTX @ _EXT4-C.TMP 12 + + L!
    _EXT4-ROB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-ROB-CTX @ _EXT4-C.TMP + 16 _EXT4-CRC-ADD
    _EXT4-ROB-BLOCK @
    _EXT4-ROB-CTX @ _EXT4-C.BSIZE + @ 8 - _EXT4-CRC-ADD
    _EXT4-CRC@ _EXT4-OCV-STORED @ = ;

VARIABLE _EXT4-JOI-NEW
VARIABLE _EXT4-JOI-RECORD
VARIABLE _EXT4-JOI-WRITER
VARIABLE _EXT4-JOI-CTX
VARIABLE _EXT4-JOI-INO
VARIABLE _EXT4-JOI-KIND
VARIABLE _EXT4-JOI-HOME
VARIABLE _EXT4-JOI-OFF
VARIABLE _EXT4-JOI-IMAGE
VARIABLE _EXT4-JOI-SNAPSHOT

: _EXT4-JTX-STAGE-ORPHAN-INODE
  ( inode-afterimage plan-record transaction -- ior )
    _EXT4-JOI-WRITER ! _EXT4-JOI-RECORD ! _EXT4-JOI-NEW !
    _EXT4-JOI-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOI-NEW @ 0= _EXT4-JOI-RECORD @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOI-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOI-CTX !
    _EXT4-JOI-RECORD @ _EXT4-JOI-CTX @ _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    \ Preserve natural C.INODE, C.BLOCK, and SCRATCH-A caller inputs before
    \ locator reauthentication overwrites those caches.  SCRATCH-B remains
    \ private and unused by non-emitting transaction staging.
    _EXT4-JOI-WRITER @ _EXT4-JWR.SCRATCH-B + @ DUP
    _EXT4-JOI-SNAPSHOT !
    _EXT4-JOI-NEW @ SWAP
    _EXT4-JOI-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-JOI-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-JOI-INO !
    _EXT4-JOI-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JOI-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOI-RECORD @ _EXT4-JOI-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOI-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-JOI-KIND !
    _EXT4-OK-MODERN = IF
        _EXT4-JOI-RECORD @ _EXT4-OE.LOCATOR-A + @
        _EXT4-JOI-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-JOI-CTX @ _EXT4-C.BLOCK +
        _EXT4-JOI-RECORD @ _EXT4-OE.LOCATOR-B + @ 4 * + L@
        _EXT4-JOI-INO @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JOI-INO @ _EXT4-JOI-CTX @ _EXT4-LOAD-ORPHAN-INODE
    ?DUP IF EXIT THEN
    _EXT4-JOI-KIND @ _EXT4-OK-LEGACY = IF
        _EXT4-JOI-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
        _EXT4-JOI-RECORD @ _EXT4-OE.LOCATOR-A + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JOI-SNAPSHOT @ _EXT4-I.GENERATION + L@
    _EXT4-JOI-CTX @ _EXT4-C.INODE + _EXT4-I.GENERATION + L@ <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-IR-BLOCK @ _EXT4-JOI-HOME !
    _EXT4-IR-OFF @ _EXT4-JOI-OFF !
    _EXT4-JOI-CTX @ _EXT4-C.BLOCK + _EXT4-JOI-HOME @
    _EXT4-JOI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _EXT4-JOI-IMAGE !
    \ Different records in one table block compose, but a second full-record
    \ replacement of this same inode must not silently discard its predecessor.
    _EXT4-JOI-IMAGE @ _EXT4-JOI-OFF @ +
    _EXT4-JOI-CTX @ _EXT4-C.INODE +
    _EXT4-JOI-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JOI-SNAPSHOT @ _EXT4-JOI-IMAGE @ _EXT4-JOI-OFF @ +
    _EXT4-JOI-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-JOI-IMAGE @ _EXT4-JOI-OFF @ + _EXT4-JOI-INO @
    _EXT4-JOI-CTX @ _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _EXT4-JOI-IMAGE @ _EXT4-JOI-HOME @ _EXT4-JOI-WRITER @
    _EXT4-JTX-META-REPLACE ;

VARIABLE _EXT4-JOS-RECORD
VARIABLE _EXT4-JOS-WRITER
VARIABLE _EXT4-JOS-CTX
VARIABLE _EXT4-JOS-INO
VARIABLE _EXT4-JOS-HOME
VARIABLE _EXT4-JOS-GEN
VARIABLE _EXT4-JOS-ORPHAN-INO
VARIABLE _EXT4-JOS-SLOT
VARIABLE _EXT4-JOS-IMAGE
VARIABLE _EXT4-JOS-EA

\ =====================================================================
\  Typed, non-emitting block-free accounting after-images
\ =====================================================================

VARIABLE _EXT4-GBC-GROUP
VARIABLE _EXT4-GBC-CTX
VARIABLE _EXT4-GBC-START

: _EXT4-GROUP-BLOCK-COUNT  ( group ctx -- blocks ior )
    _EXT4-GBC-CTX ! DUP _EXT4-GBC-GROUP !
    _EXT4-GBC-CTX @ 0= IF DROP 0 VFS-E-INVALID EXIT THEN
    _EXT4-GBC-GROUP @
    _EXT4-GBC-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        DROP 0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-GBC-GROUP @ _EXT4-GBC-CTX @ _EXT4-C.BPG + @ _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP
    _EXT4-GBC-CTX @ _EXT4-C.FIRST + @ _EXT4-UADD?
    DUP IF NIP 0 SWAP EXIT THEN DROP DUP _EXT4-GBC-START !
    _EXT4-GBC-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
        0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GBC-CTX @ _EXT4-C.BLOCKS + @ _EXT4-GBC-START @ -
    _EXT4-GBC-CTX @ _EXT4-C.BPG + @ MIN 0 ;

VARIABLE _EXT4-GBR-GROUP
VARIABLE _EXT4-GBR-CTX
VARIABLE _EXT4-GBR-COUNT

\ Return the exact half-open physical interval owned by one block group.
\ Reuse the canonical short-last-group calculation and keep every address
\ operation checked so sizing cannot wrap malformed geometry into a match.
: _EXT4-GROUP-BLOCK-RANGE  ( group ctx -- first count ior )
    _EXT4-GBR-CTX ! _EXT4-GBR-GROUP !
    _EXT4-GBR-GROUP @ _EXT4-GBR-CTX @ _EXT4-GROUP-BLOCK-COUNT
    DUP IF NIP 0 0 ROT EXIT THEN DROP _EXT4-GBR-COUNT !
    _EXT4-GBR-GROUP @
    _EXT4-GBR-CTX @ _EXT4-C.BPG + @ _EXT4-UMUL?
    DUP IF NIP 0 0 ROT EXIT THEN DROP
    _EXT4-GBR-CTX @ _EXT4-C.FIRST + @ _EXT4-UADD?
    DUP IF NIP 0 0 ROT EXIT THEN DROP
    _EXT4-GBR-COUNT @ 0 ;

VARIABLE _EXT4-GDC-DESC
VARIABLE _EXT4-GDC-GROUP
VARIABLE _EXT4-GDC-CTX
VARIABLE _EXT4-GDC-STORED
VARIABLE _EXT4-GDC-CALC

: _EXT4-GROUP-DESC-CHECKSUM?  ( descriptor group ctx -- flag )
    _EXT4-GDC-CTX ! _EXT4-GDC-GROUP ! _EXT4-GDC-DESC !
    _EXT4-GDC-DESC @ 0= _EXT4-GDC-CTX @ 0= OR IF FALSE EXIT THEN
    _EXT4-GDC-GROUP @
    _EXT4-GDC-CTX @ _EXT4-C.GROUPS + @ U< 0= IF FALSE EXIT THEN
    _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W@ _EXT4-GDC-STORED !
    0 _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
    _EXT4-GDC-GROUP @ _EXT4-GDC-CTX @ _EXT4-C.TMP + L!
    _EXT4-GDC-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-GDC-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD
    _EXT4-GDC-DESC @ _EXT4-DESC-SIZE _EXT4-CRC-ADD
    _EXT4-CRC@ 0xFFFF AND _EXT4-GDC-CALC !
    _EXT4-GDC-STORED @ _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
    _EXT4-GDC-CALC @ _EXT4-GDC-STORED @ = ;

: _EXT4-RESTAMP-GROUP-DESC  ( descriptor group ctx -- ior )
    _EXT4-GDC-CTX ! _EXT4-GDC-GROUP ! _EXT4-GDC-DESC !
    _EXT4-GDC-DESC @ 0= _EXT4-GDC-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-GDC-GROUP @
    _EXT4-GDC-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    0 _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
    _EXT4-GDC-GROUP @ _EXT4-GDC-CTX @ _EXT4-C.TMP + L!
    _EXT4-GDC-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-GDC-CTX @ _EXT4-C.TMP + 4 _EXT4-CRC-ADD
    _EXT4-GDC-DESC @ _EXT4-DESC-SIZE _EXT4-CRC-ADD
    _EXT4-CRC@ 0xFFFF AND
    _EXT4-GDC-DESC @ _EXT4-GD.CHECKSUM + W!
    0 ;

VARIABLE _EXT4-BRO-A
VARIABLE _EXT4-BRO-ACOUNT
VARIABLE _EXT4-BRO-B
VARIABLE _EXT4-BRO-BCOUNT

: _EXT4-BLOCK-RANGES-OVERLAP?
  ( first-a count-a first-b count-b -- flag )
    _EXT4-BRO-BCOUNT ! _EXT4-BRO-B !
    _EXT4-BRO-ACOUNT ! _EXT4-BRO-A !
    _EXT4-BRO-ACOUNT @ 0= _EXT4-BRO-BCOUNT @ 0= OR IF FALSE EXIT THEN
    _EXT4-BRO-A @ _EXT4-BRO-B @ _EXT4-BRO-BCOUNT @ + U<
    _EXT4-BRO-B @ _EXT4-BRO-A @ _EXT4-BRO-ACOUNT @ + U< AND ;

VARIABLE _EXT4-MWH-CTX
VARIABLE _EXT4-MWH-FIRST
VARIABLE _EXT4-MWH-COUNT

\ Prove that the primary super/GDT homes this operation will replace are not
\ also named as allocation metadata by any authenticated descriptor.  Read
\ admission alone permits flex_bg placement, so writable admission must make
\ this anti-alias invariant explicit before publishing an after-image.
: _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES  ( ctx -- ior )
    DUP 0= IF DROP VFS-E-INVALID EXIT THEN _EXT4-MWH-CTX !
    _EXT4-MWH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK _EXT4-MWH-FIRST !
    _EXT4-MWH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ 1+
    _EXT4-MWH-COUNT !
    _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @ _EXT4-MWH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    _EXT4-MWH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MWH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @
        _EXT4-MWH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @
        _EXT4-MWH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MWH-FIRST @ _EXT4-MWH-COUNT @
        _EXT4-MWH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
    LOOP
    0 ;

VARIABLE _EXT4-MBH-HOME
VARIABLE _EXT4-MBH-OWNER
VARIABLE _EXT4-MBH-CTX
VARIABLE _EXT4-MBH-FOUND
VARIABLE _EXT4-MBH-BASE
VARIABLE _EXT4-MBH-COUNT

\ A block bitmap that will be replaced must have exactly one descriptor
\ owner and must be disjoint from every inode bitmap/table, sparse-super
\ interval, and journal extent.  Otherwise one valid-looking free operation
\ could silently mutate unrelated metadata through a checksum-valid alias.
: _EXT4-VALIDATE-BLOCK-BITMAP-HOME  ( home owner-group ctx -- ior )
    _EXT4-MBH-CTX ! _EXT4-MBH-OWNER ! _EXT4-MBH-HOME !
    _EXT4-MBH-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MBH-OWNER @
    _EXT4-MBH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MBH-HOME @ 1 _EXT4-MBH-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MBH-HOME @ 1 _EXT4-MBH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    0 _EXT4-MBH-FOUND !
    _EXT4-MBH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MBH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MBH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ _EXT4-MBH-HOME @ = IF
            I _EXT4-MBH-OWNER @ <> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-MBH-FOUND +!
        THEN
        _EXT4-MBH-HOME @ 1
        _EXT4-MBH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MBH-HOME @ 1
        _EXT4-MBH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-MBH-CTX @ _EXT4-C.BPG + @ *
            _EXT4-MBH-CTX @ _EXT4-C.FIRST + @ + _EXT4-MBH-BASE !
            1 _EXT4-MBH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-MBH-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-MBH-COUNT !
            _EXT4-MBH-HOME @ 1
            _EXT4-MBH-BASE @ _EXT4-MBH-COUNT @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-MBH-FOUND @ 1 <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-MIH-HOME
VARIABLE _EXT4-MIH-OWNER
VARIABLE _EXT4-MIH-CTX
VARIABLE _EXT4-MIH-FOUND
VARIABLE _EXT4-MIH-BASE
VARIABLE _EXT4-MIH-COUNT

\ An inode bitmap that will be replaced has one exact descriptor owner.  It
\ may share neither another allocation role nor an inode-table or sparse-copy
\ interval, and it may not overlap the journal.  These mutation-side proofs
\ are deliberately stronger than checksum-valid read admission.
: _EXT4-VALIDATE-INODE-BITMAP-HOME  ( home owner-group ctx -- ior )
    _EXT4-MIH-CTX ! _EXT4-MIH-OWNER ! _EXT4-MIH-HOME !
    _EXT4-MIH-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MIH-OWNER @
    _EXT4-MIH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MIH-HOME @ 1 _EXT4-MIH-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MIH-HOME @ 1 _EXT4-MIH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    0 _EXT4-MIH-FOUND !
    _EXT4-MIH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MIH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MIH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ _EXT4-MIH-HOME @ = IF
            I _EXT4-MIH-OWNER @ <> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-MIH-FOUND +!
        THEN
        _EXT4-MIH-HOME @ 1
        _EXT4-MIH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MIH-HOME @ 1
        _EXT4-MIH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-MIH-CTX @ _EXT4-C.BPG + @ *
            _EXT4-MIH-CTX @ _EXT4-C.FIRST + @ + _EXT4-MIH-BASE !
            1 _EXT4-MIH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-MIH-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-MIH-COUNT !
            _EXT4-MIH-HOME @ 1
            _EXT4-MIH-BASE @ _EXT4-MIH-COUNT @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-MIH-FOUND @ 1 <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-MTH-HOME
VARIABLE _EXT4-MTH-OWNER
VARIABLE _EXT4-MTH-CTX
VARIABLE _EXT4-MTH-FOUND
VARIABLE _EXT4-MTH-BASE
VARIABLE _EXT4-MTH-COUNT

\ An inode-table page that will be replaced must belong to exactly one
\ authenticated group table.  It may not also name an allocation bitmap,
\ another group's table, sparse-super/GDT storage, or a journal extent.
: _EXT4-VALIDATE-INODE-TABLE-HOME  ( home owner-group ctx -- ior )
    _EXT4-MTH-CTX ! _EXT4-MTH-OWNER ! _EXT4-MTH-HOME !
    _EXT4-MTH-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MTH-OWNER @
    _EXT4-MTH-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MTH-HOME @ 1 _EXT4-MTH-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
    _EXT4-MTH-HOME @ 1 _EXT4-MTH-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    0 _EXT4-MTH-FOUND !
    _EXT4-MTH-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-MTH-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-MTH-HOME @ 1
        _EXT4-MTH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            I _EXT4-MTH-OWNER @ <> IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
            1 _EXT4-MTH-FOUND +!
        THEN
        _EXT4-MTH-HOME @ 1
        _EXT4-MTH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-MTH-HOME @ 1
        _EXT4-MTH-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        I _EXT4-SPARSE-GROUP? IF
            I _EXT4-MTH-CTX @ _EXT4-C.BPG + @ *
            _EXT4-MTH-CTX @ _EXT4-C.FIRST + @ + _EXT4-MTH-BASE !
            1 _EXT4-MTH-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-MTH-CTX @ _EXT4-C.SB +
            _EXT4-SB.RESERVED-GDT + W@ + _EXT4-MTH-COUNT !
            _EXT4-MTH-HOME @ 1
            _EXT4-MTH-BASE @ _EXT4-MTH-COUNT @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    _EXT4-MTH-FOUND @ 1 <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-FRS-FIRST
VARIABLE _EXT4-FRS-COUNT
VARIABLE _EXT4-FRS-CTX
VARIABLE _EXT4-FRS-GROUP
VARIABLE _EXT4-FRS-BASE
VARIABLE _EXT4-FRS-META-COUNT

\ Reject every journal or descriptor/geometry-authenticated static metadata
\ overlap before a mutation changes any transaction-owned after-image.
\ flex_bg means a group's bitmap/table may reside outside that group's nominal
\ interval, so the complete descriptor set is authoritative here.
: _EXT4-VALIDATE-MUTATION-RANGE-TARGETS  ( first count ctx -- ior )
    _EXT4-FRS-CTX ! _EXT4-FRS-COUNT ! _EXT4-FRS-FIRST !
    _EXT4-FRS-CTX @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-FRS-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-CTX @ _EXT4-C.FIRST + @ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
    _EXT4-FRS-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-FRS-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @ _EXT4-FRS-CTX @
    _EXT4-JOURNAL-RANGE-DISJOINT ?DUP IF EXIT THEN
    _EXT4-FRS-CTX @ _EXT4-C.GROUPS + @ 0 ?DO
        I _EXT4-FRS-GROUP !
        I _EXT4-FRS-CTX @ _EXT4-LOAD-DESC ?DUP IF UNLOOP EXIT THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
        _EXT4-FRS-CTX @ _EXT4-C.DESC +
        _EXT4-GD.BLOCK-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
        _EXT4-FRS-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-BITMAP-LO + L@ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
        _EXT4-FRS-CTX @ _EXT4-C.DESC +
        _EXT4-GD.INODE-TABLE-LO + L@ _EXT4-GD-SPAN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
        THEN
        _EXT4-FRS-GROUP @ _EXT4-SPARSE-GROUP? IF
            _EXT4-FRS-GROUP @ _EXT4-FRS-CTX @ _EXT4-C.BPG + @ *
            _EXT4-FRS-CTX @ _EXT4-C.FIRST + @ + _EXT4-FRS-BASE !
            1
            _EXT4-FRS-CTX @ _EXT4-C.J.WITNESS-GDT-SPAN + @ +
            _EXT4-FRS-CTX @ _EXT4-C.SB + _EXT4-SB.RESERVED-GDT + W@ +
            _EXT4-FRS-META-COUNT !
            _EXT4-FRS-FIRST @ _EXT4-FRS-COUNT @
            _EXT4-FRS-BASE @ _EXT4-FRS-META-COUNT @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
    LOOP
    0 ;

\ Authenticate the complete raw modern-slot mutation target without acquiring
\ a transaction image.  The descriptor-wide mutation scan clobbers C.BLOCK,
\ so restore the orphan-file mapping and slot after that scan.  On success the
\ exact physical home, generation, owner, slot, and raw block remain current.
: _EXT4-JOS-AUTH-PREFLIGHT  ( -- ior )
    _EXT4-JOS-RECORD @ _EXT4-JOS-CTX @ _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-JOS-INO !
    _EXT4-JOS-CTX @ _EXT4-VALIDATE-ACTIVE-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-C.INODE + DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-I.FILE-ACL-LO + L@ _EXT4-JOS-EA !
    _EXT4-JOS-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOS-RECORD @ _EXT4-JOS-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.LOCATOR-B + @ _EXT4-JOS-SLOT !
    _EXT4-JOS-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JOS-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-C.BLOCK + _EXT4-JOS-SLOT @ 4 * + L@
    _EXT4-JOS-INO @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-PHYS @ DUP _EXT4-JOS-HOME !
    _EXT4-JOS-EA @ = _EXT4-JOS-EA @ 0<> AND IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-OV-GEN @ _EXT4-JOS-GEN !
    _EXT4-OV-INO @ _EXT4-JOS-ORPHAN-INO !
    _EXT4-JOS-HOME @ 1 _EXT4-JOS-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOS-RECORD @ _EXT4-JOS-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JOS-CTX @ _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JOS-HOME @ <>
    _EXT4-OV-GEN @ _EXT4-JOS-GEN @ <> OR
    _EXT4-OV-INO @ _EXT4-JOS-ORPHAN-INO @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOS-CTX @ _EXT4-C.BLOCK + _EXT4-JOS-SLOT @ 4 * + L@
    _EXT4-JOS-INO @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Clearing a modern orphan slot mutates an ordinary mapped file block, so its
\ read-side checksum is necessary but not sufficient authority.  Prove the
\ exact physical home is writable non-static storage and disjoint from the
\ target's retained external xattr before publishing its after-image.
: _EXT4-JTX-CLEAR-MODERN-ORPHAN-SLOT
  ( plan-record transaction -- ior )
    _EXT4-JOS-WRITER ! _EXT4-JOS-RECORD !
    _EXT4-JOS-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOS-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JOS-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOS-CTX !
    _EXT4-JOS-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JOS-CTX @ _EXT4-C.BLOCK + _EXT4-JOS-HOME @
    _EXT4-JOS-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _EXT4-JOS-IMAGE !
    _EXT4-JOS-IMAGE @ _EXT4-JOS-SLOT @ 4 * + L@
    _EXT4-JOS-INO @ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    0 _EXT4-JOS-IMAGE @ _EXT4-JOS-SLOT @ 4 * + L!
    _EXT4-JOS-IMAGE @ _EXT4-JOS-HOME @ _EXT4-JOS-ORPHAN-INO @
    _EXT4-JOS-GEN @ _EXT4-JOS-CTX @ _EXT4-RESTAMP-ORPHAN-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JOS-IMAGE @ _EXT4-JOS-HOME @ _EXT4-JOS-WRITER @
    _EXT4-JTX-META-REPLACE ;

VARIABLE _EXT4-LBB-GROUP
VARIABLE _EXT4-LBB-CTX
VARIABLE _EXT4-LBB-HOME
VARIABLE _EXT4-LBB-STORED

: _EXT4-LOAD-BLOCK-BITMAP  ( group ctx -- bitmap-home ior )
    _EXT4-LBB-CTX ! DUP _EXT4-LBB-GROUP !
    _EXT4-LBB-GROUP @ _EXT4-LBB-CTX @ _EXT4-LOAD-DESC
    ?DUP IF NIP 0 SWAP EXIT THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-BLOCK-UNINIT AND IF
        DROP 0 EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-LBB-CTX @ _EXT4-C.DESC + DUP
    _EXT4-GD.BLOCK-BITMAP-LO + L@ DUP _EXT4-LBB-HOME !
    SWAP _EXT4-GD.BLOCK-CSUM-LO + W@
    _EXT4-LBB-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-CSUM-HI + W@
    16 LSHIFT OR _EXT4-LBB-STORED ! DROP
    _EXT4-LBB-HOME @ _EXT4-LBB-CTX @ _EXT4-READ-BLOCK
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-LBB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-LBB-CTX @ _EXT4-C.BLOCK +
    _EXT4-LBB-CTX @ _EXT4-C.BPG + @ 8 / _EXT4-CRC-ADD
    _EXT4-CRC@ _EXT4-LBB-STORED @ <> IF
        0 EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-LBB-HOME @ 0 ;

VARIABLE _EXT4-LIB-GROUP
VARIABLE _EXT4-LIB-CTX
VARIABLE _EXT4-LIB-HOME
VARIABLE _EXT4-LIB-STORED

: _EXT4-LOAD-INODE-BITMAP  ( group ctx -- bitmap-home ior )
    _EXT4-LIB-CTX ! DUP _EXT4-LIB-GROUP !
    _EXT4-LIB-GROUP @ _EXT4-LIB-CTX @ _EXT4-LOAD-DESC
    ?DUP IF NIP 0 SWAP EXIT THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-INODE-UNINIT AND IF
        DROP 0 EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-LIB-CTX @ _EXT4-C.DESC + DUP
    _EXT4-GD.INODE-BITMAP-LO + L@ DUP _EXT4-LIB-HOME !
    SWAP _EXT4-GD.INODE-CSUM-LO + W@
    _EXT4-LIB-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-CSUM-HI + W@
    16 LSHIFT OR _EXT4-LIB-STORED ! DROP
    _EXT4-LIB-HOME @ _EXT4-LIB-CTX @ _EXT4-READ-BLOCK
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-LIB-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-LIB-CTX @ _EXT4-C.BLOCK +
    _EXT4-LIB-CTX @ _EXT4-C.IPG + @ 8 / _EXT4-CRC-ADD
    _EXT4-CRC@ _EXT4-LIB-STORED @ <> IF
        0 EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-LIB-HOME @ 0 ;

VARIABLE _EXT4-BBC-BUFFER
VARIABLE _EXT4-BBC-CTX

: _EXT4-BLOCK-BITMAP-CRC  ( bitmap ctx -- crc )
    _EXT4-BBC-CTX ! _EXT4-BBC-BUFFER !
    _EXT4-BBC-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-BBC-BUFFER @ _EXT4-BBC-CTX @ _EXT4-C.BPG + @ 8 /
    _EXT4-CRC-ADD
    _EXT4-CRC@ ;

VARIABLE _EXT4-IBC-BUFFER
VARIABLE _EXT4-IBC-CTX

: _EXT4-INODE-BITMAP-CRC  ( bitmap ctx -- crc )
    _EXT4-IBC-CTX ! _EXT4-IBC-BUFFER !
    _EXT4-IBC-CTX @ _EXT4-C.SEED + @ _EXT4-CRC-START
    _EXT4-IBC-BUFFER @ _EXT4-IBC-CTX @ _EXT4-C.IPG + @ 8 /
    _EXT4-CRC-ADD
    _EXT4-CRC@ ;

VARIABLE _EXT4-BRS-BUFFER
VARIABLE _EXT4-BRS-FIRST
VARIABLE _EXT4-BRS-COUNT
VARIABLE _EXT4-BRS-BIT
VARIABLE _EXT4-BRS-ADDR

: _EXT4-BIT-RANGE-SET?  ( bitmap first-bit count -- flag )
    _EXT4-BRS-COUNT ! _EXT4-BRS-FIRST ! _EXT4-BRS-BUFFER !
    _EXT4-BRS-COUNT @ 0 ?DO
        _EXT4-BRS-FIRST @ I + DUP 8 /
        _EXT4-BRS-BUFFER @ + C@
        1 ROT 8 MOD LSHIFT AND 0= IF FALSE UNLOOP EXIT THEN
    LOOP
    TRUE ;

: _EXT4-CLEAR-BIT-RANGE  ( bitmap first-bit count -- )
    _EXT4-BRS-COUNT ! _EXT4-BRS-FIRST ! _EXT4-BRS-BUFFER !
    _EXT4-BRS-COUNT @ 0 ?DO
        _EXT4-BRS-FIRST @ I + DUP _EXT4-BRS-BIT ! 8 /
        _EXT4-BRS-BUFFER @ + DUP _EXT4-BRS-ADDR ! C@
        1 _EXT4-BRS-BIT @ 8 MOD LSHIFT INVERT AND
        _EXT4-BRS-ADDR @ C!
    LOOP ;

VARIABLE _EXT4-JPS-WRITER
VARIABLE _EXT4-JPS-CTX
VARIABLE _EXT4-JPS-HOME
VARIABLE _EXT4-JPS-OFF
VARIABLE _EXT4-JPS-RAW
VARIABLE _EXT4-JPS-RAW-CRC
VARIABLE _EXT4-JPS-IMAGE
VARIABLE _EXT4-JPS-SUPER

\ Return a private editing copy of the primary-super block, composing with an
\ earlier transaction after-image when one exists.  Both the raw source and
\ the effective image are authenticated before the caller may edit mutable
\ fields; this is the common authority used by allocation accounting and by
\ the legacy-orphan head transition.
: _EXT4-JTX-ACQUIRE-PRIMARY-SUPER
  ( transaction -- ior )
    0 _EXT4-JPS-HOME ! 0 _EXT4-JPS-OFF ! 0 _EXT4-JPS-RAW !
    0 _EXT4-JPS-RAW-CRC ! 0 _EXT4-JPS-IMAGE ! 0 _EXT4-JPS-SUPER !
    DUP _EXT4-JPS-WRITER ! _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JPS-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JPS-CTX !
    0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JPS-CTX @ _EXT4-PRIMARY-SUPER-BLOCK DUP _EXT4-JPS-HOME !
    _EXT4-JPS-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JPS-CTX @ _EXT4-PRIMARY-SUPER-OFF DUP _EXT4-JPS-OFF !
    _EXT4-JPS-CTX @ _EXT4-C.BLOCK + + _EXT4-JPS-RAW !
    _EXT4-JPS-RAW @ _EXT4-JPS-CTX @ _EXT4-C.SB + 1024
    _EXT4-BYTES=? 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-SUPER-CHECKSUM? 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-SUPER-SEED? 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-SB.CHECKSUM + L@ _EXT4-JPS-RAW-CRC !
    _EXT4-JPS-RAW @ 0 _EXT4-JPS-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-RAW @ _EXT4-JPS-CTX @ _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF EXIT THEN
    _EXT4-JPS-CTX @ _EXT4-C.BLOCK + _EXT4-JPS-HOME @
    _EXT4-JPS-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP _EXT4-JPS-IMAGE !
    _EXT4-JPS-IMAGE @ _EXT4-JPS-OFF @ + _EXT4-JPS-SUPER !
    _EXT4-JPS-SUPER @ _EXT4-SUPER-CHECKSUM? 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SUPER-SEED? 0= IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ 0 _EXT4-JPS-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-JPS-CTX @
    _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF EXIT THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-JPS-RAW @ _EXT4-SB.INCOMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JPS-SUPER @ _EXT4-SB.RO-COMPAT + L@
    _EXT4-JPS-RAW @ _EXT4-SB.RO-COMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JFB-FIRST
VARIABLE _EXT4-JFB-COUNT
VARIABLE _EXT4-JFB-WRITER
VARIABLE _EXT4-JFB-CTX
VARIABLE _EXT4-JFB-CURRENT
VARIABLE _EXT4-JFB-REMAIN
VARIABLE _EXT4-JFB-GROUP
VARIABLE _EXT4-JFB-INDEX
VARIABLE _EXT4-JFB-CHUNK
VARIABLE _EXT4-JFB-GROUP-BLOCKS
VARIABLE _EXT4-JFB-BITMAP-HOME
VARIABLE _EXT4-JFB-GDT-HOME
VARIABLE _EXT4-JFB-GDT-OFF
VARIABLE _EXT4-JFB-IMAGE
VARIABLE _EXT4-JFB-DESC
VARIABLE _EXT4-JFB-BITMAP-CRC
VARIABLE _EXT4-JFB-NEW-BITMAP-CRC
VARIABLE _EXT4-JFB-FREE
VARIABLE _EXT4-JFB-NEW-FREE
VARIABLE _EXT4-JFB-SUPER-HOME
VARIABLE _EXT4-JFB-SUPER
VARIABLE _EXT4-JFB-IOR
VARIABLE _EXT4-JFB-PUBLISHED
VARIABLE _EXT4-JFB-ABORT-IOR

\ Once this operation publishes its first complete metadata image, any later
\ failure is transaction-fatal.  Abort immediately so a caller cannot emit a
\ descriptor/bitmap prefix without the matching aggregate superblock update.
\ If local abort invariants themselves fail, latch an explicit faulted state.
: _EXT4-JFB-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JFB-IOR !
    _EXT4-JFB-PUBLISHED @ IF
        _EXT4-JFB-WRITER @ _EXT4-JTX-ABORT
        DUP _EXT4-JFB-ABORT-IOR ! IF
            _EXT4-JFB-ABORT-IOR @
            _EXT4-JFB-WRITER @ _EXT4-JWR.FAULT + !
            _EXT4-JWR-FAULTED
            _EXT4-JFB-WRITER @ _EXT4-JWR.STATE + !
        THEN
    THEN
    _EXT4-JFB-IOR @ ;

: _EXT4-JFB-RESET-WALK  ( -- )
    _EXT4-JFB-FIRST @ _EXT4-JFB-CURRENT !
    _EXT4-JFB-COUNT @ _EXT4-JFB-REMAIN ! ;

: _EXT4-JFB-NEXT-CHUNK  ( -- ior )
    _EXT4-JFB-CURRENT @ _EXT4-JFB-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-JFB-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-JFB-GROUP ! _EXT4-JFB-INDEX !
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-GROUP-BLOCK-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JFB-GROUP-BLOCKS !
    _EXT4-JFB-INDEX @ _EXT4-JFB-GROUP-BLOCKS @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-GROUP-BLOCKS @ _EXT4-JFB-INDEX @ -
    _EXT4-JFB-REMAIN @ MIN DUP 0= IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFB-CHUNK !
    0 ;

: _EXT4-JFB-ADVANCE  ( -- )
    _EXT4-JFB-CHUNK @ DUP _EXT4-JFB-CURRENT +!
    NEGATE _EXT4-JFB-REMAIN +! ;

: _EXT4-JFB-DESC-BITMAP-CRC@  ( descriptor -- crc )
    DUP _EXT4-GD.BLOCK-CSUM-LO + W@
    SWAP _EXT4-GD.BLOCK-CSUM-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFB-DESC-FREE@  ( descriptor -- blocks )
    DUP _EXT4-GD.FREE-BLOCKS-LO + W@
    SWAP _EXT4-GD.FREE-BLOCKS-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFB-DESC-FREE!  ( blocks descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.FREE-BLOCKS-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.FREE-BLOCKS-HI + W! ;

: _EXT4-JFB-DESC-BITMAP-CRC!  ( crc descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.BLOCK-CSUM-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.BLOCK-CSUM-HI + W! ;

: _EXT4-JFB-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _EXT4-JFB-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-GD.FLAGS + W@
    _EXT4-BG-BLOCK-UNINIT AND IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-GD.BLOCK-BITMAP-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JFB-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-JFB-DESC-BITMAP-CRC@
    _EXT4-JFB-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-DESC @ _EXT4-JFB-DESC-FREE@ DUP _EXT4-JFB-FREE !
    _EXT4-JFB-CHUNK @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-NEW-FREE !
    _EXT4-JFB-GROUP-BLOCKS @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFB-ACQUIRE-DESC  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ DUP _EXT4-JFB-GDT-HOME !
    _EXT4-JFB-BITMAP-HOME @ = IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-OFF @ _EXT4-JFB-GDT-OFF !
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-GDT-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    _EXT4-JFB-GDT-OFF @ + _EXT4-JFB-DESC !
    _EXT4-JFB-VALIDATE-EFFECTIVE-DESC ;

: _EXT4-JFB-PREFLIGHT-GROUP  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR ! _EXT4-JFB-BITMAP-HOME !
    _EXT4-JFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-JFB-BITMAP-HOME @ _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @
    _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
    \ The anti-alias scan leaves the descriptor table in C.BLOCK; restore and
    \ reauthenticate the actual bitmap before consulting any allocation bit.
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR !
    _EXT4-JFB-IOR @ IF DROP _EXT4-JFB-IOR @ EXIT THEN
    _EXT4-JFB-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ _EXT4-BIT-RANGE-SET? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-BITMAP-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ _EXT4-BIT-RANGE-SET? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    _EXT4-JFB-BITMAP-CRC !
    _EXT4-JFB-ACQUIRE-DESC ;

: _EXT4-JFB-ACQUIRE-SUPER  ( -- ior )
    _EXT4-JFB-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JFB-SUPER-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JFB-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JFB-IMAGE !
    _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-JFB-COUNT @ _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-NEW-FREE !
    DUP 0xFFFFFFFF U>
    SWAP _EXT4-JFB-CTX @ _EXT4-C.BLOCKS + @ U> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFB-PREFLIGHT  ( -- ior )
    _EXT4-JFB-FIRST @ _EXT4-JFB-COUNT @ _EXT4-JFB-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF EXIT THEN
        _EXT4-JFB-PREFLIGHT-GROUP ?DUP IF EXIT THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    _EXT4-JFB-ACQUIRE-SUPER ;

: _EXT4-JFB-STAGE-GROUP  ( -- ior )
    _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JFB-IOR ! _EXT4-JFB-BITMAP-HOME !
    _EXT4-JFB-IOR @ ?DUP IF EXIT THEN
    _EXT4-JFB-CTX @ _EXT4-C.BLOCK + _EXT4-JFB-BITMAP-HOME @
    _EXT4-JFB-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFB-IMAGE !
    DUP _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    _EXT4-JFB-BITMAP-CRC !
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-INDEX @ _EXT4-JFB-CHUNK @ _EXT4-CLEAR-BIT-RANGE
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-CTX @ _EXT4-BLOCK-BITMAP-CRC
    _EXT4-JFB-NEW-BITMAP-CRC !
    _EXT4-JFB-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JFB-NEW-FREE @ _EXT4-JFB-DESC @ _EXT4-JFB-DESC-FREE!
    _EXT4-JFB-NEW-BITMAP-CRC @ _EXT4-JFB-DESC @
    _EXT4-JFB-DESC-BITMAP-CRC!
    _EXT4-JFB-DESC @ _EXT4-JFB-GROUP @ _EXT4-JFB-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    _EXT4-JFB-IMAGE @ _EXT4-JFB-GDT-HOME @ _EXT4-JFB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFB-PUBLISHED !
    _EXT4-JFB-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFB-BITMAP-HOME @ _EXT4-JFB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFB-PUBLISHED !
    0 ;

: _EXT4-JFB-STAGE-SUPER  ( -- ior )
    _EXT4-JFB-ACQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFB-NEW-FREE @
    _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L!
    0 _EXT4-JFB-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L!
    _EXT4-JFB-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM
    _EXT4-JFB-IMAGE @ _EXT4-JFB-SUPER-HOME @ _EXT4-JFB-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFB-PUBLISHED !
    0 ;

\ Stage only allocation accounting for a nonempty physical block range.  The
\ caller still owns map removal, i_blocks changes, and any metadata revoke.
\ All semantic checks finish before the first table replacement.  A later
\ internal credit/conflict failure automatically aborts the whole transaction
\ so no partial accounting prefix remains eligible for emission.
: _EXT4-JTX-STAGE-FREE-BLOCK-RANGE
  ( first-block count transaction -- ior )
    _EXT4-JFB-WRITER ! _EXT4-JFB-COUNT ! _EXT4-JFB-FIRST !
    0 _EXT4-JFB-PUBLISHED !
    _EXT4-JFB-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFB-COUNT @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JFB-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFB-CTX !
    _EXT4-JFB-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFB-RESET-WALK
    BEGIN _EXT4-JFB-REMAIN @ WHILE
        _EXT4-JFB-NEXT-CHUNK ?DUP IF
            _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT
        THEN
        _EXT4-JFB-STAGE-GROUP ?DUP IF
            _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT
        THEN
        _EXT4-JFB-ADVANCE
    REPEAT
    _EXT4-JFB-STAGE-SUPER ?DUP IF
        _EXT4-JFB-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

VARIABLE _EXT4-OFR-FIRST
VARIABLE _EXT4-OFR-COUNT
VARIABLE _EXT4-OFR-RECORD
VARIABLE _EXT4-OFR-CTX
VARIABLE _EXT4-OFR-ROOT
VARIABLE _EXT4-OFR-ENTRIES
VARIABLE _EXT4-OFR-INDEX
VARIABLE _EXT4-OFR-ENTRY
VARIABLE _EXT4-OFR-PHYS
VARIABLE _EXT4-OFR-LEN

\ Prove that one proposed release range cannot name storage owned by the
\ modern orphan file.  Check both every complete inline extent, including
\ preallocation beyond EOF, and every authenticated logical orphan block.
\ Restore the target plan record before returning so callers retain its inode
\ locator rather than the orphan inode left in the shared cache.

: _EXT4-ORPHAN-FILE-RANGE-DISJOINT
  ( first count plan-record ctx -- ior )
    _EXT4-OFR-CTX ! _EXT4-OFR-RECORD !
    _EXT4-OFR-COUNT ! _EXT4-OFR-FIRST !
    _EXT4-OFR-CTX @ 0= _EXT4-OFR-RECORD @ 0= OR
    _EXT4-OFR-COUNT @ 0= OR IF VFS-E-INVALID EXIT THEN
    _EXT4-OFR-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-OFR-CTX @ _EXT4-C.INODE +
    DUP _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND 0= IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.FILE-ACL-HI + W@
    OVER _EXT4-I.FILE-ACL-LO + L@ OR IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-I.BLOCK + DUP _EXT4-OFR-ROOT !
    DUP W@ _EXT4-EXTENT-MAGIC <> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DUP 4 + W@ 4 <> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DUP 2 + W@ DUP _EXT4-OFR-ENTRIES ! 4 U> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    6 + W@ IF EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT THEN
    0 _EXT4-OFR-INDEX !
    BEGIN _EXT4-OFR-INDEX @ _EXT4-OFR-ENTRIES @ < WHILE
        _EXT4-OFR-ROOT @ 12 _EXT4-OFR-INDEX @ 12 * + + DUP
        _EXT4-OFR-ENTRY !
        DUP _EXT4-EXTENT-LEN@ _EXT4-OFR-LEN !
        8 + L@ _EXT4-OFR-PHYS !
        _EXT4-OFR-FIRST @ _EXT4-OFR-COUNT @
        _EXT4-OFR-PHYS @ _EXT4-OFR-LEN @
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        1 _EXT4-OFR-INDEX +!
    REPEAT
    0 _EXT4-OFR-INDEX !
    BEGIN _EXT4-OFR-INDEX @ _EXT4-OV-BLOCKS @ < WHILE
        _EXT4-OFR-INDEX @ _EXT4-OFR-CTX @
        _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-OFR-FIRST @ _EXT4-OFR-COUNT @ _EXT4-OV-PHYS @ 1
        _EXT4-BLOCK-RANGES-OVERLAP? IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        1 _EXT4-OFR-INDEX +!
    REPEAT
    _EXT4-OFR-RECORD @ _EXT4-OFR-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ;

\ =====================================================================
\  Plan-bound unlinked inode allocation release
\ =====================================================================

VARIABLE _EXT4-GIC-GROUP
VARIABLE _EXT4-GIC-CTX
VARIABLE _EXT4-GIC-FIRST

: _EXT4-GROUP-INODE-COUNT  ( group ctx -- inodes ior )
    _EXT4-GIC-CTX ! DUP _EXT4-GIC-GROUP !
    _EXT4-GIC-CTX @ 0= IF DROP 0 VFS-E-INVALID EXIT THEN
    _EXT4-GIC-GROUP @
    _EXT4-GIC-CTX @ _EXT4-C.GROUPS + @ U< 0= IF
        DROP 0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-GIC-GROUP @ _EXT4-GIC-CTX @ _EXT4-C.IPG + @ _EXT4-UMUL?
    DUP IF NIP 0 SWAP EXIT THEN DROP DUP _EXT4-GIC-FIRST !
    _EXT4-GIC-CTX @ _EXT4-C.INODES + @ U< 0= IF
        0 EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GIC-CTX @ _EXT4-C.INODES + @ _EXT4-GIC-FIRST @ -
    _EXT4-GIC-CTX @ _EXT4-C.IPG + @ MIN 0 ;

VARIABLE _EXT4-JFI-RECORD
VARIABLE _EXT4-JFI-WRITER
VARIABLE _EXT4-JFI-CTX
VARIABLE _EXT4-JFI-INO
VARIABLE _EXT4-JFI-INODE
VARIABLE _EXT4-JFI-GROUP
VARIABLE _EXT4-JFI-INDEX
VARIABLE _EXT4-JFI-GROUP-INODES
VARIABLE _EXT4-JFI-INODE-TABLE
VARIABLE _EXT4-JFI-INODE-HOME
VARIABLE _EXT4-JFI-INODE-OFF
VARIABLE _EXT4-JFI-BITMAP-HOME
VARIABLE _EXT4-JFI-GDT-HOME
VARIABLE _EXT4-JFI-GDT-OFF
VARIABLE _EXT4-JFI-IMAGE
VARIABLE _EXT4-JFI-DESC
VARIABLE _EXT4-JFI-BITMAP-CRC
VARIABLE _EXT4-JFI-NEW-BITMAP-CRC
VARIABLE _EXT4-JFI-GROUP-FREE
VARIABLE _EXT4-JFI-NEW-GROUP-FREE
VARIABLE _EXT4-JFI-SUPER-HOME
VARIABLE _EXT4-JFI-SUPER
VARIABLE _EXT4-JFI-NEW-SUPER-FREE
VARIABLE _EXT4-JFI-IOR
VARIABLE _EXT4-JFI-PUBLISHED
VARIABLE _EXT4-JFI-ABORT-IOR
VARIABLE _EXT4-JFI-DATA-ENTRIES
VARIABLE _EXT4-JFI-DATA-FIRST
VARIABLE _EXT4-JFI-DATA-COUNT
VARIABLE _EXT4-JFI-DATA-ROOT
VARIABLE _EXT4-JFI-DATA-ENTRY
VARIABLE _EXT4-JFI-DATA-BLOCKS

VARIABLE _EXT4-JFO-CTX
VARIABLE _EXT4-JFO-RECORD
VARIABLE _EXT4-JFO-TARGET-INO
VARIABLE _EXT4-JFO-GROUP
VARIABLE _EXT4-JFO-GROUP-INODES
VARIABLE _EXT4-JFO-GROUP-BASE
VARIABLE _EXT4-JFO-INO
VARIABLE _EXT4-JFO-INODE
VARIABLE _EXT4-JFO-NLINK
VARIABLE _EXT4-JFO-TYPE
VARIABLE _EXT4-JFO-IOR
VARIABLE _EXT4-JFO-MAP-LIMIT
VARIABLE _EXT4-JFO-INODE-TABLE

VARIABLE _EXT4-JFO-CERT-SCOPE
VARIABLE _EXT4-JFO-CERT-VALID
VARIABLE _EXT4-JFO-CERT-CTX
VARIABLE _EXT4-JFO-CERT-INO
VARIABLE _EXT4-JFO-CERT-GEN
VARIABLE _EXT4-JFO-CERT-FIRST
VARIABLE _EXT4-JFO-CERT-COUNT

: _EXT4-JFO-CERT-INVALIDATE  ( -- )
    0 _EXT4-JFO-CERT-VALID ! ;

: _EXT4-JFO-CERT-BEGIN  ( -- ior )
    _EXT4-JFO-CERT-SCOPE @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JFO-CERT-INVALIDATE
    -1 _EXT4-JFO-CERT-SCOPE !
    0 ;

: _EXT4-JFO-CERT-END  ( -- )
    _EXT4-JFO-CERT-INVALIDATE
    0 _EXT4-JFO-CERT-SCOPE ! ;

: _EXT4-JFO-CERT-MATCH?  ( -- flag )
    _EXT4-JFO-CERT-SCOPE @ 0= IF FALSE EXIT THEN
    _EXT4-JFO-CERT-VALID @ 0= IF FALSE EXIT THEN
    _EXT4-JFO-CERT-CTX @ _EXT4-JFI-CTX @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-INO @
    _EXT4-JFI-RECORD @ _EXT4-OE.INO + @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-GEN @
    _EXT4-JFI-INODE @ _EXT4-I.GENERATION + L@ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-FIRST @ _EXT4-JFI-DATA-FIRST @ <> IF FALSE EXIT THEN
    _EXT4-JFO-CERT-COUNT @ _EXT4-JFI-DATA-COUNT @ <> IF FALSE EXIT THEN
    TRUE ;

: _EXT4-JFO-CERT-STORE  ( -- )
    _EXT4-JFO-CERT-SCOPE @ 0= IF EXIT THEN
    _EXT4-JFI-CTX @ _EXT4-JFO-CERT-CTX !
    _EXT4-JFI-RECORD @ _EXT4-OE.INO + @ _EXT4-JFO-CERT-INO !
    _EXT4-JFI-INODE @ _EXT4-I.GENERATION + L@ _EXT4-JFO-CERT-GEN !
    _EXT4-JFI-DATA-FIRST @ _EXT4-JFO-CERT-FIRST !
    _EXT4-JFI-DATA-COUNT @ _EXT4-JFO-CERT-COUNT !
    -1 _EXT4-JFO-CERT-VALID ! ;

: _EXT4-JFO-REQUIRE-EMPTY-RESERVED  ( -- ior )
    _EXT4-JFO-INODE @ _EXT4-I.FILE-ACL-HI + W@
    _EXT4-JFO-INODE @ _EXT4-I.FILE-ACL-LO + L@ OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.BLOCKS-LO + L@
    _EXT4-JFO-INODE @ _EXT4-I.BLOCKS-HI + W@ OR IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.BLOCK + 60 _EXT4-BYTES-ZERO? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ With the scoped owner target active, ordinary complete map validation turns
\ every reference to the candidate block into a corruption refusal.  Inode 1
\ may own a legacy bad-block map even with mode zero; other mode-zero reserved
\ records must be storage-empty.  Fast symlink and device payload bytes are
\ interpreted by the normal inode validator rather than mistaken for maps.
: _EXT4-JFO-CHECK-CURRENT-INODE  ( -- ior )
    _EXT4-JFO-CTX @ _EXT4-C.INODE + DUP _EXT4-JFO-INODE !
    DUP _EXT4-I.FILE-ACL-HI + W@ IF
        DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-I.FILE-ACL-LO + L@ ?DUP IF
        EXT4-D-DATA-MAP _EXT4-JFO-CTX @
        _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.MODE + W@ 0xF000 AND 0= IF
        _EXT4-JFO-INO @ 1 = IF
            _EXT4-JFO-CTX @ _EXT4-VALIDATE-LEGACY-MAP EXIT
        THEN
        _EXT4-JFO-INO @
        _EXT4-JFO-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< 0= IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JFO-REQUIRE-EMPTY-RESERVED EXIT
    THEN
    _EXT4-JFO-INODE @ _EXT4-I.LINKS + W@ DUP _EXT4-JFO-NLINK !
    0= IF 1 _EXT4-JFO-INODE @ _EXT4-I.LINKS + W! THEN
    _EXT4-JFO-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JFO-IOR ! _EXT4-JFO-TYPE !
    _EXT4-JFO-NLINK @ 0= IF
        0 _EXT4-JFO-INODE @ _EXT4-I.LINKS + W!
    THEN
    _EXT4-JFO-IOR @ ;

\ The group bitmap copy is already checksum-authenticated and the caller only
\ reaches this word for a set bit.  Load the record directly from the retained
\ table home, then apply the orphan-aware dtime bound.  This avoids rereading
\ and rechecksumming the same inode bitmap for every allocated inode.
: _EXT4-JFO-LOAD-CURRENT-INODE  ( -- ior )
    _EXT4-JFO-INO @ _EXT4-JFO-CTX @
    _EXT4-PREPARE-INODE-LOOKUP ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-JFO-GROUP @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFO-INODE-TABLE @ _EXT4-LOAD-INODE-RECORD-RAW ?DUP IF EXIT THEN
    _EXT4-JFO-CTX @ _EXT4-C.INODE + _EXT4-I.DTIME + L@
    _EXT4-JFO-CTX @ _EXT4-C.INODES + @ U> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFO-SCAN-GROUP  ( -- ior )
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-LOAD-DESC ?DUP IF
        EXIT
    THEN
    _EXT4-GD-FLAGS @ _EXT4-BG-INODE-UNINIT AND IF 0 EXIT THEN
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-GROUP-INODE-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JFO-GROUP-INODES !
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-LOAD-INODE-BITMAP
    DUP IF NIP EXIT THEN 2DROP
    _EXT4-JFO-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFO-INODE-TABLE !
    _EXT4-JFO-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFO-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFO-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-C.IPG + @ _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP _EXT4-JFO-GROUP-BASE !
    _EXT4-JFO-GROUP-INODES @ 0 ?DO
        _EXT4-JFO-CTX @ _EXT4-C.DIR-BLOCK + I 8 / + C@
        1 I 8 MOD LSHIFT AND IF
            _EXT4-JFO-GROUP-BASE @ I + 1+ DUP _EXT4-JFO-INO !
            _EXT4-JFO-TARGET-INO @ <> IF
                _EXT4-JFO-LOAD-CURRENT-INODE ?DUP IF UNLOOP EXIT THEN
                _EXT4-JFO-CHECK-CURRENT-INODE ?DUP IF
                    UNLOOP EXIT
                THEN
            THEN
        THEN
    LOOP
    0 ;

: _EXT4-JFO-SCAN-OTHER-INODES  ( -- ior )
    0 _EXT4-JFO-GROUP !
    BEGIN
        _EXT4-JFO-GROUP @ _EXT4-JFO-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JFO-SCAN-GROUP ?DUP IF EXIT THEN
        1 _EXT4-JFO-GROUP +!
    REPEAT
    0 ;

VARIABLE _EXT4-UOW-INO
VARIABLE _EXT4-UOW-FIRST
VARIABLE _EXT4-UOW-COUNT
VARIABLE _EXT4-UOW-CTX
VARIABLE _EXT4-UOW-MAP-LIMIT
VARIABLE _EXT4-UOW-IOR

\ Prove that no allocated inode other than TARGET-INO maps any part of one
\ proposed mutation range.  The caller has already authenticated the target's
\ own mapping; reload it after the scan restores that authority in C.INODE.
: _EXT4-REQUIRE-UNIQUE-BLOCK-OWNER
  ( target-ino first count ctx -- ior )
    _EXT4-UOW-CTX ! _EXT4-UOW-COUNT !
    _EXT4-UOW-FIRST ! _EXT4-UOW-INO !
    _EXT4-UOW-CTX @ 0= _EXT4-UOW-COUNT @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-UOW-INO @ 0=
    _EXT4-UOW-INO @ _EXT4-UOW-CTX @ _EXT4-C.INODES + @ U> OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-UOW-FIRST @ _EXT4-UOW-CTX @ _EXT4-C.FIRST + @ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-UOW-FIRST @ _EXT4-UOW-COUNT @
    _EXT4-UOW-CTX @ _EXT4-C.BLOCKS + @ BLOCK-RANGE? 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-MUTATION-OWNER-TARGET @
    _EXT4-MUTATION-OWNER-COUNT @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-JFO-CERT-INVALIDATE
    _EXT4-UOW-CTX @ _EXT4-JFO-CTX !
    _EXT4-UOW-INO @ _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-UOW-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-UOW-FIRST @ _EXT4-MUTATION-OWNER-TARGET !
    _EXT4-UOW-COUNT @ _EXT4-MUTATION-OWNER-COUNT !
    _EXT4-JFO-SCAN-OTHER-INODES _EXT4-UOW-IOR !
    0 _EXT4-MUTATION-OWNER-TARGET !
    0 _EXT4-MUTATION-OWNER-COUNT !
    _EXT4-UOW-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-UOW-IOR @ 0= IF
        _EXT4-UOW-INO @ _EXT4-UOW-CTX @
        _EXT4-LOAD-INODE _EXT4-UOW-IOR !
    THEN
    _EXT4-UOW-IOR @ ;

_EXT4-EXTENTS-FL _EXT4-HUGE-FILE-FL OR
CONSTANT _EXT4-JOW-ALLOWED-FLAGS

VARIABLE _EXT4-JOW-SOURCE
VARIABLE _EXT4-JOW-COUNT
VARIABLE _EXT4-JOW-OFFSET
VARIABLE _EXT4-JOW-INO
VARIABLE _EXT4-JOW-EXPECTED-GEN
VARIABLE _EXT4-JOW-SECONDS
VARIABLE _EXT4-JOW-NSEC
VARIABLE _EXT4-JOW-WRITER
VARIABLE _EXT4-JOW-CTX
VARIABLE _EXT4-JOW-BSIZE
VARIABLE _EXT4-JOW-SIZE
VARIABLE _EXT4-JOW-LOGICAL
VARIABLE _EXT4-JOW-BLOCK-OFF
VARIABLE _EXT4-JOW-PHYS
VARIABLE _EXT4-JOW-PRESENT
VARIABLE _EXT4-JOW-TYPE
VARIABLE _EXT4-JOW-FLAGS
VARIABLE _EXT4-JOW-EA
VARIABLE _EXT4-JOW-GEN
VARIABLE _EXT4-JOW-NLINK
VARIABLE _EXT4-JOW-GROUP
VARIABLE _EXT4-JOW-INODE-HOME
VARIABLE _EXT4-JOW-INODE-OFF
VARIABLE _EXT4-JOW-IMAGE
VARIABLE _EXT4-JOW-RECORD
VARIABLE _EXT4-JOW-IOR
VARIABLE _EXT4-JOW-PUBLISHED
VARIABLE _EXT4-JOW-ABORT-IOR

: _EXT4-JOW-REQUIRE-FRESH-EXACT  ( -- ior )
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-CREDIT + @ 1 <>
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-CREDIT + @ 1 <> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ 0<> OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-ACTIVE + @ OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-NONE <> IF VFS-E-BUSY EXIT THEN
    _EXT4-JOW-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JOW-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-JOW-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ OR
    _EXT4-JOW-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _EXT4-JOW-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

\ Authenticate the target's complete inline depth-zero map before excluding
\ that inode from the global other-owner scan.  The inline validator proves
\ its own physical ranges do not overlap; the external xattr pointer remains
\ an independent target-owned reference and must not name the selected block.
: _EXT4-JOW-AUTH-TARGET  ( -- ior )
    _EXT4-JOW-INO @
    _EXT4-JOW-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOW-INO @ 8 =
    _EXT4-JOW-INO @ _EXT4-JOW-CTX @ _EXT4-C.ORPHAN-INO + @ = OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-EXPECTED-GEN @ 0xFFFFFFFF U> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOW-INO @ _EXT4-JOW-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JOW-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JOW-IOR ! _EXT4-JOW-TYPE !
    _EXT4-JOW-IOR @ ?DUP IF EXIT THEN
    _EXT4-JOW-TYPE @ VFS-T-FILE <> IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.FLAGS + L@ DUP _EXT4-JOW-FLAGS !
    DUP _EXT4-IMMUTABLE-FL _EXT4-APPEND-FL OR
    _EXT4-JOURNAL-DATA-FL OR AND IF
        2DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-EXTENTS-FL AND 0= IF
        2DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-ALLOWED-FLAGS INVERT AND IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.BLOCK + 6 + W@ IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.GENERATION + L@ DUP _EXT4-JOW-GEN !
    _EXT4-JOW-EXPECTED-GEN @ <> IF
        DROP VFS-E-STALE EXIT
    THEN
    DUP _EXT4-I.LINKS + W@ _EXT4-JOW-NLINK !
    _EXT4-I.FILE-ACL-LO + L@ _EXT4-JOW-EA !
    _EXT4-JOW-CTX @ _EXT4-C.R.SIZE + @ _EXT4-JOW-SIZE !
    _EXT4-JOW-OFFSET @ _EXT4-JOW-SIZE @ U< 0= IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-COUNT @
    _EXT4-JOW-SIZE @ _EXT4-JOW-OFFSET @ - U> IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-OFFSET @ _EXT4-JOW-BSIZE @ /MOD
    _EXT4-JOW-LOGICAL ! _EXT4-JOW-BLOCK-OFF !
    _EXT4-JOW-COUNT @
    _EXT4-JOW-BSIZE @ _EXT4-JOW-BLOCK-OFF @ - U> IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-LOGICAL @ _EXT4-JOW-CTX @ _EXT4-MAP-BLOCK
    _EXT4-JOW-IOR ! _EXT4-JOW-PRESENT ! _EXT4-JOW-PHYS !
    _EXT4-JOW-IOR @ ?DUP IF EXIT THEN
    _EXT4-JOW-PRESENT @ 0= IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-EA @ IF
        _EXT4-JOW-EA @ _EXT4-JOW-PHYS @ = IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JOW-EA @ EXT4-D-XATTR _EXT4-JOW-CTX @
        _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
        _EXT4-JOW-EA @ _EXT4-JOW-CTX @ _EXT4-LOAD-XATTR-BLOCK
        ?DUP IF EXIT THEN
    THEN
    _EXT4-IR-GROUP @ _EXT4-JOW-GROUP !
    _EXT4-IR-BLOCK @ _EXT4-JOW-INODE-HOME !
    _EXT4-IR-OFF @ _EXT4-JOW-INODE-OFF !
    0 ;

\ Reauthenticate every target property used by the after-images after a
\ descriptor walk or filesystem-wide owner scan has reused shared caches.
: _EXT4-JOW-REQUIRE-SAME-TARGET  ( -- ior )
    _EXT4-JOW-INO @ _EXT4-JOW-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-JOW-GROUP @ <>
    _EXT4-IR-BLOCK @ _EXT4-JOW-INODE-HOME @ <> OR
    _EXT4-IR-OFF @ _EXT4-JOW-INODE-OFF @ <> OR IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-JOW-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-JOW-IOR ! _EXT4-JOW-TYPE !
    _EXT4-JOW-IOR @ ?DUP IF EXIT THEN
    _EXT4-JOW-TYPE @ VFS-T-FILE <> IF VFS-E-STALE EXIT THEN
    _EXT4-JOW-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.GENERATION + L@ _EXT4-JOW-GEN @ <>
    OVER _EXT4-I.FLAGS + L@ _EXT4-JOW-FLAGS @ <> OR
    OVER _EXT4-I.LINKS + W@ _EXT4-JOW-NLINK @ <> OR
    OVER _EXT4-I.FILE-ACL-LO + L@ _EXT4-JOW-EA @ <> OR
    SWAP _EXT4-I.BLOCK + 6 + W@ 0<> OR IF VFS-E-STALE EXIT THEN
    _EXT4-JOW-CTX @ _EXT4-C.R.SIZE + @ _EXT4-JOW-SIZE @ <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-JOW-LOGICAL @ _EXT4-JOW-CTX @ _EXT4-MAP-BLOCK
    _EXT4-JOW-IOR ! _EXT4-JOW-PRESENT !
    _EXT4-JOW-IOR @ ?DUP IF NIP EXIT THEN
    _EXT4-JOW-PRESENT @ 0=
    SWAP _EXT4-JOW-PHYS @ <> OR IF VFS-E-STALE EXIT THEN
    0 ;

: _EXT4-JOW-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JOW-IOR !
    _EXT4-JOW-PUBLISHED @ IF
        _EXT4-JOW-WRITER @ _EXT4-JWR.STATE + @ DUP
        _EXT4-JWR-STAGING = IF
            DROP
            _EXT4-JOW-WRITER @ _EXT4-JTX-ABORT
            DUP _EXT4-JOW-ABORT-IOR ! IF
                _EXT4-JOW-ABORT-IOR @
                _EXT4-JOW-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _EXT4-JOW-WRITER @ _EXT4-JWR.STATE + !
            THEN
        ELSE
            DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
                _EXT4-JOW-IOR @
                _EXT4-JOW-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _EXT4-JOW-WRITER @ _EXT4-JWR.STATE + !
            THEN
        THEN
    THEN
    _EXT4-JOW-IOR @ ;

\ Stage one size-preserving regular-file overwrite wholly inside one already
\ initialized inline depth-zero extent block.  Ordered data carries the full
\ read-modify-write block; one checksummed inode-table after-image carries the
\ explicit mtime/ctime.  This word neither emits nor checkpoints the journal.
: _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-WRITE
  ( source count file-offset inode-number expected-generation
    seconds nsec transaction -- ior )
    _EXT4-JOW-WRITER ! _EXT4-JOW-NSEC ! _EXT4-JOW-SECONDS !
    _EXT4-JOW-EXPECTED-GEN ! _EXT4-JOW-INO ! _EXT4-JOW-OFFSET !
    _EXT4-JOW-COUNT ! _EXT4-JOW-SOURCE !
    0 _EXT4-JOW-PUBLISHED !
    _EXT4-JOW-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOW-CTX !
    _EXT4-JOW-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-JOW-BSIZE !
    _EXT4-JOW-COUNT @ 0> 0= _EXT4-JOW-OFFSET @ 0< OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOW-SOURCE @ _EXT4-JOW-COUNT @ _VFS-BUFFER? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOW-COUNT @ _EXT4-JOW-BSIZE @ U> IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOW-REQUIRE-FRESH-EXACT ?DUP IF EXIT THEN
    \ Preserve caller bytes before any checked read reuses C.BLOCK.  SCRATCH-B
    \ is not used by metadata acquisition and survives until DATA-PUT copies
    \ the completed RMW block into its retained transaction image.
    _EXT4-JOW-SOURCE @
    _EXT4-JOW-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JOW-COUNT @ MOVE
    _EXT4-JOW-AUTH-TARGET ?DUP IF EXIT THEN
    _EXT4-JOW-PHYS @ 1 _EXT4-JOW-CTX @
    _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
    _EXT4-JOW-INO @ _EXT4-JOW-PHYS @ 1 _EXT4-JOW-CTX @
    _EXT4-REQUIRE-UNIQUE-BLOCK-OWNER ?DUP IF EXIT THEN
    _EXT4-JOW-REQUIRE-SAME-TARGET ?DUP IF EXIT THEN
    _EXT4-JOW-INODE-HOME @ _EXT4-JOW-GROUP @ _EXT4-JOW-CTX @
    _EXT4-VALIDATE-INODE-TABLE-HOME ?DUP IF EXIT THEN
    _EXT4-JOW-REQUIRE-SAME-TARGET ?DUP IF EXIT THEN
    _EXT4-JOW-INODE-HOME @ _EXT4-JOW-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JOW-CTX @ _EXT4-C.BLOCK + _EXT4-JOW-INODE-HOME @
    _EXT4-JOW-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JOW-IMAGE !
    _EXT4-JOW-INODE-OFF @ + DUP _EXT4-JOW-RECORD !
    _EXT4-JOW-CTX @ _EXT4-C.INODE +
    _EXT4-JOW-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JOW-SECONDS @ _EXT4-JOW-NSEC @ _EXT4-JOW-RECORD @
    _EXT4-JOW-CTX @ _EXT4-SET-INODE-MTIME-CTIME ?DUP IF EXIT THEN
    _EXT4-JOW-RECORD @ _EXT4-JOW-INO @ _EXT4-JOW-CTX @
    _EXT4-RESTAMP-INODE ?DUP IF EXIT THEN
    _EXT4-JOW-PHYS @ _EXT4-JOW-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JOW-CTX @ _EXT4-C.BLOCK + _EXT4-JOW-BLOCK-OFF @ +
    _EXT4-JOW-COUNT @ MOVE
    _EXT4-JOW-CTX @ _EXT4-C.BLOCK + _EXT4-JOW-PHYS @
    _EXT4-JOW-WRITER @ _EXT4-JTX-DATA-PUT ?DUP IF EXIT THEN
    -1 _EXT4-JOW-PUBLISHED !
    _EXT4-JOW-IMAGE @ _EXT4-JOW-INODE-HOME @ _EXT4-JOW-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF
        _EXT4-JOW-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-USED + @ 1 <>
    _EXT4-JOW-WRITER @ _EXT4-JWR.META-ACTIVE + @ 1 <> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-USED + @ 1 <> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ 1 <> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-USED + @ 0<> OR
    _EXT4-JOW-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ 0<> OR
    _EXT4-JOW-WRITER @ _EXT4-JTX-TABLES-VALID? 0= OR IF
        VFS-E-CORRUPT _EXT4-JOW-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

\ Prove exclusive filesystem-wide inode ownership of the admitted data range.
\ The scan is allocation-free and geometry-bounded.  Mount cleanup may retain
\ one exact proof while it exclusively owns the raw pre-home metadata epoch;
\ journal-only activation, dry staging, and commit do not alter another inode's
\ home map.  Recovery convergence explicitly invalidates the proof before
\ rebuilding authority, and a durable commit consumes it before replay can
\ begin home writes.  Always clear the ambient probe before propagating an
\ error, then restore the plan-bound target inode because the scan necessarily
\ reuses the shared inode cache.
: _EXT4-JFI-REQUIRE-UNIQUE-DATA-OWNER  ( -- ior )
    _EXT4-MUTATION-OWNER-TARGET @
    _EXT4-MUTATION-OWNER-COUNT @ OR IF VFS-E-BUSY EXIT THEN
    _EXT4-JFO-CERT-MATCH? IF 0 EXIT THEN
    _EXT4-JFO-CERT-INVALIDATE
    _EXT4-JFI-CTX @ _EXT4-JFO-CTX !
    _EXT4-JFI-RECORD @ _EXT4-JFO-RECORD !
    _EXT4-JFI-RECORD @ _EXT4-OE.INO + @ _EXT4-JFO-TARGET-INO !
    _EXT4-MAP-VALIDATION-LIMIT @ _EXT4-JFO-MAP-LIMIT !
    0 _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-JFI-DATA-FIRST @ _EXT4-MUTATION-OWNER-TARGET !
    _EXT4-JFI-DATA-COUNT @ _EXT4-MUTATION-OWNER-COUNT !
    _EXT4-JFO-SCAN-OTHER-INODES _EXT4-JFO-IOR !
    0 _EXT4-MUTATION-OWNER-TARGET !
    0 _EXT4-MUTATION-OWNER-COUNT !
    _EXT4-JFO-IOR @ 0= IF
        _EXT4-JFO-RECORD @ _EXT4-JFO-CTX @
        _EXT4-REAUTH-ORPHAN-PLAN-RECORD _EXT4-JFO-IOR !
    THEN
    _EXT4-JFO-MAP-LIMIT @ _EXT4-MAP-VALIDATION-LIMIT !
    _EXT4-JFO-IOR @ 0= IF _EXT4-JFO-CERT-STORE THEN
    _EXT4-JFO-IOR @ ;

: _EXT4-JFI-INLINE-XATTR-PREFLIGHT  ( -- ior )
    \ Inline values die with the inode allocation bit and need no separate
    \ metadata after-image.  Reuse the read-side structural walker to prove
    \ that every admitted value is resident in this inode: e_value_inum must
    \ be zero, names and values are bounded and nonoverlapping, and the
    \ packed entry list is ordered and terminated.  No output buffer is live.
    _EXT4-XOP-LIST _EXT4-XA-OP !
    0 _EXT4-XA-TOTAL ! 0 _EXT4-XA-EMIT !
    0 _EXT4-XA-INLINE-FIRST ! 0 _EXT4-XA-INLINE-LIMIT !
    0 _EXT4-XA-CROSS !
    _EXT4-JFI-CTX @ _EXT4-XA-INLINE ;

: _EXT4-JFI-DATA-PREFLIGHT  ( -- ior )
    0 _EXT4-JFI-DATA-ENTRIES !
    0 _EXT4-JFI-DATA-FIRST ! 0 _EXT4-JFI-DATA-COUNT !
    _EXT4-JFI-INODE @ _EXT4-I.BLOCK + DUP _EXT4-JFI-DATA-ROOT !
    DUP W@ _EXT4-EXTENT-MAGIC <> IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    DUP 4 + W@ 4 <> IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    DUP 2 + W@ DUP _EXT4-JFI-DATA-ENTRIES ! 1 U> IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    6 + W@ IF EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT THEN
    _EXT4-JFI-DATA-ENTRIES @ IF
        _EXT4-JFI-DATA-ROOT @ 12 + DUP _EXT4-JFI-DATA-ENTRY !
        DUP L@ IF DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT THEN
        DUP 4 + W@ 1 <> IF
            DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
        THEN
        DUP 6 + W@ IF DROP EXT4-D-BOUNDS _EXT4-CORRUPT EXIT THEN
        8 + L@ DUP _EXT4-JFI-DATA-FIRST ! 0= IF
            EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
        THEN
        1 _EXT4-JFI-DATA-COUNT !
    THEN
    _EXT4-JFI-INODE @ _EXT4-JFI-CTX @ _EXT4-DECODE-I-BLOCKS
    DUP IF NIP EXIT THEN DROP _EXT4-JFI-DATA-BLOCKS !
    _EXT4-JFI-DATA-COUNT @
    _EXT4-JFI-CTX @ _EXT4-C.SPB + @ _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP
    _EXT4-JFI-DATA-BLOCKS @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DATA-COUNT @ IF
        _EXT4-JFI-DATA-FIRST @ _EXT4-JFI-DATA-COUNT @
        _EXT4-JFI-CTX @ _EXT4-VALIDATE-MUTATION-RANGE-TARGETS
        ?DUP IF EXIT THEN
        _EXT4-JFI-DATA-FIRST @ _EXT4-JFI-DATA-COUNT @
        _EXT4-JFI-RECORD @ _EXT4-JFI-CTX @
        _EXT4-ORPHAN-FILE-RANGE-DISJOINT ?DUP IF EXIT THEN
        _EXT4-JFI-REQUIRE-UNIQUE-DATA-OWNER ?DUP IF EXIT THEN
    THEN
    0 ;

\ Authenticate the smallest complete deletion shapes: either an already-empty
\ inode or exactly one initialized logical-zero data extent.  External xattr
\ storage remains outside this slice.  Structurally valid resident inline
\ xattrs die with the inode allocation bit and require no separate release.
: _EXT4-JFI-AUTH-PREFLIGHT  ( -- ior )
    _EXT4-JFI-RECORD @ 0= _EXT4-JFI-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFI-RECORD @ _EXT4-JFI-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ?DUP IF EXIT THEN
    _EXT4-JFI-RECORD @ _EXT4-OE.INO + @ DUP _EXT4-JFI-INO !
    DUP _EXT4-JFI-CTX @ _EXT4-C.SB + _EXT4-SB.FIRST-INO + L@ U< IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DROP
    _EXT4-JFI-CTX @ _EXT4-C.INODE + DUP _EXT4-JFI-INODE !
    DUP _EXT4-I.LINKS + W@ IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.MODE + W@ 0xF000 AND 0x8000 <> IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.SIZE-LO + L@
    OVER _EXT4-I.SIZE-HI + L@ OR IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.FLAGS + L@ DUP _EXT4-EXTENTS-FL AND 0=
    SWAP _EXT4-JOURNAL-DATA-FL AND 0<> OR IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.FILE-ACL-HI + W@
    OVER _EXT4-I.FILE-ACL-LO + L@ OR IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DROP
    _EXT4-JFI-DATA-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-INLINE-XATTR-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-IR-GROUP @ _EXT4-JFI-GROUP !
    _EXT4-IR-INDEX @ _EXT4-JFI-INDEX !
    _EXT4-IR-BLOCK @ _EXT4-JFI-INODE-HOME !
    _EXT4-IR-OFF @ _EXT4-JFI-INODE-OFF !
    _EXT4-JFI-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE !
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-GROUP-INODE-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JFI-GROUP-INODES !
    _EXT4-JFI-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JFI-IOR ! _EXT4-JFI-BITMAP-HOME !
    _EXT4-JFI-IOR @ ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _EXT4-JFI-GDT-HOME !
    _EXT4-GD-OFF @ _EXT4-JFI-GDT-OFF !
    _EXT4-JFI-CTX @ _EXT4-C.DESC + _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @
    _EXT4-VALIDATE-INODE-BITMAP-HOME ?DUP IF EXIT THEN
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JFI-IOR !
    _EXT4-JFI-IOR @ IF DROP _EXT4-JFI-IOR @ EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-GD-BLOCK @ _EXT4-JFI-GDT-HOME @ <>
    _EXT4-GD-OFF @ _EXT4-JFI-GDT-OFF @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFI-DESC-BITMAP-CRC@  ( descriptor -- crc )
    DUP _EXT4-GD.INODE-CSUM-LO + W@
    SWAP _EXT4-GD.INODE-CSUM-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFI-DESC-BITMAP-CRC!  ( crc descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.INODE-CSUM-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.INODE-CSUM-HI + W! ;

: _EXT4-JFI-DESC-FREE@  ( descriptor -- inodes )
    DUP _EXT4-GD.FREE-INODES-LO + W@
    SWAP _EXT4-GD.FREE-INODES-HI + W@ 16 LSHIFT OR ;

: _EXT4-JFI-DESC-FREE!  ( inodes descriptor -- )
    OVER 0xFFFF AND OVER _EXT4-GD.FREE-INODES-LO + W!
    SWAP 16 RSHIFT SWAP _EXT4-GD.FREE-INODES-HI + W! ;

: _EXT4-JFI-VALIDATE-EFFECTIVE-DESC  ( -- ior )
    _EXT4-JFI-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? 0= IF
        EXT4-D-DESC-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.FLAGS + W@
    _EXT4-BG-INODE-UNINIT AND IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-BITMAP-HI + L@
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-TABLE-HI + L@ OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-JFI-DESC-BITMAP-CRC@
    _EXT4-JFI-BITMAP-CRC @ <> IF
        EXT4-D-BITMAP-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-DESC @ _EXT4-JFI-DESC-FREE@ DUP _EXT4-JFI-GROUP-FREE !
    1 _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFI-NEW-GROUP-FREE !
    _EXT4-JFI-GROUP-INODES @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFI-ACQUIRE-DESC  ( -- ior )
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-DESC ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _EXT4-JFI-GDT-HOME @ <>
    _EXT4-GD-OFF @ _EXT4-JFI-GDT-OFF @ <> OR IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-GDT-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    _EXT4-JFI-GDT-OFF @ + _EXT4-JFI-DESC !
    _EXT4-JFI-VALIDATE-EFFECTIVE-DESC ;

: _EXT4-JFI-ACQUIRE-SUPER  ( -- ior )
    _EXT4-JFI-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JFI-SUPER-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JFI-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JFI-IMAGE !
    _EXT4-JFI-SUPER @ _EXT4-SB.FREE-INODES + L@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-NEW-SUPER-FREE !
    _EXT4-JFI-CTX @ _EXT4-C.INODES + @ U> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JFI-PREFLIGHT  ( -- ior )
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-BITMAP-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-CTX @ _EXT4-INODE-BITMAP-CRC
    _EXT4-JFI-BITMAP-CRC !
    _EXT4-JFI-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JFI-ACQUIRE-SUPER ;

: _EXT4-JFI-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JFI-IOR !
    _EXT4-JFI-PUBLISHED @ IF
        _EXT4-JFI-WRITER @ _EXT4-JWR.STATE + @ DUP
        _EXT4-JWR-STAGING = IF
            DROP _EXT4-JFI-WRITER @ _EXT4-JTX-ABORT
            DUP _EXT4-JFI-ABORT-IOR ! IF
                _EXT4-JFI-ABORT-IOR @ _EXT4-JFI-WRITER @
                _EXT4-JWR-LATCH-FAULT DROP
            THEN
        ELSE
            DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
                _EXT4-JFI-IOR @ _EXT4-JFI-WRITER @
                _EXT4-JWR-LATCH-FAULT DROP
            THEN
        THEN
    THEN
    _EXT4-JFI-IOR @ ;

: _EXT4-JFI-STAGE-GROUP  ( -- ior )
    _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JFI-IOR !
    _EXT4-JFI-IOR @ IF DROP _EXT4-JFI-IOR @ EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-BITMAP-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    DUP _EXT4-JFI-CTX @ _EXT4-INODE-BITMAP-CRC
    _EXT4-JFI-BITMAP-CRC !
    DUP _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? 0= IF
        DROP VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-WRITER @ _EXT4-JWR.BSIZE + @ MOVE
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-INDEX @ 1 _EXT4-CLEAR-BIT-RANGE
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-CTX @ _EXT4-INODE-BITMAP-CRC
    _EXT4-JFI-NEW-BITMAP-CRC !
    _EXT4-JFI-ACQUIRE-DESC ?DUP IF EXIT THEN
    _EXT4-JFI-NEW-GROUP-FREE @ _EXT4-JFI-DESC @ _EXT4-JFI-DESC-FREE!
    _EXT4-JFI-NEW-BITMAP-CRC @ _EXT4-JFI-DESC @
    _EXT4-JFI-DESC-BITMAP-CRC!
    _EXT4-JFI-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFI-CTX @
    _EXT4-RESTAMP-GROUP-DESC ?DUP IF EXIT THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-GDT-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    _EXT4-JFI-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

: _EXT4-JFI-STAGE-SUPER  ( -- ior )
    _EXT4-JFI-ACQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFI-NEW-SUPER-FREE @
    _EXT4-JFI-SUPER @ _EXT4-SB.FREE-INODES + L!
    _EXT4-JFI-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM
    _EXT4-JFI-IMAGE @ _EXT4-JFI-SUPER-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

: _EXT4-JFI-STAGE-INODE  ( -- ior )
    _EXT4-JFI-INODE-HOME @ _EXT4-JFI-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFI-CTX @ _EXT4-C.BLOCK + _EXT4-JFI-INODE-HOME @
    _EXT4-JFI-WRITER @ _EXT4-JTX-META-ACQUIRE
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFI-IMAGE !
    _EXT4-JFI-INODE-OFF @ + _EXT4-JFI-INODE @
    _EXT4-JFI-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-IMAGE @ _EXT4-JFI-INODE-OFF @ +
    _EXT4-JFI-CTX @ _EXT4-C.ISIZE + @ 0 FILL
    _EXT4-JFI-IMAGE @ _EXT4-JFI-INODE-HOME @ _EXT4-JFI-WRITER @
    _EXT4-JTX-META-REPLACE ?DUP IF EXIT THEN
    -1 _EXT4-JFI-PUBLISHED !
    0 ;

\ Release allocation authority for one exact unlinked regular-file orphan.
\ First replace its authenticated inode record with zeros so ordinary ext4
\ tools see a clean free record; then release any admitted data block and the
\ inode allocation bit in the same transaction.
: _EXT4-JTX-STAGE-FREE-ORPHAN-INODE
  ( plan-record transaction -- ior )
    _EXT4-JFI-WRITER ! _EXT4-JFI-RECORD !
    0 _EXT4-JFI-PUBLISHED !
    _EXT4-JFI-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFI-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFI-CTX !
    _EXT4-JFI-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-STAGE-INODE ?DUP IF
        _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JFI-DATA-COUNT @ IF
        _EXT4-JFI-DATA-FIRST @ _EXT4-JFI-DATA-COUNT @
        _EXT4-JFI-WRITER @ _EXT4-JTX-STAGE-FREE-BLOCK-RANGE
        ?DUP IF _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT THEN
        -1 _EXT4-JFI-PUBLISHED !
    THEN
    _EXT4-JFI-STAGE-GROUP ?DUP IF
        _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    _EXT4-JFI-STAGE-SUPER ?DUP IF
        _EXT4-JFI-FAIL-AFTER-PUBLISH EXIT
    THEN
    0 ;

\ =====================================================================
\  Plan-bound linked orphan extent truncation after-images
\ =====================================================================

VARIABLE _EXT4-EIB-SECTORS
VARIABLE _EXT4-EIB-INODE
VARIABLE _EXT4-EIB-CTX
VARIABLE _EXT4-EIB-RAW
VARIABLE _EXT4-EIB-LIMIT

\ Encode the on-disk 48-bit i_blocks field without silently changing the
\ HUGE_FILE unit convention.  Callers supply the normalized 512-byte-sector
\ count used by the rest of this driver.
: _EXT4-ENCODE-I-BLOCKS  ( blocks-512 inode ctx -- ior )
    _EXT4-EIB-CTX ! _EXT4-EIB-INODE ! _EXT4-EIB-SECTORS !
    _EXT4-EIB-CTX @ 0= _EXT4-EIB-INODE @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-EIB-SECTORS @ 0< IF VFS-E-INVALID EXIT THEN
    _EXT4-EIB-CTX @ _EXT4-C.SPB + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-EIB-CTX @ _EXT4-C.BLOCKS + @
    _EXT4-EIB-CTX @ _EXT4-C.SPB + @ _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP _EXT4-EIB-LIMIT !
    _EXT4-EIB-SECTORS @ _EXT4-EIB-LIMIT @ U> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EIB-SECTORS @
    _EXT4-EIB-INODE @ _EXT4-I.FLAGS + L@
    _EXT4-HUGE-FILE-FL AND IF
        _EXT4-EIB-CTX @ _EXT4-C.SPB + @ /MOD
        SWAP IF DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT THEN
    THEN
    DUP _EXT4-EIB-RAW ! 0xFFFFFFFFFFFF U> IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-EIB-RAW @ DUP 0xFFFFFFFF AND
    _EXT4-EIB-INODE @ _EXT4-I.BLOCKS-LO + L!
    32 RSHIFT _EXT4-EIB-INODE @ _EXT4-I.BLOCKS-HI + W!
    0 ;

\ Four leaf entries are the format-defined capacity of an inline inode
\ extent root.  Each retained pair is { first physical block, block count }.
CREATE _EXT4-JOT-RANGES 8 CELLS ALLOT

: _EXT4-JOT-RANGE  ( index -- pair-address )
    2 * CELLS _EXT4-JOT-RANGES + ;

VARIABLE _EXT4-JOT-RECORD
VARIABLE _EXT4-JOT-WRITER
VARIABLE _EXT4-JOT-CTX
VARIABLE _EXT4-JOT-INODE
VARIABLE _EXT4-JOT-ROOT
VARIABLE _EXT4-JOT-COUNT
VARIABLE _EXT4-JOT-ENTRY
VARIABLE _EXT4-JOT-LEN
VARIABLE _EXT4-JOT-PHYS
VARIABLE _EXT4-JOT-DATA-BLOCKS
VARIABLE _EXT4-JOT-EA
VARIABLE _EXT4-JOT-EXPECTED
VARIABLE _EXT4-JOT-ACTUAL
VARIABLE _EXT4-JOT-AFTERIMAGE
VARIABLE _EXT4-JOT-IOR
VARIABLE _EXT4-JOT-PUBLISHED
VARIABLE _EXT4-JOT-ABORT-IOR
VARIABLE _EXT4-JOT-OF-ROOT
VARIABLE _EXT4-JOT-OF-COUNT
VARIABLE _EXT4-JOT-OF-INDEX
VARIABLE _EXT4-JOT-OF-TARGET
VARIABLE _EXT4-JOT-OF-ENTRY
VARIABLE _EXT4-JOT-OF-PHYS
VARIABLE _EXT4-JOT-OF-LEN

: _EXT4-JOT-CAPTURE-RANGES  ( -- ior )
    0 _EXT4-JOT-DATA-BLOCKS !
    _EXT4-JOT-COUNT @ 0 ?DO
        _EXT4-JOT-ROOT @ 12 I 12 * + + DUP _EXT4-JOT-ENTRY !
        _EXT4-EXTENT-LEN@ _EXT4-JOT-LEN !
        _EXT4-JOT-ENTRY @ 8 + L@ _EXT4-JOT-PHYS !
        _EXT4-JOT-EA @ IF
            _EXT4-JOT-PHYS @ _EXT4-JOT-LEN @
            _EXT4-JOT-EA @ 1 _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT UNLOOP EXIT
            THEN
        THEN
        _EXT4-JOT-PHYS @ I _EXT4-JOT-RANGE !
        _EXT4-JOT-LEN @ I _EXT4-JOT-RANGE CELL+ !
        _EXT4-JOT-DATA-BLOCKS @ _EXT4-JOT-LEN @ _EXT4-UADD?
        DUP IF NIP UNLOOP EXIT THEN DROP _EXT4-JOT-DATA-BLOCKS !
    LOOP
    0 ;

: _EXT4-JOT-VALIDATE-ACCOUNTING  ( -- ior )
    _EXT4-JOT-DATA-BLOCKS @
    _EXT4-JOT-EA @ IF 1 ELSE 0 THEN
    _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    _EXT4-JOT-CTX @ _EXT4-C.SPB + @ _EXT4-UMUL?
    DUP IF NIP EXIT THEN DROP _EXT4-JOT-EXPECTED !
    _EXT4-JOT-INODE @ _EXT4-JOT-CTX @ _EXT4-DECODE-I-BLOCKS
    DUP IF NIP EXIT THEN DROP _EXT4-JOT-ACTUAL !
    _EXT4-JOT-ACTUAL @ _EXT4-JOT-EXPECTED @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Writable ownership is stricter than read-side map validity.  Narrow the
\ orphan-file shape to one whose complete external ownership is enumerable,
\ then prove that neither a target data range nor its retained external xattr
\ aliases orphan-file storage.  Its inline root resides in an inode table
\ already protected by free-range admission; depth zero and no external EA
\ leave only these leaf ranges.
: _EXT4-JOT-VALIDATE-ORPHAN-FILE-DISJOINT  ( -- ior )
    _EXT4-JOT-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JOT-CTX @ _EXT4-C.INODE +
    DUP _EXT4-I.FLAGS + L@ _EXT4-EXTENTS-FL AND 0= IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    DUP _EXT4-I.FILE-ACL-HI + W@
    OVER _EXT4-I.FILE-ACL-LO + L@ OR IF
        DROP EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-I.BLOCK + DUP _EXT4-JOT-OF-ROOT !
    DUP W@ _EXT4-EXTENT-MAGIC <> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DUP 4 + W@ 4 <> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    DUP 2 + W@ DUP _EXT4-JOT-OF-COUNT ! 4 U> IF
        DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    6 + W@ IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    \ Include full preallocated/unwritten ranges beyond EOF in the ownership
    \ proof; the logical stream below authenticates only blocks inside size.
    0 _EXT4-JOT-OF-INDEX !
    BEGIN _EXT4-JOT-OF-INDEX @ _EXT4-JOT-OF-COUNT @ < WHILE
        _EXT4-JOT-OF-ROOT @ 12
        _EXT4-JOT-OF-INDEX @ 12 * + + DUP _EXT4-JOT-OF-ENTRY !
        DUP _EXT4-EXTENT-LEN@ _EXT4-JOT-OF-LEN !
        8 + L@ _EXT4-JOT-OF-PHYS !
        _EXT4-JOT-EA @ IF
            _EXT4-JOT-EA @ 1
            _EXT4-JOT-OF-PHYS @ _EXT4-JOT-OF-LEN @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
        THEN
        0 _EXT4-JOT-OF-TARGET !
        BEGIN _EXT4-JOT-OF-TARGET @ _EXT4-JOT-COUNT @ < WHILE
            _EXT4-JOT-OF-TARGET @ _EXT4-JOT-RANGE DUP @
            SWAP CELL+ @
            _EXT4-JOT-OF-PHYS @ _EXT4-JOT-OF-LEN @
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            1 _EXT4-JOT-OF-TARGET +!
        REPEAT
        1 _EXT4-JOT-OF-INDEX +!
    REPEAT
    0 _EXT4-JOT-OF-INDEX !
    BEGIN _EXT4-JOT-OF-INDEX @ _EXT4-OV-BLOCKS @ < WHILE
        _EXT4-JOT-OF-INDEX @ _EXT4-JOT-CTX @
        _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        0 _EXT4-JOT-OF-TARGET !
        BEGIN _EXT4-JOT-OF-TARGET @ _EXT4-JOT-COUNT @ < WHILE
            _EXT4-JOT-OF-TARGET @ _EXT4-JOT-RANGE DUP @
            SWAP CELL+ @
            _EXT4-OV-PHYS @ 1
            _EXT4-BLOCK-RANGES-OVERLAP? IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            1 _EXT4-JOT-OF-TARGET +!
        REPEAT
        1 _EXT4-JOT-OF-INDEX +!
    REPEAT
    \ PREPARE leaves the orphan inode cached; restore and reauthenticate the
    \ target before the caller copies its proposed afterimage.
    _EXT4-JOT-RECORD @ _EXT4-JOT-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ;

: _EXT4-JOT-PREFLIGHT  ( -- ior )
    _EXT4-JOT-INODE @ _EXT4-I.LINKS + W@ 0= IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.MODE + W@ 0xF000 AND 0x8000 <> IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.SIZE-LO + L@
    _EXT4-JOT-INODE @ _EXT4-I.SIZE-HI + L@ OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.FLAGS + L@
    DUP _EXT4-EXTENTS-FL AND 0=
    SWAP _EXT4-JOURNAL-DATA-FL AND 0<> OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.BLOCK + DUP _EXT4-JOT-ROOT !
    DUP W@ _EXT4-EXTENT-MAGIC <> IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    DUP 4 + W@ 4 <> IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    DUP 2 + W@ DUP _EXT4-JOT-COUNT ! 4 U> IF
        DROP EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    6 + W@ IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.FILE-ACL-HI + W@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JOT-INODE @ _EXT4-I.FILE-ACL-LO + L@ DUP _EXT4-JOT-EA ! IF
        _EXT4-JOT-EA @ EXT4-D-XATTR _EXT4-JOT-CTX @
        _EXT4-REQUIRE-ALLOCATED-BLOCK ?DUP IF EXIT THEN
        _EXT4-JOT-EA @ _EXT4-JOT-CTX @ _EXT4-LOAD-XATTR-BLOCK
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JOT-CAPTURE-RANGES ?DUP IF EXIT THEN
    _EXT4-JOT-VALIDATE-ACCOUNTING ?DUP IF EXIT THEN
    _EXT4-JOT-VALIDATE-ORPHAN-FILE-DISJOINT ;

\ Bind the retained record to its raw target inode and capture the complete
\ depth-zero ownership ranges without acquiring or changing a transaction.
\ The final orphan-file disjointness pass restores the target inode cache and
\ its _EXT4-IR locator before returning.
: _EXT4-JOT-AUTH-PREFLIGHT  ( -- ior )
    _EXT4-JOT-RECORD @ 0= _EXT4-JOT-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JOT-RECORD @ _EXT4-JOT-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ?DUP IF EXIT THEN
    _EXT4-JOT-CTX @ _EXT4-C.INODE + _EXT4-JOT-INODE !
    _EXT4-JOT-PREFLIGHT ;

: _EXT4-JOT-BUILD-INODE  ( -- ior )
    _EXT4-JOT-WRITER @ _EXT4-JWR.SCRATCH-B + @ DUP
    _EXT4-JOT-AFTERIMAGE !
    _EXT4-JOT-INODE @ SWAP _EXT4-JOT-CTX @ _EXT4-C.ISIZE + @ MOVE
    _EXT4-JOT-AFTERIMAGE @ _EXT4-I.BLOCK +
    0 OVER 2 + W!
    12 + 48 0 FILL
    _EXT4-JOT-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        _EXT4-JOT-AFTERIMAGE @ _EXT4-I.DTIME + L@ IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JOT-EA @ IF
        _EXT4-JOT-CTX @ _EXT4-C.SPB + @
    ELSE
        0
    THEN
    _EXT4-JOT-AFTERIMAGE @ _EXT4-JOT-CTX @ _EXT4-ENCODE-I-BLOCKS ;

\ If a lower range-free preflight fails, it has not necessarily published
\ enough state to trigger its own abort.  Once the inode image exists, this
\ outer operation owns the atomic discard boundary.  A lower auto-abort is
\ observable as IDLE and must not be aborted a second time.
: _EXT4-JOT-FAIL-AFTER-PUBLISH  ( ior -- ior )
    _EXT4-JOT-IOR !
    _EXT4-JOT-PUBLISHED @ IF
        _EXT4-JOT-WRITER @ _EXT4-JWR.STATE + @ DUP
        _EXT4-JWR-STAGING = IF
            DROP
            _EXT4-JOT-WRITER @ _EXT4-JTX-ABORT
            DUP _EXT4-JOT-ABORT-IOR ! IF
                _EXT4-JOT-ABORT-IOR @
                _EXT4-JOT-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _EXT4-JOT-WRITER @ _EXT4-JWR.STATE + !
            THEN
        ELSE
            DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
                _EXT4-JOT-IOR @
                _EXT4-JOT-WRITER @ _EXT4-JWR.FAULT + !
                _EXT4-JWR-FAULTED
                _EXT4-JOT-WRITER @ _EXT4-JWR.STATE + !
            THEN
        THEN
    THEN
    _EXT4-JOT-IOR @ ;

\ Complete the storage half of an interrupted linked-file truncation whose
\ new size is already zero and whose old map fits the inode's depth-zero
\ extent root.  The external xattr block remains referenced.  This operation
\ intentionally leaves the authenticated orphan record active: slot/list
\ removal is a later protocol-completion step after truncation is durable.
: _EXT4-JTX-STAGE-ORPHAN-DEPTH0-TRUNCATE
  ( plan-record transaction -- ior )
    _EXT4-JOT-WRITER ! _EXT4-JOT-RECORD !
    0 _EXT4-JOT-PUBLISHED !
    _EXT4-JOT-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JOT-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JOT-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JOT-CTX !
    _EXT4-JOT-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JOT-COUNT @ 0= IF 0 EXIT THEN
    _EXT4-JOT-BUILD-INODE ?DUP IF EXIT THEN
    _EXT4-JOT-AFTERIMAGE @ _EXT4-JOT-RECORD @ _EXT4-JOT-WRITER @
    _EXT4-JTX-STAGE-ORPHAN-INODE ?DUP IF EXIT THEN
    -1 _EXT4-JOT-PUBLISHED !
    _EXT4-JOT-COUNT @ 0 ?DO
        I _EXT4-JOT-RANGE @
        I _EXT4-JOT-RANGE CELL+ @
        _EXT4-JOT-WRITER @ _EXT4-JTX-STAGE-FREE-BLOCK-RANGE
        ?DUP IF _EXT4-JOT-FAIL-AFTER-PUBLISH UNLOOP EXIT THEN
    LOOP
    0 ;

VARIABLE _EXT4-JFC-RECORD
VARIABLE _EXT4-JFC-WRITER
VARIABLE _EXT4-JFC-CTX
VARIABLE _EXT4-JFC-INO
VARIABLE _EXT4-JFC-LOGICAL
VARIABLE _EXT4-JFC-SLOT
VARIABLE _EXT4-JFC-TARGET-GEN
VARIABLE _EXT4-JFC-TARGET-HOME
VARIABLE _EXT4-JFC-TARGET-OFF
VARIABLE _EXT4-JFC-TARGET-ENTRIES
VARIABLE _EXT4-JFC-O-HOME
VARIABLE _EXT4-JFC-O-GEN
VARIABLE _EXT4-JFC-INDEX
VARIABLE _EXT4-JFC-FOUND
VARIABLE _EXT4-JFC-IOR
VARIABLE _EXT4-JFC-ENTRY
VARIABLE _EXT4-JFC-IMAGE
VARIABLE _EXT4-JFC-TARGET-CRC
VARIABLE _EXT4-JFC-ORPHAN-CRC
VARIABLE _EXT4-JFC-ABORT-IOR
VARIABLE _EXT4-JFC-KIND
VARIABLE _EXT4-JFC-MODE
VARIABLE _EXT4-JFC-SUPER
VARIABLE _EXT4-JFC-TARGET
VARIABLE _EXT4-JFC-DELETE
VARIABLE _EXT4-JFC-INODE-BITMAP-HOME
VARIABLE _EXT4-JFC-INODE-BITMAP-CRC
VARIABLE _EXT4-JFC-INODE-GDT-HOME
VARIABLE _EXT4-JFC-INODE-GDT-OFF
VARIABLE _EXT4-JFC-INODE-GDT-CRC
VARIABLE _EXT4-JFC-INODE-SUPER-CRC
VARIABLE _EXT4-JFC-DATA-FIRST
VARIABLE _EXT4-JFC-DATA-COUNT

: _EXT4-JFC-FIND-META  ( home writer -- ior )
    DUP _EXT4-JFC-WRITER ! >R
    R@ _EXT4-JWR.META-ENTRIES + @
    _EXT4-JWR-IMAGE-ENTRY-CELLS
    R@ _EXT4-JWR.META-HASH + @
    R@ _EXT4-JWR.META-SLOTS + @
    R@ _EXT4-JWR.META-USED + @
    _EXT4-JTX-HASH-FIND
    _EXT4-JFC-IOR ! _EXT4-JFC-FOUND ! _EXT4-JFC-INDEX !
    R> DROP
    _EXT4-JFC-IOR @ ?DUP IF EXIT THEN
    0 _EXT4-JFC-ENTRY ! 0 _EXT4-JFC-IMAGE !
    _EXT4-JFC-FOUND @ 0= IF 0 EXIT THEN
    _EXT4-JFC-INDEX @ _EXT4-JFC-WRITER @ _EXT4-JWR-META-ENTRY
    DUP _EXT4-JFC-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-INDEX @ _EXT4-JFC-WRITER @ _EXT4-JWR-META-IMAGE
    DUP _EXT4-JFC-IMAGE ! _EXT4-JFC-WRITER @ _EXT4-JTX-IMAGE-CRC
    _EXT4-JFC-ENTRY @ 2 CELLS + @ <> IF VFS-E-CORRUPT EXIT THEN
    0 ;

VARIABLE _EXT4-JFD-RECORD
VARIABLE _EXT4-JFD-WRITER
VARIABLE _EXT4-JFD-CTX
VARIABLE _EXT4-JFD-RAW-DESC
VARIABLE _EXT4-JFD-STAGED-DESC
VARIABLE _EXT4-JFD-RAW-GROUP-FREE
VARIABLE _EXT4-JFD-EXPECTED-GROUP-FREE
VARIABLE _EXT4-JFD-RAW-SUPER-FREE
VARIABLE _EXT4-JFD-EXPECTED-SUPER-FREE
VARIABLE _EXT4-JFD-BITMAP-CHECKSUM
VARIABLE _EXT4-JFD-RAW-BITMAP
VARIABLE _EXT4-JFD-STAGED-BITMAP
VARIABLE _EXT4-JFD-BITMAP-BYTE
VARIABLE _EXT4-JFD-BITMAP-MASK
VARIABLE _EXT4-JFD-COMPARE-OFF
VARIABLE _EXT4-JFD-COMPARE-LEN
VARIABLE _EXT4-JFD-RAW-GDT
VARIABLE _EXT4-JFD-STAGED-GDT
VARIABLE _EXT4-JFD-RAW-SUPER-HOME
VARIABLE _EXT4-JFD-STAGED-SUPER-HOME
VARIABLE _EXT4-JFD-RAW-SUPER
VARIABLE _EXT4-JFD-RAW-TARGET-HOME
VARIABLE _EXT4-JFD-STAGED-TARGET-HOME

: _EXT4-JFD-TARGET-HOME-EXACT?  ( -- flag )
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ 0 ?DO
        _EXT4-JFD-RAW-TARGET-HOME @ I + C@
        I _EXT4-JFI-INODE-OFF @ >=
        I _EXT4-JFI-INODE-OFF @
        _EXT4-JFD-CTX @ _EXT4-C.ISIZE + @ + U< AND IF
            DROP 0
        THEN
        _EXT4-JFD-STAGED-TARGET-HOME @ I + C@ <> IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

: _EXT4-JFD-REQUIRE-ZERO-TARGET  ( -- ior )
    _EXT4-JFI-INODE-HOME @ _EXT4-JFD-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + DUP
    _EXT4-JFD-RAW-TARGET-HOME !
    _EXT4-JFI-INODE-OFF @ + _EXT4-JFI-INODE @
    _EXT4-JFD-CTX @ _EXT4-C.ISIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFI-INODE-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-TARGET-CRC !
    _EXT4-JFC-IMAGE @ _EXT4-JFD-STAGED-TARGET-HOME !
    _EXT4-JFD-TARGET-HOME-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JFD-BITMAP-EXACT?  ( -- flag )
    _EXT4-JFI-INDEX @ DUP 8 / _EXT4-JFD-BITMAP-BYTE !
    8 MOD 1 SWAP LSHIFT _EXT4-JFD-BITMAP-MASK !
    \ The journal entry replaces the whole home block.  Bytes beyond the
    \ meaningful inode-bit count are padding, but they are still part of the
    \ after-image and therefore must remain byte-identical.
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ 0 ?DO
        _EXT4-JFD-RAW-BITMAP @ I + C@
        I _EXT4-JFD-BITMAP-BYTE @ = IF
            _EXT4-JFD-BITMAP-MASK @ INVERT AND
        THEN
        _EXT4-JFD-STAGED-BITMAP @ I + C@ <> IF
            FALSE UNLOOP EXIT
        THEN
    LOOP
    TRUE ;

: _EXT4-JFD-DESC-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN ! _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-DESC @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-GDT-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN ! _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-GDT @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-GDT @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-GDT-EXACT?  ( -- flag )
    \ Permit only the target descriptor's free-inode count, inode-bitmap
    \ checksum, and descriptor checksum.  Other descriptors and page padding
    \ are just as authoritative as the target descriptor itself.
    0 _EXT4-JFI-GDT-OFF @ 0x0E + _EXT4-JFD-GDT-RANGE-UNCHANGED?
    _EXT4-JFI-GDT-OFF @ 0x10 + 0x0A
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x1C + 0x02
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x20 + 0x0E
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x30 + 0x0A
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND
    _EXT4-JFI-GDT-OFF @ 0x3C + DUP
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ SWAP -
    _EXT4-JFD-GDT-RANGE-UNCHANGED? AND ;

: _EXT4-JFD-SUPER-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN !
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-SUPER-HOME-RANGE-UNCHANGED?  ( offset length -- flag )
    _EXT4-JFD-COMPARE-LEN ! _EXT4-JFD-COMPARE-OFF !
    _EXT4-JFD-RAW-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-STAGED-SUPER-HOME @ _EXT4-JFD-COMPARE-OFF @ +
    _EXT4-JFD-COMPARE-LEN @ _EXT4-BYTES=? ;

: _EXT4-JFD-SUPER-HOME-EXACT?  ( -- flag )
    \ Bytes before the embedded superblock are part of block zero on 2K/4K
    \ filesystems.  Preserve them along with every super field except the
    \ free-inode count, the legacy head transition, and the checksum stamp.
    0 _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x10 +
    _EXT4-JFD-SUPER-HOME-RANGE-UNCHANGED?
    0x14
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        0xE8 0x14 -
    ELSE
        0x3FC 0x14 -
    THEN
    _EXT4-JFD-SUPER-RANGE-UNCHANGED? AND
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        0xEC 0x3FC 0xEC - _EXT4-JFD-SUPER-RANGE-UNCHANGED? AND
    THEN
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF 0x400 + DUP
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ SWAP -
    _EXT4-JFD-SUPER-HOME-RANGE-UNCHANGED? AND ;

: _EXT4-JFD-DESC-UNCHANGED?  ( -- flag )
    \ The only semantic changes are the split free-inode counter and the
    \ split inode-bitmap checksum.  The descriptor checksum is restamped.
    \ Compare every remaining byte, including exclude-bitmap and reserved
    \ fields, instead of maintaining a permissive list of named fields.
    0x00 0x0E _EXT4-JFD-DESC-RANGE-UNCHANGED?
    0x10 0x0A _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x1C 0x02 _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x20 0x0E _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x30 0x0A _EXT4-JFD-DESC-RANGE-UNCHANGED? AND
    0x3C 0x04 _EXT4-JFD-DESC-RANGE-UNCHANGED? AND ;

\ Rebuild raw unlinked-inode authority, then prove the complete staged
\ allocation transition: one cleared bitmap bit, its matching descriptor
\ checksum/counter update, and the matching primary-super counter update.
: _EXT4-JFD-VERIFY-EMPTY-STAGED  ( plan-record writer -- ior )
    DUP _EXT4-JFD-WRITER ! _EXT4-JFC-WRITER !
    _EXT4-JFD-RECORD !
    _EXT4-JFD-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JFD-CTX !
    _EXT4-JFI-CTX !
    _EXT4-JFD-RECORD @ _EXT4-JFI-RECORD !
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + _EXT4-JFD-RAW-BITMAP !
    _EXT4-JFD-CTX @ _EXT4-C.DESC + DUP _EXT4-JFD-RAW-DESC !
    _EXT4-JFI-DESC-FREE@ DUP _EXT4-JFD-RAW-GROUP-FREE !
    1 _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFD-EXPECTED-GROUP-FREE !
    _EXT4-JFI-GROUP-INODES @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.FREE-INODES + L@
    DUP _EXT4-JFD-RAW-SUPER-FREE ! 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JFD-EXPECTED-SUPER-FREE !
    _EXT4-JFD-CTX @ _EXT4-C.INODES + @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-INODE-BITMAP-CRC !
    _EXT4-JFC-IMAGE @ DUP _EXT4-JFD-STAGED-BITMAP !
    _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-BITMAP-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFD-CTX @ _EXT4-INODE-BITMAP-CRC
    _EXT4-JFD-BITMAP-CHECKSUM !
    _EXT4-JFI-GDT-HOME @ _EXT4-JFD-CTX @ _EXT4-READ-BLOCK
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + DUP _EXT4-JFD-RAW-GDT !
    _EXT4-JFI-GDT-OFF @ + DUP _EXT4-JFD-RAW-DESC !
    _EXT4-JFD-CTX @ _EXT4-C.DESC + _EXT4-DESC-SIZE
    _EXT4-BYTES=? 0= IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JFI-GDT-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-INODE-GDT-CRC !
    _EXT4-JFC-IMAGE @ DUP _EXT4-JFD-STAGED-GDT !
    _EXT4-JFI-GDT-OFF @ + _EXT4-JFD-STAGED-DESC !
    _EXT4-JFD-GDT-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-DESC-UNCHANGED? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-JFI-BITMAP-HOME @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFI-DESC-BITMAP-CRC@
    _EXT4-JFD-BITMAP-CHECKSUM @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-STAGED-DESC @ _EXT4-JFI-DESC-FREE@
    _EXT4-JFD-EXPECTED-GROUP-FREE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JFD-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-INODE-SUPER-CRC !
    _EXT4-JFC-IMAGE @ DUP _EXT4-JFD-STAGED-SUPER-HOME !
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-JFC-SUPER ! DROP
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JFD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK + DUP _EXT4-JFD-RAW-SUPER-HOME !
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-JFD-RAW-SUPER !
    _EXT4-JFD-CTX @ _EXT4-C.SB + 1024 _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFD-SUPER-HOME-EXACT? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-SUPER @
    DUP _EXT4-SUPER-CHECKSUM? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-SUPER-SEED? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    DUP 0 _EXT4-JFD-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-JFD-CTX @ _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF NIP EXIT THEN
    DUP _EXT4-SB.FREE-INODES + L@
    _EXT4-JFD-EXPECTED-SUPER-FREE @ <> IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.FREE-BLOCKS-LO + L@ <>
    OVER _EXT4-SB.FREE-BLOCKS-HI + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.FREE-BLOCKS-HI + L@ <> OR IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP _EXT4-SB.INCOMPAT + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <>
    SWAP _EXT4-SB.RO-COMPAT + L@
    _EXT4-JFD-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFD-REQUIRE-ZERO-TARGET ?DUP IF EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFC-INODE-BITMAP-HOME !
    _EXT4-JFI-GDT-HOME @ _EXT4-JFC-INODE-GDT-HOME !
    _EXT4-JFI-GDT-OFF @ _EXT4-JFC-INODE-GDT-OFF !
    0 ;

VARIABLE _EXT4-JDD-EXPECTED
VARIABLE _EXT4-JDD-HOME
VARIABLE _EXT4-JDD-IOR
VARIABLE _EXT4-JDD-DATA-GROUP
VARIABLE _EXT4-JDD-DATA-INDEX
VARIABLE _EXT4-JDD-DATA-GROUP-BLOCKS
VARIABLE _EXT4-JDD-DATA-BITMAP-HOME
VARIABLE _EXT4-JDD-DATA-BITMAP-CRC
VARIABLE _EXT4-JDD-INODE-BITMAP-CRC
VARIABLE _EXT4-JDD-DATA-GDT-HOME
VARIABLE _EXT4-JDD-DATA-GDT-OFF
VARIABLE _EXT4-JDD-DESC
VARIABLE _EXT4-JDD-FREE
VARIABLE _EXT4-JDD-CHANGED
VARIABLE _EXT4-JDD-GDT-CRC
VARIABLE _EXT4-JDD-SUPER-HOME
VARIABLE _EXT4-JDD-SUPER
VARIABLE _EXT4-JDD-EXPECTED-CREDIT

: _EXT4-JDD-REQUIRE-EXPECTED  ( expected home -- crc ior )
    _EXT4-JDD-HOME ! _EXT4-JDD-EXPECTED !
    _EXT4-JDD-HOME @ _EXT4-JFD-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF 0 VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-EXPECTED @ _EXT4-JFC-IMAGE @
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
        0 VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ 0 ;

: _EXT4-JDD-AUTH-DATA-LOCATOR  ( -- ior )
    _EXT4-JFI-DATA-FIRST @ _EXT4-JFD-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-JFD-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-JDD-DATA-GROUP ! _EXT4-JDD-DATA-INDEX !
    _EXT4-JDD-DATA-GROUP @ _EXT4-JFD-CTX @ _EXT4-GROUP-BLOCK-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-DATA-GROUP-BLOCKS !
    _EXT4-JDD-DATA-INDEX @ _EXT4-JDD-DATA-GROUP-BLOCKS @ U< 0= IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-DATA-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JDD-IOR ! _EXT4-JDD-DATA-BITMAP-HOME !
    _EXT4-JDD-IOR @ ?DUP IF EXIT THEN
    _EXT4-JDD-DATA-BITMAP-HOME @ _EXT4-JDD-DATA-GROUP @
    _EXT4-JFD-CTX @ _EXT4-VALIDATE-BLOCK-BITMAP-HOME ?DUP IF EXIT THEN
    _EXT4-JDD-DATA-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JDD-IOR !
    _EXT4-JDD-IOR @ IF DROP _EXT4-JDD-IOR @ EXIT THEN
    _EXT4-JDD-DATA-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JDD-DATA-INDEX @ 1 _EXT4-BIT-RANGE-SET? 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JDD-DATA-INDEX @ 1 _EXT4-CLEAR-BIT-RANGE
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-BLOCK-BITMAP-CRC
    _EXT4-JDD-DATA-BITMAP-CRC !
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JDD-DATA-BITMAP-HOME @ _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN 2DROP
    _EXT4-JDD-DATA-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-DESC
    ?DUP IF EXIT THEN
    _EXT4-GD-BLOCK @ _EXT4-JDD-DATA-GDT-HOME !
    _EXT4-GD-OFF @ _EXT4-JDD-DATA-GDT-OFF !
    _EXT4-JFD-CTX @ _EXT4-C.DESC + _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JDD-DATA-BITMAP-HOME @ <> IF
        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-JDD-REQUIRE-INODE-BITMAP  ( -- ior )
    _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JDD-IOR !
    _EXT4-JDD-IOR @ IF DROP _EXT4-JDD-IOR @ EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ <> IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFI-INDEX @ 1 _EXT4-BIT-RANGE-SET? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFI-INDEX @ 1 _EXT4-CLEAR-BIT-RANGE
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-INODE-BITMAP-CRC
    _EXT4-JDD-INODE-BITMAP-CRC !
    _EXT4-JFD-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN DROP _EXT4-JFC-INODE-BITMAP-CRC !
    0 ;

: _EXT4-JDD-MUTATE-DATA-DESC  ( descriptor -- ior )
    _EXT4-JDD-DESC !
    _EXT4-JDD-DESC @ _EXT4-JDD-DATA-GROUP @ _EXT4-JFD-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-GD.BLOCK-BITMAP-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.BLOCK-BITMAP-LO + L@
    _EXT4-JDD-DATA-BITMAP-HOME @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-JFB-DESC-FREE@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JDD-FREE !
    _EXT4-JDD-DATA-GROUP-BLOCKS @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-FREE @ _EXT4-JDD-DESC @ _EXT4-JFB-DESC-FREE!
    _EXT4-JDD-DATA-BITMAP-CRC @ _EXT4-JDD-DESC @
    _EXT4-JFB-DESC-BITMAP-CRC!
    _EXT4-JDD-DESC @ _EXT4-JDD-DATA-GROUP @ _EXT4-JFD-CTX @
    _EXT4-RESTAMP-GROUP-DESC ;

: _EXT4-JDD-MUTATE-INODE-DESC  ( descriptor -- ior )
    _EXT4-JDD-DESC !
    _EXT4-JDD-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @
    _EXT4-GROUP-DESC-CHECKSUM? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-BITMAP-HI + L@
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-TABLE-HI + L@ OR IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-BITMAP-LO + L@
    _EXT4-JFI-BITMAP-HOME @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-GD.INODE-TABLE-LO + L@
    _EXT4-JFI-INODE-TABLE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-DESC @ _EXT4-JFI-DESC-FREE@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP DUP _EXT4-JDD-FREE !
    _EXT4-JFI-GROUP-INODES @ U> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-FREE @ _EXT4-JDD-DESC @ _EXT4-JFI-DESC-FREE!
    _EXT4-JDD-INODE-BITMAP-CRC @ _EXT4-JDD-DESC @
    _EXT4-JFI-DESC-BITMAP-CRC!
    _EXT4-JDD-DESC @ _EXT4-JFI-GROUP @ _EXT4-JFD-CTX @
    _EXT4-RESTAMP-GROUP-DESC ;

: _EXT4-JDD-REQUIRE-GDT-HOME  ( home -- ior )
    DUP _EXT4-JDD-HOME ! _EXT4-JFD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    0 _EXT4-JDD-CHANGED !
    _EXT4-JDD-HOME @ _EXT4-JDD-DATA-GDT-HOME @ = IF
        _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JDD-DATA-GDT-OFF @ + _EXT4-JDD-MUTATE-DATA-DESC
        ?DUP IF EXIT THEN
        -1 _EXT4-JDD-CHANGED !
    THEN
    _EXT4-JDD-HOME @ _EXT4-JFI-GDT-HOME @ = IF
        _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-JFI-GDT-OFF @ + _EXT4-JDD-MUTATE-INODE-DESC
        ?DUP IF EXIT THEN
        -1 _EXT4-JDD-CHANGED !
    THEN
    _EXT4-JDD-CHANGED @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK + _EXT4-JDD-HOME @
    _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN DROP _EXT4-JDD-GDT-CRC !
    _EXT4-JDD-HOME @ _EXT4-JFI-GDT-HOME @ = IF
        _EXT4-JDD-GDT-CRC @ _EXT4-JFC-INODE-GDT-CRC !
    THEN
    0 ;

: _EXT4-JDD-REQUIRE-SUPER  ( -- ior )
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-BLOCK DUP
    _EXT4-JDD-SUPER-HOME !
    _EXT4-JFD-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    _EXT4-JFD-CTX @ _EXT4-C.SB + 1024 _EXT4-BYTES=? 0= IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JFD-CTX @ _EXT4-C.BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-C.BSIZE + @ MOVE
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JFD-CTX @ _EXT4-PRIMARY-SUPER-OFF + _EXT4-JDD-SUPER !
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L@ IF
        EXT4-D-BOUNDS _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L@
    _EXT4-JFI-DATA-COUNT @
    _EXT4-UADD? DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFD-CTX @ _EXT4-C.BLOCKS + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-LO + L!
    0 _EXT4-JDD-SUPER @ _EXT4-SB.FREE-BLOCKS-HI + L!
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-INODES + L@ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP
    DUP _EXT4-JFD-CTX @ _EXT4-C.INODES + @ U> IF
        DROP EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SB.FREE-INODES + L!
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY = IF
        _EXT4-JDD-SUPER @ _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JFD-RECORD @ _EXT4-OE.INO + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        0 _EXT4-JDD-SUPER @ _EXT4-SB.LAST-ORPHAN + L!
    THEN
    _EXT4-JDD-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM
    _EXT4-JDD-SUPER @ _EXT4-SUPER-CHECKSUM? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ _EXT4-SUPER-SEED? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDD-SUPER @ 0 _EXT4-JFD-CTX @ _EXT4-C.SB +
    _EXT4-SUPER-INVARIANTS? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-SUPER @ _EXT4-JFD-CTX @
    _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
    ?DUP IF EXIT THEN
    _EXT4-JFD-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-JDD-SUPER-HOME @ _EXT4-JDD-REQUIRE-EXPECTED
    DUP IF NIP EXIT THEN DROP _EXT4-JFC-INODE-SUPER-CRC !
    0 ;


: _EXT4-JDD-VERIFY-STAGED  ( -- ior )
    _EXT4-JFI-DATA-COUNT @ 1 <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDD-AUTH-DATA-LOCATOR ?DUP IF EXIT THEN
    _EXT4-JDD-REQUIRE-INODE-BITMAP ?DUP IF EXIT THEN
    _EXT4-JDD-DATA-GDT-HOME @ _EXT4-JDD-REQUIRE-GDT-HOME
    ?DUP IF EXIT THEN
    _EXT4-JDD-DATA-GDT-HOME @ _EXT4-JFI-GDT-HOME @ <> IF
        _EXT4-JFI-GDT-HOME @ _EXT4-JDD-REQUIRE-GDT-HOME
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JDD-REQUIRE-SUPER ?DUP IF EXIT THEN
    _EXT4-JFD-REQUIRE-ZERO-TARGET ?DUP IF EXIT THEN
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFC-INODE-BITMAP-HOME !
    _EXT4-JFI-GDT-HOME @ _EXT4-JFC-INODE-GDT-HOME !
    _EXT4-JFI-GDT-OFF @ _EXT4-JFC-INODE-GDT-OFF !
    _EXT4-JFD-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        6
    ELSE
        5
    THEN
    _EXT4-JDD-DATA-GDT-HOME @ _EXT4-JFI-GDT-HOME @ <> IF 1+ THEN
    _EXT4-JDD-EXPECTED-CREDIT !
    _EXT4-JFD-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JDD-EXPECTED-CREDIT @ <>
    _EXT4-JFD-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JDD-EXPECTED-CREDIT @ <> OR
    _EXT4-JFD-WRITER @ _EXT4-JWR.META-CREDIT + @
    _EXT4-JDD-EXPECTED-CREDIT @ <> OR IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JFD-VERIFY-STAGED  ( plan-record writer -- ior )
    _EXT4-JFD-WRITER ! _EXT4-JFD-RECORD !
    _EXT4-JFD-WRITER @ _EXT4-JFC-WRITER !
    _EXT4-JFD-WRITER @ _EXT4-JWR.CTX + @ DUP
    _EXT4-JFD-CTX ! _EXT4-JFI-CTX !
    _EXT4-JFD-RECORD @ _EXT4-JFI-RECORD !
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JFI-DATA-COUNT @ IF _EXT4-JDD-VERIFY-STAGED EXIT THEN
    _EXT4-JFD-RECORD @ _EXT4-JFD-WRITER @
    _EXT4-JFD-VERIFY-EMPTY-STAGED ;

: _EXT4-JFC-FAIL  ( ior -- ior )
    _EXT4-JFC-IOR !
    _EXT4-JFC-WRITER @ _EXT4-JWR.STATE + @ DUP
    _EXT4-JWR-STAGING = IF
        DROP _EXT4-JFC-WRITER @ _EXT4-JTX-ABORT
        DUP _EXT4-JFC-ABORT-IOR ! IF
            _EXT4-JFC-ABORT-IOR @ _EXT4-JFC-WRITER @
            _EXT4-JWR-LATCH-FAULT DROP
        THEN
    ELSE
        DUP _EXT4-JWR-IDLE = SWAP _EXT4-JWR-FAULTED = OR 0= IF
            _EXT4-JFC-IOR @ _EXT4-JFC-WRITER @
            _EXT4-JWR-LATCH-FAULT DROP
        THEN
    THEN
    _EXT4-JFC-IOR @ ;

VARIABLE _EXT4-SMO-RECORD
VARIABLE _EXT4-SMO-CTX
VARIABLE _EXT4-SMO-KIND

\ Require one exact retained singleton plan record before dereferencing any of
\ its fields.  Modern authority is one occupied orphan-file slot with an empty
\ legacy head.  Legacy authority is one list head whose retained successor is
\ already zero; ORPHAN_PRESENT may independently describe an empty modern file.
: _EXT4-REQUIRE-SINGLETON-ORPHAN
  ( plan-record ctx -- ior )
    _EXT4-SMO-CTX ! _EXT4-SMO-RECORD !
    _EXT4-SMO-RECORD @ 0= _EXT4-SMO-CTX @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-SMO-CTX @ _EXT4-C.O.ACTIVE + @ 1 <> IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-SMO-RECORD @ _EXT4-SMO-CTX @
    _EXT4-ORPHAN-PLAN-MEMBER? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SMO-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-SMO-KIND !
    _EXT4-OK-MODERN = IF
        _EXT4-SMO-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ 1 <>
        _EXT4-SMO-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ 0<> OR IF
            EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.SB + DUP
        _EXT4-SB.LAST-ORPHAN + L@ IF
            DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SB.RO-COMPAT + L@ _EXT4-RO-ORPHAN-PRESENT AND 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-SMO-KIND @ _EXT4-OK-LEGACY <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ 0<>
        _EXT4-SMO-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ 1 <> OR IF
            EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-A + @
        _EXT4-SMO-RECORD @ _EXT4-OE.LOCATOR-B + @ OR IF
            EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-SMO-CTX @ _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-SMO-RECORD @ _EXT4-OE.INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-SMO-RECORD @ _EXT4-SMO-CTX @
    _EXT4-REAUTH-ORPHAN-PLAN-RECORD ;

: _EXT4-JFC-REQUIRE-SINGLETON  ( -- ior )
    _EXT4-JFC-RECORD @ _EXT4-JFC-CTX @
    _EXT4-REQUIRE-SINGLETON-ORPHAN ;

VARIABLE _EXT4-JLH-RECORD
VARIABLE _EXT4-JLH-WRITER
VARIABLE _EXT4-JLH-CTX
VARIABLE _EXT4-JLH-INO
VARIABLE _EXT4-JLH-IMAGE
VARIABLE _EXT4-JLH-SUPER
VARIABLE _EXT4-JLH-HOME

\ Clear the sole legacy-list head in the transaction-aware primary-super
\ after-image.  A singleton successor is already zero, so no no-op i_dtime
\ rewrite is manufactured.  Block-free accounting may have edited this same
\ super image first; acquire composes with and reauthenticates that edit.
: _EXT4-JTX-CLEAR-SINGLETON-LEGACY-HEAD
  ( plan-record transaction -- ior )
    _EXT4-JLH-WRITER ! _EXT4-JLH-RECORD !
    _EXT4-JLH-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JLH-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JLH-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JLH-CTX !
    0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JLH-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-LEGACY <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JLH-RECORD @ _EXT4-JLH-CTX @
    _EXT4-REQUIRE-SINGLETON-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JLH-RECORD @ _EXT4-OE.INO + @ _EXT4-JLH-INO !
    _EXT4-JLH-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
    ?DUP IF EXIT THEN
    _EXT4-JLH-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JLH-HOME !
    _EXT4-JPS-SUPER @ _EXT4-JLH-SUPER !
    _EXT4-JPS-IMAGE @ _EXT4-JLH-IMAGE !
    _EXT4-JLH-HOME @ _EXT4-JLH-CTX @ _EXT4-PRIMARY-SUPER-BLOCK <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JLH-SUPER @ _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JLH-INO @ <> IF VFS-E-CONFLICT EXIT THEN
    _EXT4-JLH-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-JLH-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    _EXT4-JLH-SUPER @ _EXT4-SB.RO-COMPAT + L@
    _EXT4-JLH-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> IF
        VFS-E-CONFLICT EXIT
    THEN
    0 _EXT4-JLH-SUPER @ _EXT4-SB.LAST-ORPHAN + L!
    _EXT4-JLH-SUPER @ _EXT4-STAMP-SUPER-CHECKSUM
    _EXT4-JLH-IMAGE @ _EXT4-JLH-HOME @ _EXT4-JLH-WRITER @
    _EXT4-JTX-META-REPLACE ;

VARIABLE _EXT4-JCM-RECORD
VARIABLE _EXT4-JCM-CTX
VARIABLE _EXT4-JCM-ORPHAN-HOME
VARIABLE _EXT4-JCM-INODE-HOME
VARIABLE _EXT4-JCM-SUPER-HOME
VARIABLE _EXT4-JCM-GROUP
VARIABLE _EXT4-JCM-GROUP-FIRST
VARIABLE _EXT4-JCM-GROUP-COUNT
VARIABLE _EXT4-JCM-RANGE-INDEX
VARIABLE _EXT4-JCM-TOUCHED
VARIABLE _EXT4-JCM-BITMAP-HOME
VARIABLE _EXT4-JCM-GDT-HOME
VARIABLE _EXT4-JCM-PREV-GDT
VARIABLE _EXT4-JCM-HAVE-GDT
VARIABLE _EXT4-JCM-HAVE-GROUP
VARIABLE _EXT4-JCM-CREDIT
VARIABLE _EXT4-JCM-IOR
VARIABLE _EXT4-JCM-KIND
VARIABLE _EXT4-JCM-DELETE

: _EXT4-JCM-GROUP-TOUCHED?  ( group -- flag ior )
    DUP _EXT4-JCM-GROUP ! _EXT4-JCM-CTX @ _EXT4-GROUP-BLOCK-RANGE
    _EXT4-JCM-IOR ! _EXT4-JCM-GROUP-COUNT !
    _EXT4-JCM-GROUP-FIRST !
    _EXT4-JCM-IOR @ ?DUP IF FALSE SWAP EXIT THEN
    0 _EXT4-JCM-RANGE-INDEX !
    BEGIN
        _EXT4-JCM-RANGE-INDEX @ _EXT4-JOT-COUNT @ U<
    WHILE
        _EXT4-JCM-RANGE-INDEX @ _EXT4-JOT-RANGE DUP @
        SWAP CELL+ @
        _EXT4-JCM-GROUP-FIRST @ _EXT4-JCM-GROUP-COUNT @
        _EXT4-BLOCK-RANGES-OVERLAP? IF TRUE 0 EXIT THEN
        1 _EXT4-JCM-RANGE-INDEX +!
    REPEAT
    FALSE 0 ;

: _EXT4-JCM-ADD-CREDIT  ( -- ior )
    _EXT4-JCM-CREDIT @ 1 _EXT4-UADD?
    DUP IF NIP EXIT THEN DROP _EXT4-JCM-CREDIT !
    0 ;

: _EXT4-JCM-BASE-DISJOINT?  ( -- flag )
    _EXT4-JCM-INODE-HOME @ _EXT4-JCM-SUPER-HOME @ = IF FALSE EXIT THEN
    _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF TRUE EXIT THEN
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JCM-INODE-HOME @ =
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JCM-SUPER-HOME @ = OR 0= ;

: _EXT4-JCM-GROUP-HOMES-DISJOINT?  ( -- flag )
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-GDT-HOME @ =
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-INODE-HOME @ = OR
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-INODE-HOME @ = OR
    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-SUPER-HOME @ = OR IF FALSE EXIT THEN
    _EXT4-JCM-DELETE @ IF
        _EXT4-JCM-BITMAP-HOME @ _EXT4-JFI-BITMAP-HOME @ =
        _EXT4-JCM-BITMAP-HOME @ _EXT4-JFI-GDT-HOME @ = OR
        _EXT4-JCM-GDT-HOME @ _EXT4-JFI-BITMAP-HOME @ = OR IF
            FALSE EXIT
        THEN
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF TRUE EXIT THEN
    _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-ORPHAN-HOME @ =
    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-ORPHAN-HOME @ = OR 0= ;

: _EXT4-JCM-DELETE-HOMES-DISJOINT?  ( -- flag )
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-GDT-HOME @ =
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JFI-BITMAP-HOME @ _EXT4-JFI-INODE-HOME @ = OR
    _EXT4-JFI-GDT-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JFI-GDT-HOME @ _EXT4-JFI-INODE-HOME @ = OR
    _EXT4-JCM-SUPER-HOME @ _EXT4-JFI-INODE-HOME @ = OR IF
        FALSE EXIT
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF TRUE EXIT THEN
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-BITMAP-HOME @ =
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-GDT-HOME @ = OR
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JCM-SUPER-HOME @ = OR
    _EXT4-JCM-ORPHAN-HOME @ _EXT4-JFI-INODE-HOME @ = OR 0= ;

: _EXT4-JCM-VALIDATE-RANGES  ( -- ior )
    0 _EXT4-JCM-RANGE-INDEX !
    BEGIN
        _EXT4-JCM-RANGE-INDEX @ _EXT4-JOT-COUNT @ U<
    WHILE
        _EXT4-JCM-RANGE-INDEX @ _EXT4-JOT-RANGE DUP @
        SWAP CELL+ @ _EXT4-JCM-CTX @
        _EXT4-VALIDATE-MUTATION-RANGE-TARGETS ?DUP IF EXIT THEN
        1 _EXT4-JCM-RANGE-INDEX +!
    REPEAT
    0 ;

: _EXT4-JCM-COUNT-GROUP-HOMES  ( -- ior )
    0 _EXT4-JCM-GROUP !
    0 _EXT4-JCM-HAVE-GDT !
    0 _EXT4-JCM-HAVE-GROUP !
    BEGIN
        _EXT4-JCM-GROUP @ _EXT4-JCM-CTX @ _EXT4-C.GROUPS + @ U<
    WHILE
        _EXT4-JCM-GROUP @ _EXT4-JCM-GROUP-TOUCHED?
        _EXT4-JCM-IOR ! _EXT4-JCM-TOUCHED !
        _EXT4-JCM-IOR @ ?DUP IF EXIT THEN
        _EXT4-JCM-TOUCHED @ IF
            -1 _EXT4-JCM-HAVE-GROUP !
            _EXT4-JCM-GROUP @ _EXT4-JCM-CTX @
            _EXT4-LOAD-BLOCK-BITMAP
            _EXT4-JCM-IOR ! _EXT4-JCM-BITMAP-HOME !
            _EXT4-JCM-IOR @ ?DUP IF EXIT THEN
            _EXT4-GD-BLOCK @ _EXT4-JCM-GDT-HOME !
            _EXT4-JCM-BITMAP-HOME @ _EXT4-JCM-GROUP @
            _EXT4-JCM-CTX @ _EXT4-VALIDATE-BLOCK-BITMAP-HOME
            ?DUP IF EXIT THEN
            _EXT4-JCM-GROUP-HOMES-DISJOINT? 0= IF
                EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
            _EXT4-JCM-ADD-CREDIT ?DUP IF EXIT THEN
            _EXT4-JCM-DELETE @
            _EXT4-JCM-GDT-HOME @ _EXT4-JFI-GDT-HOME @ = AND 0= IF
                _EXT4-JCM-HAVE-GDT @ IF
                    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-PREV-GDT @ U< IF
                        EXT4-D-GEOMETRY _EXT4-CORRUPT EXIT
                    THEN
                    _EXT4-JCM-GDT-HOME @ _EXT4-JCM-PREV-GDT @ <> IF
                        _EXT4-JCM-ADD-CREDIT ?DUP IF EXIT THEN
                    THEN
                ELSE
                    _EXT4-JCM-ADD-CREDIT ?DUP IF EXIT THEN
                    -1 _EXT4-JCM-HAVE-GDT !
                THEN
                _EXT4-JCM-GDT-HOME @ _EXT4-JCM-PREV-GDT !
            THEN
        THEN
        1 _EXT4-JCM-GROUP +!
    REPEAT
    _EXT4-JCM-HAVE-GROUP @ 0= IF
        EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    0 ;

\ Derive the exact coalesced metadata-home credit for a sealed singleton
\ depth-zero cleanup.  Every delete includes the zeroed inode-table block,
\ inode bitmap, primary GDT, primary superblock, and (for modern authority)
\ orphan-file block.  A nonempty root adds one uniquely owned block bitmap per
\ touched group and one primary GDT block per distinct descriptor page.
\ The group scan is constant-space and imposes no policy capacity beyond the
\ authenticated filesystem geometry.

: _EXT4-JCM-MEASURE-DELETE  ( -- meta-credit ior )
    _EXT4-JCM-RECORD @ _EXT4-JFI-RECORD !
    _EXT4-JCM-CTX @ _EXT4-JFI-CTX !
    _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JFI-INODE-HOME @ _EXT4-JCM-INODE-HOME !
    _EXT4-JCM-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JCM-SUPER-HOME !
    _EXT4-JCM-DELETE-HOMES-DISJOINT? 0= IF
        0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-MODERN = IF 5 ELSE 4 THEN
    _EXT4-JCM-CREDIT !
    _EXT4-JFI-DATA-COUNT @ 0= IF _EXT4-JCM-CREDIT @ 0 EXIT THEN
    1 _EXT4-JOT-COUNT !
    _EXT4-JFI-DATA-FIRST @ 0 _EXT4-JOT-RANGE !
    _EXT4-JFI-DATA-COUNT @ 0 _EXT4-JOT-RANGE CELL+ !
    _EXT4-JCM-VALIDATE-RANGES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-COUNT-GROUP-HOMES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-CREDIT @ 0 ;

: _EXT4-MEASURE-SINGLETON-ORPHAN-DEPTH0
  ( plan-record ctx -- meta-credit ior )
    _EXT4-JCM-CTX ! _EXT4-JCM-RECORD !
    _EXT4-JCM-RECORD @ 0= _EXT4-JCM-CTX @ 0= OR IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-JCM-RECORD @ _EXT4-JCM-CTX @
    _EXT4-REQUIRE-SINGLETON-ORPHAN
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-RECORD @ _EXT4-OE.KIND + @ _EXT4-JCM-KIND !
    _EXT4-JCM-CTX @ _EXT4-C.INODE + _EXT4-I.LINKS + W@ 0=
    _EXT4-JCM-DELETE !
    _EXT4-JCM-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JCM-RECORD @ _EXT4-JOS-RECORD !
        _EXT4-JCM-CTX @ _EXT4-JOS-CTX !
        _EXT4-JOS-AUTH-PREFLIGHT ?DUP IF 0 SWAP EXIT THEN
        _EXT4-JOS-HOME @ _EXT4-JCM-ORPHAN-HOME !
    ELSE
        0 _EXT4-JCM-ORPHAN-HOME !
        _EXT4-JCM-CTX @ _EXT4-VALIDATE-PRIMARY-MUTATION-HOMES
        ?DUP IF 0 SWAP EXIT THEN
    THEN
    _EXT4-JCM-DELETE @ IF
        _EXT4-JCM-MEASURE-DELETE EXIT
    THEN
    _EXT4-JCM-RECORD @ _EXT4-JOT-RECORD !
    _EXT4-JCM-CTX @ _EXT4-JOT-CTX !
    _EXT4-JOT-AUTH-PREFLIGHT ?DUP IF 0 SWAP EXIT THEN
    _EXT4-IR-BLOCK @ _EXT4-JCM-INODE-HOME !
    _EXT4-JCM-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JCM-SUPER-HOME !
    _EXT4-JOT-COUNT @ 0= IF
        _EXT4-JCM-KIND @ _EXT4-OK-LEGACY = IF
            _EXT4-JCM-BASE-DISJOINT? 0= IF
                0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
            THEN
        THEN
        1 0 EXIT
    THEN
    _EXT4-JCM-VALIDATE-RANGES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-BASE-DISJOINT? 0= IF
        0 EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JCM-KIND @ _EXT4-OK-MODERN = IF 3 ELSE 2 THEN
    _EXT4-JCM-CREDIT !
    _EXT4-JCM-COUNT-GROUP-HOMES ?DUP IF 0 SWAP EXIT THEN
    _EXT4-JCM-CREDIT @ 0 ;

: _EXT4-JFC-SEAL-MODERN-PROTOCOL  ( -- ior )
    _EXT4-JFC-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-JFC-CTX @ _EXT4-ORPHAN-RECORD? 0= IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JFC-LOGICAL @ _EXT4-JFC-CTX @
    _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
    _EXT4-OV-PHYS @ _EXT4-JFC-O-HOME !
    _EXT4-OV-GEN @ _EXT4-JFC-O-GEN !
    _EXT4-JFC-CTX @ _EXT4-C.BLOCK + _EXT4-JFC-SLOT @ 4 * + L@
    _EXT4-JFC-INO @ <> IF EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    _EXT4-JFC-O-HOME @ _EXT4-JFC-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFC-SLOT @ 4 * + L@ IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFC-O-HOME @
    _EXT4-JFC-CTX @ _EXT4-C.ORPHAN-INO + @ _EXT4-JFC-O-GEN @
    _EXT4-JFC-CTX @ _EXT4-ORPHAN-BLOCK-CHECKSUM? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-ORPHAN-CRC !
    _EXT4-JCPM-ORPHAN-MODERN-FINAL _EXT4-JFC-MODE !
    0 ;

: _EXT4-JFC-SEAL-LEGACY-PROTOCOL  ( -- ior )
    0 _EXT4-JFC-LOGICAL ! 0 _EXT4-JFC-SLOT !
    _EXT4-JFC-WRITER @ _EXT4-JTX-ACQUIRE-PRIMARY-SUPER ?DUP IF EXIT THEN
    _EXT4-JPS-HOME @ _EXT4-JFC-O-HOME !
    _EXT4-JPS-RAW-CRC @ _EXT4-JFC-O-GEN !
    _EXT4-JPS-RAW @ _EXT4-SB.LAST-ORPHAN + L@
    _EXT4-JFC-INO @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JPS-SUPER @ DUP _EXT4-JFC-SUPER !
    _EXT4-SB.LAST-ORPHAN + L@ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-SUPER @ _EXT4-SB.INCOMPAT + L@
    _EXT4-JFC-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-SUPER @ _EXT4-SB.RO-COMPAT + L@
    _EXT4-JFC-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JFC-O-HOME @ _EXT4-JFC-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-IMAGE @ _EXT4-JFC-CTX @ _EXT4-PRIMARY-SUPER-OFF +
    DUP _EXT4-SUPER-CHECKSUM? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    DUP _EXT4-SUPER-SEED? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    _EXT4-SB.LAST-ORPHAN + L@ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-ORPHAN-CRC !
    _EXT4-JCPM-ORPHAN-LEGACY-FINAL _EXT4-JFC-MODE !
    0 ;

: _EXT4-JFC-SEAL  ( -- ior )
    0 _EXT4-JFC-INODE-BITMAP-HOME !
    0 _EXT4-JFC-INODE-BITMAP-CRC !
    0 _EXT4-JFC-INODE-GDT-HOME !
    0 _EXT4-JFC-INODE-GDT-OFF !
    0 _EXT4-JFC-INODE-GDT-CRC !
    0 _EXT4-JFC-INODE-SUPER-CRC !
    0 _EXT4-JFC-DATA-FIRST ! 0 _EXT4-JFC-DATA-COUNT !
    _EXT4-JFC-RECORD @ _EXT4-JFC-CTX @
    _EXT4-REQUIRE-SINGLETON-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-OE.KIND + @ _EXT4-JFC-KIND !
    _EXT4-JFC-CTX @ _EXT4-C.INODE +
    _EXT4-I.LINKS + W@ 0= _EXT4-JFC-DELETE !
    _EXT4-JFC-CTX @ _EXT4-C.INODE + DUP
    _EXT4-I.GENERATION + L@ _EXT4-JFC-TARGET-GEN !
    _EXT4-I.BLOCK + 2 + W@ _EXT4-JFC-TARGET-ENTRIES !
    _EXT4-IR-BLOCK @ _EXT4-JFC-TARGET-HOME !
    _EXT4-IR-OFF @ _EXT4-JFC-TARGET-OFF !
    _EXT4-JFC-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JFC-SEAL-MODERN-PROTOCOL ?DUP IF EXIT THEN
    ELSE
        _EXT4-JFC-KIND @ _EXT4-OK-LEGACY <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-SEAL-LEGACY-PROTOCOL ?DUP IF EXIT THEN
    THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
        _EXT4-JFD-VERIFY-STAGED ?DUP IF EXIT THEN
        _EXT4-JFI-INODE-HOME @ _EXT4-JFC-TARGET-HOME @ <>
        _EXT4-JFI-INODE-OFF @ _EXT4-JFC-TARGET-OFF @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFI-INODE @ _EXT4-I.GENERATION + L@
        _EXT4-JFC-TARGET-GEN @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFI-DATA-FIRST @ _EXT4-JFC-DATA-FIRST !
        _EXT4-JFI-DATA-COUNT @ _EXT4-JFC-DATA-COUNT !
    THEN
    _EXT4-JFC-TARGET-HOME @ _EXT4-JFC-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JFC-TARGET-CRC @ <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-IMAGE @ _EXT4-JFC-TARGET-OFF @ +
        _EXT4-JFC-CTX @ _EXT4-C.ISIZE + @
        _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE _EXT4-JFC-TARGET-ENTRIES @ IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-IMAGE @ _EXT4-JFC-TARGET-OFF @ + DUP _EXT4-JFC-TARGET !
        _EXT4-I.GENERATION + L@ _EXT4-JFC-TARGET-GEN @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-TARGET @ DUP _EXT4-I.SIZE-LO + L@
        SWAP _EXT4-I.SIZE-HI + L@ OR IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-TARGET @ _EXT4-I.BLOCK + DUP
        W@ _EXT4-EXTENT-MAGIC <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP 2 + W@ IF DROP VFS-E-CORRUPT EXIT THEN
        6 + W@ IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-KIND @ _EXT4-OK-LEGACY = IF
            _EXT4-JFC-TARGET @ _EXT4-I.DTIME + L@ IF
                VFS-E-CORRUPT EXIT
            THEN
        THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @ _EXT4-JFC-TARGET-CRC !
    ELSE
        _EXT4-JFC-FOUND @ IF VFS-E-CORRUPT EXIT THEN
        0 _EXT4-JFC-TARGET-CRC !
    THEN
    THEN
    _EXT4-JFC-DELETE @ IF
        _EXT4-JFC-DATA-COUNT @ IF
            _EXT4-JFC-KIND @ _EXT4-OK-MODERN = IF
                _EXT4-JCPM-ORPHAN-MODERN-DATA-DELETE-FINAL
            ELSE
                _EXT4-JCPM-ORPHAN-LEGACY-DATA-DELETE-FINAL
            THEN
        ELSE
            _EXT4-JFC-KIND @ _EXT4-OK-MODERN = IF
                _EXT4-JCPM-ORPHAN-MODERN-DELETE-FINAL
            ELSE
                _EXT4-JCPM-ORPHAN-LEGACY-DELETE-FINAL
            THEN
        THEN _EXT4-JFC-MODE !
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.EPOCH + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-EPOCH + !
    _EXT4-JFC-INO @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-INO + !
    _EXT4-JFC-LOGICAL @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-LOGICAL + !
    _EXT4-JFC-SLOT @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-SLOT + !
    _EXT4-JFC-O-HOME @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-HOME + !
    _EXT4-JFC-O-GEN @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-O-GEN + !
    _EXT4-JFC-TARGET-GEN @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-GEN + !
    _EXT4-JFC-TARGET-HOME @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-HOME + !
    _EXT4-JFC-TARGET-OFF @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-OFF + !
    _EXT4-JFC-TARGET-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-CRC + !
    _EXT4-JFC-ORPHAN-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + !
    _EXT4-JFC-TARGET-ENTRIES @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + !
    _EXT4-JFC-INODE-BITMAP-HOME @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + !
    _EXT4-JFC-INODE-BITMAP-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + !
    _EXT4-JFC-INODE-GDT-HOME @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + !
    _EXT4-JFC-INODE-GDT-OFF @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + !
    _EXT4-JFC-INODE-GDT-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + !
    _EXT4-JFC-INODE-SUPER-CRC @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + !
    _EXT4-JFC-DATA-FIRST @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-DATA-FIRST + !
    _EXT4-JFC-DATA-COUNT @
    _EXT4-JFC-WRITER @ _EXT4-JWR.CP-DATA-COUNT + !
    _EXT4-JFC-MODE @ _EXT4-JFC-WRITER @ _EXT4-JWR.CP-MODE + !
    _EXT4-JFC-WRITER @ _EXT4-JWR-CP-AUTHORITY? 0= IF
        _EXT4-JFC-WRITER @ _EXT4-JWR-CLEAR-CP-AUTHORITY
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

\ Own one initially empty transaction, compose all depth-zero truncation and
\ protocol-removal afterimages, then freeze them behind an exact singleton plan
\ certificate.  Emit and abort remain legal; every later mutation is rejected
\ by _EXT4-JTX-MUTABLE?.
: _EXT4-JTX-STAGE-SINGLETON-ORPHAN-DEPTH0-FINAL
  ( plan-record transaction -- ior )
    _EXT4-JFC-WRITER ! _EXT4-JFC-RECORD !
    _EXT4-JFC-WRITER @ _EXT4-JTX-MUTABLE? ?DUP IF EXIT THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-CREDIT + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.DATA-CREDIT + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.DATA-USED + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.DATA-ACTIVE + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-CREDIT + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-USED + @ OR
    _EXT4-JFC-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.CTX + @ _EXT4-JFC-CTX !
    _EXT4-JFC-RECORD @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JFC-REQUIRE-SINGLETON ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-OE.INO + @ _EXT4-JFC-INO !
    _EXT4-JFC-RECORD @ _EXT4-OE.LOCATOR-A + @ _EXT4-JFC-LOGICAL !
    _EXT4-JFC-RECORD @ _EXT4-OE.LOCATOR-B + @ _EXT4-JFC-SLOT !
    _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
    _EXT4-JFC-CTX @ _EXT4-C.INODE + _EXT4-I.LINKS + W@ 0= IF
        _EXT4-JTX-STAGE-FREE-ORPHAN-INODE
    ELSE
        _EXT4-JTX-STAGE-ORPHAN-DEPTH0-TRUNCATE
    THEN
    ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    _EXT4-JFC-RECORD @ _EXT4-JFC-WRITER @
    _EXT4-JFC-RECORD @ _EXT4-OE.KIND + @ _EXT4-OK-MODERN = IF
        _EXT4-JTX-CLEAR-MODERN-ORPHAN-SLOT
    ELSE
        _EXT4-JTX-CLEAR-SINGLETON-LEGACY-HEAD
    THEN
    ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-USED + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @ <>
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-ACTIVE + @
    _EXT4-JFC-WRITER @ _EXT4-JWR.META-CREDIT + @ <> OR IF
        VFS-E-CORRUPT _EXT4-JFC-FAIL EXIT
    THEN
    _EXT4-JFC-SEAL ?DUP IF _EXT4-JFC-FAIL EXIT THEN
    0 ;

\ True only after the unified legacy/modern pass has authenticated an empty
\ active union and proved that its derived clear-pending state agrees with the
\ raw ORPHAN_PRESENT bit.  This does not require that bit to be set: a legacy
\ singleton may finish with no modern transient feature to clear.
: _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION?  ( ctx -- flag )
    DUP _EXT4-C.O.ACTIVE + @ IF DROP FALSE EXIT THEN
    DUP _EXT4-C.O.MODERN-ACTIVE + @ IF DROP FALSE EXIT THEN
    DUP _EXT4-C.O.LEGACY-ACTIVE + @ IF DROP FALSE EXIT THEN
    DUP _EXT4-C.SB + _EXT4-SB.LAST-ORPHAN + L@ IF
        DROP FALSE EXIT
    THEN
    DUP _EXT4-C.O.CLEAR-PENDING + @ 0<>
    SWAP _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@
    _EXT4-RO-ORPHAN-PRESENT AND 0<> = ;

\ The empty-modern landing additionally requires the authenticated transient
\ bit whose final-super transition it is about to clear.
: _EXT4-EMPTY-ORPHAN-RECOVERY?  ( ctx -- flag )
    DUP _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF DROP FALSE EXIT THEN
    _EXT4-C.O.CLEAR-PENDING + @ 0<> ;

VARIABLE _EXT4-RS-CTX
VARIABLE _EXT4-RS-V

: _EXT4-AUTHENTICATE-REST  ( ctx -- ior )
    DUP _EXT4-C.J.STRICT + -1 SWAP !
    DUP _EXT4-VALIDATE-GROUPS ?DUP IF NIP EXIT THEN
    DUP _EXT4-VALIDATE-BACKUPS ?DUP IF NIP EXIT THEN
    DUP _EXT4-AUTHENTICATE-ORPHAN-PLAN ?DUP IF NIP EXIT THEN
    _EXT4-VALIDATE-JOURNAL ;

: _EXT4-VALIDATE-REST  ( ctx -- ior )
    DUP _EXT4-AUTHENTICATE-REST ?DUP IF NIP EXIT THEN
    _EXT4-C.O.ACTIVE + @ IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

: _EXT4-RELOAD-AUTHENTICATED  ( ctx vfs -- ior )
    _EXT4-RS-V ! _EXT4-RS-CTX !
    _EXT4-RS-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-RS-V @ _EXT4-VALIDATE-SUPER ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-AUTHENTICATE-REST ;

: _EXT4-RELOAD-STRICT  ( ctx vfs -- ior )
    _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
    _EXT4-RS-CTX @ _EXT4-C.O.ACTIVE + @ IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    0 ;

VARIABLE _EXT4-JPF-WRITER
VARIABLE _EXT4-JPF-CTX
VARIABLE _EXT4-JPF-V
VARIABLE _EXT4-JPF-RECORD
VARIABLE _EXT4-JPF-COUNT
VARIABLE _EXT4-JPF-MODE
VARIABLE _EXT4-JPF-KIND
VARIABLE _EXT4-JPF-TARGET

: _EXT4-JWR-SINGLETON-FINAL-PREPLAN  ( writer ctx -- ior )
    _EXT4-JPF-CTX ! _EXT4-JPF-WRITER !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JPF-MODE !
    _EXT4-JCPM-ORPHAN-FINAL? 0= IF
        VFS-E-INVALID EXIT
    THEN
    0 _EXT4-JPF-RECORD ! 0 _EXT4-JPF-COUNT !
    _EXT4-JPF-CTX @ _EXT4-C.O.SLOTS + @ 0 ?DO
        I _EXT4-JPF-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
            _EXT4-JPF-RECORD @ IF
                DROP EXT4-D-ORPHAN-FILE _EXT4-CORRUPT UNLOOP EXIT
            THEN
            _EXT4-JPF-RECORD ! 1 _EXT4-JPF-COUNT +!
        ELSE
            DROP
        THEN
    LOOP
    _EXT4-JPF-COUNT @ 1 <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.INO + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.KIND + @ DUP _EXT4-JPF-KIND !
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-OK-MODERN <>
    ELSE
        _EXT4-OK-LEGACY <>
    THEN IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.LOCATOR-A + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-OE.LOCATOR-B + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-RECORD @ _EXT4-JPF-CTX @
    _EXT4-REQUIRE-SINGLETON-ORPHAN ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-C.INODE + DUP _EXT4-JPF-TARGET !
    _EXT4-I.LINKS + W@ 0=
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DELETE? <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-TARGET @ _EXT4-I.GENERATION + L@
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-TARGET @ _EXT4-I.BLOCK + 2 + W@
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ <> IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JPF-RECORD @ _EXT4-JFI-RECORD !
        _EXT4-JPF-CTX @ _EXT4-JFI-CTX !
        _EXT4-JFI-AUTH-PREFLIGHT ?DUP IF EXIT THEN
        _EXT4-JFI-DATA-FIRST @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-DATA-FIRST + @ <>
        _EXT4-JFI-DATA-COUNT @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-DATA-COUNT + @ <> OR IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-MODE @ _EXT4-JCPM-ORPHAN-DATA-DELETE?
        _EXT4-JFI-DATA-COUNT @ 0<> <> IF
            EXT4-D-DATA-MAP _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-IR-BLOCK @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @ <>
    _EXT4-IR-OFF @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ <> OR IF
        EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
    THEN
    _EXT4-JPF-KIND @ _EXT4-OK-MODERN = IF
        _EXT4-JPF-CTX @ _EXT4-PREPARE-ORPHAN-FILE ?DUP IF EXIT THEN
        _EXT4-OV-GEN @ _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-RECORD @ _EXT4-JPF-CTX @
        _EXT4-ORPHAN-RECORD? 0= IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ _EXT4-JPF-CTX @
        _EXT4-READ-ORPHAN-BLOCK ?DUP IF EXIT THEN
        _EXT4-OV-PHYS @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-CTX @ _EXT4-C.BLOCK +
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ <> IF
            EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-JPF-CTX @ _EXT4-C.SB + DUP
        _EXT4-SB.CHECKSUM + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ <> IF
            DROP EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
        _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-INO + @ <> IF
            EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT
        THEN
    THEN
    0 ;

: _EXT4-JWR-SINGLETON-FINAL-STAGED?  ( writer -- ior )
    DUP _EXT4-JPF-WRITER ! _EXT4-JWR.CTX + @ _EXT4-JPF-CTX !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @ _EXT4-JPF-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-ORPHAN-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-MODERN? IF
        _EXT4-JFC-IMAGE @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-SLOT + @ 4 * + L@ IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @ _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-HOME + @
        _EXT4-JPF-CTX @ _EXT4-C.ORPHAN-INO + @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-GEN + @ _EXT4-JPF-CTX @
        _EXT4-ORPHAN-BLOCK-CHECKSUM? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
        _EXT4-JCPM-ORPHAN-LEGACY? 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-IMAGE @ _EXT4-JPF-CTX @ _EXT4-PRIMARY-SUPER-OFF +
        DUP _EXT4-JFC-SUPER !
        DUP _EXT4-SUPER-CHECKSUM? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-SUPER-SEED? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        DUP 0 _EXT4-JPF-CTX @ _EXT4-C.SB +
        _EXT4-SUPER-INVARIANTS? 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JPF-CTX @ _EXT4-VALIDATE-SUPER-COUNTER-BOUNDS
        ?DUP IF NIP EXIT THEN
        DUP _EXT4-SB.LAST-ORPHAN + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-O-LOGICAL + @ <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-SB.INCOMPAT + L@
        _EXT4-JPF-CTX @ _EXT4-C.SB + _EXT4-SB.INCOMPAT + L@ <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-SB.RO-COMPAT + L@
        _EXT4-JPF-CTX @ _EXT4-C.SB + _EXT4-SB.RO-COMPAT + L@ <> IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JPF-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ +
        _EXT4-JPF-CTX @ _EXT4-C.ISIZE + @
        _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-ENTRIES + @ IF
        _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JFC-ENTRY @ 2 CELLS + @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFC-IMAGE @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ +
        DUP _EXT4-JPF-TARGET ! _EXT4-I.GENERATION + L@
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-TARGET-GEN + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JPF-TARGET @ DUP _EXT4-I.SIZE-LO + L@
        SWAP _EXT4-I.SIZE-HI + L@ OR IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JPF-TARGET @ _EXT4-I.BLOCK + DUP
        W@ _EXT4-EXTENT-MAGIC <> IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP 2 + W@ IF DROP VFS-E-CORRUPT EXIT THEN
        6 + W@ IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
        _EXT4-JCPM-ORPHAN-LEGACY-FINAL = IF
            _EXT4-JPF-TARGET @ _EXT4-I.DTIME + L@ IF
                VFS-E-CORRUPT EXIT
            THEN
        THEN
    ELSE
        _EXT4-JFC-FOUND @ IF VFS-E-CORRUPT EXIT THEN
    THEN
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JPF-RECORD @ _EXT4-JPF-WRITER @
        _EXT4-JFD-VERIFY-STAGED ?DUP IF EXIT THEN
        _EXT4-JFC-INODE-BITMAP-HOME @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + @ <>
        _EXT4-JFC-INODE-BITMAP-CRC @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + @ <> OR
        _EXT4-JFC-INODE-GDT-HOME @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @ <> OR
        _EXT4-JFC-INODE-GDT-OFF @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @ <> OR
        _EXT4-JFC-INODE-GDT-CRC @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @ <> OR
        _EXT4-JFC-INODE-SUPER-CRC @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JFI-DATA-FIRST @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-DATA-FIRST + @ <>
        _EXT4-JFI-DATA-COUNT @
        _EXT4-JPF-WRITER @ _EXT4-JWR.CP-DATA-COUNT + @ <> OR IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    0 ;

\ The only nonempty-orphan reload admitted by checkpoint is bound to one
\ sealed writer, its exact checkpoint phase, and a fully authenticated
\ singleton plan.  It skips only the public policy refusal.
: _EXT4-RELOAD-STRICT-SINGLETON-FINAL  ( writer ctx vfs -- ior )
    _EXT4-JPF-V ! _EXT4-JPF-CTX ! _EXT4-JPF-WRITER !
    _EXT4-JPF-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-FINAL? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.STATE + @
    _EXT4-JWR-CHECKPOINTING <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.PHASE + @
    _EXT4-JWP-CHECKPOINT-PREFLIGHT <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR.CTX + @
    _EXT4-JPF-CTX @ <> IF VFS-E-INVALID EXIT THEN
    _EXT4-JPF-V @ _EXT4-CTX _EXT4-JPF-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-JPF-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0=
    _EXT4-JPF-CTX @ _EXT4-C.RECOVERY + @ 0= OR
    _EXT4-JPF-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JPF-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS
    ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-JPF-V @ _EXT4-VALIDATE-SUPER
    ?DUP IF EXIT THEN
    -1 _EXT4-JPF-CTX @ _EXT4-C.J.STRICT + !
    _EXT4-JPF-CTX @ _EXT4-VALIDATE-GROUPS ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-VALIDATE-BACKUPS ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-AUTHENTICATE-ORPHAN-PLAN ?DUP IF EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JPF-CTX @
    _EXT4-JWR-SINGLETON-FINAL-PREPLAN ?DUP IF EXIT THEN
    _EXT4-JPF-CTX @ _EXT4-VALIDATE-JOURNAL ?DUP IF EXIT THEN
    _EXT4-JPF-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-VALIDATE-ROOT  ( ctx -- ior )
    DUP _EXT4-RJ-CTX ! 2 SWAP _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-STAGE-ROOT ;

VARIABLE _EXT4-JCP-WRITER
VARIABLE _EXT4-JCP-CTX
VARIABLE _EXT4-JCP-V
VARIABLE _EXT4-JCP-INDEX
VARIABLE _EXT4-JCP-ENTRY
VARIABLE _EXT4-JCP-WROTE
VARIABLE _EXT4-JCP-ENTRY-READY

: _EXT4-JCP-FAULT  ( ior -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR-LATCH-FAULT ;

: _EXT4-JCP-RELOAD-PREFLIGHT  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @ DUP
    _EXT4-JCPM-NONE = IF
        DROP _EXT4-JCP-CTX @ _EXT4-JCP-V @ _EXT4-RELOAD-STRICT EXIT
    THEN
    _EXT4-JCPM-ORPHAN-FINAL? IF
        _EXT4-JCP-WRITER @ _EXT4-JCP-CTX @ _EXT4-JCP-V @
        _EXT4-RELOAD-STRICT-SINGLETON-FINAL EXIT
    THEN
    VFS-E-CORRUPT ;

VARIABLE _EXT4-JCE-GROUP
VARIABLE _EXT4-JCE-INDEX
VARIABLE _EXT4-JCE-HOME
VARIABLE _EXT4-JCE-IOR
VARIABLE _EXT4-JCE-META-INDEX
VARIABLE _EXT4-JCE-META-ENTRY
VARIABLE _EXT4-JCE-META-IMAGE
VARIABLE _EXT4-JCE-DATA-GROUP
VARIABLE _EXT4-JCE-DATA-INDEX
VARIABLE _EXT4-JCE-DATA-GROUP-BLOCKS
VARIABLE _EXT4-JCE-DATA-BITMAP-HOME
VARIABLE _EXT4-JCE-DATA-GDT-HOME

: _EXT4-JCP-REQUIRE-RETAINED-META-HOMES  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JCE-META-INDEX !
    BEGIN
        _EXT4-JCE-META-INDEX @
        _EXT4-JCP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JCE-META-INDEX @ _EXT4-JCP-WRITER @
        _EXT4-JWR-META-ENTRY DUP _EXT4-JCE-META-ENTRY !
        CELL+ @ _EXT4-JE-ACTIVE <> IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JCE-META-ENTRY @ @ DUP 0< IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JCP-CTX @ _EXT4-C.BLOCKS + @ U< 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
        _EXT4-JCE-META-INDEX @ _EXT4-JCP-WRITER @
        _EXT4-JWR-META-IMAGE DUP _EXT4-JCE-META-IMAGE !
        _EXT4-JCP-WRITER @ _EXT4-JTX-IMAGE-CRC
        _EXT4-JCE-META-ENTRY @ 2 CELLS + @ <> IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCE-META-IMAGE @
        _EXT4-JCP-CTX @ _EXT4-C.BSIZE + @ _EXT4-BYTES=? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        1 _EXT4-JCE-META-INDEX +!
    REPEAT
    0 ;

: _EXT4-JCP-REQUIRE-DELETE-DATA  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-DATA-COUNT + @ 0= IF 0 EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-DATA-COUNT + @ 1 <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-DATA-FIRST + @ DUP
    _EXT4-JCP-CTX @ _EXT4-C.FIRST + @ U< IF
        DROP VFS-E-CORRUPT EXIT
    THEN
    DUP 1 _EXT4-JCP-CTX @ _EXT4-C.BLOCKS + @
    BLOCK-RANGE? 0= IF DROP VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.FIRST + @ -
    _EXT4-JCP-CTX @ _EXT4-C.BPG + @ /MOD
    _EXT4-JCE-DATA-GROUP ! _EXT4-JCE-DATA-INDEX !
    _EXT4-JCE-DATA-GROUP @ _EXT4-JCP-CTX @ _EXT4-GROUP-BLOCK-COUNT
    DUP IF NIP EXIT THEN DROP _EXT4-JCE-DATA-GROUP-BLOCKS !
    _EXT4-JCE-DATA-INDEX @ _EXT4-JCE-DATA-GROUP-BLOCKS @ U< 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCE-DATA-GROUP @ _EXT4-JCP-CTX @ _EXT4-LOAD-BLOCK-BITMAP
    _EXT4-JCE-IOR ! _EXT4-JCE-DATA-BITMAP-HOME !
    _EXT4-JCE-IOR @ ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCE-DATA-INDEX @ 1
    _EXT4-BIT-RANGE-SET? IF VFS-E-CORRUPT EXIT THEN
    _EXT4-GD-BLOCK @ _EXT4-JCE-DATA-GDT-HOME !
    _EXT4-JCE-DATA-BITMAP-HOME @ _EXT4-JCP-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCE-DATA-GDT-HOME @ _EXT4-JCP-WRITER @
    _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JCP-REQUIRE-DELETE-HOMES  ( -- ior )
    _EXT4-JCP-REQUIRE-RETAINED-META-HOMES ?DUP IF EXIT THEN
    _EXT4-JCP-REQUIRE-DELETE-DATA ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-O-INO + @ 1-
    _EXT4-JCP-CTX @ _EXT4-C.IPG + @ /MOD
    _EXT4-JCE-GROUP ! _EXT4-JCE-INDEX !
    _EXT4-JCE-GROUP @ _EXT4-JCP-CTX @ _EXT4-LOAD-INODE-BITMAP
    _EXT4-JCE-IOR ! _EXT4-JCE-HOME !
    _EXT4-JCE-IOR @ ?DUP IF EXIT THEN
    _EXT4-JCE-HOME @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-HOME + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-GD-BLOCK @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @ <>
    _EXT4-GD-OFF @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-OFF + @ <> OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCE-INDEX @ 1
    _EXT4-BIT-RANGE-SET? IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCP-WRITER @
    _EXT4-JTX-IMAGE-CRC
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-BITMAP-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-HOME + @
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCP-WRITER @
    _EXT4-JTX-IMAGE-CRC
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-GDT-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK + _EXT4-JCP-WRITER @
    _EXT4-JTX-IMAGE-CRC
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-INODE-SUPER-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JCP-WRITER @ _EXT4-JFC-FIND-META ?DUP IF EXIT THEN
    _EXT4-JFC-FOUND @ 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JFC-ENTRY @ 2 CELLS + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-CRC + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-HOME + @
    _EXT4-JCP-CTX @ _EXT4-READ-BLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-TARGET-OFF + @ +
    _EXT4-JCP-CTX @ _EXT4-C.ISIZE + @
    _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JCP-REQUIRE-FINAL-EMPTY  ( -- ior )
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @
    DUP _EXT4-JCPM-NONE = IF
        DROP
        _EXT4-JCP-CTX @
        _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        0 EXIT
    THEN
    DUP _EXT4-JCPM-ORPHAN-MODERN? IF
        DROP
        _EXT4-JCP-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    ELSE
        _EXT4-JCPM-ORPHAN-LEGACY? 0= IF VFS-E-CORRUPT EXIT THEN
        _EXT4-JCP-CTX @
        _EXT4-AUTHENTICATED-EMPTY-ORPHAN-UNION? 0= IF
            VFS-E-CORRUPT EXIT
        THEN
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-DELETE? IF
        _EXT4-JCP-REQUIRE-DELETE-HOMES ?DUP IF EXIT THEN
    THEN
    0 ;

\ Reauthenticate both the persisted transaction and its retained checkpoint
\ source before the first home write.  JSCAN proves the exact committed disk
\ prefix; the bounded writer tables prove the home identities and images that
\ will be consumed without allocating recovery-only revoke workspace.
: _EXT4-JTX-CHECKPOINT-PREFLIGHT  ( -- ior )
    _EXT4-JCP-RELOAD-PREFLIGHT ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JTX-TABLES-VALID? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    0 _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.SCRATCH-A + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-START + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.LOG-RESERVED + @ 1-
    _EXT4-JCP-CTX @ _EXT4-JOURNAL-ADVANCE
    _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.SCRATCH-B + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @ _EXT4-BYTES=? 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    \ Root staging may use TREE-BLOCK.  Freeze inode 8 again before JSCAN and
    \ retained-image authority checks consume the retry-preservation proof.
    8 _EXT4-JCP-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.INODE +
    _EXT4-JCP-CTX @ _EXT4-C.TREE-BLOCK +
    _EXT4-JCP-CTX @ _EXT4-C.ISIZE + @ CMOVE
    \ First prove an ordinary complete committed prefix, then repeat the same
    \ bounded scan in lockstep with retained metadata and revoke order.  The
    \ second pass cannot grant home-write authority merely because two valid
    \ but different transaction descriptions happen to have the same shape.
    _EXT4-JSCAN-PREFLIGHT _EXT4-JCP-CTX @ _EXT4-JSCAN ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JSCAN-BIND-BEGIN
    _EXT4-JSCAN-BINDING _EXT4-JCP-CTX @ _EXT4-JSCAN
    _EXT4-JSCAN-BIND-FINISH ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-CURSOR + @
    _EXT4-JCP-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.BLOCK +
    _EXT4-JCP-WRITER @ _EXT4-JWR.BSIZE + @
    _EXT4-BYTES-ZERO? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.COMMITTED + @ 1 <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.CURSOR + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-CURSOR + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.NEXT-SEQUENCE + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.TX-TID + @ 2 +
    0xFFFFFFFF AND <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.REVOKE-COUNT + @
    _EXT4-JCP-WRITER @ _EXT4-JWR.REVOKE-ACTIVE + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JTX-PREFLIGHT-IMAGES ?DUP IF EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CP-MODE + @
    _EXT4-JCPM-ORPHAN-FINAL? IF
        _EXT4-JCP-WRITER @ _EXT4-JWR-SINGLETON-FINAL-STAGED?
        ?DUP IF EXIT THEN
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR-VALID? 0= IF VFS-E-CORRUPT EXIT THEN
    0 ;

: _EXT4-JTX-CHECKPOINT-HOMES  ( -- ior )
    _EXT4-JWP-CHECKPOINT-HOME
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    0 _EXT4-JCP-INDEX ! 0 _EXT4-JCP-WROTE !
    0 _EXT4-JCP-CTX @ _EXT4-C.J.HOME-WRITES + !
    BEGIN
        _EXT4-JCP-INDEX @
        _EXT4-JCP-WRITER @ _EXT4-JWR.META-USED + @ U<
    WHILE
        _EXT4-JCP-INDEX @ _EXT4-JCP-WRITER @ _EXT4-JWR-META-ENTRY
        DUP _EXT4-JCP-ENTRY ! CELL+ @ _EXT4-JE-ACTIVE = IF
            _EXT4-JCP-INDEX @ _EXT4-JCP-WRITER @ _EXT4-JWR-META-IMAGE
            _EXT4-JCP-ENTRY @ @ _EXT4-JCP-CTX @ _EXT4-WRITE-BLOCK
            ?DUP IF EXIT THEN
            1 _EXT4-JCP-WROTE +!
            1 _EXT4-JCP-CTX @ _EXT4-C.J.HOME-WRITES + +!
        THEN
        1 _EXT4-JCP-INDEX +!
    REPEAT
    _EXT4-JCP-WROTE @
    _EXT4-JCP-WRITER @ _EXT4-JWR.META-ACTIVE + @ <> IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JWP-CHECKPOINT-HOME-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ;

\ Checkpoint one durable transaction, release its complete log reservation,
\ and keep the mounted filesystem at a standard empty RECOVER-set journal.
\ Any failure after publication enters CHECKPOINTING is quarantined for
\ remount; same-session retry never guesses which prefix reached the medium.
: _EXT4-JTX-CHECKPOINT  ( transaction -- ior )
    DUP _EXT4-JCP-WRITER ! _EXT4-JWR-VALID? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.STATE + @
    _EXT4-JWR-COMMITTED <> IF VFS-E-BUSY EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.FAULT + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JCP-CTX !
    _EXT4-C.J.WRITER-CURRENT + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.READY + @ DUP _EXT4-JCP-ENTRY-READY !
    DUP 0= SWAP -1 = OR 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-IO-VFS @ DUP 0= IF DROP VFS-E-INVALID EXIT THEN
    DUP _EXT4-JCP-V ! _EXT4-CTX _EXT4-JCP-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JCP-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-JCP-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-JWP-CHECKPOINT-PREFLIGHT
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JWR-CHECKPOINTING
    _EXT4-JCP-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JTX-CHECKPOINT-PREFLIGHT ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JTX-CHECKPOINT-HOMES ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-PROOF
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-JCP-V @ _EXT4-RELOAD-STRICT
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-REQUIRE-FINAL-EMPTY ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-VALIDATE-ROOT
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-WRITER @ _EXT4-JWR-VALID? 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-JWP-CHECKPOINT-RESET
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-RESET-JOURNAL
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-RESET-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-WITNESS-CLEAR
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS-DIRTY
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-WITNESS-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-GUARD-RETIRE
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-GUARD-FLUSH
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-FLUSH ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JWP-CHECKPOINT-FINAL-PROOF
    _EXT4-JCP-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JCP-CTX @ _EXT4-C.RECOVERY + @ 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-JCP-CTX @ _EXT4-C.SB + DUP
    _EXT4-SUPER-CHECKSUM? 0= IF
        DROP VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        VFS-E-CORRUPT _EXT4-JCP-FAULT EXIT
    THEN
    \ Context and writer publication are withdrawn before strict reload turns
    \ the in-memory active-log view into the empty write-active endpoint.
    0 _EXT4-JCP-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-JCP-CTX @ _EXT4-C.READY + !
    _EXT4-JCP-CTX @ _EXT4-JCP-V @ _EXT4-RELOAD-STRICT
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-REQUIRE-FINAL-EMPTY ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-CTX @ _EXT4-VALIDATE-ROOT
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    _EXT4-JCP-V @ _EXT4-ATTACHED? 0= IF
        VFS-E-STALE _EXT4-JCP-FAULT EXIT
    THEN
    0 _EXT4-JCP-CTX @ _EXT4-C.J.COMMITTED + !
    0 _EXT4-JCP-CTX @ _EXT4-C.J.REVOKE-COUNT + !
    0 _EXT4-JCP-CTX @ _EXT4-C.J.REVOKE-HITS + !
    _EXT4-JCP-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-JCP-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-JCP-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-JCP-CTX @ _EXT4-C.J.FIRST + @
    THEN _EXT4-JCP-CTX @ _EXT4-C.J.CURSOR + !
    _EXT4-JCP-CTX @ _EXT4-JWR-REBASE-WRITE-ACTIVE
    ?DUP IF _EXT4-JCP-FAULT EXIT THEN
    -1 _EXT4-JCP-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    _EXT4-JCP-ENTRY-READY @ _EXT4-JCP-CTX @ _EXT4-C.READY + !
    0 ;

VARIABLE _EXT4-MOW-SOURCE
VARIABLE _EXT4-MOW-COUNT
VARIABLE _EXT4-MOW-OFFSET
VARIABLE _EXT4-MOW-INO
VARIABLE _EXT4-MOW-GEN
VARIABLE _EXT4-MOW-SECONDS
VARIABLE _EXT4-MOW-NSEC
VARIABLE _EXT4-MOW-V
VARIABLE _EXT4-MOW-CTX
VARIABLE _EXT4-MOW-WRITER
VARIABLE _EXT4-MOW-TX
VARIABLE _EXT4-MOW-IOR
VARIABLE _EXT4-MOW-ACTIVE
CREATE _EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK ALLOT

: _EXT4-MOW-SCRUB  ( -- )
    _EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK 0 FILL ;

: _EXT4-MOW-ENTRY  ( -- ior )
    _EXT4-MOW-V @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-MOW-V @ V.LIFECYCLE @ VFS-L-MOUNTED <> IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-MOW-V @ V.VOLUME @ DUP 0= IF
        DROP VFS-E-INVALID EXIT
    THEN _EXT4-IO-VOL !
    _EXT4-MOW-V @ _EXT4-IO-VFS !
    _EXT4-MOW-V @ V.BCTX @ DUP _EXT4-MOW-CTX ! 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-MOW-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-MOW-V @ _EXT4-READY? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-MOW-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        VFS-E-STALE EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.J.START + @
    _EXT4-MOW-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.O.ACTIVE + @
    _EXT4-MOW-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _EXT4-MOW-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    _EXT4-MOW-CTX @ _EXT4-C.RECOVERY + @ 0<> DUP
    _EXT4-MOW-ACTIVE !
    _EXT4-MOW-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0<> = 0= IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-MOW-ACTIVE @ IF
        _EXT4-MOW-V @ V.FLAGS @ VFS-F-DIRTY AND 0= IF
            VFS-E-CORRUPT EXIT
        THEN
        _EXT4-MOW-CTX @ _EXT4-C.J.WRITER + @ DUP 0= IF
            DROP VFS-E-CORRUPT EXIT
        THEN
        DUP _EXT4-JWR-VALID? 0= IF DROP VFS-E-CORRUPT EXIT THEN
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
            DUP _EXT4-JWR.FAULT + @ ?DUP IF NIP EXIT THEN
            DROP VFS-E-BUSY EXIT
        THEN
        DUP _EXT4-JWR.FAULT + @ IF DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-JWR-IDLE-CLEAN? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-MOW-V @ V.FLAGS @ VFS-F-DIRTY AND IF
            VFS-E-BUSY EXIT
        THEN
    THEN
    _EXT4-MOW-CTX @ _EXT4-RECOVERY-MEDIA ;

\ Clean staging errors retain no media authority.  Abort only when the
\ transaction is still mutable; the typed builder may already have aborted
\ itself after an internal ordered-data publication.  A structurally failed
\ abort is latched because the persistent workspace can no longer be reused.
: _EXT4-MOW-FAIL  ( ior -- actual ior )
    _EXT4-MOW-IOR !
    _EXT4-MOW-WRITER @ ?DUP IF
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING = IF
            _EXT4-JTX-ABORT ?DUP IF
                _EXT4-MOW-WRITER @ _EXT4-JWR-LATCH-FAULT
                _EXT4-MOW-IOR !
            THEN
        ELSE
            DUP _EXT4-JWR.STATE + @ _EXT4-JWR-FAULTED = IF
                _EXT4-JWR.FAULT + @ ?DUP IF _EXT4-MOW-IOR ! THEN
            ELSE
                DROP
            THEN
        THEN
    THEN
    _EXT4-MOW-SCRUB
    0 _EXT4-MOW-IOR @ ;

\ Production-shaped private client for the exact qualified overwrite.  The
\ first clean call dry-stages before it can activate the journal.  Successful
\ calls checkpoint synchronously and retain one scrubbed write-active writer
\ for sequential reuse; ordinary unmount performs final clean deactivation.
\ This is deliberately absent from EXT4-OPS and does not update VFS vnodes.
\ ACTUAL counts only fully checkpointed caller bytes: zero after an emission
\ fault does not assert that ordered data or a replayable commit stayed absent.
: _EXT4-MOUNTED-ONEBLOCK-WRITE
  ( source count file-offset inode-number expected-generation
    seconds nsec vfs -- actual ior )
    _EXT4-MOW-V ! _EXT4-MOW-NSEC ! _EXT4-MOW-SECONDS !
    _EXT4-MOW-GEN ! _EXT4-MOW-INO ! _EXT4-MOW-OFFSET !
    _EXT4-MOW-COUNT ! _EXT4-MOW-SOURCE !
    0 _EXT4-MOW-WRITER ! 0 _EXT4-MOW-TX !
    _EXT4-MOW-ENTRY ?DUP IF 0 SWAP EXIT THEN
    _EXT4-MOW-COUNT @ 0< IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-MOW-COUNT @ 0= IF 0 0 EXIT THEN
    _EXT4-MOW-SOURCE @ _EXT4-MOW-COUNT @ _VFS-BUFFER? 0= IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-MOW-SOURCE @ _EXT4-MOW-COUNT @
    _EXT4-MOW-SNAPSHOT _EXT4-MAX-BLOCK MSPAN-OVERLAP? IF
        0 VFS-E-INVALID EXIT
    THEN
    _EXT4-MOW-OFFSET @ 0< IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-MOW-COUNT @ _EXT4-MOW-CTX @ _EXT4-C.BSIZE + @ U> IF
        0 EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
    THEN
    \ Preserve caller bytes across dry-stage abort, activation cache reuse,
    \ and live-stage writer rebase, then scrub them on every later return.
    _EXT4-MOW-SOURCE @ _EXT4-MOW-SNAPSHOT _EXT4-MOW-COUNT @ MOVE
    1 1 0 _EXT4-MOW-CTX @ _EXT4-JTX-PREFLIGHT-CAPACITY
    ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    1 1 0 _EXT4-MOW-CTX @ _EXT4-JWR-ENSURE
    _EXT4-MOW-IOR ! _EXT4-MOW-WRITER !
    _EXT4-MOW-IOR @ ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-ACTIVE @ 0= IF
        1 1 0 _EXT4-MOW-WRITER @ _EXT4-JTX-BEGIN
        _EXT4-MOW-IOR ! _EXT4-MOW-TX !
        _EXT4-MOW-IOR @ ?DUP IF _EXT4-MOW-FAIL EXIT THEN
        _EXT4-MOW-SNAPSHOT _EXT4-MOW-COUNT @ _EXT4-MOW-OFFSET @
        _EXT4-MOW-INO @ _EXT4-MOW-GEN @ _EXT4-MOW-SECONDS @
        _EXT4-MOW-NSEC @ _EXT4-MOW-TX @
        _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-WRITE
        ?DUP IF _EXT4-MOW-FAIL EXIT THEN
        _EXT4-MOW-TX @ _EXT4-JTX-ABORT
        ?DUP IF _EXT4-MOW-FAIL EXIT THEN
        _EXT4-MOW-WRITER @ _EXT4-JWR-ACTIVATE
        ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    THEN
    1 1 0 _EXT4-MOW-WRITER @ _EXT4-JTX-BEGIN
    _EXT4-MOW-IOR ! _EXT4-MOW-TX !
    _EXT4-MOW-IOR @ ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-SNAPSHOT _EXT4-MOW-COUNT @ _EXT4-MOW-OFFSET @
    _EXT4-MOW-INO @ _EXT4-MOW-GEN @ _EXT4-MOW-SECONDS @
    _EXT4-MOW-NSEC @ _EXT4-MOW-TX @
    _EXT4-JTX-STAGE-REGULAR-ONEBLOCK-WRITE
    ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-TX @ _EXT4-JTX-EMIT
    ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-TX @ _EXT4-JTX-CHECKPOINT
    ?DUP IF _EXT4-MOW-FAIL EXIT THEN
    _EXT4-MOW-WRITER @ _EXT4-JWR-VALID? 0= IF
        VFS-E-CORRUPT _EXT4-MOW-WRITER @ _EXT4-JWR-LATCH-FAULT
        _EXT4-MOW-FAIL EXIT
    THEN
    _EXT4-MOW-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <>
    _EXT4-MOW-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= OR IF
        VFS-E-CORRUPT _EXT4-MOW-WRITER @ _EXT4-JWR-LATCH-FAULT
        _EXT4-MOW-FAIL EXIT
    THEN
    _EXT4-MOW-COUNT @ _EXT4-MOW-SCRUB 0 ;

VARIABLE _EXT4-EL-CTX
VARIABLE _EXT4-EL-V
VARIABLE _EXT4-EL-WRITER

: _EXT4-EL-PHASE  ( phase -- )
    _EXT4-EL-WRITER @ ?DUP IF _EXT4-JWR.PHASE + ! ELSE DROP THEN ;

\ Land an exact empty checksum-v3 journal through AKR1.  RECOVER must already
\ be durable: a clean authenticated-empty-orphan mount first enters that state
\ through AKW1.  Strict reload proves the orphan file empty before the final
\ superblock endpoint clears RECOVER and ORPHAN_PRESENT together.
: _EXT4-LAND-EMPTY-JOURNAL  ( ctx vfs writer|0 -- ior )
    _EXT4-EL-WRITER ! _EXT4-EL-V ! _EXT4-EL-CTX !
    _EXT4-EL-CTX @ _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.SUPER-TORN + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.START + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.WITNESS + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.PRIMARY-TORN + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.CLEANUP + @ IF VFS-E-INVALID EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM? 0= IF
        DROP EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-EL-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
    _EXT4-EL-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
    _EXT4-EL-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-EL-CTX @ _EXT4-C.J.FIRST + @
    THEN
    _EXT4-EL-CTX @ _EXT4-C.J.CURSOR + !
    _EXT4-JWP-DEACTIVATE-PREFLIGHT _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-EL-V @ _EXT4-RELOAD-STRICT ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-PREPARE-CLEAR
    _EXT4-JWP-DEACTIVATE-RESET _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-RESET-JOURNAL ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-RESET-FLUSH _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-SUPER _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-WRITE-CLEARED-SUPER ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-SUPER-FLUSH _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-WITNESS-CLEAR _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-WITNESS-FLUSH _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-GUARD-RETIRE _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-GUARD-FLUSH _EXT4-EL-PHASE
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-FINAL-PROOF _EXT4-EL-PHASE
    _EXT4-EL-CTX @ _EXT4-EL-V @ _EXT4-RELOAD-STRICT ?DUP IF EXIT THEN
    _EXT4-EL-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    0 _EXT4-EL-CTX @ _EXT4-C.RECOVERY + !
    -1 _EXT4-EL-CTX @ _EXT4-C.J.REPLAYED + !
    0 ;

VARIABLE _EXT4-OEC-CTX
VARIABLE _EXT4-OEC-V
VARIABLE _EXT4-OEC-GUARD
VARIABLE _EXT4-OEC-NEXT

\ Complete an authenticated empty modern-orphan state without allocating a
\ private writer.  AKW1 first upgrades and authenticates even a feature-zero
\ clean journal while making RECOVER durable.  AKR1 can then clear both ext4
\ transient bits at its already witnessed final-super endpoint.
: _EXT4-COMPLETE-EMPTY-ORPHAN  ( ctx vfs -- ior )
    _EXT4-OEC-V ! _EXT4-OEC-CTX !
    _EXT4-OEC-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-OEC-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-OEC-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-OEC-V @ _EXT4-CTX _EXT4-OEC-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-OEC-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-OEC-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-OEC-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    0 _EXT4-OEC-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
    _EXT4-OEC-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
        DROP _EXT4-OEC-CTX @ _EXT4-C.J.FIRST + @
    THEN DUP _EXT4-OEC-GUARD !
    DUP _EXT4-OEC-CTX @ _EXT4-C.J.FIRST + @ U<
    SWAP _EXT4-OEC-CTX @ _EXT4-C.J.MAXLEN + @ U< 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-OEC-CTX @ _EXT4-C.J.SEQUENCE + @ 1+
    0xFFFFFFFF AND _EXT4-OEC-NEXT !
    _EXT4-OEC-CTX @ _EXT4-C.BLOCK +
    _EXT4-OEC-CTX @
    _EXT4-OEC-GUARD @
    _EXT4-OEC-NEXT @
    _EXT4-ACTIVATION-PRIMARY? 0= IF VFS-E-CORRUPT EXIT THEN
    _EXT4-OEC-CTX @
    _EXT4-OEC-GUARD @
    _EXT4-OEC-CTX @ _EXT4-C.DIR-BLOCK +
    _EXT4-OEC-CTX @ _EXT4-C.TREE-BLOCK +
    0 _EXT4-ACTIVATE-CLEAN-JOURNAL ?DUP IF EXIT THEN
    _EXT4-OEC-CTX @ _EXT4-C.RECOVERY + @ 0=
    _EXT4-OEC-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= OR
    _EXT4-OEC-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? 0= OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-OEC-CTX @ _EXT4-OEC-V @ 0
    _EXT4-LAND-EMPTY-JOURNAL ?DUP IF EXIT THEN
    0 _EXT4-OEC-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-OEC-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-OEC-CTX @ _EXT4-C.O.ACTIVE + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.O.MODERN-ACTIVE + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.O.LEGACY-ACTIVE + @ OR
    _EXT4-OEC-CTX @ _EXT4-C.O.CLEAR-PENDING + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    0 ;

VARIABLE _EXT4-JDE-WRITER
VARIABLE _EXT4-JDE-CTX
VARIABLE _EXT4-JDE-V
VARIABLE _EXT4-JDE-IOR

: _EXT4-JDE-FAULT  ( ior -- ior )
    _EXT4-JDE-IOR !
    _EXT4-JDE-IOR @ _EXT4-JDE-WRITER @ _EXT4-JWR-LATCH-FAULT
    VFS-L-STALE _EXT4-JDE-V @ V.LIFECYCLE ! ;

\ Gracefully close one write-active mount only from the checkpointed IDLE
\ boundary.  The common AKR1 landing supplies the durable clean transition;
\ this wrapper supplies same-mount ownership, phase attribution, quarantine,
\ final publication withdrawal, and bounded-workspace scrubbing.
: _EXT4-JWR-DEACTIVATE  ( writer vfs -- ior )
    _EXT4-JDE-V ! DUP _EXT4-JDE-WRITER !
    _EXT4-JWR-VALID? 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JDE-WRITER @ _EXT4-JWR.STATE + @
    _EXT4-JWR-IDLE <> IF VFS-E-BUSY EXIT THEN
    _EXT4-JDE-WRITER @ _EXT4-JWR.FAULT + @ IF VFS-E-BUSY EXIT THEN
    _EXT4-JDE-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= IF VFS-E-BUSY EXIT THEN
    _EXT4-JDE-WRITER @ _EXT4-JWR.CTX + @ DUP _EXT4-JDE-CTX !
    _EXT4-C.RECOVERY + @ 0= IF VFS-E-INVALID EXIT THEN
    _EXT4-JDE-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDE-CTX @ _EXT4-C.J.START + @ IF VFS-E-CORRUPT EXIT THEN
    _EXT4-JDE-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JDE-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-CORRUPT EXIT
    THEN
    _EXT4-JDE-V @ _EXT4-CTX _EXT4-JDE-CTX @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDE-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-JDE-V @ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT
    THEN
    _EXT4-JDE-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-JWP-DEACTIVATE-PREFLIGHT
    _EXT4-JDE-WRITER @ _EXT4-JWR.PHASE + !
    _EXT4-JWR-DEACTIVATING
    _EXT4-JDE-WRITER @ _EXT4-JWR.STATE + !
    _EXT4-JDE-CTX @ _EXT4-JDE-V @ _EXT4-JDE-WRITER @
    _EXT4-LAND-EMPTY-JOURNAL ?DUP IF _EXT4-JDE-FAULT EXIT THEN
    _EXT4-JDE-V @ _EXT4-ATTACHED? 0= IF
        VFS-E-STALE _EXT4-JDE-FAULT EXIT
    THEN
    _EXT4-JDE-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-JDE-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-JDE-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
        VFS-E-CORRUPT _EXT4-JDE-FAULT EXIT
    THEN
    _EXT4-JDE-CTX @ _EXT4-C.SB + DUP _EXT4-SUPER-CHECKSUM? 0= IF
        DROP VFS-E-CORRUPT _EXT4-JDE-FAULT EXIT
    THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND IF
        VFS-E-CORRUPT _EXT4-JDE-FAULT EXIT
    THEN
    0 _EXT4-JDE-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-JDE-CTX @ _EXT4-C.READY + !
    0 _EXT4-JDE-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-JDE-CTX @ _EXT4-JWR-REBASE-MOUNTED
    ?DUP IF _EXT4-JDE-FAULT EXIT THEN
    _EXT4-JDE-V @ V.FLAGS DUP @ VFS-F-DIRTY INVERT AND SWAP !
    0 ;

VARIABLE _EXT4-AWR-CTX
VARIABLE _EXT4-AWR-V
VARIABLE _EXT4-AWR-PHYS

\ Resolve either side, or an admitted prefix tear, of the clean-to-RECOVER
\ transition without ever reversing a torn write.  Install tears advance to
\ the exact AKW1 anchor and ext4 dirty endpoint; clear tears advance to the
\ ordinary JBD2 primary.  Once AKW1 is gone, the caller decides whether an
\ authenticated empty orphan set may land clean or a retained orphan must keep
\ RECOVER set and resume through a new transaction.
: _EXT4-RESOLVE-ACTIVATION-WITNESS  ( ctx vfs -- ior )
    _EXT4-AWR-V ! _EXT4-AWR-CTX !
    _EXT4-AWR-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-ACTIVATION <> IF VFS-E-INVALID EXIT THEN
    _EXT4-AWR-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-AWR-CTX @ _EXT4-C.J.CLEANUP + @ DUP
    _EXT4-JC-ANCHOR U> IF DROP VFS-E-INVALID EXIT THEN
    DUP IF
        _EXT4-AWR-CTX @ _EXT4-C.J.PRIMARY-TORN + @ 0= IF
            DROP VFS-E-INVALID EXIT
        THEN
    THEN
    _EXT4-JC-STANDARD = IF
        \ C/A is reachable only after the dirty ext4 endpoint was durable.
        _EXT4-AWR-CTX @ _EXT4-C.RECOVERY + @ 0=
        _EXT4-AWR-CTX @ _EXT4-C.SUPER-TORN + @ OR IF
            EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-AWR-CTX @ _EXT4-C.J.PRIMARY-TORN + @ IF
        _EXT4-AWR-CTX @ _EXT4-C.J.ANCHOR + @
        _EXT4-AWR-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
        _EXT4-AWR-CTX @ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-STANDARD = IF
            _EXT4-AWR-CTX @ _EXT4-C.BLOCK +
            _EXT4-ZERO-JOURNAL-WITNESS
        THEN
        0 _EXT4-AWR-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-AWR-PHYS !
        _EXT4-AWR-CTX @ _EXT4-C.BLOCK + _EXT4-AWR-PHYS @ _EXT4-AWR-CTX @
        _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        0 _EXT4-AWR-CTX @ _EXT4-C.J.PRIMARY-TORN + !
    THEN
    _EXT4-AWR-CTX @ _EXT4-C.J.CLEANUP + @
    _EXT4-JC-STANDARD <> IF
        \ D over a D/C prefix is idempotent, so a repeated W4 tear remains
        \ inside the exact activation-prefix proof.
        _EXT4-AWR-CTX @ _EXT4-C.SB + _EXT4-PREPARE-DIRTY-SUPER
        _EXT4-AWR-CTX @ _EXT4-C.SB + 2 2 _EXT4-WRITE-SECTORS
        ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        -1 _EXT4-AWR-CTX @ _EXT4-C.RECOVERY + !
        0 _EXT4-AWR-CTX @ _EXT4-C.SUPER-TORN + !
        _EXT4-AWR-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
    THEN
    _EXT4-AWR-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    -1 _EXT4-AWR-CTX @ _EXT4-C.RECOVERY + !
    0 _EXT4-AWR-CTX @ _EXT4-C.SUPER-TORN + !
    _EXT4-JW-NONE _EXT4-AWR-CTX @ _EXT4-C.J.WITNESS + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.WITNESS-CHECKSUM + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.ANCHOR + !
    _EXT4-JC-NONE _EXT4-AWR-CTX @ _EXT4-C.J.CLEANUP + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.PRIMARY-TORN + !
    0 _EXT4-AWR-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    0 ;

VARIABLE _EXT4-RT-CTX
VARIABLE _EXT4-RT-V

: _EXT4-FINISH-RECOVERY-LANDING  ( ctx vfs -- ior )
    _EXT4-RT-V ! _EXT4-RT-CTX !
    _EXT4-RT-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-ACTIVATION = IF
        _EXT4-RT-CTX @ _EXT4-RT-V @
        _EXT4-RESOLVE-ACTIVATION-WITNESS ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-RT-V @ 0 _EXT4-LAND-EMPTY-JOURNAL EXIT
    THEN
    _EXT4-RT-CTX @ _EXT4-C.J.CLEANUP + @ DUP 0<> IF
        DUP _EXT4-JC-STANDARD = SWAP _EXT4-JC-ANCHOR = OR 0= IF
            VFS-E-INVALID EXIT
        THEN
        0 _EXT4-RT-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-C.BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.BSIZE + @ CMOVE
        _EXT4-RT-CTX @ _EXT4-C.J.ANCHOR + @
        _EXT4-RT-CTX @ _EXT4-READ-JBLOCK ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-C.J.ANCHOR + @ _EXT4-RT-CTX @
        _EXT4-JBD2-ANCHOR-BLOCK? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RT-CTX @ _EXT4-C.BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.BSIZE + @ CMOVE
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK + _EXT4-ZERO-JOURNAL-WITNESS
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-JBD2-SUPER-CHECKSUM? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.DIR-BLOCK +
        _EXT4-RT-CTX @ _EXT4-C.BSIZE + @
        _EXT4-PREFIX-MERGE? 0= IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT
        THEN
        _EXT4-RT-CTX @ _EXT4-C.TREE-BLOCK +
        0 _EXT4-RT-CTX @ _EXT4-JOURNAL-MAP@ _EXT4-RT-CTX @
        _EXT4-WRITE-BLOCK ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
        _EXT4-RT-CTX @ _EXT4-RT-V @ _EXT4-RELOAD-STRICT EXIT
    ELSE DROP THEN
    _EXT4-RT-CTX @ _EXT4-PREPARE-CLEAR
    _EXT4-RT-CTX @ _EXT4-C.J.PRIMARY-TORN + @ IF
        _EXT4-RT-CTX @ _EXT4-RESET-JOURNAL ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
    THEN
    _EXT4-RT-CTX @ _EXT4-WRITE-CLEARED-SUPER ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RT-CTX @ _EXT4-RT-V @ _EXT4-RELOAD-STRICT ;

: _EXT4-RECOVER-JOURNAL  ( ctx vfs -- ior )
    _EXT4-RJ-V ! _EXT4-RJ-CTX !
    _EXT4-RJ-CTX @ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @
    _EXT4-JW-ACTIVATION = IF
        _EXT4-RJ-CTX @ _EXT4-RJ-V @
        _EXT4-RESOLVE-ACTIVATION-WITNESS ?DUP IF EXIT THEN
    THEN
    0 _EXT4-RJ-CTX @ _EXT4-C.J.REPLAYED + !
    0 _EXT4-RJ-CTX @ _EXT4-C.J.HOME-WRITES + !
    0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-COUNT + !
    0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-HITS + !
    0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
    _EXT4-RJ-CTX @ _EXT4-C.J.START + @ IF
        _EXT4-RJ-CTX @ _EXT4-C.J.FEATURES + @ DUP
        _EXT4-JBD2-I-RECOVERY = SWAP
        _EXT4-JBD2-I-RECOVERY-REVOKE = OR 0= IF
            EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT
        THEN
        _EXT4-JSCAN-PREFLIGHT _EXT4-RJ-CTX @ _EXT4-JSCAN
        ?DUP IF EXIT THEN
        _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-COUNT + @ _EXT4-RJ-CTX @
        _EXT4-ENSURE-REVOKE-WORKSPACE ?DUP IF EXIT THEN
        _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-COUNT + @ IF
            _EXT4-JSCAN-REVOKES _EXT4-RJ-CTX @ _EXT4-JSCAN
            ?DUP IF EXIT THEN
        THEN
        -1 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
        \ A dirty checksum-torn primary super has no authority of its own.
        \ Its latest authenticated replacement must be committed and must
        \ survive the completed revoke pass before any home write is allowed.
        _EXT4-RJ-CTX @ _EXT4-C.SUPER-TORN + @
        _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @ 0= AND IF
            _EXT4-RJ-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + @ 0= IF
                0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
                EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
            _EXT4-RJ-CTX @ _EXT4-PRIMARY-SUPER-BLOCK
            _EXT4-RJ-CTX @ _EXT4-C.J.SUPER-REPAIR-SEEN + @ 1-
            0xFFFFFFFF AND
            _EXT4-RJ-CTX @ _EXT4-JOURNAL-REVOKED? IF
                0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
                EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT
            THEN
        THEN
        _EXT4-JSCAN-REPLAY _EXT4-RJ-CTX @ _EXT4-JSCAN
        0 _EXT4-RJ-CTX @ _EXT4-C.J.REVOKE-READY + !
        ?DUP IF EXIT THEN
    ELSE
        _EXT4-RJ-CTX @ _EXT4-C.J.SEQUENCE + @ 1+ 0xFFFFFFFF AND
        _EXT4-RJ-CTX @ _EXT4-C.J.NEXT-SEQUENCE + !
        _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @ IF
            _EXT4-RJ-CTX @ _EXT4-C.J.ANCHOR + @
        ELSE
            _EXT4-RJ-CTX @ _EXT4-C.J.HEAD + @ DUP 0= IF
                DROP _EXT4-RJ-CTX @ _EXT4-C.J.FIRST + @
            THEN
        THEN
        _EXT4-RJ-CTX @ _EXT4-C.J.CURSOR + !
    THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    \ Replay may intentionally leave a durable orphan record when no cleanup
    \ commit existed.  Authenticate that plan before deciding whether the
    \ ordinary clear is authorized; policy refusal belongs after this branch.
    _EXT4-RJ-CTX @ _EXT4-RJ-V @
    _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-C.O.ACTIVE + @ IF
        -1 _EXT4-RJ-CTX @ _EXT4-C.J.REPLAYED + !
        0 EXIT
    THEN
    _EXT4-RJ-CTX @ _EXT4-PREPARE-CLEAR
    _EXT4-RJ-CTX @ _EXT4-C.J.START + @ 0=
    _EXT4-RJ-CTX @ _EXT4-C.J.WITNESS + @ 0<> AND
    _EXT4-RJ-CTX @ _EXT4-C.J.PRIMARY-TORN + @ 0= AND 0= IF
        _EXT4-RJ-CTX @ _EXT4-RESET-JOURNAL ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN
    THEN
    _EXT4-RJ-CTX @ _EXT4-WRITE-CLEARED-SUPER ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-CLEAR-JOURNAL-WITNESS ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    _EXT4-RJ-CTX @ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
    _EXT4-FLUSH ?DUP IF EXIT THEN
    0 _EXT4-RJ-CTX @ _EXT4-C.RECOVERY + !
    -1 _EXT4-RJ-CTX @ _EXT4-C.J.REPLAYED + !
    0 ;

VARIABLE _EXT4-MSF-CTX VARIABLE _EXT4-MSF-INDEX
VARIABLE _EXT4-MSF-COUNT VARIABLE _EXT4-MSF-RECORD

: _EXT4-FIND-SINGLETON-ORPHAN
  ( ctx -- plan-record ior )
    DUP _EXT4-MSF-CTX ! 0= IF 0 VFS-E-INVALID EXIT THEN
    _EXT4-MSF-CTX @ _EXT4-ORPHAN-WORKSPACE? 0= IF
        0 EXT4-D-ORPHAN-FILE _EXT4-CORRUPT EXIT THEN
    0 _EXT4-MSF-INDEX ! 0 _EXT4-MSF-COUNT ! 0 _EXT4-MSF-RECORD !
    BEGIN
        _EXT4-MSF-INDEX @ _EXT4-MSF-CTX @ _EXT4-C.O.SLOTS + @ U<
    WHILE
        _EXT4-MSF-INDEX @ _EXT4-MSF-CTX @ _EXT4-ORPHAN-TABLE-ENTRY DUP @ IF
            DUP _EXT4-MSF-RECORD ! 1 _EXT4-MSF-COUNT +! THEN
        DROP 1 _EXT4-MSF-INDEX +!
    REPEAT
    _EXT4-MSF-COUNT @ 1 <> IF 0 EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT THEN
    _EXT4-MSF-RECORD @ _EXT4-MSF-CTX @
    _EXT4-REQUIRE-SINGLETON-ORPHAN
    ?DUP IF 0 SWAP EXIT THEN
    _EXT4-MSF-RECORD @ 0 ;

VARIABLE _EXT4-MOC-CTX VARIABLE _EXT4-MOC-V
VARIABLE _EXT4-MOC-RECORD VARIABLE _EXT4-MOC-CREDIT
VARIABLE _EXT4-MOC-WRITER VARIABLE _EXT4-MOC-TX VARIABLE _EXT4-MOC-IOR
VARIABLE _EXT4-MOC-ARENA VARIABLE _EXT4-MOC-MARK VARIABLE _EXT4-MOC-END
VARIABLE _EXT4-MOC-SPAN VARIABLE _EXT4-MOC-MARK-VALID
VARIABLE _EXT4-MOC-TRANSIENT

: _EXT4-MOC@  ( -- ctx )  _EXT4-MOC-CTX @ ;
: _EXT4-MOC-V@  ( -- vfs )  _EXT4-MOC-V @ ;

\ Prove that a remounted reset prefix was derived from an active journal, not
\ from an empty-journal landing whose intended endpoint would clear the orphan
\ protocol bit.  The exact AKG1 anchor is the durable authority in either an
\ intact-witness or sequential-prefix-torn primary state.
: _EXT4-MOC-REQUIRE-ACTIVE-RESET  ( -- ior )
    _EXT4-MOC@ _EXT4-C.J.ANCHOR + @ DUP 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
    DUP _EXT4-MOC@ _EXT4-READ-JBLOCK ?DUP IF NIP EXIT THEN
    DUP _EXT4-MOC@ _EXT4-JBD2-ANCHOR-BLOCK? 0= IF
        DROP EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN DROP
    _EXT4-MOC@ _EXT4-C.BLOCK + _EXT4-JS.ACTIVATION-CHECKSUM + _EXT4-BE32@
    _EXT4-JBD2-ACTIVE-RESET-MAGIC <> IF
        EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN 0 ;

\ Convert only an authenticated, retained singleton-orphan recovery prefix to
\ the standard empty RECOVER-set journal.  AKG1 is retired with the dirty
\ superblock still authoritative; ORPHAN_PRESENT is never prepared or cleared.
\ The caller may then emit a fresh cleanup transaction without repeating AKW1.
: _EXT4-MOC-CONVERGE-RETAINED-JOURNAL  ( -- ior )
    _EXT4-MOC@ _EXT4-C.RECOVERY + @ 0=
    _EXT4-MOC@ _EXT4-C.J.REPLAYED + @ -1 <> OR IF VFS-E-INVALID EXIT THEN
    _EXT4-MOC@ _EXT4-C.SUPER-TORN + @ IF
        EXT4-D-SUPER-CHECKSUM _EXT4-CORRUPT EXIT THEN
    0 _EXT4-MOC-TRANSIENT !
    _EXT4-MOC@ _EXT4-C.J.START + @ IF
        _EXT4-MOC@ _EXT4-C.J.CLEANUP + @
        _EXT4-JC-ACTIVE <> IF EXT4-D-JOURNAL _EXT4-UNSUPPORTED EXIT THEN
        _EXT4-MOC@ _EXT4-C.J.WITNESS + @ IF
            EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN -1 _EXT4-MOC-TRANSIENT !
    ELSE
        _EXT4-MOC@ _EXT4-C.J.WITNESS + @
        _EXT4-MOC@ _EXT4-C.J.PRIMARY-TORN + @ OR
        _EXT4-MOC@ _EXT4-C.J.CLEANUP + @ OR IF
            _EXT4-MOC@ _EXT4-C.J.WITNESS + @ DUP IF
                _EXT4-JW-RECOVERY <> IF
                    EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
            ELSE
                DROP
                _EXT4-MOC@ _EXT4-C.J.PRIMARY-TORN + @ 0= IF
                    EXT4-D-JOURNAL _EXT4-CORRUPT EXIT THEN
            THEN
            _EXT4-MOC-REQUIRE-ACTIVE-RESET ?DUP IF EXIT THEN
            -1 _EXT4-MOC-TRANSIENT ! THEN
    THEN
    -1 _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-MOC@ _EXT4-C.J.START + @
    _EXT4-MOC@ _EXT4-C.J.PRIMARY-TORN + @ OR IF
        _EXT4-MOC@ _EXT4-RESET-JOURNAL ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN THEN
    _EXT4-MOC-TRANSIENT @ IF
        _EXT4-MOC@ _EXT4-CLEAR-JOURNAL-WITNESS-DIRTY
        ?DUP IF EXIT THEN _EXT4-FLUSH ?DUP IF EXIT THEN
        _EXT4-MOC@ _EXT4-RETIRE-JOURNAL-ANCHOR ?DUP IF EXIT THEN
        _EXT4-FLUSH ?DUP IF EXIT THEN THEN
    _EXT4-MOC@ _EXT4-MOC-V@ _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
    _EXT4-MOC@ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    -1 _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + !
    _EXT4-MOC@ _EXT4-JWR-REBASE-WRITE-ACTIVE ?DUP IF EXIT THEN
    -1 _EXT4-MOC@ _EXT4-C.J.REPLAYED + ! 0 ;

: _EXT4-MOC-WITHDRAW  ( -- )
    0 _EXT4-MOC@ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + ! ;

\ Mount cleanup owns every allocation after this arena mark.  All exits scrub
\ and roll back that tail, so its narrow writer geometry cannot pin the
\ capacity needed by a later public writer.
: _EXT4-MOC-MARK-ARENA  ( -- )
    _EXT4-MOC@ _EXT4-C.ARENA + @ DUP _EXT4-MOC-ARENA !
    ARENA-SNAP _EXT4-MOC-MARK !
    -1 _EXT4-MOC-MARK-VALID ! ;

: _EXT4-MOC-WRITER-ALLOCATION?  ( writer -- flag )
    DUP _EXT4-MOC-MARK @ <> IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.MAGIC + @ _EXT4-JWR-MAGIC <> IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.SELF + @ OVER <> IF DROP FALSE EXIT THEN
    DUP _EXT4-JWR.CTX + @ _EXT4-MOC@ <> IF DROP FALSE EXIT THEN
    _EXT4-JWR.TOTAL + @ _EXT4-MOC-SPAN @ = ;

: _EXT4-MOC-RELEASE  ( -- ior )
    _EXT4-MOC-MARK-VALID @ 0= IF 0 EXIT THEN
    _EXT4-MOC@ _EXT4-C.ARENA + @ _EXT4-MOC-ARENA @ <> IF
        VFS-E-CORRUPT EXIT THEN
    _EXT4-MOC-ARENA @ A.PTR @ _EXT4-MOC-END !
    _EXT4-MOC-MARK @ _EXT4-MOC-ARENA @ A.BASE @ U<
    _EXT4-MOC-END @ _EXT4-MOC-MARK @ U< OR
    _EXT4-MOC-END @ _EXT4-MOC-ARENA @ A.BASE @
    _EXT4-MOC-ARENA @ A.SIZE @ + U> OR IF VFS-E-CORRUPT EXIT THEN
    _EXT4-MOC-END @ _EXT4-MOC-MARK @ - _EXT4-MOC-SPAN !
    _EXT4-MOC-WRITER @ ?DUP IF
        DUP _EXT4-MOC@ _EXT4-C.J.WRITER + @ <> IF
            DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-MOC-SPAN @ _EXT4-JWR-SIZE U< IF
            DROP VFS-E-CORRUPT EXIT THEN
        _EXT4-MOC-WRITER-ALLOCATION? 0= IF VFS-E-CORRUPT EXIT THEN
    ELSE
        _EXT4-MOC@ _EXT4-C.J.WRITER + @ IF VFS-E-CORRUPT EXIT THEN
    THEN
    0 _EXT4-MOC@ _EXT4-C.J.WRITER + !
    _EXT4-MOC-MARK @ _EXT4-MOC-SPAN @ 0 FILL
    _EXT4-MOC-ARENA @ _EXT4-MOC-MARK @ ARENA-ROLLBACK
    0 _EXT4-MOC-WRITER ! 0 _EXT4-MOC-TX !
    0 _EXT4-MOC-MARK-VALID ! 0 ;

: _EXT4-MOC-RELEASE-RESULT  ( -- )
    _EXT4-MOC-RELEASE ?DUP IF _EXT4-MOC-IOR ! THEN ;

: _EXT4-MOC-FAIL-CLEAN  ( ior -- ior )
    _EXT4-MOC-IOR !
    _EXT4-MOC-WRITER @ ?DUP IF
        DUP _EXT4-JWR.STATE + @ _EXT4-JWR-STAGING = IF
            _EXT4-JTX-ABORT ?DUP IF _EXT4-MOC-IOR ! THEN
        ELSE
            DROP
        THEN
    THEN
    _EXT4-MOC-WITHDRAW _EXT4-MOC-RELEASE-RESULT _EXT4-MOC-IOR @ ;

: _EXT4-MOC-FAIL-DIRTY  ( ior -- ior )
    _EXT4-MOC-IOR ! _EXT4-MOC-WITHDRAW
    _EXT4-MOC-RELEASE-RESULT _EXT4-MOC-IOR @ ;

\ Complete the first production-selected nonempty recovery case from either an
\ exact clean journal or a crash-converged empty RECOVER-set endpoint.  Dry
\ staging proves semantics and measured credit before the first transaction
\ mutation.  The second identical staging is emitted durably, then fed through
\ ordinary replay/landing so the orphan protocol bit is cleared only after
\ committed afterimages have reached home.
: _EXT4-COMPLETE-SINGLETON-ORPHAN-BODY  ( ctx vfs -- ior )
    _EXT4-MOC-V ! _EXT4-MOC-CTX !
    0 _EXT4-MOC-WRITER ! 0 _EXT4-MOC-TX !
    0 _EXT4-MOC-MARK-VALID !
    _EXT4-MOC@ _EXT4-C.READY + @ _EXT4-MOC@ _EXT4-C.J.WRITER-CURRENT + @ OR
    _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-MOC@ _EXT4-C.J.WRITER + @ OR IF VFS-E-INVALID EXIT THEN
    _EXT4-MOC-V@ _EXT4-CTX _EXT4-MOC@ <> IF
        VFS-E-INVALID EXIT THEN
    _EXT4-MOC-V@ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-MOC-V@ V.VOLUME @ _EXT4-IO-VOL @ <> IF
        VFS-E-INVALID EXIT THEN
    _EXT4-MOC@ _EXT4-RECOVERY-MEDIA ?DUP IF EXIT THEN
    _EXT4-MOC@ _EXT4-FIND-SINGLETON-ORPHAN
    _EXT4-MOC-IOR ! _EXT4-MOC-RECORD !
    _EXT4-MOC-IOR @ ?DUP IF EXIT THEN
    _EXT4-MOC-RECORD @ _EXT4-MOC@
    _EXT4-MEASURE-SINGLETON-ORPHAN-DEPTH0
    _EXT4-MOC-IOR ! _EXT4-MOC-CREDIT !
    _EXT4-MOC-IOR @ ?DUP IF EXIT THEN
    _EXT4-MOC-CREDIT @ 0 0 _EXT4-MOC@
    _EXT4-JTX-PREFLIGHT-CAPACITY ?DUP IF EXIT THEN
    _EXT4-MOC@ _EXT4-C.RECOVERY + @ IF
        _EXT4-JFO-CERT-INVALIDATE
        _EXT4-MOC-CONVERGE-RETAINED-JOURNAL DUP IF
            0 _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + ! EXIT
        THEN DROP
        \ Convergence performs a strict media reload and rebuilds the plan.
        \ Reacquire its arena record and require the exact credit again.
        _EXT4-MOC@ _EXT4-FIND-SINGLETON-ORPHAN
        _EXT4-MOC-IOR ! _EXT4-MOC-RECORD !
        _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
        _EXT4-MOC-RECORD @ _EXT4-MOC@
        _EXT4-MEASURE-SINGLETON-ORPHAN-DEPTH0
        _EXT4-MOC-IOR ! _EXT4-MOC-CREDIT !
        _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
        _EXT4-MOC-CREDIT @ 0 0 _EXT4-MOC@
        _EXT4-JTX-PREFLIGHT-CAPACITY
        ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    ELSE
        _EXT4-MOC@ _EXT4-C.J.START + @ _EXT4-MOC@ _EXT4-C.J.WITNESS + @ OR
        _EXT4-MOC@ _EXT4-C.J.PRIMARY-TORN + @ OR
        _EXT4-MOC@ _EXT4-C.J.CLEANUP + @ OR
        _EXT4-MOC@ _EXT4-C.SUPER-TORN + @ OR IF VFS-E-INVALID EXIT THEN
        _EXT4-MOC@ _EXT4-JWR-REBASE-MOUNTED ?DUP IF EXIT THEN
    THEN
    _EXT4-MOC-MARK-ARENA
    -1 _EXT4-MOC@ _EXT4-C.J.WRITER-CURRENT + !
    _EXT4-MOC-CREDIT @ 0 0 _EXT4-MOC@ _EXT4-JWR-ENSURE
    _EXT4-MOC-IOR ! _EXT4-MOC-WRITER !
    _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-CLEAN EXIT THEN
    _EXT4-MOC-CREDIT @ 0 0 _EXT4-MOC-WRITER @ _EXT4-JTX-BEGIN
    _EXT4-MOC-IOR ! _EXT4-MOC-TX !
    _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-CLEAN EXIT THEN
    _EXT4-MOC-RECORD @ _EXT4-MOC-TX @
    _EXT4-JTX-STAGE-SINGLETON-ORPHAN-DEPTH0-FINAL
    ?DUP IF _EXT4-MOC-FAIL-CLEAN EXIT THEN
    _EXT4-MOC-TX @ _EXT4-JTX-ABORT
    ?DUP IF _EXT4-MOC-FAIL-CLEAN EXIT THEN
    _EXT4-MOC@ _EXT4-C.J.WRITE-ACTIVE + @ 0= IF
        _EXT4-MOC-WRITER @ _EXT4-JWR-ACTIVATE
        ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    THEN
    _EXT4-MOC-CREDIT @ 0 0 _EXT4-MOC-WRITER @ _EXT4-JTX-BEGIN
    _EXT4-MOC-IOR ! _EXT4-MOC-TX !
    _EXT4-MOC-IOR @ ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    _EXT4-MOC-RECORD @ _EXT4-MOC-TX @
    _EXT4-JTX-STAGE-SINGLETON-ORPHAN-DEPTH0-FINAL
    ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    _EXT4-MOC-TX @ _EXT4-JTX-EMIT
    ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    _EXT4-JFO-CERT-INVALIDATE
    _EXT4-MOC-WITHDRAW
    _EXT4-MOC@ _EXT4-MOC-V@ _EXT4-RECOVER-JOURNAL
    ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    _EXT4-MOC@ _EXT4-MOC-V@ _EXT4-RELOAD-STRICT
    ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    _EXT4-MOC@ _EXT4-VALIDATE-ROOT
    ?DUP IF _EXT4-MOC-FAIL-DIRTY EXIT THEN
    _EXT4-MOC-V@ _EXT4-ATTACHED? 0= IF
        VFS-E-STALE _EXT4-MOC-FAIL-DIRTY EXIT THEN
    _EXT4-MOC-RELEASE ?DUP IF EXIT THEN 0 ;

\ One mount-cleanup invocation owns the proof scope.  Every exit, including a
\ media or writer failure returned by the body, clears the certificate before
\ control can return to a caller or another filesystem context.
: _EXT4-COMPLETE-SINGLETON-ORPHAN  ( ctx vfs -- ior )
    _EXT4-JFO-CERT-BEGIN ?DUP IF >R 2DROP R> EXIT THEN
    _EXT4-COMPLETE-SINGLETON-ORPHAN-BODY
    _EXT4-JFO-CERT-END ;

\ =====================================================================
\  Mount, metadata callbacks, and read-only binding descriptor
\ =====================================================================

VARIABLE _EXT4-M-V
VARIABLE _EXT4-M-CTX
VARIABLE _EXT4-M-IOR
VARIABLE _EXT4-M-FRESH

: _EXT4-MOUNT-AUTHENTICATE  ( vfs -- ior )
    DUP _EXT4-M-V !
    \ Invalidate every retained transaction pointer before any remount check
    \ or media-derived context reset can fail.
    _EXT4-M-V @ V.BCTX @ ?DUP IF
        0 SWAP _EXT4-C.J.WRITER-CURRENT + !
    THEN
    DUP _EXT4-ATTACHED? 0= IF DROP EXT4-D-ATTACHMENT _EXT4-CORRUPT EXIT THEN
    DROP
    _EXT4-M-V @ V.VOLUME @ DUP VOL.SECTOR-SIZE _EXT4-SECTOR <> IF
        DROP 0 0 VFS-IOR-D-VOLUME VFS-R-UNSUPPORTED VFS-IOR-MAKE EXIT
    THEN
    _EXT4-IO-VOL ! _EXT4-M-V @ _EXT4-IO-VFS !
    0 _EXT4-M-FRESH !
    _EXT4-M-V @ V.BCTX @ ?DUP IF
        _EXT4-M-CTX !
    ELSE
        _EXT4-M-V @ V.ARENA @ _EXT4-CTX-SIZE ARENA-ALLOT?
        IF DROP VFS-E-NOMEM EXIT THEN
        DUP _EXT4-M-CTX ! _EXT4-M-V @ V.BCTX !
        -1 _EXT4-M-FRESH !
    THEN
    _EXT4-M-FRESH @ IF
        _EXT4-M-CTX @ _EXT4-CTX-SIZE 0 FILL
        _EXT4-M-V @ V.ARENA @ _EXT4-M-CTX @ _EXT4-C.ARENA + !
    ELSE
        \ Preserve arena workspace allocations owned by this binding across a
        \ failed-mount retry while resetting all media-derived state.
        _EXT4-M-CTX @ _EXT4-CTX-RESET-SIZE 0 FILL
    THEN
    0 _EXT4-M-CTX @ _EXT4-C.J.REVOKE-COUNT + !
    0 _EXT4-M-CTX @ _EXT4-C.J.REVOKE-HITS + !
    0 _EXT4-M-CTX @ _EXT4-C.J.REVOKE-READY + !
    0 _EXT4-M-CTX @ _EXT4-C.J.HEAD + !
    0 _EXT4-M-CTX @ _EXT4-C.J.MAX-TRANSACTION + !
    0 _EXT4-M-CTX @ _EXT4-C.J.MAX-TRANS-DATA + !
    0 _EXT4-M-CTX @ _EXT4-C.J.WITNESS-NEW-CHECKSUM + !
    0 _EXT4-M-CTX @ _EXT4-C.J.WRITE-ACTIVE + !
    0 _EXT4-M-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-M-CTX @ _EXT4-C.O.ACTIVE + !
    0 _EXT4-M-CTX @ _EXT4-C.O.MODERN-ACTIVE + !
    0 _EXT4-M-CTX @ _EXT4-C.O.LEGACY-ACTIVE + !
    0 _EXT4-M-CTX @ _EXT4-C.O.CLEAR-PENDING + !
    _EXT4-M-CTX @ _EXT4-C.SB + 2 2 _EXT4-READ-SECTORS
    DUP IF EXIT THEN DROP
    _EXT4-M-CTX @ _EXT4-M-V @ _EXT4-VALIDATE-SUPER
    DUP IF EXIT THEN DROP
    _EXT4-M-CTX @ _EXT4-C.RECOVERY + @ IF
        \ Bootstrap from inode 8 without trusting mutable aggregate counters;
        \ strict whole-filesystem validation follows replay while the journal
        \ is still intact and replayable.
        _EXT4-M-CTX @ _EXT4-VALIDATE-JOURNAL ?DUP IF EXIT THEN
        _EXT4-M-CTX @ _EXT4-M-V @ _EXT4-RECOVER-JOURNAL ?DUP IF EXIT THEN
        _EXT4-M-CTX @ _EXT4-M-V @
        _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
    ELSE
        _EXT4-M-CTX @ _EXT4-AUTHENTICATE-REST ?DUP IF EXIT THEN
        _EXT4-M-CTX @ _EXT4-C.O.ACTIVE + @ IF
            _EXT4-M-CTX @ _EXT4-C.SUPER-TORN + @
            _EXT4-M-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
            _EXT4-M-CTX @ _EXT4-C.J.WITNESS + @ OR
            _EXT4-M-CTX @ _EXT4-C.J.CLEANUP + @ OR IF
                _EXT4-M-CTX @ _EXT4-C.J.WITNESS + @
                _EXT4-JW-ACTIVATION <> IF
                    EXT4-D-RECOVERY _EXT4-UNSUPPORTED EXIT
                THEN
                _EXT4-M-CTX @ _EXT4-M-V @
                _EXT4-RECOVER-JOURNAL ?DUP IF EXIT THEN
                _EXT4-M-CTX @ _EXT4-M-V @
                _EXT4-RELOAD-AUTHENTICATED ?DUP IF EXIT THEN
            THEN
        ELSE
            _EXT4-M-CTX @ _EXT4-C.SUPER-TORN + @
            _EXT4-M-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
            _EXT4-M-CTX @ _EXT4-C.J.WITNESS + @ OR IF
                _EXT4-M-CTX @ _EXT4-M-V @
                _EXT4-FINISH-RECOVERY-LANDING ?DUP IF EXIT THEN
            THEN
        THEN
    THEN
    _EXT4-M-CTX @ _EXT4-VALIDATE-ROOT ?DUP IF EXIT THEN
    _EXT4-M-V @ _EXT4-ATTACHED? 0= IF
        EXT4-D-ATTACHMENT _EXT4-CORRUPT EXIT
    THEN
    0 ;

: _EXT4-MOUNT  ( vfs -- ior )
    _EXT4-MOUNT-AUTHENTICATE ?DUP IF EXIT THEN
    _EXT4-M-CTX @ _EXT4-C.O.ACTIVE + @ IF
        _EXT4-M-CTX @ _EXT4-M-V @
        _EXT4-COMPLETE-SINGLETON-ORPHAN ?DUP IF EXIT THEN
        _EXT4-M-V @ _EXT4-ATTACHED? 0= IF
            EXT4-D-ATTACHMENT _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-M-CTX @ _EXT4-EMPTY-ORPHAN-RECOVERY? IF
        _EXT4-M-CTX @ _EXT4-M-V @
        _EXT4-COMPLETE-EMPTY-ORPHAN ?DUP IF EXIT THEN
        _EXT4-M-V @ _EXT4-ATTACHED? 0= IF
            EXT4-D-ATTACHMENT _EXT4-CORRUPT EXIT
        THEN
    THEN
    _EXT4-M-CTX @ _EXT4-JWR-REBASE-MOUNTED ?DUP IF EXIT THEN
    _EXT4-M-V @ V.FLAGS DUP @ VFS-F-DIRTY INVERT AND SWAP !
    _EXT4-M-CTX @ _EXT4-M-V @ _EXT4-PUBLISH-ROOT
    -1 _EXT4-M-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    -1 _EXT4-M-CTX @ _EXT4-C.READY + !
    0 ;

VARIABLE _EXT4-GA-D
VARIABLE _EXT4-GA-V
VARIABLE _EXT4-GA-CTX
VARIABLE _EXT4-GA-TYPE
VARIABLE _EXT4-GA-IOR

: _EXT4-GETATTR  ( dentry vfs -- ior )
    _EXT4-GA-V ! _EXT4-GA-D !
    _EXT4-GA-V @ _EXT4-CTX _EXT4-GA-CTX !
    _EXT4-GA-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-GA-V @ _EXT4-IO-VFS !
    _EXT4-GA-D @ IN.BID @ _EXT4-GA-CTX @ _EXT4-LOAD-INODE ?DUP IF EXIT THEN
    _EXT4-GA-CTX @ _EXT4-STAGE-CURRENT-INODE
    _EXT4-GA-IOR ! _EXT4-GA-TYPE !
    _EXT4-GA-IOR @ ?DUP IF EXIT THEN
    _EXT4-GA-TYPE @ _EXT4-GA-D @ IN.TYPE @ <> IF VFS-E-CORRUPT EXIT THEN
    _EXT4-GA-CTX @ _EXT4-C.R.GEN + @
    _EXT4-GA-D @ D.VNODE @ VN.GEN @ <> IF VFS-E-STALE EXIT THEN
    _EXT4-GA-V @ _EXT4-ATTACHED? 0= IF VFS-E-STALE EXIT THEN
    _EXT4-GA-CTX @ _EXT4-GA-D @ _EXT4-GA-TYPE @ _EXT4-PUBLISH-STAGED
    0 ;

VARIABLE _EXT4-SF-BUF
VARIABLE _EXT4-SF-SIZE
VARIABLE _EXT4-SF-V
VARIABLE _EXT4-SF-CTX
VARIABLE _EXT4-SF-OUT
VARIABLE _EXT4-SF-AVAIL

: _EXT4-STATFS  ( buffer bytes vfs -- ior )
    _EXT4-SF-V ! _EXT4-SF-SIZE ! _EXT4-SF-BUF !
    _EXT4-SF-V @ _EXT4-CTX DUP _EXT4-SF-CTX !
    _EXT4-C.STAT + DUP _EXT4-SF-OUT ! VFS-STATFS-SIZE 0 FILL
    _EXT4-SF-CTX @ _EXT4-C.BSIZE + @ DUP
    _EXT4-SF-OUT @ VSF.BSIZE !
    _EXT4-SF-OUT @ VSF.FRSIZE !
    _EXT4-SF-CTX @ _EXT4-C.BLOCKS + @ _EXT4-SF-OUT @ VSF.BLOCKS !
    _EXT4-SF-CTX @ _EXT4-C.FREE-BLOCKS + @ DUP
    _EXT4-SF-OUT @ VSF.BFREE !
    _EXT4-SF-CTX @ _EXT4-C.RESERVED-BLOCKS + @
    2DUP U< IF 2DROP 0 ELSE - THEN DUP _EXT4-SF-AVAIL !
    _EXT4-SF-OUT @ VSF.BAVAIL !
    _EXT4-SF-CTX @ _EXT4-C.INODES + @ _EXT4-SF-OUT @ VSF.FILES !
    _EXT4-SF-CTX @ _EXT4-C.FREE-INODES + @ _EXT4-SF-OUT @ VSF.FFREE !
    255 _EXT4-SF-OUT @ VSF.NAMEMAX !
    0 _EXT4-SF-OUT @ VSF.FLAGS !
    _EXT4-SF-CTX @ _EXT4-C.UUID-LO + @ _EXT4-SF-OUT @ VSF.FSID-LO !
    _EXT4-SF-CTX @ _EXT4-C.UUID-HI + @ _EXT4-SF-OUT @ VSF.FSID-HI !
    0 _EXT4-SF-OUT @ VSF.RESERVED !
    _EXT4-SF-OUT @ _EXT4-SF-BUF @ VFS-STATFS-SIZE CMOVE
    0 ;

VARIABLE _EXT4-UM-V
VARIABLE _EXT4-UM-CTX
VARIABLE _EXT4-UM-WRITER
VARIABLE _EXT4-UM-STATE

: _EXT4-UM-QUARANTINE  ( ior -- ior )
    VFS-L-STALE _EXT4-UM-V @ V.LIFECYCLE ! ;

: _EXT4-UM-CLEAN-ENDPOINT?  ( -- flag )
    _EXT4-UM-V @ _EXT4-ATTACHED? 0= IF FALSE EXIT THEN
    _EXT4-UM-CTX @ _EXT4-C.RECOVERY + @
    _EXT4-UM-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ OR
    _EXT4-UM-CTX @ _EXT4-C.J.START + @ OR
    _EXT4-UM-CTX @ _EXT4-C.J.WITNESS + @ OR
    _EXT4-UM-CTX @ _EXT4-C.J.PRIMARY-TORN + @ OR
    _EXT4-UM-CTX @ _EXT4-C.J.CLEANUP + @ OR
    _EXT4-UM-CTX @ _EXT4-C.SUPER-TORN + @ OR
    _EXT4-UM-V @ V.FLAGS @ VFS-F-DIRTY AND OR IF
        FALSE EXIT
    THEN
    _EXT4-UM-CTX @ _EXT4-C.SB + DUP
    _EXT4-SUPER-CHECKSUM? 0= IF DROP FALSE EXIT THEN
    _EXT4-SB.INCOMPAT + L@ _EXT4-INCOMPAT-RECOVER AND 0= ;

: _EXT4-UM-PREPARE-WRITER  ( -- ior )
    _EXT4-UM-CTX @ _EXT4-C.J.WRITER + @ DUP _EXT4-UM-WRITER ! 0= IF
        0 EXIT
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR-SHAPE? 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR.STATE + @ DUP _EXT4-UM-STATE !
    _EXT4-JWR-FAULTED = IF
        _EXT4-UM-WRITER @ _EXT4-JWR.FAULT + @ DUP 0= IF
            DROP VFS-E-CORRUPT
        THEN
        _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-CTX @ _EXT4-C.J.WRITER-CURRENT + @ 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR-VALID? 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-STATE @ _EXT4-JWR-STAGING =
    _EXT4-UM-STATE @ _EXT4-JWR-ACTIVATING = OR
    _EXT4-UM-STATE @ _EXT4-JWR-EMITTING = OR
    _EXT4-UM-STATE @ _EXT4-JWR-CHECKPOINTING = OR
    _EXT4-UM-STATE @ _EXT4-JWR-DEACTIVATING = OR IF
        VFS-E-BUSY EXIT
    THEN
    _EXT4-UM-STATE @ _EXT4-JWR-COMMITTED = IF
        _EXT4-UM-WRITER @ _EXT4-JTX-CHECKPOINT
        ?DUP IF _EXT4-UM-QUARANTINE EXIT THEN
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR.STATE + @ _EXT4-JWR-IDLE <> IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    _EXT4-UM-WRITER @ _EXT4-JWR-IDLE-CLEAN? 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    0 ;

: _EXT4-UNMOUNT  ( flags vfs -- ior )
    _EXT4-UM-V ! DROP
    _EXT4-UM-V @ V.BCTX @ DUP 0= IF DROP 0 EXIT THEN _EXT4-UM-CTX !
    _EXT4-UM-V @ V.VOLUME @ _EXT4-IO-VOL !
    _EXT4-UM-V @ _EXT4-IO-VFS !
    _EXT4-UM-PREPARE-WRITER ?DUP IF EXIT THEN
    _EXT4-UM-CTX @ _EXT4-C.J.WRITE-ACTIVE + @ IF
        _EXT4-UM-WRITER @ DUP 0= IF
            DROP VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
        THEN
        _EXT4-UM-V @ _EXT4-JWR-DEACTIVATE
        ?DUP IF _EXT4-UM-QUARANTINE EXIT THEN
    THEN
    _EXT4-UM-CLEAN-ENDPOINT? 0= IF
        VFS-E-CORRUPT _EXT4-UM-QUARANTINE EXIT
    THEN
    0 _EXT4-UM-CTX @ _EXT4-C.J.WRITER-CURRENT + !
    0 _EXT4-UM-CTX @ _EXT4-C.READY + !
    0 _EXT4-UM-V @ V.BCTX !
    0 ;

VFS-CAP-PROBE VFS-CAP-MOUNT OR VFS-CAP-UNMOUNT OR
VFS-CAP-READDIR OR VFS-CAP-OPEN OR VFS-CAP-RELEASE OR
VFS-CAP-READ OR VFS-CAP-GETATTR OR VFS-CAP-READLINK OR
VFS-CAP-SYNCFS OR VFS-CAP-FSYNC OR VFS-CAP-STATFS OR
VFS-CAP-LISTXATTR OR VFS-CAP-GETXATTR OR
VFS-CAP-SPARSE OR VFS-CAP-STABLE-HANDLES OR CONSTANT EXT4-CAPS

CREATE EXT4-OPS VFS-OPS-SIZE ALLOT
EXT4-OPS VFS-OPS-SIZE 0 FILL
' _EXT4-PROBE   EXT4-OPS VFS-OP-PROBE   CELLS + !
' _EXT4-MOUNT   EXT4-OPS VFS-OP-MOUNT   CELLS + !
' _EXT4-UNMOUNT EXT4-OPS VFS-OP-UNMOUNT CELLS + !
' _EXT4-READDIR EXT4-OPS VFS-OP-READDIR CELLS + !
' _EXT4-OPEN    EXT4-OPS VFS-OP-OPEN    CELLS + !
' _EXT4-RELEASE EXT4-OPS VFS-OP-RELEASE CELLS + !
' _EXT4-READ    EXT4-OPS VFS-OP-READ    CELLS + !
' _EXT4-GETATTR EXT4-OPS VFS-OP-GETATTR CELLS + !
' _EXT4-READLINK EXT4-OPS VFS-OP-READLINK CELLS + !
' _EXT4-SYNCFS  EXT4-OPS VFS-OP-SYNCFS  CELLS + !
' _EXT4-FSYNC   EXT4-OPS VFS-OP-FSYNC   CELLS + !
' _EXT4-LISTXATTR EXT4-OPS VFS-OP-LISTXATTR CELLS + !
' _EXT4-GETXATTR  EXT4-OPS VFS-OP-GETXATTR  CELLS + !
' _EXT4-STATFS  EXT4-OPS VFS-OP-STATFS  CELLS + !

CREATE EXT4-BINDING
VFS-BINDING-MAGIC ,
VFS-BINDING-ABI-MAJOR ,
VFS-BINDING-ABI-MINOR ,
VFS-BINDING-DESC-SIZE ,
VFS-OPS-SIZE ,
EXT4-CAPS ,
VFS-BF-NEEDS-VOLUME VFS-BF-READ-ONLY OR VFS-BF-STABLE-IDS OR ,
EXT4-OPS ,
0 , 0 ,

: EXT4-NEW  ( arena volume -- vfs ior )
    EXT4-BINDING SWAP VFS-NEW ;

: EXT4-BLOCK-SIZE@  ( vfs -- bytes )  _EXT4-CTX _EXT4-C.BSIZE + @ ;
: EXT4-BLOCK-COUNT@ ( vfs -- blocks ) _EXT4-CTX _EXT4-C.BLOCKS + @ ;
: EXT4-GROUP-COUNT@ ( vfs -- groups ) _EXT4-CTX _EXT4-C.GROUPS + @ ;
: EXT4-INODE-SIZE@  ( vfs -- bytes )  _EXT4-CTX _EXT4-C.ISIZE + @ ;
